create or replace function public.cfx_venta() returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce((select valor from public.cfx_config where clave = 'modulos_venta'), '{}'::jsonb)
$$;
-- Precio al mes de un módulo o pack (0 = incluido gratis).
create or replace function public.cfx_venta_precio(p_item text) returns int
language sql stable security definer set search_path = '' as $$
  select coalesce((v #>> array['packs', p_item, 'precio'])::int, (v #>> array['precios', p_item])::int, (v ->> 'precio')::int, 0)
  from (select public.cfx_venta() v) x
$$;
-- ¿Está prendida la venta de módulos en esta app? (si no, todo funciona como antes del G19)
create or replace function public.cfx_venta_on() returns boolean
language sql stable security definer set search_path = '' as $$ select coalesce((public.cfx_venta() ->> 'activo')::boolean, false) $$;
-- ¿Este módulo se vende aparte en esta app? (venta prendida y precio > 0)
create or replace function public.cfx_venta_activa(p_modulo text) returns boolean
language sql stable security definer set search_path = '' as $$
  select public.cfx_venta_on() and p_modulo = any(public.cfx_modulos_de_app()) and public.cfx_venta_precio(p_modulo) > 0
$$;
-- Módulos que trae un pack ('*' = todos los de la app) o el módulo mismo.
create or replace function public.cfx_venta_modulos(p_item text) returns text[]
language plpgsql stable security definer set search_path = '' as $$
declare p jsonb := public.cfx_venta() #> array['packs', p_item];
begin
  if p is null then return case when p_item = any(public.cfx_modulos_de_app()) then array[p_item] else '{}'::text[] end; end if;
  if p ->> 'modulos' = '*' then return public.cfx_modulos_de_app(); end if;
  return array(select x from jsonb_array_elements_text(coalesce(p -> 'modulos', '[]')) x where x = any(public.cfx_modulos_de_app()));
end $$;

-- G74 b · 🎁 Campaña de lanzamiento: {"modulos": [...], "meses": 3, "hasta": "AAAA-MM-DD"} en cfx_venta() -> 'campana'.
-- Activa hasta el día "hasta" incluido (hora de Chile): sin cron, se apaga sola al pasar la fecha.
create or replace function public.cfx_campana() returns jsonb
language sql stable security definer set search_path = '' as $$
  select case when public.cfx_venta_on() and jsonb_typeof(c) = 'object' and (c ->> 'hasta') ~ '^\d{4}-\d{2}-\d{2}$'
    and (c ->> 'hasta')::date >= (now() at time zone 'America/Santiago')::date and coalesce((c ->> 'meses')::int, 0) between 1 and 12
    and jsonb_typeof(c -> 'modulos') = 'array' and jsonb_array_length(c -> 'modulos') > 0 then c end
  from (select public.cfx_venta() -> 'campana' c) x
$$;
create or replace function public.cfx_negocio_cuenta(p_cuenta uuid) returns uuid
language plpgsql stable security definer set search_path = '' as $$
declare n uuid;
begin
  if p_cuenta is null then return null; end if;
  if to_regprocedure('public.cfx_negocio_de_cuenta(uuid)') is not null then execute 'select public.cfx_negocio_de_cuenta($1)' into n using p_cuenta;
  elsif to_regprocedure('public.cfx_analisis_negocio(uuid)') is not null then execute 'select public.cfx_analisis_negocio($1)' into n using p_cuenta;
  else n := p_cuenta; end if;
  return n;
end $$;
-- G95: la cuenta del dueño de un negocio. Gancho opcional de la app: cfx_negocio_dueno_app(uuid) → uuid (Billetera: el negocio no es la cuenta).
create or replace function public.cfx_negocio_dueno(p_negocio uuid) returns uuid
language plpgsql stable security definer set search_path = '' as $$
declare d uuid;
begin
  if p_negocio is null then return null; end if;
  if to_regprocedure('public.cfx_negocio_dueno_app(uuid)') is not null then execute 'select public.cfx_negocio_dueno_app($1)' into d using p_negocio; return d; end if;
  return p_negocio;
end $$;
create or replace function public.cfx_negocio_premium(p_negocio uuid) returns boolean
language plpgsql stable security definer set search_path = '' as $$
declare r boolean;
begin
  if p_negocio is null or to_regprocedure('public.cfx_es_premium(uuid)') is null then return false; end if;
  execute 'select public.cfx_es_premium($1)' into r using p_negocio;
  return coalesce(r, false);
end $$;

-- ¿El negocio puede usar el módulo ahora? (prendido en la app + comprado, en prueba, regalado o incluido gratis)
create or replace function public.cfx_modulo_de(p_modulo text, p_negocio uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select public.cfx_modulo(p_modulo) and (not public.cfx_venta_activa(p_modulo)
    or exists (select 1 from public.cfx_modulos_negocio m where m.negocio = p_negocio and m.modulo = p_modulo and m.hasta > now()))
$$;
create or replace function public.cfx_modulo_mio(p_modulo text) returns boolean
language sql stable security definer set search_path = '' as $$ select public.cfx_modulo_de(p_modulo, public.cfx_negocio_cuenta(auth.uid())) $$;

-- Lo que puede usar cada negocio: {"chat": true, ...}. Para una tienda que ve un cliente.
create or replace function public.cfx_modulos_de(p_negocio uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce((select jsonb_object_agg(k, public.cfx_modulo_de(k, p_negocio)) from unnest(public.cfx_modulos_de_app()) k), '{}')
$$;

-- Activa (o alarga) los módulos de un item por N días; N <= 0 los quita. Devuelve hasta cuándo.
create or replace function public.cfx_modulos_dar(p_negocio uuid, p_item text, p_dias int, p_origen text default 'pago') returns timestamptz
language plpgsql security definer set search_path = '' as $$
declare k text; h timestamptz; mx timestamptz;
begin
  if p_negocio is null or cardinality(public.cfx_venta_modulos(p_item)) = 0 then raise exception 'Módulo no válido'; end if;
  foreach k in array public.cfx_venta_modulos(p_item) loop
    if coalesce(p_dias, 0) <= 0 then delete from public.cfx_modulos_negocio where negocio = p_negocio and modulo = k; continue; end if;
    insert into public.cfx_modulos_negocio as m (negocio, modulo, hasta, origen) values (p_negocio, k, now() + make_interval(days => p_dias), p_origen)
    on conflict (negocio, modulo) do update set hasta = greatest(m.hasta, now()) + make_interval(days => p_dias),
      origen = case when excluded.origen = 'prueba' then m.origen else excluded.origen end, avisado = null
    returning hasta into h;
    mx := greatest(mx, h);
  end loop;
  return mx;
end $$;

-- G53: ¿el plan del negocio ya trae este módulo? (ej. Barbería: Premium incluye los 3 primeros). Gancho opcional de cada app:
-- cfx_modulo_plan_app(text, uuid) → boolean. Sin gancho: ninguno viene en el plan.
create or replace function public.cfx_modulo_plan(p_modulo text, p_negocio uuid) returns boolean
language plpgsql stable security definer set search_path = '' as $$
declare r boolean;
begin
  if p_negocio is null or to_regprocedure('public.cfx_modulo_plan_app(text,uuid)') is null then return false; end if;
  execute 'select public.cfx_modulo_plan_app($1, $2)' into r using p_modulo, p_negocio;
  return coalesce(r, false);
end $$;

-- ¿Este negocio puede activar gratis este módulo con la campaña? (una vez por módulo)
create or replace function public.cfx_campana_puede(p_modulo text, p_negocio uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select p_negocio is not null and public.cfx_campana() is not null and public.cfx_campana() -> 'modulos' ? p_modulo
    and public.cfx_modulo(p_modulo) and public.cfx_venta_activa(p_modulo) and not public.cfx_modulo_plan(p_modulo, p_negocio)
    and not exists (select 1 from public.cfx_modulos_pruebas p where p.negocio = p_negocio and p.item = 'campana:' || p_modulo)
$$;

-- Pantalla 🧩 Módulos del negocio: catálogo, precios (con su descuento Premium), lo que tiene y hasta cuándo.
create or replace function public.cfx_modulos_tienda() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v jsonb := public.cfx_venta(); n uuid := public.cfx_negocio_cuenta(auth.uid()); dn uuid := public.cfx_negocio_dueno(public.cfx_negocio_cuenta(auth.uid())); pre boolean; d int; am int;
begin
  if n is null then raise exception 'Solo para negocios'; end if;
  pre := public.cfx_negocio_premium(n);
  d := case when pre then greatest(0, least(90, coalesce((v ->> 'descuento_premium')::int, 0))) else 0 end;
  am := greatest(1, least(12, coalesce((v ->> 'anual_meses')::int, 10)));
  return jsonb_build_object('activo', coalesce((v ->> 'activo')::boolean, false), 'premium', pre, 'descuento', d, 'anual_meses', am,
    'descuento_pro', case when pre then 0 else greatest(0, least(90, coalesce((v ->> 'descuento_premium')::int, 0))) end,
    'prueba_dias', coalesce((v ->> 'prueba_dias')::int, 7), 'dueno', dn = auth.uid(),
    'campana', (select jsonb_build_object('meses', (c ->> 'meses')::int, 'hasta', c ->> 'hasta') from (select public.cfx_campana() c) x where c is not null),
    'prueba_pack', exists (select 1 from public.cfx_modulos_pruebas p where p.negocio = n and p.item like 'pack:%') or public.cfx_prueba_usada(dn, 'pack'),  -- G95: por correo
    'modulos', coalesce((select jsonb_agg(jsonb_build_object('clave', k, 'nombre', coalesce(c.nombre, k), 'detalle', coalesce(c.detalle, ''),
        'precio', round(public.cfx_venta_precio(k) * (100 - d) / 100.0)::int, 'lista', public.cfx_venta_precio(k),
        'vende', public.cfx_venta_activa(k), 'activo', public.cfx_modulo_de(k, n) or public.cfx_modulo_plan(k, n), 'plan', public.cfx_modulo_plan(k, n),
        'hasta', m.hasta, 'origen', m.origen, 'regalo', public.cfx_campana_puede(k, n), 'prueba_usada', exists (select 1 from public.cfx_modulos_pruebas p where p.negocio = n and p.item = k) or public.cfx_prueba_usada(dn, k),
        'links', v #> array['links', k]) order by o)
      from unnest(public.cfx_modulos_de_app()) with ordinality u(k, o)
      left join public.cfx_modulos_catalogo() c on c.clave = k
      left join public.cfx_modulos_negocio m on m.negocio = n and m.modulo = k
      where public.cfx_modulo(k)), '[]'),
    'packs', coalesce((select jsonb_agg(jsonb_build_object('clave', p.key, 'nombre', p.value ->> 'nombre', 'detalle', coalesce(p.value ->> 'detalle', ''),
        'destacado', coalesce((p.value ->> 'destacado')::boolean, false), 'modulos', to_jsonb(public.cfx_venta_modulos(p.key)),
        'precio', round(coalesce((p.value ->> 'precio')::int, 0) * (100 - d) / 100.0)::int, 'lista', coalesce((p.value ->> 'precio')::int, 0),
        'suelto', (select coalesce(sum(public.cfx_venta_precio(x)), 0) from unnest(public.cfx_venta_modulos(p.key)) x),
        'links', v #> array['links', p.key]) order by coalesce((p.value ->> 'precio')::int, 0))
      from jsonb_each(coalesce(v -> 'packs', '{}')) p where cardinality(public.cfx_venta_modulos(p.key)) > 0), '[]'));
end $$;

-- Probar gratis: cada módulo una vez, y un solo pack por negocio. Solo el dueño. G95: también una vez por CORREO (cfx_pruebas_usadas, no se borra).
-- prueba_dias = 0 → sin prueba gratis.
create or replace function public.cfx_modulo_probar(p_item text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v jsonb := public.cfx_venta(); n uuid := public.cfx_negocio_cuenta(auth.uid()); pack boolean := (public.cfx_venta() #> array['packs', p_item]) is not null;
        dias int := least(30, coalesce((v ->> 'prueba_dias')::int, 7)); h timestamptz;
begin
  if n is null or public.cfx_negocio_dueno(n) is distinct from auth.uid() then raise exception 'Solo el dueño del negocio'; end if;
  if dias <= 0 then raise exception 'La prueba gratis no está disponible ahora'; end if;
  if not coalesce((v ->> 'activo')::boolean, false) or cardinality(public.cfx_venta_modulos(p_item)) = 0 then raise exception 'Módulo no válido'; end if;
  if pack and exists (select 1 from public.cfx_modulos_pruebas where negocio = n and item like 'pack:%') then raise exception 'Ya usaste la prueba gratis de un pack'; end if;
  if not pack and exists (select 1 from public.cfx_modulos_pruebas where negocio = n and item = p_item) then raise exception 'Ya usaste la prueba gratis de este módulo'; end if;
  if public.cfx_prueba_usada(auth.uid(), case when pack then 'pack' else p_item end) then
    raise exception '%', case when pack then 'Ya usaste la prueba gratis de un pack con este correo' else 'Ya usaste la prueba gratis de este módulo con este correo' end; end if;
  if not pack and public.cfx_modulo_de(p_item, n) then raise exception 'Ya tienes este módulo activo'; end if;
  insert into public.cfx_modulos_pruebas (negocio, item) values (n, case when pack then 'pack:' || p_item else p_item end);
  perform public.cfx_prueba_marcar(auth.uid(), case when pack then 'pack' else p_item end);
  -- La prueba no alarga lo que ya está pagado: solo prende lo que no tiene.
  insert into public.cfx_modulos_negocio as m (negocio, modulo, hasta, origen)
  select n, k, now() + make_interval(days => dias), 'prueba' from unnest(public.cfx_venta_modulos(p_item)) k
  on conflict (negocio, modulo) do update set hasta = greatest(m.hasta, excluded.hasta), origen = case when m.hasta > now() then m.origen else 'prueba' end, avisado = null;
  select max(hasta) into h from public.cfx_modulos_negocio where negocio = n and modulo = any(public.cfx_venta_modulos(p_item));
  perform public.cfx_anotar('módulo', 'prueba ' || p_item || ' · ' || n);
  return jsonb_build_object('ok', true, 'hasta', h);
end $$;

-- G74 b: el dueño toca 🎁 Activar → queda al tiro con el módulo N meses (origen 'regalo'). Una vez por módulo y negocio.
create or replace function public.cfx_modulo_campana(p_modulo text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.cfx_negocio_cuenta(auth.uid()); c jsonb := public.cfx_campana(); h timestamptz;
begin
  if n is null or public.cfx_negocio_dueno(n) is distinct from auth.uid() then raise exception 'Solo el dueño del negocio'; end if;
  if c is null then raise exception 'La campaña ya terminó'; end if;
  if not public.cfx_campana_puede(p_modulo, n) then
    raise exception '%', case when exists (select 1 from public.cfx_modulos_pruebas p where p.negocio = n and p.item = 'campana:' || p_modulo)
      then 'Ya activaste este regalo' else 'Este módulo no está en la campaña' end;
  end if;
  insert into public.cfx_modulos_pruebas (negocio, item) values (n, 'campana:' || p_modulo);
  insert into public.cfx_modulos_negocio as m (negocio, modulo, hasta, origen)
  values (n, p_modulo, now() + make_interval(months => (c ->> 'meses')::int), 'regalo')
  on conflict (negocio, modulo) do update set hasta = greatest(m.hasta, now()) + make_interval(months => (c ->> 'meses')::int), origen = 'regalo', avisado = null
  returning hasta into h;
  perform public.cfx_anotar('módulo', 'campaña ' || p_modulo || ' · ' || n);
  return jsonb_build_object('ok', true, 'hasta', h);
end $$;

-- Aviso 3 días antes de que venza (7 días si es regalo, G74 b; una vez por vencimiento). Lo corre el cron diario.
create or replace function public.cfx_modulos_avisar() returns int
language plpgsql security definer set search_path = '' as $$
declare r record; c int := 0;
begin
  for r in select m.negocio, min(m.hasta) hasta, string_agg(coalesce(k.nombre, m.modulo), ', ' order by m.modulo) nombres
           from public.cfx_modulos_negocio m left join public.cfx_modulos_catalogo() k on k.clave = m.modulo
           where m.avisado is null and m.hasta between now() and now() + case when m.origen = 'regalo' then interval '7 days' else interval '3 days' end
           group by m.negocio limit 500 loop
    perform public.cfx_avisar(r.negocio, '🧩 Tus módulos vencen pronto', left(r.nombres, 120) || ' · vence el ' ||
      to_char(r.hasta at time zone 'America/Santiago', 'DD/MM') || '. Renuévalos en Ajustes → 🧩 Módulos y no pierdes nada.');
    update public.cfx_modulos_negocio set avisado = now() where negocio = r.negocio and avisado is null
      and hasta between now() and now() + case when origen = 'regalo' then interval '7 days' else interval '3 days' end;
    c := c + 1;
  end loop;
  return c;
end $$;

-- Al borrar un negocio (lo llama la app): sus módulos y sus pruebas.
create or replace function public.cfx_modulos_borrar(p_negocio uuid) returns void
language sql security definer set search_path = '' as $$
  delete from public.cfx_modulos_negocio where negocio = p_negocio;
  delete from public.cfx_modulos_pruebas where negocio = p_negocio;
$$;

-- ---------- Centro de Mando ----------
create or replace function public.cfx_venta_admin() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  perform public.cfx_es_admin();
  return jsonb_build_object('config', public.cfx_venta(), 'app', to_jsonb(public.cfx_modulos_de_app()),
    'catalogo', (select coalesce(jsonb_agg(jsonb_build_object('clave', c.clave, 'nombre', c.nombre)), '[]') from public.cfx_modulos_catalogo() c where c.clave = any(public.cfx_modulos_de_app())),
    'activos', (select count(distinct negocio) from public.cfx_modulos_negocio where hasta > now() and origen = 'pago'),
    'pruebas', (select count(distinct negocio) from public.cfx_modulos_negocio where hasta > now() and origen = 'prueba'),
    'campana_on', public.cfx_campana() is not null,
    'campana_usos', (select count(distinct negocio) from public.cfx_modulos_pruebas where item like 'campana:%'),
    'negocios', coalesce((select jsonb_agg(x order by x.hasta) from (
      select m.negocio, coalesce((select u.email from auth.users u where u.id = m.negocio), '') email, min(m.hasta) hasta,
        jsonb_agg(jsonb_build_object('modulo', m.modulo, 'hasta', m.hasta, 'origen', m.origen) order by m.modulo) modulos
      from public.cfx_modulos_negocio m where m.hasta > now() - interval '30 days' group by m.negocio limit 300) x), '[]'));
end $$;

create or replace function public.cfx_venta_guardar(p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v jsonb := public.cfx_venta(); l record; u record;
begin
  perform public.cfx_es_admin();
  if jsonb_typeof(p) <> 'object' then raise exception 'Datos no válidos'; end if;
  v := v || jsonb_strip_nulls(p - 'packs' - 'precios' - 'links' - 'campana')
         || jsonb_build_object('precios', coalesce(p -> 'precios', v -> 'precios', '{}'),   -- llegan completos desde el CM
                               'links', coalesce(p -> 'links', v -> 'links', '{}'),
                               'packs', coalesce(p -> 'packs', v -> 'packs', '{}'));
  if p ? 'campana' then  -- G74 b: null o {} = terminar la campaña ahora
    if coalesce((p #>> '{campana,fin}')::boolean, false) then  -- ⏹️ Terminar hoy: la fecha pasa a ayer (queda el historial)
      if jsonb_typeof(v -> 'campana') = 'object' then
        v := jsonb_set(v, '{campana,hasta}', to_jsonb(to_char((now() at time zone 'America/Santiago')::date - 1, 'YYYY-MM-DD')));
      end if;
    else v := v - 'campana'; end if;
    if jsonb_typeof(p -> 'campana') = 'object' and p -> 'campana' <> '{}'::jsonb and not (p -> 'campana' ? 'fin') then
      if coalesce(p #>> '{campana,meses}', '') !~ '^\d{1,2}$' or (p #>> '{campana,meses}')::int not between 1 and 12 then raise exception 'Meses de regalo: de 1 a 12'; end if;
      if coalesce(p #>> '{campana,hasta}', '') !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Elige la fecha de término'; end if;
      if (p #>> '{campana,hasta}')::date < (now() at time zone 'America/Santiago')::date or (p #>> '{campana,hasta}')::date > (now() at time zone 'America/Santiago')::date + 366 then
        raise exception 'La fecha de término va de hoy a un año más'; end if;
      if jsonb_typeof(p #> '{campana,modulos}') <> 'array' or not exists (select 1 from jsonb_array_elements_text(p #> '{campana,modulos}') x where x = any(public.cfx_modulos_de_app())) then
        raise exception 'Elige al menos un módulo'; end if;
      v := v || jsonb_build_object('campana', jsonb_build_object('meses', (p #>> '{campana,meses}')::int, 'hasta', p #>> '{campana,hasta}',
        'modulos', (select jsonb_agg(distinct x) from jsonb_array_elements_text(p #> '{campana,modulos}') x where x = any(public.cfx_modulos_de_app()))));
    end if;
  end if;
  if coalesce((v ->> 'precio')::numeric, 0) not between 0 and 1000000 or coalesce((v ->> 'descuento_premium')::numeric, 0) not between 0 and 90
     or coalesce((v ->> 'prueba_dias')::numeric, 7) not between 0 and 30 or coalesce((v ->> 'anual_meses')::numeric, 10) not between 1 and 12 then
    raise exception 'Revisa los números: precio de 0 a 1.000.000, descuento de 0 a 90 %%, prueba de 0 a 30 días, anual de 1 a 12 meses';
  end if;
  for l in select key, value from jsonb_each(coalesce(v -> 'precios', '{}')) loop
    if jsonb_typeof(l.value) <> 'number' or l.value::numeric not between 0 and 1000000 then raise exception 'Precio no válido: %', l.key; end if;
  end loop;
  for l in select key, value from jsonb_each(coalesce(v -> 'links', '{}')) loop
    for u in select key, value from jsonb_each_text(case when jsonb_typeof(l.value) = 'object' then l.value else '{}' end) loop
      if coalesce(u.value, '') <> '' and u.value !~ '^https://[^ ]+$' then raise exception 'El link de % debe empezar con https://', l.key; end if;
    end loop;
  end loop;
  update public.cfx_config set valor = v where clave = 'modulos_venta';
  perform public.cfx_anotar('módulos', 'venta ' || case when coalesce((v ->> 'activo')::boolean, false) then 'prendida' else 'apagada' end);
  return public.cfx_venta_admin();
end $$;

-- Regalar o quitar (p_dias = 0) un módulo o pack a un negocio por su correo.
create or replace function public.cfx_modulo_regalar(p_email text, p_item text, p_dias int) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare u uuid; n uuid; h timestamptz;
begin
  perform public.cfx_es_admin();
  select id into u from auth.users where lower(email) = lower(trim(coalesce(p_email, '')));
  if u is null then raise exception 'No hay una cuenta con ese correo en esta app'; end if;
  n := public.cfx_negocio_cuenta(u);
  if n is null then raise exception 'Esa cuenta no es un negocio'; end if;
  if coalesce(p_dias, 0) not between 0 and 3660 then raise exception 'De 0 a 3660 días'; end if;
  h := public.cfx_modulos_dar(n, p_item, p_dias, 'regalo');
  if h is not null then perform public.cfx_avisar(n, '🎁 Te regalamos un módulo', coalesce((select c.nombre from public.cfx_modulos_catalogo() c where c.clave = p_item), public.cfx_venta() #>> array['packs', p_item, 'nombre'], p_item) ||
    ' activo hasta el ' || to_char(h at time zone 'America/Santiago', 'DD/MM/YYYY') || '.'); end if;
  perform public.cfx_anotar('módulo', case when h is null then 'quitó ' else 'regaló ' || p_dias || ' días de ' end || p_item || ' a ' || lower(trim(p_email)));
  return public.cfx_venta_admin();
end $$;

revoke all on function public.cfx_modulos_catalogo(), public.cfx_venta(), public.cfx_venta_on(), public.cfx_venta_precio(text), public.cfx_venta_activa(text), public.cfx_venta_modulos(text),
  public.cfx_negocio_cuenta(uuid), public.cfx_negocio_dueno(uuid), public.cfx_negocio_premium(uuid), public.cfx_modulo_plan(text, uuid), public.cfx_modulo_de(text, uuid), public.cfx_modulo_mio(text),
  public.cfx_modulos_dar(uuid, text, int, text), public.cfx_modulos_avisar(), public.cfx_modulos_borrar(uuid),
  public.cfx_campana(), public.cfx_campana_puede(text, uuid) from public, anon, authenticated;
revoke all on function public.cfx_modulos_de(uuid), public.cfx_modulos_tienda(), public.cfx_modulo_probar(text), public.cfx_modulo_campana(text), public.cfx_venta_admin(),
  public.cfx_venta_guardar(jsonb), public.cfx_modulo_regalar(text, text, int) from public, anon;
grant execute on function public.cfx_modulos_de(uuid) to anon, authenticated;
grant execute on function public.cfx_modulos_tienda(), public.cfx_modulo_probar(text), public.cfx_modulo_campana(text), public.cfx_venta_admin(), public.cfx_venta_guardar(jsonb),
  public.cfx_modulo_regalar(text, text, int) to authenticated;
do $$
begin
  perform cron.unschedule(jobid) from cron.job where jobname = 'cfx-modulos';
  perform cron.schedule('cfx-modulos', '17 13 * * *', 'select public.cfx_modulos_avisar()');
exception when others then
  raise notice 'Aviso de módulos por vencer no programado (%).', sqlerrm;
end $$;
-- ---------- Chat entre personas (C14): las mismas reglas en todas las apps (módulo 'chat') ----------
-- Reglas: hasta N mensajes seguidos sin respuesta (el gancho decide N; null = sin límite, p. ej. el admin), 100 al día,
-- bloquear (ninguno de los dos escribe), reportar (le llega al admin) y borrar la conversación (para los dos).
-- Ganchos que pone cada app que usa el chat (y 'chat' en cfx_modulos_app()):
--   cfx_chat_puede(a, b) boolean         ¿a puede escribirle a b?
--   cfx_chat_seguidos(a, b) int          mensajes seguidos sin respuesta (null = sin límite)
--   cfx_chat_quien(u) jsonb              {"nombre": ..., "rol": ...} para la lista y los reportes
--   cfx_chat_aviso(para, de, texto) void push al que recibe (con el link a la conversación)
--   cfx_chat_suspender(u) void           el admin suspende una cuenta reportada
create table if not exists public.cfx_mensajes (
  id      uuid primary key default gen_random_uuid(),
  de      uuid not null references auth.users (id) on delete cascade,
  para    uuid not null references auth.users (id) on delete cascade,
  texto   text not null check (char_length(texto) between 1 and 1000),
  creado  timestamptz not null default now(),
  leido   timestamptz
);
create index if not exists cfx_mensajes_par_idx on public.cfx_mensajes (least(de, para), greatest(de, para), creado desc);
create index if not exists cfx_mensajes_para_idx on public.cfx_mensajes (para) where leido is null;
create index if not exists cfx_mensajes_de_idx on public.cfx_mensajes (de, creado);
create index if not exists cfx_mensajes_creado_idx on public.cfx_mensajes (creado);
create table if not exists public.cfx_bloqueos (
  quien   uuid not null references auth.users (id) on delete cascade,
  a       uuid not null references auth.users (id) on delete cascade,
  creado  timestamptz not null default now(),
  primary key (quien, a)
);
create table if not exists public.cfx_reportes (
  id        uuid primary key default gen_random_uuid(),
  quien     uuid not null references auth.users (id) on delete cascade,
  a         uuid not null references auth.users (id) on delete cascade,
  mensaje   uuid references public.cfx_mensajes (id) on delete set null,
  motivo    text not null,
  extracto  text not null default '',
  resuelto  boolean not null default false,
  creado    timestamptz not null default now()
);
alter table public.cfx_mensajes enable row level security;
alter table public.cfx_bloqueos enable row level security;
alter table public.cfx_reportes enable row level security;
revoke all on public.cfx_mensajes, public.cfx_bloqueos, public.cfx_reportes from anon, authenticated;

create or replace function public.cfx_msg_listo() returns uuid
language plpgsql stable security definer set search_path = '' as $$
begin
  if auth.uid() is null then raise exception 'Inicia sesión primero'; end if;
  if not public.cfx_modulo('chat') then raise exception 'El chat no está disponible en esta app'; end if;
  return auth.uid();
end $$;

create or replace function public.cfx_msg_bloqueado(p_uno uuid, p_otro uuid) returns boolean
language plpgsql stable security definer set search_path = '' as $$
begin
  return exists (select 1 from public.cfx_bloqueos x where (x.quien = p_uno and x.a = p_otro) or (x.quien = p_otro and x.a = p_uno));
end $$;

-- Cuántos me quedan seguidos con "otro": {"restantes": n, "limite": n} (null = sin límite).
create or replace function public.cfx_msg_restantes(p_otro uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare u uuid := public.cfx_msg_listo(); lim int := public.cfx_chat_seguidos(u, p_otro); n int;
begin
  if lim is null then return jsonb_build_object('restantes', null, 'limite', null); end if;
  select count(*) into n from public.cfx_mensajes m where m.de = u and m.para = p_otro
    and m.creado > coalesce((select max(x.creado) from public.cfx_mensajes x where x.de = p_otro and x.para = u), '-infinity');
  return jsonb_build_object('restantes', greatest(0, lim - n), 'limite', lim);
end $$;

-- Enviar: {"ok": true, "id", "restantes"} o {"ok": false, "error"}.
create or replace function public.cfx_msg_enviar(p_para uuid, p_texto text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare u uuid := public.cfx_msg_listo(); t text := trim(coalesce(p_texto, '')); lim int; r jsonb; i uuid;
begin
  if t = '' then return jsonb_build_object('ok', false, 'error', 'Escribe un mensaje'); end if;
  if char_length(t) > 1000 then return jsonb_build_object('ok', false, 'error', 'Máximo 1000 caracteres por mensaje'); end if;
  if p_para is null or not coalesce(public.cfx_chat_puede(u, p_para), false) then
    return jsonb_build_object('ok', false, 'error', 'No puedes escribirle a esta cuenta');
  end if;
  lim := public.cfx_chat_seguidos(u, p_para);
  -- G19: con el chat a la venta, el negocio de la conversación debe tenerlo (con soporte siempre se puede).
  if lim is not null and public.cfx_chat_seguidos(p_para, u) is not null and public.cfx_venta_activa('chat') then
    if public.cfx_negocio_cuenta(u) is not null and not public.cfx_modulo_de('chat', public.cfx_negocio_cuenta(u)) then
      return jsonb_build_object('ok', false, 'error', 'El chat es un módulo. Actívalo en Ajustes → 🧩 Módulos');
    end if;
    if public.cfx_negocio_cuenta(p_para) is not null and not public.cfx_modulo_de('chat', public.cfx_negocio_cuenta(p_para)) then
      return jsonb_build_object('ok', false, 'error', 'Esta tienda no tiene chat. Escríbele por WhatsApp');
    end if;
  end if;
  if lim is not null then
    if public.cfx_msg_bloqueado(u, p_para) then return jsonb_build_object('ok', false, 'error', 'La conversación está bloqueada'); end if;
    if (public.cfx_msg_restantes(p_para) ->> 'restantes')::int <= 0 then
      return jsonb_build_object('ok', false, 'error', case when lim = 1
        then 'Envías 1 mensaje a la vez. Espera la respuesta para escribir de nuevo.'
        else 'Ya enviaste ' || lim || ' mensajes seguidos. Espera la respuesta para escribir de nuevo.' end);
    end if;
    if (select count(*) from public.cfx_mensajes where de = u and creado > now() - interval '1 day') >= 100 then
      return jsonb_build_object('ok', false, 'error', 'Llegaste al máximo de 100 mensajes por día');
    end if;
  end if;
  insert into public.cfx_mensajes (de, para, texto) values (u, p_para, t) returning id into i;
  perform public.cfx_chat_aviso(p_para, u, t);
  r := public.cfx_msg_restantes(p_para);
  return jsonb_build_object('ok', true, 'id', i, 'restantes', r -> 'restantes');
end $$;

-- Mis conversaciones: [{otro, nombre, rol, ultimo, ultimo_at, mio, no_leidos, bloqueado}] (las 100 más recientes).
create or replace function public.cfx_msg_lista() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare u uuid := public.cfx_msg_listo();
begin
  return coalesce((with z as (select case when m.de = u then m.para else m.de end as otro, m.texto, m.creado, m.de = u as mio
                               from public.cfx_mensajes m where m.de = u or m.para = u),
                          l as (select distinct on (otro) * from z order by otro, creado desc),
                          t as (select * from l order by creado desc limit 100)
    select jsonb_agg(jsonb_build_object('otro', t.otro, 'nombre', coalesce(q.v ->> 'nombre', 'Cuenta'), 'rol', coalesce(q.v ->> 'rol', ''),
      'ultimo', t.texto, 'ultimo_at', t.creado, 'mio', t.mio,
      'no_leidos', (select count(*) from public.cfx_mensajes x where x.de = t.otro and x.para = u and x.leido is null),
      'bloqueado', exists (select 1 from public.cfx_bloqueos b where b.quien = u and b.a = t.otro)) order by t.creado desc)
    from t cross join lateral (select public.cfx_chat_quien(t.otro) as v) q), '[]');
end $$;

create or replace function public.cfx_msg_sin_leer() returns int
language plpgsql stable security definer set search_path = '' as $$
begin
  if auth.uid() is null or not public.cfx_modulo('chat') then return 0; end if;
  return (select count(*)::int from public.cfx_mensajes where para = auth.uid() and leido is null);
end $$;

-- Una conversación (las últimas 200; marca como leídos los recibidos): [{id, mio, texto, creado, leido}].
create or replace function public.cfx_msg_hilo(p_otro uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare u uuid := public.cfx_msg_listo();
begin
  update public.cfx_mensajes set leido = now() where de = p_otro and para = u and leido is null;
  return coalesce((select jsonb_agg(jsonb_build_object('id', m.id, 'mio', m.de = u, 'texto', m.texto, 'creado', m.creado, 'leido', m.leido) order by m.creado)
    from (select * from public.cfx_mensajes x where (x.de = u and x.para = p_otro) or (x.de = p_otro and x.para = u)
          order by x.creado desc limit 200) m), '[]');
end $$;

create or replace function public.cfx_msg_bloquear(p_otro uuid, p_bloquear boolean) returns void
language plpgsql security definer set search_path = '' as $$
declare u uuid := public.cfx_msg_listo();
begin
  if p_otro is null or p_otro = u then raise exception 'Cuenta no válida'; end if;
  if p_bloquear then insert into public.cfx_bloqueos (quien, a) values (u, p_otro) on conflict do nothing;
  else delete from public.cfx_bloqueos where quien = u and a = p_otro; end if;
end $$;

create or replace function public.cfx_msg_reportar(p_mensaje uuid, p_motivo text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare u uuid := public.cfx_msg_listo(); m public.cfx_mensajes;
begin
  select * into m from public.cfx_mensajes where id = p_mensaje and para = u;
  if m.id is null then return jsonb_build_object('ok', false, 'error', 'Mensaje no encontrado'); end if;
  if (select count(*) from public.cfx_reportes where quien = u and creado > now() - interval '1 day') >= 10 then
    return jsonb_build_object('ok', false, 'error', 'Máximo 10 reportes por día');
  end if;
  insert into public.cfx_reportes (quien, a, mensaje, motivo, extracto)
  values (u, m.de, m.id, left(coalesce(nullif(trim(p_motivo), ''), 'Sin motivo'), 300), left(m.texto, 300));
  perform public.cfx_avisar_admin('🚩 Nuevo reporte en el chat', left(m.texto, 100));
  return jsonb_build_object('ok', true);
end $$;

-- Borra la conversación completa (para los dos).
create or replace function public.cfx_msg_borrar(p_otro uuid) returns int
language plpgsql security definer set search_path = '' as $$
declare u uuid := public.cfx_msg_listo(); n int;
begin
  delete from public.cfx_mensajes where (de = u and para = p_otro) or (de = p_otro and para = u);
  get diagnostics n = row_count;
  return n;
end $$;

-- Administrador: reportes sin resolver y resolverlos (descartar o suspender a la cuenta reportada).
create or replace function public.cfx_msg_reportes() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  perform public.cfx_es_admin();
  return coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'motivo', r.motivo, 'extracto', r.extracto, 'creado', r.creado,
      'quien', coalesce(public.cfx_chat_quien(r.quien) ->> 'nombre', ''), 'a', coalesce(public.cfx_chat_quien(r.a) ->> 'nombre', ''),
      'quien_email', (select email from auth.users where id = r.quien), 'a_email', (select email from auth.users where id = r.a)) order by r.creado desc)
    from public.cfx_reportes r where not r.resuelto), '[]');
end $$;

create or replace function public.cfx_msg_resolver(p_id uuid, p_suspender boolean) returns void
language plpgsql security definer set search_path = '' as $$
declare r public.cfx_reportes;
begin
  perform public.cfx_es_admin();
  update public.cfx_reportes set resuelto = true where id = p_id and not resuelto returning * into r;
  if r.id is null then raise exception 'El reporte ya fue atendido'; end if;
  if p_suspender then perform public.cfx_chat_suspender(r.a); end if;
  perform public.cfx_anotar('reporte chat', case when p_suspender then 'suspendida ' else 'descartado ' end || coalesce((select email from auth.users where id = r.a), ''));
end $$;

revoke all on function public.cfx_msg_listo(), public.cfx_msg_bloqueado(uuid, uuid) from public, anon, authenticated;
revoke all on function public.cfx_msg_restantes(uuid), public.cfx_msg_enviar(uuid, text), public.cfx_msg_lista(), public.cfx_msg_sin_leer(),
  public.cfx_msg_hilo(uuid), public.cfx_msg_bloquear(uuid, boolean), public.cfx_msg_reportar(uuid, text), public.cfx_msg_borrar(uuid),
  public.cfx_msg_reportes(), public.cfx_msg_resolver(uuid, boolean) from public, anon;
grant execute on function public.cfx_msg_restantes(uuid), public.cfx_msg_enviar(uuid, text), public.cfx_msg_lista(), public.cfx_msg_sin_leer(),
  public.cfx_msg_hilo(uuid), public.cfx_msg_bloquear(uuid, boolean), public.cfx_msg_reportar(uuid, text), public.cfx_msg_borrar(uuid),
  public.cfx_msg_reportes(), public.cfx_msg_resolver(uuid, boolean) to authenticated;

-- ---------- G128 💬 Chat DEL PEDIDO (hilo ligado a una referencia, no aparece en Mensajes) ----------
-- Solo para clientes CON cuenta y su tienda. Sin cuenta: el enlace /r/ + WhatsApp. Es parte del pedido (no es el módulo 'chat').
-- A los 7 días de cerrado el pedido se borran sus mensajes (cron diario 'cfx-hilos'); el pedido queda como registro.
-- Ganchos que pone cada app que lo usa (sin ganchos todo responde "no disponible"):
--   cfx_hilo_app(ref, u) jsonb   {"ok": bool, "tienda": bool, "cerrado": timestamptz|null, "existe": bool}
--                                 ¿u participa en el hilo ref? (u null = la limpieza pregunta si existe y cuándo cerró)
--   cfx_hilo_aviso_app(ref, de, texto) void  push al otro lado (con el link al pedido)
create table if not exists public.cfx_hilos (
  id      uuid primary key default gen_random_uuid(),
  ref     text not null check (char_length(ref) between 3 and 80),
  de      uuid not null references auth.users (id) on delete cascade,
  tienda  boolean not null default false,
  texto   text not null check (char_length(texto) between 1 and 1000),
  creado  timestamptz not null default now(),
  leido   timestamptz
);
create index if not exists cfx_hilos_ref_idx on public.cfx_hilos (ref, creado);
create index if not exists cfx_hilos_de_idx on public.cfx_hilos (de, creado);
alter table public.cfx_hilos enable row level security;
revoke all on public.cfx_hilos from anon, authenticated;

create or replace function public.cfx_hilo_quien(p_ref text, u uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare r jsonb;
begin
  if to_regprocedure('public.cfx_hilo_app(text,uuid)') is null or coalesce(p_ref, '') = '' then return jsonb_build_object('ok', false, 'existe', false); end if;
  execute 'select public.cfx_hilo_app($1, $2)' into r using left(p_ref, 80), u;
  return coalesce(r, jsonb_build_object('ok', false, 'existe', false));
end $$;

-- Ver el hilo (marca como leídos los del otro lado): {"ok", "abierto", "mensajes": [{id, mio, tienda, texto, creado, leido}]}.
create or replace function public.cfx_hilo_ver(p_ref text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare q jsonb := public.cfx_hilo_quien(p_ref, auth.uid()); t boolean;
begin
  if auth.uid() is null or not coalesce((q ->> 'ok')::boolean, false) then return jsonb_build_object('ok', false, 'error', 'Chat no disponible para este pedido'); end if;
  t := coalesce((q ->> 'tienda')::boolean, false);
  update public.cfx_hilos set leido = now() where ref = p_ref and tienda <> t and leido is null;
  return jsonb_build_object('ok', true, 'abierto', q ->> 'cerrado' is null, 'cerrado', q -> 'cerrado',
    'mensajes', coalesce((select jsonb_agg(jsonb_build_object('id', m.id, 'mio', m.de = auth.uid(), 'tienda', m.tienda, 'texto', m.texto,
      'creado', m.creado, 'leido', m.leido) order by m.creado)
      from (select * from public.cfx_hilos where ref = p_ref order by creado desc limit 200) m), '[]'));
end $$;

-- Escribir: hasta 1000 caracteres, 60 al día por persona y 200 por pedido. Se puede hasta que se borra (7 días después de cerrar).
create or replace function public.cfx_hilo_enviar(p_ref text, p_texto text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare q jsonb := public.cfx_hilo_quien(p_ref, auth.uid()); t text := trim(coalesce(p_texto, '')); i uuid;
begin
  if auth.uid() is null or not coalesce((q ->> 'ok')::boolean, false) then return jsonb_build_object('ok', false, 'error', 'Chat no disponible para este pedido'); end if;
  if t = '' then return jsonb_build_object('ok', false, 'error', 'Escribe un mensaje'); end if;
  if char_length(t) > 1000 then return jsonb_build_object('ok', false, 'error', 'Máximo 1000 caracteres por mensaje'); end if;
  if (q ->> 'cerrado') is not null and (q ->> 'cerrado')::timestamptz < now() - interval '7 days' then
    return jsonb_build_object('ok', false, 'error', 'Este pedido cerró hace más de 7 días');
  end if;
  if (select count(*) from public.cfx_hilos where de = auth.uid() and creado > now() - interval '1 day') >= 60 then
    return jsonb_build_object('ok', false, 'error', 'Llegaste al máximo de 60 mensajes por día');
  end if;
  if (select count(*) from public.cfx_hilos where ref = p_ref) >= 200 then
    return jsonb_build_object('ok', false, 'error', 'Este pedido llegó a 200 mensajes: sigue por WhatsApp');
  end if;
  insert into public.cfx_hilos (ref, de, tienda, texto) values (p_ref, auth.uid(), coalesce((q ->> 'tienda')::boolean, false), t) returning id into i;
  if to_regprocedure('public.cfx_hilo_aviso_app(text,uuid,text)') is not null then
    begin execute 'select public.cfx_hilo_aviso_app($1, $2, $3)' using p_ref, auth.uid(), t; exception when others then null; end;
  end if;
  return jsonb_build_object('ok', true, 'id', i);
end $$;

-- Sin leer por hilo, para las listas: [{ref, n}] (solo los refs donde participo; máx. 300).
create or replace function public.cfx_hilos_sin_leer(p_refs text[]) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if auth.uid() is null then return '[]'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('ref', z.ref, 'n', z.n)) from (
    select r.ref, (select count(*)::int from public.cfx_hilos h where h.ref = r.ref and h.leido is null and h.tienda <> (w.q ->> 'tienda')::boolean) n
    from (select distinct x as ref from unnest((coalesce(p_refs, '{}'::text[]))[1:300]) x
          where exists (select 1 from public.cfx_hilos h where h.ref = x and h.leido is null)) r
    cross join lateral (select public.cfx_hilo_quien(r.ref, auth.uid()) q) w
    where coalesce((w.q ->> 'ok')::boolean, false)) z where z.n > 0), '[]');
end $$;

-- Cada noche: borra los mensajes de pedidos cerrados hace más de 7 días (o que ya no existen).
create or replace function public.cfx_hilos_limpiar() returns int
language plpgsql security definer set search_path = '' as $$
declare r text; q jsonb; n int := 0; k int;
begin
  for r in select distinct ref from public.cfx_hilos loop
    q := public.cfx_hilo_quien(r, null);
    if not coalesce((q ->> 'existe')::boolean, false) or ((q ->> 'cerrado') is not null and (q ->> 'cerrado')::timestamptz < now() - interval '7 days') then
      delete from public.cfx_hilos where ref = r;
      get diagnostics k = row_count; n := n + k;
    end if;
  end loop;
  return n;
end $$;
revoke all on function public.cfx_hilo_quien(text, uuid), public.cfx_hilos_limpiar() from public, anon, authenticated;
revoke all on function public.cfx_hilo_ver(text), public.cfx_hilo_enviar(text, text), public.cfx_hilos_sin_leer(text[]) from public, anon;
grant execute on function public.cfx_hilo_ver(text), public.cfx_hilo_enviar(text, text), public.cfx_hilos_sin_leer(text[]) to authenticated;
do $$
begin
  perform cron.unschedule(jobid) from cron.job where jobname = 'cfx-hilos';
  perform cron.schedule('cfx-hilos', '52 7 * * *', 'select public.cfx_hilos_limpiar()');
exception when others then
  raise notice 'Limpieza del chat de pedidos no programada (%).', sqlerrm;
end $$;
-- ---------- Calificaciones en dos direcciones (C15): el cliente califica al negocio y el negocio al cliente (módulo 'calificaciones') ----------
-- Una calificación por "ref" (pedido, reserva, arriendo…) y por lado. Estrellas 1-5 y comentario opcional (300).
-- Gancho que pone cada app que las usa (y 'calificaciones' en cfx_modulos_app()):
--   cfx_calif_ref(ref, u) jsonb   quién califica esa ref: {"ref": text, "negocio": uuid, "cliente": uuid|null, "cliente_ref": text|null, "de_negocio": bool}
--                                 ("ref" = la referencia de verdad, p. ej. el id del pedido cuando llega su token)
--                                 o {"error": "..."} (no existe, aún no se puede, no es tuyo). u puede ser null (invitado con token).
-- Para mostrar: cfx_calif_negocio(n) y cfx_calif_cliente(c, ref) → {"promedio", "total"}; cfx_calif_hecha(ref, de_negocio).
-- Si el módulo está apagado no se califica, los promedios vuelven null y cfx_calif_hecha dice true (no aparece "Califica").
create table if not exists public.cfx_calificaciones (
  ref          text not null,
  de_negocio   boolean not null,
  negocio_id   uuid not null,
  cliente_id   uuid references auth.users (id) on delete set null,
  cliente_ref  text,
  estrellas    int not null check (estrellas between 1 and 5),
  comentario   text not null default '' check (char_length(comentario) <= 300),
  creado       timestamptz not null default now(),
  primary key (ref, de_negocio)
);
create index if not exists cfx_calif_negocio_idx on public.cfx_calificaciones (negocio_id) where not de_negocio;
create index if not exists cfx_calif_cliente_idx on public.cfx_calificaciones (cliente_id) where de_negocio;
create index if not exists cfx_calif_cref_idx on public.cfx_calificaciones (cliente_ref) where de_negocio and cliente_ref is not null;
alter table public.cfx_calificaciones enable row level security;
revoke all on public.cfx_calificaciones from anon, authenticated;

-- Calificar: {"ok": true} o {"ok": false, "error"}.
create or replace function public.cfx_calificar(p_ref text, p_estrellas int, p_comentario text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare r jsonb;
begin
  if not public.cfx_modulo('calificaciones') then return jsonb_build_object('ok', false, 'error', 'Las calificaciones no están disponibles'); end if;
  if p_estrellas is null or p_estrellas < 1 or p_estrellas > 5 then return jsonb_build_object('ok', false, 'error', 'Elige de 1 a 5 estrellas'); end if;
  if coalesce(trim(p_ref), '') = '' then return jsonb_build_object('ok', false, 'error', 'No encontrado'); end if;
  r := public.cfx_calif_ref(p_ref, auth.uid());
  if r is null or r ? 'error' or r ->> 'negocio' is null then return jsonb_build_object('ok', false, 'error', coalesce(r ->> 'error', 'No encontrado')); end if;
  if not public.cfx_modulo_de('calificaciones', (r ->> 'negocio')::uuid) then return jsonb_build_object('ok', false, 'error', 'Las calificaciones no están disponibles'); end if;
  insert into public.cfx_calificaciones (ref, de_negocio, negocio_id, cliente_id, cliente_ref, estrellas, comentario)
  values (coalesce(r ->> 'ref', p_ref), coalesce((r ->> 'de_negocio')::boolean, false), (r ->> 'negocio')::uuid, (r ->> 'cliente')::uuid,
          nullif(left(r ->> 'cliente_ref', 60), ''), p_estrellas, left(trim(coalesce(p_comentario, '')), 300))
  on conflict (ref, de_negocio) do nothing;
  if not found then return jsonb_build_object('ok', false, 'error', 'Ya fue calificado'); end if;
  return jsonb_build_object('ok', true);
end $$;

-- ¿Ya calificó ese lado? (con el módulo apagado: true, para no pedirlo)
create or replace function public.cfx_calif_hecha(p_ref text, p_de_negocio boolean) returns boolean
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.cfx_modulo('calificaciones') then return true; end if;
  if public.cfx_venta_activa('calificaciones') and not coalesce(public.cfx_modulo_de('calificaciones', (public.cfx_calif_ref(p_ref, auth.uid()) ->> 'negocio')::uuid), false) then return true; end if;
  return exists (select 1 from public.cfx_calificaciones where ref = p_ref and de_negocio = p_de_negocio);
end $$;

-- Lo que los clientes dicen del negocio.
create or replace function public.cfx_calif_negocio(p_negocio uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.cfx_modulo_de('calificaciones', p_negocio) then return null; end if;
  return (select jsonb_build_object('promedio', round(avg(estrellas), 1), 'total', count(*))
          from public.cfx_calificaciones where negocio_id = p_negocio and not de_negocio);
end $$;

-- Lo que los negocios dicen del cliente (por su cuenta o, si es invitado, por su referencia: teléfono…).
create or replace function public.cfx_calif_cliente(p_cliente uuid, p_cliente_ref text default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.cfx_modulo_mio('calificaciones') or (p_cliente is null and coalesce(p_cliente_ref, '') = '') then return null; end if;
  return (select jsonb_build_object('promedio', round(avg(estrellas), 1), 'total', count(*))
          from public.cfx_calificaciones where de_negocio
            and ((p_cliente is not null and cliente_id = p_cliente) or (p_cliente is null and cliente_ref = p_cliente_ref)));
end $$;

-- Al borrar un negocio o una ref (lo llama la app).
create or replace function public.cfx_calif_borrar(p_negocio uuid, p_ref text default null) returns void
language plpgsql security definer set search_path = '' as $$
begin
  delete from public.cfx_calificaciones where negocio_id = p_negocio and (p_ref is null or ref = p_ref);
end $$;

revoke all on function public.cfx_calif_hecha(text, boolean), public.cfx_calif_negocio(uuid), public.cfx_calif_cliente(uuid, text),
  public.cfx_calif_borrar(uuid, text) from public, anon, authenticated;
revoke all on function public.cfx_calificar(text, int, text) from public;
grant execute on function public.cfx_calificar(text, int, text) to anon, authenticated;
-- ---------- Cupones del negocio y tarjeta de sellos (C16): módulos 'cupones' y 'sellos' ----------
-- OJO: no son los cupones del Premium (cfx_cupones / cfx_cupon_ver, los crea el admin). Estos los crea cada negocio para SUS clientes.
-- Ganchos que pone cada app que los usa (y 'cupones' / 'sellos' en cfx_modulos_app()):
--   cfx_fid_dueno(u) uuid                  negocio que administra la cuenta u (null = no es negocio)
--   cfx_fid_activo(negocio, modulo) bool   ¿el plan del negocio incluye ese módulo? (p. ej. solo Pro)
--   cfx_fid_cliente(u, negocio) bool       ¿u es cliente de ese negocio? (ve sus sellos y prueba cupones)
--   cfx_sellos_aviso(negocio, cliente, premio) void   push al cliente que completó la tarjeta
-- La app usa, dentro de sus funciones: cfx_desc_pct + cfx_desc_usar (al crear el pedido), cfx_sello_sumar (al entregar)
-- y cfx_sellos_cfg_de (para mostrar la tarjeta). cfx_fid_borrar al borrar un negocio.
create table if not exists public.cfx_descuentos (
  id          uuid primary key default gen_random_uuid(),
  owner_id    uuid not null,
  codigo      text not null check (codigo ~ '^[A-Z0-9]{3,20}$'),
  porcentaje  int not null check (porcentaje between 1 and 90),
  hasta       date,
  activo      boolean not null default true,
  usos        int not null default 0,
  creado      timestamptz not null default now(),
  unique (owner_id, codigo)
);
create table if not exists public.cfx_sellos_cfg (
  owner_id  uuid primary key,
  meta      int not null check (meta between 2 and 30),
  premio    text check (char_length(premio) <= 80),
  creado    timestamptz not null default now()
);
create table if not exists public.cfx_sellos (
  negocio_id  uuid not null,
  cliente_id  uuid not null references auth.users (id) on delete cascade,
  cantidad    int not null default 0,
  premios     int not null default 0,
  actualizado timestamptz not null default now(),
  primary key (negocio_id, cliente_id)
);
create index if not exists cfx_sellos_cliente_idx on public.cfx_sellos (cliente_id);
alter table public.cfx_descuentos enable row level security;
alter table public.cfx_sellos_cfg enable row level security;
alter table public.cfx_sellos enable row level security;
revoke all on public.cfx_descuentos, public.cfx_sellos_cfg, public.cfx_sellos from anon, authenticated;

create or replace function public.cfx_desc_codigo(p_codigo text) returns text
language sql immutable set search_path = '' as $$ select upper(regexp_replace(coalesce(p_codigo, ''), '[^A-Za-z0-9]', '', 'g')) $$;

-- El negocio de la cuenta, si el módulo está prendido y su plan lo incluye.
create or replace function public.cfx_fid_mio(p_modulo text) returns uuid
language plpgsql stable security definer set search_path = '' as $$
declare n uuid;
begin
  if not public.cfx_modulo(p_modulo) then
    raise exception '% no está disponible en esta app', case p_modulo when 'cupones' then 'Los cupones' else 'La tarjeta de sellos' end;
  end if;
  n := public.cfx_fid_dueno(auth.uid());
  if n is null then raise exception 'Solo el negocio'; end if;
  if public.cfx_venta_on() then
    if not public.cfx_modulo_de(p_modulo, n) then
      raise exception '% Actívalo en Ajustes → 🧩 Módulos', case p_modulo when 'cupones' then 'Los cupones son un módulo.' else 'La tarjeta de sellos es un módulo.' end;
    end if;
  elsif not coalesce(public.cfx_fid_activo(n, p_modulo), false) then
    raise exception '% de la versión Pro', case p_modulo when 'cupones' then 'Los cupones son' else 'La tarjeta de sellos es' end;
  end if;
  return n;
end $$;

-- ¿El negocio puede usar el módulo ahora? (prendido + su plan)
create or replace function public.cfx_fid_ok(p_negocio uuid, p_modulo text) returns boolean
language plpgsql stable security definer set search_path = '' as $$
begin
  if p_negocio is null or not public.cfx_modulo(p_modulo) then return false; end if;
  if public.cfx_venta_on() then return public.cfx_modulo_de(p_modulo, p_negocio); end if;
  return coalesce(public.cfx_fid_activo(p_negocio, p_modulo), false);
end $$;

-- ---------- Cupones ----------
create or replace function public.cfx_desc_guardar(p_codigo text, p_porcentaje int, p_hasta date) returns void
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.cfx_fid_mio('cupones'); c text := public.cfx_desc_codigo(p_codigo);
begin
  if length(c) < 3 or length(c) > 20 then raise exception 'El código debe tener entre 3 y 20 letras o números'; end if;
  if p_porcentaje is null or p_porcentaje < 1 or p_porcentaje > 90 then raise exception 'El descuento debe ser entre 1 y 90 por ciento'; end if;
  if (select count(*) from public.cfx_descuentos where owner_id = n) >= 50
     and not exists (select 1 from public.cfx_descuentos where owner_id = n and codigo = c) then raise exception 'Máximo 50 cupones'; end if;
  insert into public.cfx_descuentos (owner_id, codigo, porcentaje, hasta) values (n, c, p_porcentaje, p_hasta)
  on conflict (owner_id, codigo) do update set porcentaje = excluded.porcentaje, hasta = excluded.hasta, activo = true;
end $$;

create or replace function public.cfx_desc_borrar(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  delete from public.cfx_descuentos where id = p_id and owner_id = public.cfx_fid_dueno(auth.uid());
end $$;

-- Mis cupones: [{id, codigo, porcentaje, hasta, activo, usos}]
create or replace function public.cfx_desc_lista() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare n uuid := public.cfx_fid_mio('cupones');
begin
  return coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'codigo', c.codigo, 'porcentaje', c.porcentaje, 'hasta', c.hasta,
    'activo', c.activo, 'usos', c.usos) order by c.creado desc) from public.cfx_descuentos c where c.owner_id = n), '[]');
end $$;

-- Porcentaje de un cupón vigente (null = no sirve). Interna: la app la usa al armar el pedido.
create or replace function public.cfx_desc_pct(p_negocio uuid, p_codigo text) returns int
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.cfx_fid_ok(p_negocio, 'cupones') then return null; end if;
  return (select c.porcentaje from public.cfx_descuentos c
          where c.owner_id = p_negocio and c.codigo = public.cfx_desc_codigo(p_codigo) and c.activo and (c.hasta is null or c.hasta >= current_date));
end $$;

-- Suma un uso (la app la llama cuando el pedido ya quedó guardado).
create or replace function public.cfx_desc_usar(p_negocio uuid, p_codigo text) returns void
language plpgsql security definer set search_path = '' as $$
begin
  update public.cfx_descuentos set usos = usos + 1 where owner_id = p_negocio and codigo = public.cfx_desc_codigo(p_codigo);
end $$;

-- El cliente prueba un cupón: devuelve el porcentaje o avisa que no sirve.
create or replace function public.cfx_desc_validar(p_negocio uuid, p_codigo text) returns int
language plpgsql stable security definer set search_path = '' as $$
declare pct int;
begin
  if not public.cfx_modulo('cupones') then raise exception 'Cupón no válido o vencido'; end if;
  if not coalesce(public.cfx_fid_cliente(auth.uid(), p_negocio), false) then raise exception 'Sin permiso'; end if;
  pct := public.cfx_desc_pct(p_negocio, p_codigo);
  if pct is null then raise exception 'Cupón no válido o vencido'; end if;
  return pct;
end $$;

-- ---------- Tarjeta de sellos ----------
-- El negocio la arma (meta 2-30 y premio) o la apaga (meta null).
create or replace function public.cfx_sellos_guardar(p_meta int, p_premio text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare n uuid;
begin
  if p_meta is null then
    n := public.cfx_fid_dueno(auth.uid());
    if n is null then raise exception 'Solo el negocio'; end if;
    delete from public.cfx_sellos_cfg where owner_id = n;
    return null;
  end if;
  n := public.cfx_fid_mio('sellos');
  if p_meta < 2 or p_meta > 30 then raise exception 'La tarjeta debe tener entre 2 y 30 sellos'; end if;
  insert into public.cfx_sellos_cfg (owner_id, meta, premio) values (n, p_meta, nullif(left(trim(coalesce(p_premio, '')), 80), ''))
  on conflict (owner_id) do update set meta = excluded.meta, premio = excluded.premio;
  return public.cfx_sellos_cfg_de(n);
end $$;

-- La tarjeta del negocio {meta, premio} (null = no tiene, módulo apagado o su plan no la incluye).
create or replace function public.cfx_sellos_cfg_de(p_negocio uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.cfx_fid_ok(p_negocio, 'sellos') then return null; end if;
  return (select jsonb_build_object('meta', c.meta, 'premio', c.premio) from public.cfx_sellos_cfg c where c.owner_id = p_negocio);
end $$;

-- Mis sellos en un negocio: {cantidad, premios, meta, premio} o null.
create or replace function public.cfx_sellos_mios(p_negocio uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare c jsonb := public.cfx_sellos_cfg_de(p_negocio);
begin
  if c is null then return null; end if;
  if not coalesce(public.cfx_fid_cliente(auth.uid(), p_negocio), false) then return null; end if;
  return c || coalesce((select jsonb_build_object('cantidad', s.cantidad, 'premios', s.premios) from public.cfx_sellos s
                        where s.negocio_id = p_negocio and s.cliente_id = auth.uid()), jsonb_build_object('cantidad', 0, 'premios', 0));
end $$;

-- Suma un sello (al entregar una compra). Al llegar a la meta: vuelve a 0, suma un premio y avisa. Devuelve {cantidad, premio} o null.
create or replace function public.cfx_sello_sumar(p_negocio uuid, p_cliente uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare c jsonb := public.cfx_sellos_cfg_de(p_negocio); s public.cfx_sellos;
begin
  if c is null or p_cliente is null then return null; end if;
  insert into public.cfx_sellos (negocio_id, cliente_id, cantidad) values (p_negocio, p_cliente, 1)
  on conflict (negocio_id, cliente_id) do update set cantidad = public.cfx_sellos.cantidad + 1, actualizado = now() returning * into s;
  if s.cantidad >= (c ->> 'meta')::int then
    update public.cfx_sellos set cantidad = 0, premios = premios + 1 where negocio_id = p_negocio and cliente_id = p_cliente;
    perform public.cfx_sellos_aviso(p_negocio, p_cliente, c ->> 'premio');
    return jsonb_build_object('cantidad', 0, 'premio', true);
  end if;
  return jsonb_build_object('cantidad', s.cantidad, 'premio', false);
end $$;

-- Al borrar un negocio (lo llama la app): sus cupones, su tarjeta y los sellos de sus clientes.
create or replace function public.cfx_fid_borrar(p_negocio uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  delete from public.cfx_descuentos where owner_id = p_negocio;
  delete from public.cfx_sellos_cfg where owner_id = p_negocio;
  delete from public.cfx_sellos where negocio_id = p_negocio;
end $$;

revoke all on function public.cfx_desc_codigo(text), public.cfx_fid_mio(text), public.cfx_fid_ok(uuid, text), public.cfx_desc_pct(uuid, text),
  public.cfx_desc_usar(uuid, text), public.cfx_sellos_cfg_de(uuid), public.cfx_sello_sumar(uuid, uuid), public.cfx_fid_borrar(uuid)
  from public, anon, authenticated;
revoke all on function public.cfx_desc_guardar(text, int, date), public.cfx_desc_borrar(uuid), public.cfx_desc_lista(), public.cfx_desc_validar(uuid, text),
  public.cfx_sellos_guardar(int, text), public.cfx_sellos_mios(uuid) from public, anon;
grant execute on function public.cfx_desc_guardar(text, int, date), public.cfx_desc_borrar(uuid), public.cfx_desc_lista(), public.cfx_desc_validar(uuid, text),
  public.cfx_sellos_guardar(int, text), public.cfx_sellos_mios(uuid) to authenticated;
-- ---------- 🛒 Carrito y 🚚 despacho (C17) ----------
-- Carrito guardado en la nube (para recordarle al cliente lo que dejó) y el cálculo del despacho por comuna y al resto de Chile (2.58).
-- Ganchos que pone cada app que lo usa (y 'carrito' en cfx_modulos_app() para el recordatorio):
--   cfx_carrito_puede(u, negocio) bool           ¿u puede guardar carrito en ese negocio? (es su cliente, puede comprar)
--   cfx_carrito_aviso(cliente, negocio, n) bool  manda el recordatorio (push); false = no corresponde (plan, vacaciones…)
-- La app usa: cfx_carrito_vaciar (al crear el pedido), cfx_carritos_recordar (pg_cron, cada hora), cfx_carrito_borrar (al borrar una cuenta).
-- Despacho (sin tabla: cada app guarda su { retiro, gratis_desde, zonas: [{comuna, precio}] } donde quiera):
--   cfx_despacho_limpio(p) → la misma config revisada (o error claro) · cfx_despacho_costo(cfg, entrega, direccion, monto) → {costo, comuna} o {error}
create table if not exists public.cfx_carritos (
  cliente     uuid not null references auth.users (id) on delete cascade,
  negocio     uuid not null,
  items       jsonb not null default '[]'::jsonb,
  actualizado timestamptz not null default now(),
  avisado     timestamptz,
  primary key (cliente, negocio)
);
create index if not exists cfx_carritos_negocio_idx on public.cfx_carritos (negocio);
create index if not exists cfx_carritos_aviso_idx on public.cfx_carritos (actualizado) where avisado is null;
alter table public.cfx_carritos enable row level security;
revoke all on public.cfx_carritos from anon, authenticated;

-- El cliente guarda su carrito (hasta 50 productos). Vacío = se borra.
create or replace function public.cfx_carrito_guardar(p_negocio uuid, p_items jsonb) returns void
language plpgsql security definer set search_path = '' as $$
declare l jsonb := '[]'::jsonb; it jsonb; ok boolean := false;
begin
  if auth.uid() is null or p_negocio is null or to_regprocedure('public.cfx_carrito_puede(uuid,uuid)') is null then return; end if;
  execute 'select public.cfx_carrito_puede($1, $2)' into ok using auth.uid(), p_negocio;
  if not coalesce(ok, false) or jsonb_typeof(coalesce(p_items, '[]'::jsonb)) <> 'array' then return; end if;
  for it in select * from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) limit 50 loop
    continue when jsonb_typeof(it) <> 'object' or coalesce(it ->> 'clave', '') = '';
    l := l || jsonb_build_object('clave', left(it ->> 'clave', 60), 'cant', least(greatest(coalesce((it ->> 'cant')::int, 1), 1), 99), 'nombre', left(it ->> 'nombre', 80));
  end loop;
  if jsonb_array_length(l) = 0 then
    delete from public.cfx_carritos where cliente = auth.uid() and negocio = p_negocio;
  else
    insert into public.cfx_carritos (cliente, negocio, items) values (auth.uid(), p_negocio, l)
    on conflict (cliente, negocio) do update set items = excluded.items, actualizado = now(), avisado = null
      where public.cfx_carritos.items is distinct from excluded.items;
  end if;
end $$;

create or replace function public.cfx_carrito_vaciar(p_cliente uuid, p_negocio uuid) returns void
language sql security definer set search_path = '' as $$ delete from public.cfx_carritos where cliente = p_cliente and negocio = p_negocio $$;
create or replace function public.cfx_carrito_borrar(p_cuenta uuid) returns void
language sql security definer set search_path = '' as $$ delete from public.cfx_carritos where cliente = p_cuenta or negocio = p_cuenta $$;

-- Cada hora: carritos sin pedir de hace más de 20 horas (y menos de 4 días) reciben UN aviso, de 10 a 20 h de Chile.
create or replace function public.cfx_carritos_recordar() returns int
language plpgsql security definer set search_path = '' as $$
declare r record; n int := 0; ok boolean; h int := extract(hour from now() at time zone 'America/Santiago');
begin
  if h < 10 or h > 20 or not public.cfx_modulo('carrito') or to_regprocedure('public.cfx_carrito_aviso(uuid,uuid,integer)') is null then return 0; end if;
  for r in select * from public.cfx_carritos where avisado is null and actualizado < now() - interval '20 hours' and actualizado > now() - interval '4 days' limit 500 loop
    if not public.cfx_modulo_de('carrito', r.negocio) then  -- G19: la tienda no tiene el módulo (no se vuelve a revisar)
      update public.cfx_carritos set avisado = now() where cliente = r.cliente and negocio = r.negocio; continue;
    end if;
    execute 'select public.cfx_carrito_aviso($1, $2, $3)' into ok using r.cliente, r.negocio, jsonb_array_length(r.items);
    update public.cfx_carritos set avisado = now() where cliente = r.cliente and negocio = r.negocio;
    if coalesce(ok, false) then n := n + 1; end if;
  end loop;
  return n;
end $$;

-- ---------- Despacho por comuna ----------
create or replace function public.cfx_comuna_norm(t text) returns text
language sql immutable set search_path = '' as $$ select lower(trim(translate(coalesce(t, ''), 'ÁÉÍÓÚÜÑáéíóúüñ', 'AEIOUUNaeiouun'))) $$;

create or replace function public.cfx_despacho_limpio(p jsonb) returns jsonb
language plpgsql immutable set search_path = '' as $$
declare z jsonb; l jsonb := '[]'::jsonb; vistas text[] := '{}'; rm text;
begin
  if jsonb_typeof(p) is distinct from 'object' then raise exception 'Datos no válidos'; end if;
  for z in select * from jsonb_array_elements(case when jsonb_typeof(p -> 'zonas') = 'array' then p -> 'zonas' else '[]'::jsonb end) loop
    if coalesce(trim(z ->> 'comuna'), '') = '' then continue; end if;
    if length(z ->> 'comuna') > 40 then raise exception 'Nombre de comuna muy largo'; end if;
    if coalesce((z ->> 'precio')::numeric, -1) not between 0 and 200000 then raise exception 'El despacho a % debe costar entre $0 y $200.000', z ->> 'comuna'; end if;
    if public.cfx_comuna_norm(z ->> 'comuna') = any (vistas) then raise exception 'La comuna % está repetida', z ->> 'comuna'; end if;
    vistas := vistas || public.cfx_comuna_norm(z ->> 'comuna');
    l := l || jsonb_build_object('comuna', trim(z ->> 'comuna'), 'precio', round((z ->> 'precio')::numeric));
  end loop;
  if jsonb_array_length(l) > 80 then raise exception 'Máximo 80 comunas'; end if;
  -- Resto de Chile (regiones y comunas que no están en la lista): 'no' | 'fijo' (un precio) | 'por_pagar' (lo paga quien recibe al courier).
  -- G102 b 'courier' = la app cotiza con el courier (Despega: Chilexpress); precio = respaldo si el courier no responde (0 = por pagar).
  rm := coalesce(nullif(p #>> '{resto,modo}', ''), 'no');
  if rm not in ('no', 'fijo', 'por_pagar', 'courier') then raise exception 'Elige cómo despachas al resto de Chile'; end if;
  if rm = 'fijo' and coalesce((p #>> '{resto,precio}')::numeric, -1) not between 0 and 200000 then raise exception 'El despacho al resto de Chile debe costar entre $0 y $200.000'; end if;
  if rm = 'courier' and coalesce((p #>> '{resto,precio}')::numeric, 0) not between 0 and 200000 then raise exception 'El precio de respaldo debe ser entre $0 y $200.000'; end if;
  if not coalesce((p ->> 'retiro')::boolean, true) and jsonb_array_length(l) = 0 and rm = 'no' then raise exception 'Activa el retiro en tienda o agrega al menos una comuna de despacho'; end if;
  if coalesce((p ->> 'gratis_desde')::numeric, 0) not between 0 and 10000000 then raise exception 'Monto de despacho gratis no válido'; end if;
  return jsonb_build_object('retiro', coalesce((p ->> 'retiro')::boolean, true), 'gratis_desde', round(coalesce((p ->> 'gratis_desde')::numeric, 0)), 'zonas', l,
    'resto', jsonb_build_object('modo', rm, 'precio', case when rm in ('fijo', 'courier') then round(coalesce((p #>> '{resto,precio}')::numeric, 0)) else 0 end));
end $$;

-- La comuna va al final de la dirección ("…, Ñuñoa"). Sin zonas ni resto de Chile: se coordina con el negocio ($0 aquí).
-- Comuna fuera de la lista: con resto 'fijo' cobra ese precio; con 'por_pagar' $0 y por_pagar = true (lo paga quien recibe); con 'courier' la app cotiza (G102 b).
create or replace function public.cfx_despacho_costo(p_cfg jsonb, p_entrega text, p_direccion text, p_monto numeric) returns jsonb
language plpgsql immutable set search_path = '' as $$
declare c jsonb := coalesce(p_cfg, '{}'::jsonb); com text; z jsonb; rm text := coalesce(nullif(p_cfg #>> '{resto,modo}', ''), 'no'); orig text;
  gratis boolean := coalesce((p_cfg ->> 'gratis_desde')::numeric, 0) > 0 and p_monto >= (p_cfg ->> 'gratis_desde')::numeric;
begin
  if p_entrega is distinct from 'despacho' or (jsonb_array_length(coalesce(c -> 'zonas', '[]'::jsonb)) = 0 and rm = 'no') then return jsonb_build_object('costo', 0, 'comuna', null); end if;
  orig := left(trim(regexp_replace(coalesce(p_direccion, ''), '^.*,', '')), 60);
  com := public.cfx_comuna_norm(orig);
  select e into z from jsonb_array_elements(coalesce(c -> 'zonas', '[]'::jsonb)) e where public.cfx_comuna_norm(e ->> 'comuna') = com limit 1;
  if z is null then
    if com = '' or position(',' in coalesce(p_direccion, '')) = 0 then return jsonb_build_object('error', 'Escribe la dirección y la comuna de despacho'); end if;
    if rm = 'fijo' then return jsonb_build_object('comuna', orig, 'costo', case when gratis then 0 else greatest(0, coalesce((c #>> '{resto,precio}')::numeric, 0)) end); end if;
    if rm = 'por_pagar' then return jsonb_build_object('comuna', orig, 'costo', 0, 'por_pagar', true); end if;
    -- 'courier': la app reemplaza el costo con la tarifa (cotizar = true). Si la app no cotiza, vale el respaldo (o por pagar si es $0).
    if rm = 'courier' then return jsonb_build_object('comuna', orig, 'cotizar', not gratis, 'respaldo', greatest(0, coalesce((c #>> '{resto,precio}')::numeric, 0)),
      'costo', case when gratis then 0 else greatest(0, coalesce((c #>> '{resto,precio}')::numeric, 0)) end,
      'por_pagar', not gratis and coalesce((c #>> '{resto,precio}')::numeric, 0) = 0); end if;
    return jsonb_build_object('error', 'Esta tienda no despacha a esa comuna. Elige otra comuna o retiro en tienda.');
  end if;
  return jsonb_build_object('comuna', z ->> 'comuna', 'costo', case when gratis then 0 else greatest(0, coalesce((z ->> 'precio')::numeric, 0)) end);
end $$;

-- G96 🛒 Carritos olvidados (módulo 'carrito'): el negocio ve quién dejó productos sin pedir y le escribe por WhatsApp con un toque.
-- Gancho de la app: cfx_carrito_contacto_app(cliente uuid, negocio uuid) → {"nombre", "tel"} (null = no mostrar a ese cliente).
alter table public.cfx_carritos add column if not exists wa_at timestamptz;
create or replace function public.cfx_carritos_mios() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare n uuid := public.cfx_negocio_cuenta(auth.uid()); r record; c jsonb; out jsonb := '[]'::jsonb;
begin
  if n is null then raise exception 'Solo para negocios'; end if;
  if not public.cfx_modulo_de('carrito', n) then raise exception '🛒 Recordar carrito es un módulo 🧩: actívalo en Más → Mi plan y módulos'; end if;
  if to_regprocedure('public.cfx_carrito_contacto_app(uuid,uuid)') is null then return out; end if;
  for r in select * from public.cfx_carritos where negocio = n and actualizado > now() - interval '14 days' order by actualizado desc limit 100 loop
    execute 'select public.cfx_carrito_contacto_app($1, $2)' into c using r.cliente, n;
    continue when c is null;
    out := out || jsonb_build_object('cliente', r.cliente, 'nombre', c ->> 'nombre', 'tel', c ->> 'tel', 'items', r.items,
      'actualizado', r.actualizado, 'avisado', r.avisado, 'wa_at', r.wa_at);
  end loop;
  return out;
end $$;
-- Al tocar 💬 WhatsApp queda anotado (para no escribirle dos veces).
create or replace function public.cfx_carrito_wa(p_cliente uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.cfx_negocio_cuenta(auth.uid());
begin
  if n is null or not public.cfx_modulo_de('carrito', n) then raise exception 'Sin permiso'; end if;
  update public.cfx_carritos set wa_at = now() where negocio = n and cliente = p_cliente;
end $$;
revoke all on function public.cfx_carritos_mios(), public.cfx_carrito_wa(uuid) from public, anon;
grant execute on function public.cfx_carritos_mios(), public.cfx_carrito_wa(uuid) to authenticated;
revoke all on function public.cfx_carrito_vaciar(uuid, uuid), public.cfx_carrito_borrar(uuid), public.cfx_carritos_recordar(), public.cfx_comuna_norm(text),
  public.cfx_despacho_limpio(jsonb), public.cfx_despacho_costo(jsonb, text, text, numeric) from public, anon, authenticated;
revoke all on function public.cfx_carrito_guardar(uuid, jsonb) from public, anon;
grant execute on function public.cfx_carrito_guardar(uuid, jsonb) to authenticated;
do $$
begin
  perform cron.unschedule(jobid) from cron.job where jobname = 'cfx-carritos';
  perform cron.schedule('cfx-carritos', '23 * * * *', 'select public.cfx_carritos_recordar()');
exception when others then
  raise notice 'Recordatorio de carritos no programado (%).', sqlerrm;
end $$;
-- ---------- 🧹 Limpieza (C18): una sola lista para el Centro de Mando → Mis aplicaciones → ↻ → 🧹 Respaldo y limpieza ----------
-- Lo del núcleo (claves "n_…") se borra solo cada noche si la limpieza automática está prendida (por defecto sí).
-- Lo propio de cada app viene del gancho cfx_limpieza_app() → [{clave, titulo, detalle, filas}] y cfx_limpiar_app(clave) → int
-- (la app ya lo borra sola con su propio horario; aquí se puede borrar a mano).
create index if not exists cfx_registro_creado_idx on public.cfx_registro (creado);
create index if not exists cfx_errores_ultimo_idx on public.cfx_errores (ultimo);
insert into public.cfx_config (clave, valor) values ('limpieza_auto', 'true') on conflict (clave) do nothing;

create or replace function public.cfx_limpieza_nucleo() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  return jsonb_build_array(
    jsonb_build_object('clave', 'n_registro', 'titulo', 'Registro de cambios', 'detalle', 'Más de 180 días.', 'auto', true,
      'filas', (select count(*) from public.cfx_registro where creado < now() - interval '180 days')),
    jsonb_build_object('clave', 'n_errores', 'titulo', 'Errores de la app', 'detalle', 'Sin repetirse hace más de 30 días.', 'auto', true,
      'filas', (select count(*) from public.cfx_errores where ultimo < now() - interval '30 days')),
    jsonb_build_object('clave', 'n_reportes', 'titulo', 'Reportes del chat ya revisados', 'detalle', 'Más de 90 días.', 'auto', true,
      'filas', (select count(*) from public.cfx_reportes where resuelto and creado < now() - interval '90 days')),
    jsonb_build_object('clave', 'n_carritos', 'titulo', 'Carritos abandonados', 'detalle', 'Sin tocar hace más de 30 días.', 'auto', true,
      'filas', (select count(*) from public.cfx_carritos where actualizado < now() - interval '30 days')))
    -- G131 b: se borra desde el CM por la API de Storage (no por SQL); las que algo aún usa se quedan.
    || jsonb_build_array(jsonb_build_object('clave', 'n_fotos_cuentas', 'titulo', '🖼️ Fotos de cuentas borradas', 'detalle', 'En Storage; las que algo aún usa se quedan.', 'auto', false, 'storage', true,
      'filas', public.cfx_fotos_sin_cuenta_n()));
end $$;

-- G131 b: cuántas fotos hay en carpetas de cuentas que ya no existen (rápido, sin revisar tablas). Sin Storage → 0.
create or replace function public.cfx_fotos_sin_cuenta_n() returns int
language plpgsql stable security definer set search_path = '' as $$
declare n int := 0;
begin
  if to_regclass('storage.objects') is null then return 0; end if;
  execute $q$select count(*) from storage.objects o where o.bucket_id = 'vitrina'
    and split_part(o.name, '/', 1) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    and not exists (select 1 from auth.users x where x.id::text = split_part(o.name, '/', 1))$q$ into n;
  return n;
exception when others then return 0;
end $$;
revoke all on function public.cfx_fotos_sin_cuenta_n() from public, anon, authenticated;

create or replace function public.cfx_limpiar_nucleo(p_clave text) returns int
language plpgsql security definer set search_path = '' as $$
declare n int := 0;
begin
  if p_clave = 'n_registro' then delete from public.cfx_registro where creado < now() - interval '180 days';
  elsif p_clave = 'n_errores' then delete from public.cfx_errores where ultimo < now() - interval '30 days';
  elsif p_clave = 'n_reportes' then delete from public.cfx_reportes where resuelto and creado < now() - interval '90 days';
  elsif p_clave = 'n_carritos' then delete from public.cfx_carritos where actualizado < now() - interval '30 days';
  else return 0; end if;
  get diagnostics n = row_count;
  return n;
end $$;

create or replace function public.cfx_limpieza() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare a jsonb := '[]';
begin
  perform public.cfx_es_admin();
  if to_regprocedure('public.cfx_limpieza_app()') is not null then
    execute 'select public.cfx_limpieza_app()' into a;
  end if;
  return public.cfx_limpieza_nucleo() || coalesce(a, '[]');
end $$;

create or replace function public.cfx_limpiar(p_clave text) returns int
language plpgsql security definer set search_path = '' as $$
declare n int := 0;
begin
  perform public.cfx_es_admin();
  if p_clave like 'n\_%' then
    if not exists (select 1 from jsonb_array_elements(public.cfx_limpieza_nucleo()) x where x ->> 'clave' = p_clave) then raise exception 'Opción no válida'; end if;
    n := public.cfx_limpiar_nucleo(p_clave);
  elsif to_regprocedure('public.cfx_limpiar_app(text)') is not null then
    execute 'select public.cfx_limpiar_app($1)' into n using p_clave;
  else raise exception 'Opción no válida'; end if;
  perform public.cfx_anotar('limpieza', p_clave || ': ' || coalesce(n, 0) || ' borrados');
  return coalesce(n, 0);
end $$;

-- Cada noche (pg_cron 'cfx-limpieza'): borra lo del núcleo marcado "auto" y anota cuánto.
create or replace function public.cfx_limpieza_auto() returns int
language plpgsql security definer set search_path = '' as $$
declare x jsonb; n int := 0;
begin
  if not coalesce(((select valor from public.cfx_config where clave = 'limpieza_auto') #>> '{}')::boolean, true) then return 0; end if;
  for x in select * from jsonb_array_elements(public.cfx_limpieza_nucleo()) loop
    if (x ->> 'auto')::boolean and (x ->> 'filas')::int > 0 then n := n + public.cfx_limpiar_nucleo(x ->> 'clave'); end if;
  end loop;
  insert into public.cfx_salud (clave, valor, cuando) values ('limpieza', jsonb_build_object('filas', n), now())
  on conflict (clave) do update set valor = excluded.valor, cuando = excluded.cuando;
  if n > 0 then perform public.cfx_anotar('limpieza automática', n || ' filas viejas borradas'); end if;
  return n;
end $$;

-- Interruptor del Centro de Mando: { activo, ultima, filas }.
create or replace function public.cfx_limpieza_auto_ver() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  perform public.cfx_es_admin();
  return jsonb_build_object('activo', coalesce(((select valor from public.cfx_config where clave = 'limpieza_auto') #>> '{}')::boolean, true),
    'ultima', (select cuando from public.cfx_salud where clave = 'limpieza'), 'filas', (select (valor ->> 'filas')::int from public.cfx_salud where clave = 'limpieza'));
end $$;
create or replace function public.cfx_limpieza_auto_guardar(p_activo boolean) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  perform public.cfx_es_admin();
  insert into public.cfx_config (clave, valor) values ('limpieza_auto', to_jsonb(coalesce(p_activo, true)))
  on conflict (clave) do update set valor = excluded.valor;
  perform public.cfx_anotar('limpieza automática', case when coalesce(p_activo, true) then 'prendida' else 'apagada' end);
  return public.cfx_limpieza_auto_ver();
end $$;

revoke all on function public.cfx_limpieza_nucleo(), public.cfx_limpiar_nucleo(text), public.cfx_limpieza_auto() from public, anon, authenticated;
revoke all on function public.cfx_limpieza(), public.cfx_limpiar(text), public.cfx_limpieza_auto_ver(), public.cfx_limpieza_auto_guardar(boolean) from public, anon;
grant execute on function public.cfx_limpieza(), public.cfx_limpiar(text), public.cfx_limpieza_auto_ver(), public.cfx_limpieza_auto_guardar(boolean) to authenticated;
do $$
begin
  if to_regprocedure('public.cfx_limpieza_app()') is not null then revoke all on function public.cfx_limpieza_app() from public, anon, authenticated; end if;
  if to_regprocedure('public.cfx_limpiar_app(text)') is not null then revoke all on function public.cfx_limpiar_app(text) from public, anon, authenticated; end if;
end $$;
do $$
begin
  perform cron.unschedule(jobid) from cron.job where jobname = 'cfx-limpieza';
  perform cron.schedule('cfx-limpieza', '40 7 * * *', 'select public.cfx_limpieza_auto()');
exception when others then
  raise notice 'Limpieza automática no programada (%).', sqlerrm;
end $$;

-- ---------- Analítica (E24 · E25 · E27): el análisis nocturno lo hace Python en GitHub Actions (SaaS: analisis.yml + analisis/analisis.py) ----------
-- 1) Python lee cfx_analisis_datos() con la conexión del respaldo (solo la base: nadie con cuenta puede llamarla).
-- 2) Calcula tendencias de la app (CM → 📊 Analítica) y, por negocio, clientes que dejaron de comprar y productos quietos (E27).
-- 3) Lo devuelve con cfx_analisis_guardar(): una fila 'app' y una por negocio en cfx_analisis.
-- Ganchos de cada app (opcionales; sin ellos hay solo números generales):
--   cfx_analisis_datos_app() → {ventas: [{n, c, f, m, l: [[clave, cant]]}], clientes: {c: {nombre, tel}}, productos: [{n, k, nombre, stock, creado}],
--                               negocios: [{id, nombre, creado, ingreso}]}
--   cfx_analisis_negocio(u) → uuid del negocio que ve ese usuario (null: ninguno). Módulo 'analisis' (🧩 en el CM).
create table if not exists public.cfx_analisis (clave text primary key, datos jsonb not null default '{}', calculado timestamptz not null default now());
alter table public.cfx_analisis enable row level security;
revoke all on public.cfx_analisis from anon, authenticated;

create or replace function public.cfx_analisis_datos() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare a jsonb; d date := (now() at time zone 'America/Santiago')::date;
begin
  if to_regprocedure('public.cfx_analisis_datos_app()') is not null then execute 'select public.cfx_analisis_datos_app()' into a; end if;
  return jsonb_build_object('hoy', d, 'modulo', public.cfx_modulo('analisis'),
    'usuarios', (select jsonb_build_object('total', count(*),
        'activos7', count(*) filter (where last_sign_in_at > now() - interval '7 days'),
        'activos30', count(*) filter (where last_sign_in_at > now() - interval '30 days'),
        'dias', coalesce((select jsonb_object_agg(x.f, x.n) from (select (created_at at time zone 'America/Santiago')::date f, count(*) n from auth.users
          where created_at > now() - interval '61 days' and deleted_at is null group by 1) x), '{}'))
      from auth.users where deleted_at is null),
    'ingresos', coalesce((select jsonb_object_agg(x.f, x.m) from (select (coalesce(resuelto, creado) at time zone 'America/Santiago')::date f, sum(monto) m
      from public.cfx_pagos where estado = 'aprobado' and coalesce(resuelto, creado) > now() - interval '61 days' and coalesce(resuelto, creado) >= public.cfx_ingresos_desde() group by 1) x), '{}'),
    'premium', (select count(distinct cuenta) from public.cfx_pagos where estado = 'aprobado' and coalesce(resuelto, creado) > now() - interval '30 days'),
    'previo', coalesce((select jsonb_object_agg(clave, datos -> 'mov') from public.cfx_analisis where clave <> 'app' and datos ? 'mov'), '{}'),
    'app', a);
end $$;

create or replace function public.cfx_analisis_guardar(p jsonb) returns int
language plpgsql security definer set search_path = '' as $$
declare n int := 0; k text; v jsonb;
begin
  if jsonb_typeof(p -> 'app') = 'object' then
    insert into public.cfx_analisis (clave, datos, calculado) values ('app', p -> 'app', now())
    on conflict (clave) do update set datos = excluded.datos, calculado = now();
  end if;
  delete from public.cfx_analisis where clave <> 'app' and not (coalesce(p -> 'negocios', '{}') ? clave);
  for k, v in select * from jsonb_each(coalesce(p -> 'negocios', '{}')) loop
    insert into public.cfx_analisis (clave, datos, calculado) values (k, v, now())
    on conflict (clave) do update set datos = excluded.datos, calculado = now();
    n := n + 1;
  end loop;
  perform public.cfx_salud_marca('analisis', jsonb_build_object('negocios', n, 'run', coalesce(p ->> 'run', '')));
  return n;
end $$;
revoke all on function public.cfx_analisis_datos(), public.cfx_analisis_guardar(jsonb) from public, anon, authenticated;

-- Centro de Mando → 📊 Analítica.
create or replace function public.cfx_analisis_app() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  perform public.cfx_es_admin();
  return (select datos || jsonb_build_object('calculado', calculado) from public.cfx_analisis where clave = 'app');
end $$;
revoke all on function public.cfx_analisis_app() from public, anon;
grant execute on function public.cfx_analisis_app() to authenticated;

-- Para el negocio (E27): sus clientes en riesgo y productos quietos (sin la foto interna del stock).
create or replace function public.cfx_analisis_mio() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare n uuid;
begin
  if auth.uid() is null or not public.cfx_modulo('analisis') or to_regprocedure('public.cfx_analisis_negocio(uuid)') is null then return null; end if;
  execute 'select public.cfx_analisis_negocio($1)' into n using auth.uid();
  if n is null or not public.cfx_modulo_de('analisis', n) then return null; end if;
  return (select (datos - 'mov') || jsonb_build_object('calculado', calculado) from public.cfx_analisis where clave = n::text);
end $$;
revoke all on function public.cfx_analisis_mio() from public, anon;
grant execute on function public.cfx_analisis_mio() to authenticated;

-- ---------- G32 d · 🔑 Entrar con QR (núcleo): el celular con sesión aprueba y el computador entra sin escribir la clave ----------
-- 1) El computador (sin cuenta) pide un código: cfx_qr_crear → { token (va en el QR), codigo (6 letras para escribir), secreto (solo el PC) }.
-- 2) El celular con sesión lo abre o lo escribe: cfx_qr_ver muestra qué computador es → "Sí, entrar" = cfx_qr_aprobar.
-- 3) El computador pregunta cada 2 s (cfx_qr_estado). Aprobado → la Edge Function (clave de servidor) canjea UNA vez (cfx_qr_canjear)
--    y devuelve un enlace mágico de un solo uso; el computador lo usa y queda con sesión. Vence a los 2 minutos.
create table if not exists public.cfx_login_qr (
  token       text primary key,
  codigo      text not null,
  secreto     text not null,              -- sha256 del secreto (el secreto real solo lo tiene el computador)
  equipo      text,
  user_id     uuid references auth.users(id) on delete cascade,
  aprobado_at timestamptz,
  usado_at    timestamptz,
  created_at  timestamptz not null default now()
);
create index if not exists cfx_login_qr_codigo on public.cfx_login_qr (codigo);
alter table public.cfx_login_qr enable row level security;
revoke all on public.cfx_login_qr from anon, authenticated;

create or replace function public.cfx_qr_crear(p_equipo text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare t text; c text; s text; L text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789'; b bytea; i int;
begin
  delete from public.cfx_login_qr where created_at < now() - interval '10 minutes';
  if (select count(*) from public.cfx_login_qr where created_at > now() - interval '2 minutes') > 300 then
    return jsonb_build_object('ok', false, 'error', 'Muchos intentos. Espera un minuto.');
  end if;
  t := encode(extensions.gen_random_bytes(18), 'hex');
  s := encode(extensions.gen_random_bytes(24), 'hex');
  loop
    b := extensions.gen_random_bytes(6); c := '';
    for i in 0..5 loop c := c || substr(L, 1 + get_byte(b, i) % length(L), 1); end loop;
    exit when not exists (select 1 from public.cfx_login_qr where codigo = c and usado_at is null);
  end loop;
  insert into public.cfx_login_qr (token, codigo, secreto, equipo)
  values (t, c, encode(extensions.digest(s, 'sha256'), 'hex'), left(nullif(regexp_replace(coalesce(p_equipo, ''), '[^[:alnum:] ·.()-]', '', 'g'), ''), 60));
  return jsonb_build_object('ok', true, 'token', t, 'codigo', c, 'secreto', s, 'vence', 120);
end $$;
grant execute on function public.cfx_qr_crear(text) to anon, authenticated;

-- p = token del QR o el código de 6 letras. Solo códigos de menos de 2 minutos, sin aprobar.
create or replace function public.cfx_qr_buscar(p text) returns public.cfx_login_qr
language sql stable security definer set search_path = '' as $$
  select * from public.cfx_login_qr
  where (token = lower(trim(p)) or codigo = upper(regexp_replace(coalesce(p, ''), '[^A-Za-z0-9]', '', 'g')))
    and created_at > now() - interval '2 minutes' and aprobado_at is null and usado_at is null
  order by created_at desc limit 1 $$;
revoke all on function public.cfx_qr_buscar(text) from public, anon, authenticated;

create or replace function public.cfx_qr_ver(p text) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare q public.cfx_login_qr := public.cfx_qr_buscar(p);
begin
  if auth.uid() is null then return jsonb_build_object('ok', false, 'error', 'Primero inicia sesión en este celular'); end if;
  if q.token is null then return jsonb_build_object('ok', false, 'error', 'El código venció o no existe. En el computador toca "Otro código".'); end if;
  return jsonb_build_object('ok', true, 'equipo', coalesce(q.equipo, 'Computador'),
    'segundos', greatest(0, 120 - extract(epoch from now() - q.created_at)::int));
end $$;
revoke all on function public.cfx_qr_ver(text) from public, anon;
grant execute on function public.cfx_qr_ver(text) to authenticated;

-- El computador pregunta: esperando | aprobado | vencido (con su secreto: nadie más puede preguntar).
create or replace function public.cfx_qr_estado(p_token text, p_secreto text) returns text
language sql stable security definer set search_path = '' as $$
  select coalesce((select case when usado_at is not null then 'vencido'
                               when aprobado_at is not null and aprobado_at > now() - interval '2 minutes' then 'aprobado'
                               when aprobado_at is null and created_at > now() - interval '2 minutes' then 'esperando'
                               else 'vencido' end
    from public.cfx_login_qr where token = p_token and secreto = encode(extensions.digest(coalesce(p_secreto, ''), 'sha256'), 'hex')), 'vencido') $$;
grant execute on function public.cfx_qr_estado(text, text) to anon, authenticated;


-- ---------- G32 f · 🔒 3 claves malas: no se bloquea la cuenta, solo la clave y el QR; se entra con el enlace al correo (gratis) ----------
-- Se cuenta por correo (exista o no la cuenta: no revela nada). Al entrar con el enlace (amr otp/magiclink) se desbloquea.
create table if not exists public.cfx_login_fallos (
  email      text primary key,
  fallos     int not null default 0,
  updated_at timestamptz not null default now()
);
alter table public.cfx_login_fallos enable row level security;
revoke all on public.cfx_login_fallos from anon, authenticated;

create or replace function public.cfx_login_bloqueado(p_email text) returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce((select fallos >= 3 from public.cfx_login_fallos where email = lower(trim(coalesce(p_email, '')))), false) $$;
grant execute on function public.cfx_login_bloqueado(text) to anon, authenticated;

-- Clave mala → suma 1 y responde si quedó bloqueada (y cuántos intentos quedan).
create or replace function public.cfx_login_fallo(p_email text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare e text := lower(trim(coalesce(p_email, ''))); n int;
begin
  if e !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then return jsonb_build_object('ok', false); end if;
  delete from public.cfx_login_fallos where updated_at < now() - interval '30 days';
  insert into public.cfx_login_fallos (email, fallos) values (e, 1)
  on conflict (email) do update set fallos = least(public.cfx_login_fallos.fallos + 1, 99), updated_at = now()
  returning fallos into n;
  return jsonb_build_object('ok', true, 'bloqueado', n >= 3, 'quedan', greatest(0, 3 - n));
end $$;
grant execute on function public.cfx_login_fallo(text) to anon, authenticated;

-- Con sesión: clave correcta (sin bloqueo) o entró por el enlace del correo → contador a cero. 'estaba' = venía bloqueada (ofrecer cambiar la clave).
create or replace function public.cfx_login_desbloquear() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare e text := lower(coalesce(auth.jwt() ->> 'email', '')); f int; enlace boolean;
begin
  if auth.uid() is null or e = '' then return jsonb_build_object('ok', false); end if;
  enlace := exists (select 1 from jsonb_array_elements(coalesce(auth.jwt() -> 'amr', '[]'::jsonb)) a where a ->> 'method' in ('otp', 'magiclink', 'email/signup', 'recovery'));
  select fallos into f from public.cfx_login_fallos where email = e;
  if f is null then return jsonb_build_object('ok', true, 'estaba', false); end if;
  if f >= 3 and not enlace then return jsonb_build_object('ok', false, 'bloqueado', true); end if;
  delete from public.cfx_login_fallos where email = e;
  return jsonb_build_object('ok', true, 'estaba', f >= 3);
end $$;
revoke all on function public.cfx_login_desbloquear() from public, anon;
grant execute on function public.cfx_login_desbloquear() to authenticated;

-- Aprobar (celular) y canjear (solo la Edge Function, clave de servidor: marca el código usado UNA vez y entrega el correo).
-- El QR también queda cerrado mientras la cuenta esté protegida.
create or replace function public.cfx_qr_aprobar(p text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare q public.cfx_login_qr := public.cfx_qr_buscar(p);
begin
  if auth.uid() is null then return jsonb_build_object('ok', false, 'error', 'Primero inicia sesión en este celular'); end if;
  if public.cfx_login_bloqueado(auth.jwt() ->> 'email') then return jsonb_build_object('ok', false, 'error', '🔒 Tu cuenta está protegida por 3 claves malas. Entra en el computador con el enlace de tu correo.'); end if;
  if q.token is null then return jsonb_build_object('ok', false, 'error', 'El código venció o no existe. En el computador toca "Otro código".'); end if;
  update public.cfx_login_qr set user_id = auth.uid(), aprobado_at = now() where token = q.token and aprobado_at is null;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.cfx_qr_aprobar(text) from public, anon;
grant execute on function public.cfx_qr_aprobar(text) to authenticated;

create or replace function public.cfx_qr_canjear(p_token text, p_secreto text) returns text
language plpgsql security definer set search_path = '' as $$
declare u uuid; m text;
begin
  update public.cfx_login_qr set usado_at = now()
  where token = p_token and secreto = encode(extensions.digest(coalesce(p_secreto, ''), 'sha256'), 'hex')
    and aprobado_at is not null and aprobado_at > now() - interval '2 minutes' and usado_at is null
  returning user_id into u;
  if u is null then return null; end if;
  m := (select email from auth.users where id = u);
  if public.cfx_login_bloqueado(m) then return null; end if;
  return m;
end $$;
revoke all on function public.cfx_qr_canjear(text, text) from public, anon, authenticated;
grant execute on function public.cfx_qr_canjear(text, text) to service_role;

-- ---------- Seguridad (A7): lo que puede hacer alguien sin cuenta (anon) y los buckets de archivos ----------
-- Va al final del núcleo: así alcanza a todas las funciones de la app.
-- 1) En Supabase anon recibe permiso para TODA función nueva ("revoke ... from public" no se lo quita). Las que lo primero que hacen es
--    exigir ser admin igual fallarían: se les quita el permiso a anon (no cambia nada para quien tiene cuenta).
do $$
declare f record;
begin
  for f in select p.oid::regprocedure as fn from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.prokind = 'f' and has_function_privilege('anon', p.oid, 'execute')
      and p.prolang = (select oid from pg_language where lanname = 'plpgsql')
      and substring(lower(p.prosrc) from '\mbegin\M(.*)$') ~ ('^\s*perform\s+' || regexp_replace(lower('public.cfx_es_admin()'), '([().])', '\\\1', 'g') || '\s*;')
  loop
    execute 'revoke execute on function ' || f.fn || ' from public, anon';
  end loop;
end $$;
revoke execute on function public.cfx_anotar(text, text) from public, anon;

-- 2) Buckets públicos (se ven con su dirección): solo fotos y de hasta 5 MB, si la app no puso otro límite.
update storage.buckets set file_size_limit = 5242880 where public and file_size_limit is null;
update storage.buckets set allowed_mime_types = array['image/webp', 'image/jpeg', 'image/png'] where public and allowed_mime_types is null;

-- 3) Revisión para el Centro de Mando → Control → 🛡️ Seguridad.
create or replace function public.cfx_seguridad() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  perform public.cfx_es_admin();
  return jsonb_build_object(
    'sin_rls', coalesce((select jsonb_agg(c.relname order by c.relname) from pg_class c join pg_namespace n on n.oid = c.relnamespace
      where n.nspname = 'public' and c.relkind in ('r', 'p') and not c.relrowsecurity
        and (has_table_privilege('anon', c.oid, 'select') or has_table_privilege('anon', c.oid, 'insert,update,delete'))), '[]'),
    'anon_escribe', coalesce((select jsonb_agg(p.tablename || ' · ' || lower(p.cmd) order by p.tablename) from pg_policies p
      where p.schemaname = 'public' and p.cmd <> 'SELECT' and (p.roles @> '{anon}' or p.roles @> '{public}')), '[]'),
    'anon_lee', coalesce((select jsonb_agg(distinct p.tablename) from pg_policies p
      where p.schemaname = 'public' and p.cmd in ('SELECT', 'ALL') and (p.roles @> '{anon}' or p.roles @> '{public}')), '[]'),
    'funciones_anon', coalesce((select jsonb_agg(p.proname order by p.proname) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
      where n.nspname = 'public' and p.prokind = 'f' and p.prosecdef and has_function_privilege('anon', p.oid, 'execute')), '[]'),
    'buckets', coalesce((select jsonb_agg(jsonb_build_object('id', b.id, 'publico', b.public, 'mb', round(b.file_size_limit / 1048576.0, 1),
        'tipos', b.allowed_mime_types,
        'anon_lista', exists (select 1 from pg_policies p where p.schemaname = 'storage' and p.tablename = 'objects'
          and p.cmd in ('SELECT', 'ALL') and (p.roles @> '{anon}' or p.roles @> '{public}'))) order by b.id) from storage.buckets b), '[]'),
    'humano', public.cfx_humano() - 'site_key' || jsonb_build_object('activo', coalesce(public.cfx_humano() ->> 'site_key', '') <> ''));
end $$;
revoke all on function public.cfx_seguridad() from public, anon;
grant execute on function public.cfx_seguridad() to authenticated;

-- G87 C · 🔑 Clave temporal: la cuenta que crea el admin (o a la que le restablece la clave) debe crear su clave al entrar.
-- Solo guarda el correo (nunca la clave). El admin la marca; la persona la borra al guardar su clave nueva.
create table if not exists public.cfx_clave_temporal (email text primary key, creado timestamptz not null default now());
alter table public.cfx_clave_temporal enable row level security;
revoke all on public.cfx_clave_temporal from anon, authenticated;
create or replace function public.cfx_clave_temporal_marcar(p_email text) returns void
language plpgsql security definer set search_path = '' as $$
begin
  perform public.cfx_es_admin();
  if coalesce(p_email, '') !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Correo no válido'; end if;
  insert into public.cfx_clave_temporal (email) values (lower(trim(p_email))) on conflict (email) do update set creado = now();
  perform public.cfx_anotar('clave temporal', lower(trim(p_email)));
end $$;
create or replace function public.cfx_clave_debo() returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.cfx_clave_temporal t join auth.users u on lower(u.email) = t.email where u.id = auth.uid())
$$;
create or replace function public.cfx_clave_cambiada() returns void
language sql security definer set search_path = '' as $$
  delete from public.cfx_clave_temporal where email = (select lower(email) from auth.users where id = auth.uid())
$$;
revoke all on function public.cfx_clave_temporal_marcar(text), public.cfx_clave_debo(), public.cfx_clave_cambiada() from public, anon;
grant execute on function public.cfx_clave_temporal_marcar(text), public.cfx_clave_debo(), public.cfx_clave_cambiada() to authenticated;
-- ---------- G33 🌐 Dominio de CodeFix (núcleo 2.69, se puede volver a correr) ----------
-- El CM (Control → 🌐 Dominio) arma los dominios en Cloudflare y le guarda a cada app su dirección: ej. https://despega.codefix.cl/
-- "activo" = Cloudflare ya lo sirve. Mientras no esté activo (o vacío) todo sigue en workers.dev como hoy.
-- Público (no es secreto): las apps lo usan para armar links, QR y correos.
insert into public.cfx_config (clave, valor) values ('sitio', '{"dominio": "", "url": "", "activo": false}') on conflict (clave) do nothing;
create or replace function public.cfx_sitio() returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce((select valor from public.cfx_config where clave = 'sitio'), '{"dominio": "", "url": "", "activo": false}'::jsonb) $$;
revoke all on function public.cfx_sitio() from public;
grant execute on function public.cfx_sitio() to anon, authenticated;
-- Dirección de la app para correos y links del servidor: null si no hay dominio activo (se usa la de siempre).
create or replace function public.cfx_sitio_url() returns text
language sql stable security definer set search_path = '' as $$
  select case when (valor->>'activo')::boolean and coalesce(valor->>'url', '') <> '' then valor->>'url' end
  from public.cfx_config where clave = 'sitio' $$;
revoke all on function public.cfx_sitio_url() from public;
grant execute on function public.cfx_sitio_url() to anon, authenticated;
create or replace function public.cfx_sitio_guardar(p_dominio text, p_url text, p_activo boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare d text := nullif(lower(trim(regexp_replace(coalesce(p_dominio, ''), '^https?://|/.*$|\.$', '', 'gi'))), '');
        u text := nullif(lower(trim(coalesce(p_url, ''))), '');
begin
  perform public.cfx_es_admin();
  if d is not null and (d !~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}$' or length(d) > 80) then raise exception 'Escribe solo el dominio, ej: codefix.cl'; end if;
  if u is not null and (u !~ '^https://([a-z0-9-]+\.)+[a-z]{2,24}/$' or d is null or right(u, length(d) + 1) <> d || '/') then raise exception 'Dirección no válida'; end if;
  insert into public.cfx_config (clave, valor) values ('sitio', jsonb_build_object('dominio', coalesce(d, ''), 'url', coalesce(u, ''), 'activo', d is not null and u is not null and coalesce(p_activo, false)))
    on conflict (clave) do update set valor = excluded.valor;
  return public.cfx_sitio();
end $$;
revoke all on function public.cfx_sitio_guardar(text, text, boolean) from public, anon;
grant execute on function public.cfx_sitio_guardar(text, text, boolean) to authenticated;
-- ---------- G61 a · 📲 Push insistente (núcleo): cada aviso se reenvía hasta que el celular confirma que llegó ----------
-- La función de la app (enviar/servidor) anota cada envío por dispositivo (cfx_push_anotar) con un "grupo" (= el aviso).
-- El service worker, al recibirlo, confirma (cfx_push_recibido) → se cortan los reenvíos de ese aviso en TODOS los dispositivos.
-- Sin confirmación se reenvía a los 1, 2, 5, 10, 15 y 30 min y luego cada 1 h, hasta 48 h (más es spam: Google/Apple lo bloquean).
-- Abrir la app también corta lo pendiente de ese celular (cfx_push_abri). Suscripción muerta (404/410) → cfx_push_muerto.
create table if not exists public.cfx_push_entrega (
  id          bigserial primary key,
  grupo       uuid not null,
  endpoint    text not null,
  p256dh      text not null,
  auth        text not null,
  payload     text not null,
  intentos    int not null default 0,
  proximo     timestamptz not null default now() + interval '1 minute',
  recibido_at timestamptz,
  created_at  timestamptz not null default now(),
  unique (grupo, endpoint)
);
create index if not exists cfx_push_entrega_prox on public.cfx_push_entrega (proximo) where recibido_at is null;
create index if not exists cfx_push_entrega_end on public.cfx_push_entrega (endpoint);
alter table public.cfx_push_entrega enable row level security;
revoke all on public.cfx_push_entrega from anon, authenticated;

-- p_lista: [{ grupo, endpoint, p256dh, auth, payload }] (solo la función de la app, con la clave de servidor)
create or replace function public.cfx_push_anotar(p_lista jsonb) returns int
language plpgsql security definer set search_path = '' as $$
declare n int;
begin
  insert into public.cfx_push_entrega (grupo, endpoint, p256dh, auth, payload)
  select (x->>'grupo')::uuid, x->>'endpoint', x->>'p256dh', x->>'auth', x->>'payload'
  from jsonb_array_elements(coalesce(p_lista, '[]'::jsonb)) x
  where x->>'grupo' ~ '^[0-9a-f-]{36}$' and coalesce(x->>'endpoint', '') like 'https://%'
  on conflict (grupo, endpoint) do nothing;
  get diagnostics n = row_count;
  return n;
end $$;
revoke all on function public.cfx_push_anotar(jsonb) from public, anon, authenticated;
grant execute on function public.cfx_push_anotar(jsonb) to service_role;

-- Lo que toca reenviar ahora (y deja agendado el siguiente intento). Limpia lo viejo.
create or replace function public.cfx_push_tomar(p_max int default 200) returns setof public.cfx_push_entrega
language plpgsql security definer set search_path = '' as $$
begin
  delete from public.cfx_push_entrega where created_at < now() - interval '50 hours' or recibido_at < now() - interval '1 day';
  return query
  update public.cfx_push_entrega e set intentos = e.intentos + 1,
    proximo = now() + case e.intentos when 0 then interval '1 minute' when 1 then interval '3 minutes' when 2 then interval '5 minutes'
      when 3 then interval '5 minutes' when 4 then interval '15 minutes' else interval '1 hour' end
  where e.id in (select x.id from public.cfx_push_entrega x where x.recibido_at is null and x.proximo <= now() and x.created_at > now() - interval '48 hours'
                 order by x.proximo limit greatest(1, least(coalesce(p_max, 200), 500)) for update skip locked)
  returning e.*;
end $$;
revoke all on function public.cfx_push_tomar(int) from public, anon, authenticated;
grant execute on function public.cfx_push_tomar(int) to service_role;

-- El service worker confirma que llegó (el grupo es un uuid al azar que solo viaja cifrado en el aviso).
create or replace function public.cfx_push_recibido(p_grupo uuid) returns boolean
language sql security definer set search_path = '' as $$
  with u as (update public.cfx_push_entrega set recibido_at = now() where grupo = p_grupo and recibido_at is null returning 1)
  select count(*) > 0 from u;
$$;
grant execute on function public.cfx_push_recibido(uuid) to anon, authenticated;

-- Abrir la app en un celular = ya vio sus avisos: se corta lo pendiente de ese celular (y de esos avisos en los otros).
create or replace function public.cfx_push_abri(p_endpoint text) returns int
language plpgsql security definer set search_path = '' as $$
declare n int;
begin
  update public.cfx_push_entrega set recibido_at = now()
  where recibido_at is null and grupo in (select grupo from public.cfx_push_entrega where endpoint = p_endpoint and recibido_at is null);
  get diagnostics n = row_count;
  return n;
end $$;
grant execute on function public.cfx_push_abri(text) to anon, authenticated;

-- Suscripción dada de baja (404/410): no se reintenta más a ese celular.
create or replace function public.cfx_push_muerto(p_endpoint text) returns void
language sql security definer set search_path = '' as $$ delete from public.cfx_push_entrega where endpoint = p_endpoint; $$;
revoke all on function public.cfx_push_muerto(text) from public, anon, authenticated;
grant execute on function public.cfx_push_muerto(text) to service_role;

-- ---------------------------------------------------------------------
-- 🧾 Boleta SII del núcleo (G92, desde Despega): el negocio guarda sus datos de emisor y emite la boleta de una venta.
--   Manual: la emite gratis en el SII y anota el N° (folio). Automática: con su API key de OpenFactura (Haulmer) la boleta
--   electrónica (tipo 39, precios con IVA) sale sola. La API key queda solo en la base (al dueño se le muestran 4 caracteres).
--   Gancho por app: cfx_boleta_negocio_app(p_dueno) → negocio de quien llama (null = sin permiso). Cada app lo redefine DESPUÉS
--   de este bloque; el de aquí no da permiso a nadie. Los montos SIEMPRE salen de la base (la app manda solo la venta: ref).
--   Despega mantiene su boleta_* propia (pedidos de la tienda online).
-- ---------------------------------------------------------------------
create table if not exists public.cfx_boleta_cuentas (
  negocio_id uuid primary key,
  modo       text not null default 'manual' check (modo in ('manual', 'openfactura')),
  apikey     text,
  rut        text not null,
  razon      text not null,
  giro       text not null,
  direccion  text not null,
  comuna     text not null,
  auto       boolean not null default true,
  updated_at timestamptz not null default now()
);
alter table public.cfx_boleta_cuentas enable row level security;
revoke all on public.cfx_boleta_cuentas from anon, authenticated;
create table if not exists public.cfx_boletas (
  negocio_id uuid not null,
  ref        text not null check (ref ~ '^[A-Za-z0-9_:-]{4,80}$'),
  total      numeric not null default 0,
  folio      text,
  url        text,
  error      text,
  intentos   int not null default 0,
  created_at timestamptz not null default now(),
  primary key (negocio_id, ref)
);
alter table public.cfx_boletas enable row level security;
revoke all on public.cfx_boletas from anon, authenticated;

do $$ begin
  if not exists (select 1 from pg_proc where proname = 'cfx_boleta_negocio_app' and pronamespace = 'public'::regnamespace) then
    execute 'create function public.cfx_boleta_negocio_app(p_dueno boolean) returns uuid language sql stable as $f$ select null::uuid $f$';
  end if;
end $$;

-- RUT normal '12345678-5' o null (dígito verificador con cfx_rut_ok).
create or replace function public.cfx_rut_normal(p text) returns text
language sql immutable set search_path = '' as $$
  select case when public.cfx_rut_ok(r) and r ~ '^[0-9]{7,8}[0-9K]$' then ltrim(left(r, -1), '0') || '-' || right(r, 1) end
  from (select upper(regexp_replace(coalesce(p, ''), '[^0-9kK]', '', 'g')) r) x
$$;

create or replace function public.cfx_boleta_estado() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare n uuid := public.cfx_boleta_negocio_app(false); d boolean := public.cfx_boleta_negocio_app(true) is not null; b public.cfx_boleta_cuentas;
begin
  if n is null then return jsonb_build_object('puede', false); end if;
  select * into b from public.cfx_boleta_cuentas where negocio_id = n;
  return jsonb_build_object('puede', true, 'dueno', d, 'conectado', b.negocio_id is not null, 'modo', coalesce(b.modo, 'manual'), 'rut', b.rut, 'razon', b.razon,
    'giro', b.giro, 'direccion', b.direccion, 'comuna', b.comuna, 'auto', coalesce(b.auto, true), 'fin', case when d then right(b.apikey, 4) end);
end $$;

-- El dueño guarda sus datos (p null = quitar). apikey vacía mantiene la anterior.
create or replace function public.cfx_boleta_guardar(p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  n uuid := public.cfx_boleta_negocio_app(true); md text := coalesce(p ->> 'modo', 'manual'); rt text := public.cfx_rut_normal(p ->> 'rut');
  k text := nullif(regexp_replace(coalesce(p ->> 'apikey', ''), '\s', '', 'g'), ''); t text;
begin
  if n is null then raise exception 'Solo el dueño del negocio'; end if;
  if p is null then delete from public.cfx_boleta_cuentas where negocio_id = n; return public.cfx_boleta_estado(); end if;
  if md not in ('manual', 'openfactura') then raise exception 'Modo no válido'; end if;
  if rt is null then raise exception 'RUT no válido: revisa el número y el dígito verificador'; end if;
  foreach t in array array['razon', 'giro', 'direccion', 'comuna'] loop
    if length(trim(coalesce(p ->> t, ''))) < 2 then
      raise exception 'Falta %', case t when 'razon' then 'la razón social' when 'giro' then 'el giro' when 'direccion' then 'la dirección' else 'la comuna' end;
    end if;
  end loop;
  if k is not null and k !~ '^[A-Za-z0-9_-]{16,120}$' then raise exception 'Esa no parece una API key de OpenFactura'; end if;
  if md = 'openfactura' and k is null and not exists (select 1 from public.cfx_boleta_cuentas where negocio_id = n and apikey is not null) then
    raise exception 'Pega tu API key de OpenFactura';
  end if;
  insert into public.cfx_boleta_cuentas (negocio_id, modo, apikey, rut, razon, giro, direccion, comuna, auto)
  values (n, md, k, rt, left(trim(p ->> 'razon'), 100), left(trim(p ->> 'giro'), 80), left(trim(p ->> 'direccion'), 70), left(trim(p ->> 'comuna'), 20), coalesce((p ->> 'auto')::boolean, true))
  on conflict (negocio_id) do update set modo = excluded.modo, apikey = coalesce(excluded.apikey, public.cfx_boleta_cuentas.apikey), rut = excluded.rut, razon = excluded.razon,
    giro = excluded.giro, direccion = excluded.direccion, comuna = excluded.comuna, auto = excluded.auto, updated_at = now();
  return public.cfx_boleta_estado();
end $$;

-- Boleta tipo 39 en el formato de OpenFactura. items = [{ nombre, cant, subtotal }]; si suman más que el total, la diferencia va como descuento.
create or replace function public.cfx_boleta_dte(p_items jsonb, p_total numeric, c public.cfx_boleta_cuentas) returns jsonb
language plpgsql stable set search_path = '' as $$
declare det jsonb := '[]'::jsonb; l jsonb; n int := 0; suma numeric := 0; m numeric; q numeric; tot numeric := round(p_total); neto numeric; d numeric;
begin
  for l in select * from jsonb_array_elements(coalesce(p_items, '[]')) loop
    exit when n >= 59;
    q := greatest(coalesce((l ->> 'cant')::numeric, 1), 1); m := round(coalesce((l ->> 'subtotal')::numeric, 0));
    if m <= 0 then continue; end if;
    n := n + 1; suma := suma + m;
    det := det || jsonb_build_object('NroLinDet', n, 'NmbItem', left(coalesce(nullif(trim(l ->> 'nombre'), ''), 'Producto'), 80), 'QtyItem', q, 'PrcItem', round(m / q, 2), 'MontoItem', m);
  end loop;
  if suma < tot then n := n + 1; det := det || jsonb_build_object('NroLinDet', n, 'NmbItem', 'Otros', 'QtyItem', 1, 'PrcItem', tot - suma, 'MontoItem', tot - suma); suma := tot; end if;
  d := suma - tot; neto := round(tot / 1.19);
  return jsonb_build_object('response', jsonb_build_array('FOLIO', 'SELF_SERVICE'), 'dte', jsonb_build_object(
    'Encabezado', jsonb_build_object(
      'IdDoc', jsonb_build_object('TipoDTE', 39, 'Folio', 0, 'FchEmis', to_char(now() at time zone 'America/Santiago', 'YYYY-MM-DD'), 'IndServicio', 3),
      'Emisor', jsonb_build_object('RUTEmisor', c.rut, 'RznSocEmisor', c.razon, 'GiroEmisor', c.giro, 'DirOrigen', c.direccion, 'CmnaOrigen', c.comuna),
      'Receptor', jsonb_build_object('RUTRecep', '66666666-6'),
      'Totales', jsonb_build_object('MntNeto', neto, 'IVA', tot - neto, 'MntTotal', tot)),
    'Detalle', det) || case when d > 0 then jsonb_build_object('DscRcgGlobal', jsonb_build_array(
      jsonb_build_object('NroLinDR', 1, 'TpoMov', 'D', 'GlosaDR', 'Descuento', 'TpoValor', '$', 'ValorDR', d))) else '{}'::jsonb end);
end $$;

create or replace function public.cfx_of_api(p_key text, p_cuerpo jsonb, p_idem text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare st int; c text;
begin
  perform extensions.http_set_curlopt('CURLOPT_TIMEOUT', '15');
  execute 'select status, content from extensions.http(row($1, $2, $3, $4, $5)::extensions.http_request)' into st, c
    using 'POST', 'https://api.haulmer.com/v2/dte/document',
          array[row('apikey', p_key)::extensions.http_header, row('Idempotency-Key', p_idem)::extensions.http_header], 'application/json', p_cuerpo::text;
  return jsonb_build_object('status', st, 'body', case when c ~ '^\s*[\{\[]' then c::jsonb end);
exception when others then
  return jsonb_build_object('status', 0, 'error', sqlerrm);
end $$;

-- Interna (la llama la función de cada app, que ya revisó el permiso y armó los ítems DESDE LA BASE).
-- p_folio = N° anotado a mano (modo manual); null = OpenFactura. Una boleta por venta: si ya tiene folio, la devuelve.
create or replace function public.cfx_boleta_crear(p_negocio uuid, p_ref text, p_items jsonb, p_total numeric, p_folio text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare c public.cfx_boleta_cuentas; b public.cfx_boletas; r jsonb; f text; e text; fm text := nullif(regexp_replace(coalesce(p_folio, ''), '\D', '', 'g'), '');
begin
  if p_negocio is null or p_ref !~ '^[A-Za-z0-9_:-]{4,80}$' then raise exception 'Venta no válida'; end if;
  select * into b from public.cfx_boletas where negocio_id = p_negocio and ref = p_ref;
  if b.folio is not null and (b.url is not null or fm is null) then return jsonb_build_object('ok', true, 'folio', b.folio, 'url', b.url); end if;
  if round(coalesce(p_total, 0)) < 1 then raise exception 'La venta no tiene monto'; end if;
  select * into c from public.cfx_boleta_cuentas where negocio_id = p_negocio;
  if fm is not null or c.negocio_id is null or c.modo <> 'openfactura' then
    if fm is null then return jsonb_build_object('ok', false, 'manual', true, 'error', 'Escribe el N° (folio) de la boleta del SII'); end if;
    if length(fm) > 10 then raise exception 'El N° de boleta tiene hasta 10 dígitos'; end if;
    insert into public.cfx_boletas (negocio_id, ref, total, folio) values (p_negocio, p_ref, round(p_total), fm)
    on conflict (negocio_id, ref) do update set folio = excluded.folio, total = excluded.total, error = null;
    return jsonb_build_object('ok', true, 'folio', fm);
  end if;
  if c.apikey is null then raise exception 'Pega tu API key de OpenFactura en 🧾 Boleta SII'; end if;
  r := public.cfx_of_api(c.apikey, public.cfx_boleta_dte(p_items, p_total, c), 'cfx-' || p_negocio::text || '-' || p_ref);
  f := nullif(coalesce(r #>> '{body,FOLIO}', r #>> '{body,folio}'), '');
  if coalesce((r ->> 'status')::int, 0) in (200, 201) and f is not null then
    insert into public.cfx_boletas (negocio_id, ref, total, folio, url) values (p_negocio, p_ref, round(p_total), left(f, 20),
      case when r #>> '{body,SELF_SERVICE,url}' ~ '^https://[^\s"<>]+$' then left(r #>> '{body,SELF_SERVICE,url}', 500) end)
    on conflict (negocio_id, ref) do update set folio = excluded.folio, url = excluded.url, total = excluded.total, error = null
    returning * into b;
    return jsonb_build_object('ok', true, 'folio', b.folio, 'url', b.url);
  end if;
  e := left(coalesce(case when (r ->> 'status')::int = 0 then 'No se pudo conectar con OpenFactura' end,
                     r #>> '{body,error,message}', r #>> '{body,message}', 'OpenFactura respondió ' || coalesce(r ->> 'status', '?')), 200);
  if (r ->> 'status')::int in (401, 403) then e := 'OpenFactura no aceptó la API key'; end if;
  insert into public.cfx_boletas (negocio_id, ref, total, error, intentos) values (p_negocio, p_ref, round(p_total), e, 1)
  on conflict (negocio_id, ref) do update set error = excluded.error, intentos = public.cfx_boletas.intentos + 1;
  return jsonb_build_object('ok', false, 'error', e);
end $$;
revoke all on function public.cfx_boleta_crear(uuid, text, jsonb, numeric, text), public.cfx_of_api(text, jsonb, text) from public, anon, authenticated;
revoke all on function public.cfx_boleta_estado(), public.cfx_boleta_guardar(jsonb) from public, anon;
grant execute on function public.cfx_boleta_estado(), public.cfx_boleta_guardar(jsonb) to authenticated;

-- ---------------------------------------------------------------------
-- CodeFix · 📣 Anuncios (G93 · G87 D). Solo promos PROPIAS (de CodeFix a quienes usan las apps), nunca publicidad de terceros.
--   CM → Control → 📣 Anuncios: Campaña → Conjuntos (a quién) → Anuncios (título, texto, imagen, botón). Se publican en cada app elegida.
--   En la app: tarjeta con ✕ (no vuelve a salir a esa persona) · cuenta vistas, clics y cierres (1 vez por persona).
-- ---------------------------------------------------------------------
create table if not exists public.cfx_anuncios (
  id uuid primary key, campana uuid not null, campana_nombre text not null default '' check (length(campana_nombre) <= 60),
  conjunto text not null default '' check (length(conjunto) <= 60),
  publico text not null default 'todos' check (publico in ('todos', 'negocios', 'clientes', 'premium', 'gratis')),
  titulo text not null check (length(titulo) between 1 and 80), texto text not null default '' check (length(texto) <= 240),
  imagen text not null default '' check (length(imagen) <= 90000 and (imagen = '' or imagen ~ '^https://' or imagen ~ '^data:image/(png|jpeg|webp);base64,')),
  boton text not null default '' check (length(boton) <= 30),
  link text not null default '' check (length(link) <= 500 and (link = '' or link ~ '^(https://|/|#)')),
  desde date, hasta date, activo boolean not null default true, orden int not null default 0, creado timestamptz not null default now());
create index if not exists cfx_anuncios_campana_idx on public.cfx_anuncios (campana);
create table if not exists public.cfx_anuncio_vistos (
  anuncio uuid not null references public.cfx_anuncios (id) on delete cascade, cuenta uuid not null,
  visto timestamptz not null default now(), clic timestamptz, cerrado timestamptz, primary key (anuncio, cuenta));
-- G96 b 📣 Promos del negocio a SUS clientes: misma tabla, con negocio (null = de CodeFix). Solo las ven sus clientes (gancho de la app).
alter table public.cfx_anuncios add column if not exists negocio uuid;
create index if not exists cfx_anuncios_negocio_idx on public.cfx_anuncios (negocio) where negocio is not null;
alter table public.cfx_anuncios enable row level security;
alter table public.cfx_anuncio_vistos enable row level security;
revoke all on public.cfx_anuncios, public.cfx_anuncio_vistos from anon, authenticated;

-- Publicar una campaña completa en ESTA app: reemplaza sus anuncios (los que ya no vienen se borran). Solo admin.
create or replace function public.cfx_anuncios_publicar(p_campana uuid, p_nombre text, p_lista jsonb) returns int
language plpgsql security definer set search_path = '' as $$
declare a jsonb; n int := 0; ids uuid[] := '{}';
begin
  perform public.cfx_es_admin();
  if p_campana is null or jsonb_typeof(coalesce(p_lista, 'null')) <> 'array' or jsonb_array_length(p_lista) > 30 then raise exception 'Datos no válidos'; end if;
  for a in select * from jsonb_array_elements(p_lista) loop
    ids := ids || (a ->> 'id')::uuid;
    insert into public.cfx_anuncios as x (id, campana, campana_nombre, conjunto, publico, titulo, texto, imagen, boton, link, desde, hasta, activo, orden)
    values ((a ->> 'id')::uuid, p_campana, left(trim(coalesce(p_nombre, '')), 60), left(trim(coalesce(a ->> 'conjunto', '')), 60), coalesce(nullif(a ->> 'publico', ''), 'todos'),
            left(trim(coalesce(a ->> 'titulo', '')), 80), left(trim(coalesce(a ->> 'texto', '')), 240), trim(coalesce(a ->> 'imagen', '')), left(trim(coalesce(a ->> 'boton', '')), 30),
            trim(coalesce(a ->> 'link', '')), nullif(a ->> 'desde', '')::date, nullif(a ->> 'hasta', '')::date, coalesce((a ->> 'activo')::boolean, true), n)
    on conflict (id) do update set campana = excluded.campana, campana_nombre = excluded.campana_nombre, conjunto = excluded.conjunto, publico = excluded.publico,
      titulo = excluded.titulo, texto = excluded.texto, imagen = excluded.imagen, boton = excluded.boton, link = excluded.link, desde = excluded.desde,
      hasta = excluded.hasta, activo = excluded.activo, orden = excluded.orden
    where x.campana = p_campana;
    n := n + 1;
  end loop;
  delete from public.cfx_anuncios where campana = p_campana and not (id = any (ids));
  perform public.cfx_anotar('anuncios', 'Campaña "' || left(coalesce(p_nombre, ''), 60) || '": ' || n || ' anuncio(s)');
  return n;
end $$;

-- Quitar una campaña de ESTA app (se borran sus anuncios y contadores). Solo admin.
create or replace function public.cfx_anuncios_quitar(p_campana uuid) returns int
language plpgsql security definer set search_path = '' as $$
declare n int;
begin
  perform public.cfx_es_admin();
  delete from public.cfx_anuncios where campana = p_campana; get diagnostics n = row_count;
  perform public.cfx_anotar('anuncios', 'Campaña quitada (' || n || ')');
  return n;
end $$;

-- Resultados por anuncio en ESTA app (vistas, clics, cierres = personas distintas). Solo admin.
create or replace function public.cfx_anuncios_admin() returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  perform public.cfx_es_admin();
  return coalesce((select jsonb_agg(jsonb_build_object('id', a.id, 'campana', a.campana, 'titulo', a.titulo, 'activo', a.activo,
    'vistas', (select count(*) from public.cfx_anuncio_vistos v where v.anuncio = a.id),
    'clics', (select count(*) from public.cfx_anuncio_vistos v where v.anuncio = a.id and v.clic is not null),
    'cierres', (select count(*) from public.cfx_anuncio_vistos v where v.anuncio = a.id and v.cerrado is not null)) order by a.creado) from public.cfx_anuncios a where a.negocio is null), '[]');
end $$;

-- G96 b 📣 PROMOS DEL NEGOCIO. Gancho de cada app que tiene clientes con cuenta (y 'promos' en cfx_modulos_app()):
--   cfx_promo_negocios_app(u) jsonb   [{"n": negocio, "nombre": "Barbería Juan"}] de los que u es cliente (sin gancho: ninguno).
-- Módulo 'promos' (con la venta de módulos apagada: Premium). Máx. 3 activas y 10 guardadas por negocio. Validado aquí.
create or replace function public.cfx_promo_negocios(u uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare r jsonb;
begin
  if u is null or to_regprocedure('public.cfx_promo_negocios_app(uuid)') is null then return '[]'; end if;
  execute 'select public.cfx_promo_negocios_app($1)' into r using u;
  return case when jsonb_typeof(r) = 'array' then r else '[]' end;
end $$;
create or replace function public.cfx_promos_puede(n uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select n is not null and case when public.cfx_venta_on() and 'promos' = any (public.cfx_modulos_de_app()) then public.cfx_modulo_de('promos', n)
    else public.cfx_negocio_premium(n) end
$$;
-- El negocio de quien llama, solo si es el dueño (null si no).
create or replace function public.cfx_promo_mi_negocio() returns uuid
language sql stable security definer set search_path = '' as $$
  select n from (select public.cfx_negocio_cuenta(auth.uid()) n) x where n is not null and public.cfx_negocio_dueno(n) = auth.uid()
$$;
create or replace function public.cfx_promos_mias() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare n uuid := public.cfx_promo_mi_negocio();
begin
  if n is null then raise exception 'Solo el dueño del negocio'; end if;
  return jsonb_build_object('puede', public.cfx_promos_puede(n), 'lista', coalesce((select jsonb_agg(jsonb_build_object('id', a.id, 'titulo', a.titulo, 'texto', a.texto,
    'imagen', a.imagen, 'boton', a.boton, 'link', a.link, 'desde', a.desde, 'hasta', a.hasta, 'activo', a.activo,
    'vistas', (select count(*) from public.cfx_anuncio_vistos v where v.anuncio = a.id),
    'clics', (select count(*) from public.cfx_anuncio_vistos v where v.anuncio = a.id and v.clic is not null),
    'cierres', (select count(*) from public.cfx_anuncio_vistos v where v.anuncio = a.id and v.cerrado is not null)) order by a.creado desc)
    from public.cfx_anuncios a where a.negocio = n), '[]'));
end $$;
create or replace function public.cfx_promo_guardar(p jsonb) returns uuid
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.cfx_promo_mi_negocio(); i uuid := nullif(p ->> 'id', '')::uuid; r uuid; act boolean := coalesce((p ->> 'activo')::boolean, true);
  lk text := trim(coalesce(p ->> 'link', '')); de date := nullif(p ->> 'desde', '')::date; ha date := nullif(p ->> 'hasta', '')::date;
begin
  if n is null then raise exception 'Solo el dueño del negocio'; end if;
  if not public.cfx_promos_puede(n) then raise exception '📣 Promo destacada es un módulo 🧩: actívalo en Mi plan y módulos'; end if;
  if length(trim(coalesce(p ->> 'titulo', ''))) = 0 then raise exception 'Escribe el título de la promo'; end if;
  if lk <> '' and lk !~ '^https://' then raise exception 'El link debe partir con https://'; end if;
  if ha is not null and de is not null and ha < de then raise exception 'La fecha de término es antes del inicio'; end if;
  if i is null and (select count(*) from public.cfx_anuncios where negocio = n) >= 10 then raise exception 'Máximo 10 promos guardadas: borra alguna'; end if;
  if act and (select count(*) from public.cfx_anuncios where negocio = n and activo and id is distinct from i) >= 3 then raise exception 'Máximo 3 promos activas a la vez: pausa alguna'; end if;
  if i is null then
    insert into public.cfx_anuncios (id, campana, negocio, publico, titulo, texto, imagen, boton, link, desde, hasta, activo)
    values (gen_random_uuid(), gen_random_uuid(), n, 'clientes', left(trim(p ->> 'titulo'), 80), left(trim(coalesce(p ->> 'texto', '')), 240), trim(coalesce(p ->> 'imagen', '')),
            case when lk = '' then '' else left(trim(coalesce(nullif(p ->> 'boton', ''), 'Ver')), 30) end, lk, de, ha, act) returning id into r;
  else
    update public.cfx_anuncios set titulo = left(trim(p ->> 'titulo'), 80), texto = left(trim(coalesce(p ->> 'texto', '')), 240), imagen = trim(coalesce(p ->> 'imagen', '')),
      boton = case when lk = '' then '' else left(trim(coalesce(nullif(p ->> 'boton', ''), 'Ver')), 30) end, link = lk, desde = de, hasta = ha, activo = act
    where id = i and negocio = n returning id into r;
    if r is null then raise exception 'Promo no encontrada'; end if;
  end if;
  return r;
end $$;
create or replace function public.cfx_promo_borrar(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.cfx_promo_mi_negocio();
begin
  if n is null then raise exception 'Solo el dueño del negocio'; end if;
  delete from public.cfx_anuncios where id = p_id and negocio = n;
end $$;
revoke all on function public.cfx_promo_negocios(uuid), public.cfx_promos_puede(uuid), public.cfx_promo_mi_negocio() from public, anon, authenticated;
revoke all on function public.cfx_promos_mias(), public.cfx_promo_guardar(jsonb), public.cfx_promo_borrar(uuid) from public, anon;
grant execute on function public.cfx_promos_mias(), public.cfx_promo_guardar(jsonb), public.cfx_promo_borrar(uuid) to authenticated;

-- Lo que ve la persona: anuncios activos, vigentes, de su público y que no cerró (máx. 3). La app no los pide para admin/socio.
create or replace function public.cfx_anuncios_ver() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare u uuid := auth.uid(); hoy date := (now() at time zone 'America/Santiago')::date;
begin
  if u is null then return '[]'; end if;
  -- G96 b: + 📣 promos de los negocios de los que es cliente (con el nombre del negocio en 'de'), después de las de CodeFix.
  return coalesce((select jsonb_agg(jsonb_build_object('id', a.id, 'titulo', a.titulo, 'texto', a.texto, 'imagen', a.imagen, 'boton', a.boton, 'link', a.link, 'de', a.de) order by a.k, a.orden, a.creado)
    from (select a.*, case when a.negocio is null then 0 else 1 end k, (select x ->> 'nombre' from jsonb_array_elements(ng) x where x ->> 'n' = a.negocio::text limit 1) de
          from public.cfx_anuncios a, (select public.cfx_promo_negocios(u) ng) g
          where a.activo and (a.desde is null or a.desde <= hoy) and (a.hasta is null or a.hasta >= hoy)
            and not exists (select 1 from public.cfx_anuncio_vistos v where v.anuncio = a.id and v.cuenta = u and v.cerrado is not null)
            and (case when a.negocio is null then a.publico = 'todos' or u in (select d from public.cfx_destinatarios(a.publico) d)
                      else exists (select 1 from jsonb_array_elements(ng) x where x ->> 'n' = a.negocio::text) and public.cfx_promos_puede(a.negocio) end)
          order by case when a.negocio is null then 0 else 1 end, a.orden, a.creado limit 3) a), '[]');
end $$;

-- Marca vista / clic / cierre (una fila por persona y anuncio: no se infla contando de nuevo).
create or replace function public.cfx_anuncio_marcar(p_id uuid, p_que text) returns void
language plpgsql security definer set search_path = '' as $$
declare u uuid := auth.uid();
begin
  if u is null or p_que not in ('vista', 'clic', 'cierre') or not exists (select 1 from public.cfx_anuncios where id = p_id) then return; end if;
  insert into public.cfx_anuncio_vistos (anuncio, cuenta) values (p_id, u) on conflict do nothing;
  if p_que = 'clic' then update public.cfx_anuncio_vistos set clic = coalesce(clic, now()) where anuncio = p_id and cuenta = u;
  elsif p_que = 'cierre' then update public.cfx_anuncio_vistos set cerrado = coalesce(cerrado, now()) where anuncio = p_id and cuenta = u; end if;
end $$;
revoke all on function public.cfx_anuncios_publicar(uuid, text, jsonb), public.cfx_anuncios_quitar(uuid), public.cfx_anuncios_admin(), public.cfx_anuncios_ver(), public.cfx_anuncio_marcar(uuid, text) from public, anon;
grant execute on function public.cfx_anuncios_publicar(uuid, text, jsonb), public.cfx_anuncios_quitar(uuid), public.cfx_anuncios_admin(), public.cfx_anuncios_ver(), public.cfx_anuncio_marcar(uuid, text) to authenticated;

-- ---------------------------------------------------------------------
-- G98 ⚡ MERCADO PAGO PROPIO DE CADA NEGOCIO (cobrar a SUS clientes: abonos, arriendos, órdenes…). La plata llega directo al negocio.
--   El dueño pega su Access Token una vez (cfx_mp_neg_guardar; nadie lo puede leer después, ni el equipo ni la app).
--   La app crea un cobro con cfx_mp_neg_cobro(negocio, ref, título, monto, volver, vence) → url de Mercado Pago.
--   Al volver (cfx_mp_neg_revisar(ref)) o cada 1 min (cron 'cfx-mp-neg') la BASE consulta a Mercado Pago: aprobado + CLP + monto
--   completo + n° de pago usado 1 sola vez → marca el cobro pagado y llama al gancho de la app cfx_mp_neg_pagado_app(ref, pago, monto).
--   ref = '<tipo>:<id>' (ej. 'reserva:uuid'); la app decide qué hacer al pagarse (agendar, extender, etc.).
--   Despega tiene su propio mp_cuentas (pedidos) desde antes: no se toca.
-- ---------------------------------------------------------------------
create table if not exists public.cfx_mp_negocio (
  negocio    uuid primary key,
  token      text not null,
  nick       text,
  activo     boolean not null default true,
  updated_at timestamptz not null default now()
);
alter table public.cfx_mp_negocio enable row level security;
alter table public.cfx_mp_negocio add column if not exists llave_desde timestamptz not null default now(); -- G112 c2
revoke all on public.cfx_mp_negocio from anon, authenticated;

create table if not exists public.cfx_mp_neg_cobros (
  id         uuid primary key default gen_random_uuid(),
  negocio    uuid not null,
  ref        text not null,
  titulo     text,
  monto      int not null check (monto > 0),
  vence      timestamptz,
  pago       text unique,
  pagado_at  timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists cfx_mp_neg_cobros_ref on public.cfx_mp_neg_cobros (ref, created_at desc);
create index if not exists cfx_mp_neg_cobros_pend on public.cfx_mp_neg_cobros (created_at) where pago is null;
alter table public.cfx_mp_neg_cobros enable row level security;
revoke all on public.cfx_mp_neg_cobros from anon, authenticated;

-- El negocio de quien llama, solo si es el dueño (null si no).
create or replace function public.cfx_mp_neg_mio() returns uuid
language sql stable security definer set search_path = '' as $$
  select n from (select public.cfx_negocio_cuenta(auth.uid()) n) x where n is not null and public.cfx_negocio_dueno(n) = auth.uid()
$$;

-- G107: "cobro automático" = su ⚡ Mercado Pago O su 💳 Flow (Webpay). cfx_mp_neg_mp = solo Mercado Pago (suscripciones G106).
create table if not exists public.cfx_flow_negocio (
  negocio    uuid primary key,
  apikey     text not null,
  secret     text not null,
  sandbox    boolean not null default false,
  activo     boolean not null default true,
  updated_at timestamptz not null default now()
);
alter table public.cfx_flow_negocio enable row level security;
alter table public.cfx_flow_negocio add column if not exists llave_desde timestamptz not null default now(); -- G112 c2
revoke all on public.cfx_flow_negocio from anon, authenticated;
alter table public.cfx_mp_neg_cobros add column if not exists medio text not null default 'mp';
alter table public.cfx_mp_neg_cobros add column if not exists volver text;

create or replace function public.cfx_mp_neg_mp(p_negocio uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.cfx_mp_negocio where negocio = p_negocio and activo)
$$;
create or replace function public.cfx_flow_neg_on(p_negocio uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.cfx_flow_negocio where negocio = p_negocio and activo)
$$;
create or replace function public.cfx_mp_neg_activo(p_negocio uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select public.cfx_mp_neg_mp(p_negocio) or public.cfx_flow_neg_on(p_negocio)
$$;
-- Para la pantalla del cliente: qué botones mostrar.
create or replace function public.cfx_mp_neg_medios(p_negocio uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('mp', public.cfx_mp_neg_mp(p_negocio), 'flow', public.cfx_flow_neg_on(p_negocio))
$$;

create or replace function public.cfx_mp_neg_estado() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('dueno', n is not null, 'conectado', m.negocio is not null, 'activo', coalesce(m.activo, false), 'nick', m.nick, 'fin', right(public.cfx_secreto(m.token), 4),
    'desde', m.llave_desde, 'rotar', coalesce(m.llave_desde < now() - interval '365 days', false))
  from (select public.cfx_mp_neg_mio() n) x left join public.cfx_mp_negocio m on m.negocio = x.n
$$;

-- El dueño conecta (token), activa/pausa (p_activo) o desconecta (sin token y p_activo null).
create or replace function public.cfx_mp_neg_guardar(p_token text, p_activo boolean) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.cfx_mp_neg_mio(); tk text := nullif(regexp_replace(coalesce(p_token, ''), '\s', '', 'g'), ''); r jsonb;
begin
  if n is null then raise exception 'Solo el dueño del negocio'; end if;
  if tk is null then
    if p_activo is null then delete from public.cfx_mp_negocio where negocio = n;
    else
      update public.cfx_mp_negocio set activo = p_activo, updated_at = now() where negocio = n;
      if not found and p_activo then raise exception 'Pega tu Access Token de Mercado Pago'; end if;
    end if;
    return public.cfx_mp_neg_estado();
  end if;
  if tk !~ '^(APP_USR|TEST)-[A-Za-z0-9-]{20,}$' or length(tk) > 300 then raise exception 'Ese no es un Access Token: empieza con APP_USR-'; end if;
  r := public.cfx_mp_api(tk, 'GET', '/users/me');
  if coalesce((r ->> 'status')::int, 0) = 0 then raise exception 'No se pudo conectar con Mercado Pago. Intenta de nuevo.'; end if;
  if (r ->> 'status')::int <> 200 then raise exception 'Mercado Pago no aceptó el token: copia el Access Token de producción'; end if;
  insert into public.cfx_mp_negocio (negocio, token, nick, activo)
  values (n, tk, left(coalesce(r #>> '{body,nickname}', r #>> '{body,email}', ''), 80), coalesce(p_activo, true))
  on conflict (negocio) do update set token = excluded.token, nick = excluded.nick, activo = excluded.activo, updated_at = now();
  return public.cfx_mp_neg_estado();
end $$;

-- La app pide el cobro (solo desde sus funciones; no se llama directo). Devuelve { ok, url } o { ok: false, error }.
-- G107: p_medio 'mp' | 'flow' (null = Mercado Pago si está, si no Flow).
drop function if exists public.cfx_mp_neg_cobro(uuid, text, text, int, text, timestamptz);
create or replace function public.cfx_mp_neg_cobro(p_negocio uuid, p_ref text, p_titulo text, p_monto int, p_volver text, p_vence timestamptz default null, p_medio text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare tk text; c public.cfx_mp_neg_cobros; r jsonb; v text := left(coalesce(p_volver, ''), 500);
        md text := coalesce(p_medio, case when public.cfx_mp_neg_mp(p_negocio) then 'mp' else 'flow' end);
begin
  if md = 'flow' then return public.cfx_flow_neg_cobro(p_negocio, p_ref, p_titulo, p_monto, p_volver, p_vence); end if;
  select public.cfx_secreto(token) into tk from public.cfx_mp_negocio where negocio = p_negocio and activo;
  if tk is null then return jsonb_build_object('ok', false, 'error', 'Este negocio no tiene Mercado Pago activo'); end if;
  if coalesce(p_monto, 0) < 1 then return jsonb_build_object('ok', false, 'error', 'Monto no válido'); end if;
  if p_vence is not null and p_vence < now() + interval '1 minute' then return jsonb_build_object('ok', false, 'error', 'Se pasó el tiempo para pagar'); end if;
  if exists (select 1 from public.cfx_mp_neg_cobros where ref = p_ref and pago is not null) then return jsonb_build_object('ok', false, 'error', 'Esto ya está pagado'); end if;
  if v !~ '^https://[^\s"<>]+$' then v := null; end if;
  insert into public.cfx_mp_neg_cobros (negocio, ref, titulo, monto, vence) values (p_negocio, left(p_ref, 120), left(coalesce(p_titulo, 'Pago'), 120), p_monto, p_vence)
  returning * into c;
  r := public.cfx_mp_api(tk, 'POST', '/checkout/preferences', jsonb_build_object(
    'items', jsonb_build_array(jsonb_build_object('id', c.id, 'title', c.titulo, 'quantity', 1, 'currency_id', 'CLP', 'unit_price', c.monto)),
    'external_reference', c.id::text,
    'payment_methods', jsonb_build_object('excluded_payment_types', jsonb_build_array(jsonb_build_object('id', 'ticket'))))
    || public.cfx_mp_notif('n:' || c.id::text)
    || case when p_vence is null then '{}'::jsonb else jsonb_build_object('expires', true,
         'expiration_date_to', to_char(p_vence at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS".000+00:00"')) end
    || case when v is null then '{}'::jsonb else jsonb_build_object('back_urls', jsonb_build_object('success', v, 'pending', v, 'failure', v), 'auto_return', 'approved') end);
  if coalesce((r ->> 'status')::int, 0) not in (200, 201) or r #>> '{body,init_point}' is null then
    delete from public.cfx_mp_neg_cobros where id = c.id;
    return jsonb_build_object('ok', false, 'error', 'Mercado Pago no respondió. Intenta de nuevo o usa otro medio de pago.');
  end if;
  return jsonb_build_object('ok', true, 'url', r #>> '{body,init_point}');
end $$;

-- Pregunta a Mercado Pago por UN cobro; si está aprobado (CLP, monto completo, n° no usado) lo marca y llama al gancho de la app.
create or replace function public.cfx_mp_neg_confirmar(p_id uuid) returns boolean
language plpgsql security definer set search_path = '' as $$
declare c public.cfx_mp_neg_cobros; tk text; r jsonb; pg jsonb;
begin
  select * into c from public.cfx_mp_neg_cobros where id = p_id for update skip locked;
  if c.id is null then return false; end if;
  if c.pago is not null then return true; end if;
  if c.medio = 'flow' then return public.cfx_flow_neg_confirmar(c); end if;  -- G107
  select public.cfx_secreto(token) into tk from public.cfx_mp_negocio where negocio = c.negocio;
  if tk is null then return false; end if;
  r := public.cfx_mp_api(tk, 'GET', '/v1/payments/search?sort=date_created&criteria=desc&external_reference=' || c.id::text);
  select e into pg from jsonb_array_elements(coalesce(r #> '{body,results}', '[]'::jsonb)) e
  where e ->> 'status' = 'approved' and e ->> 'external_reference' = c.id::text
    and coalesce(e ->> 'currency_id', 'CLP') = 'CLP' and (e ->> 'transaction_amount')::numeric >= c.monto
    and not exists (select 1 from public.cfx_mp_neg_cobros u where u.pago = left(e ->> 'id', 40)) limit 1;
  if pg is null then return false; end if;
  update public.cfx_mp_neg_cobros set pago = left(pg ->> 'id', 40), pagado_at = now() where id = c.id;
  if to_regprocedure('public.cfx_mp_neg_pagado_app(text, text, integer)') is not null then
    execute 'select public.cfx_mp_neg_pagado_app($1, $2, $3)' using c.ref, left(pg ->> 'id', 40), c.monto;
  end if;
  return true;
end $$;

-- Al volver de Mercado Pago: revisa los cobros de esa referencia (la app lo llama dentro de su propia función, con su control de acceso).
create or replace function public.cfx_mp_neg_revisar(p_ref text) returns boolean
language plpgsql security definer set search_path = '' as $$
declare i uuid;
begin
  if exists (select 1 from public.cfx_mp_neg_cobros where ref = p_ref and pago is not null) then return true; end if;
  for i in select id from public.cfx_mp_neg_cobros where ref = p_ref and pago is null and created_at > now() - interval '3 days' order by created_at desc limit 5 loop
    if public.cfx_mp_neg_confirmar(i) then return true; end if;
  end loop;
  return false;
end $$;

create or replace function public.cfx_mp_neg_pagado(p_ref text) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.cfx_mp_neg_cobros where ref = p_ref and pago is not null)
$$;

-- Cada 1 min: cobros abiertos de los últimos 2 días (por si la persona no volvió a la página).
create or replace function public.cfx_mp_neg_revisar_pendientes() returns int
language plpgsql security definer set search_path = '' as $$
declare i uuid; n int := 0;
begin
  for i in select id from public.cfx_mp_neg_cobros c where pago is null and created_at > now() - interval '2 days'
             and (vence is null or vence > now() - interval '30 minutes')
             and not exists (select 1 from public.cfx_mp_neg_cobros p where p.ref = c.ref and p.pago is not null)
           order by created_at desc limit 40 loop
    if public.cfx_mp_neg_confirmar(i) then n := n + 1; end if;
  end loop;
  delete from public.cfx_mp_neg_cobros where pago is null and created_at < now() - interval '30 days';
  return n;
end $$;

-- ---------------------------------------------------------------------
-- G107 💳 FLOW PROPIO DE CADA NEGOCIO (Webpay débito/crédito, transferencia y MACH; la plata llega a SU cuenta Flow).
--   Mismo molde que su Mercado Pago: el dueño pega API Key + Secret Key 1 vez (nadie las lee después). El cobro va en
--   cfx_mp_neg_cobros (medio 'flow'), se confirma con getStatusByCommerceId (pagado + CLP + monto completo + n° de Flow 1 vez)
--   al volver, con el aviso de Flow (función ?cfx_mp=n:<id>) y con el cron 'cfx-mp-neg' → mismo gancho cfx_mp_neg_pagado_app.
--   Flow exige el correo de quien paga: el de la persona con sesión; si no hay (invitado), el del dueño (le llega el recibo).
-- ---------------------------------------------------------------------
create or replace function public.cfx_flow_neg_cfg(p_negocio uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('apikey', public.cfx_secreto(apikey), 'secret', public.cfx_secreto(secret), 'sandbox', sandbox) from public.cfx_flow_negocio where negocio = p_negocio
$$;

create or replace function public.cfx_flow_neg_cobro(p_negocio uuid, p_ref text, p_titulo text, p_monto int, p_volver text, p_vence timestamptz default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare f jsonb; c public.cfx_mp_neg_cobros; r jsonb; v text := left(coalesce(p_volver, ''), 500); n text; em text;
begin
  if not public.cfx_flow_neg_on(p_negocio) then return jsonb_build_object('ok', false, 'error', 'Este negocio no tiene Webpay (Flow) activo'); end if;
  f := public.cfx_flow_neg_cfg(p_negocio);
  if coalesce(p_monto, 0) < 350 then return jsonb_build_object('ok', false, 'error', 'Webpay cobra desde $350. Usa otro medio de pago.'); end if;
  if p_vence is not null and p_vence < now() + interval '1 minute' then return jsonb_build_object('ok', false, 'error', 'Se pasó el tiempo para pagar'); end if;
  if exists (select 1 from public.cfx_mp_neg_cobros where ref = p_ref and pago is not null) then return jsonb_build_object('ok', false, 'error', 'Esto ya está pagado'); end if;
  if v !~ '^https://[^\s"<>]+$' then v := null; end if;
  select email into em from auth.users where id = auth.uid();
  if coalesce(em, '') !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then select email into em from auth.users where id = public.cfx_negocio_dueno(p_negocio); end if;
  if coalesce(em, '') !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then return jsonb_build_object('ok', false, 'error', 'Falta un correo para Webpay. Usa otro medio de pago.'); end if;
  insert into public.cfx_mp_neg_cobros (negocio, ref, titulo, monto, vence, medio, volver)
  values (p_negocio, left(p_ref, 120), left(coalesce(p_titulo, 'Pago'), 120), p_monto, p_vence, 'flow', v) returning * into c;
  n := public.cfx_mp_notif('n:' || c.id::text) ->> 'notification_url';
  if n is null and v is null then
    delete from public.cfx_mp_neg_cobros where id = c.id;
    return jsonb_build_object('ok', false, 'error', 'Webpay no está listo en esta app. Usa otro medio de pago.');
  end if;
  r := public.cfx_flow_api('POST', '/payment/create', jsonb_build_object('commerceOrder', c.id::text, 'subject', c.titulo,
    'currency', 'CLP', 'amount', c.monto::text, 'email', lower(em), 'paymentMethod', '9',
    'urlConfirmation', coalesce(n, v), 'urlReturn', coalesce(n || '&cfx_volver=1', v))
    || case when p_vence is null then '{}'::jsonb else jsonb_build_object('timeout', greatest(120, least(86400, extract(epoch from p_vence - now())::int))::text) end, f);
  if coalesce((r ->> 'status')::int, 0) <> 200 or coalesce(r #>> '{body,url}', '') !~ '^https://' or coalesce(r #>> '{body,token}', '') = '' then
    delete from public.cfx_mp_neg_cobros where id = c.id;
    return jsonb_build_object('ok', false, 'error', 'Webpay (Flow) no respondió. Intenta de nuevo o usa otro medio de pago.');
  end if;
  return jsonb_build_object('ok', true, 'url', (r #>> '{body,url}') || '?token=' || public.cfx_url_cod(r #>> '{body,token}'));
end $$;

create or replace function public.cfx_flow_neg_confirmar(c public.cfx_mp_neg_cobros) returns boolean
language plpgsql security definer set search_path = '' as $$
declare f jsonb := public.cfx_flow_neg_cfg(c.negocio); r jsonb; b jsonb; nro text;
begin
  if f is null then return false; end if;
  r := public.cfx_flow_api('GET', '/payment/getStatusByCommerceId', jsonb_build_object('commerceId', c.id::text), f);
  b := r -> 'body';
  if coalesce((r ->> 'status')::int, 0) <> 200 or b is null or coalesce((b ->> 'status')::int, 0) <> 2 or b ->> 'commerceOrder' is distinct from c.id::text
     or coalesce(b ->> 'currency', 'CLP') <> 'CLP' or coalesce((b ->> 'amount')::numeric, 0) < c.monto or coalesce(b ->> 'flowOrder', '') = '' then return false; end if;
  nro := 'flow:' || left(b ->> 'flowOrder', 34);
  if exists (select 1 from public.cfx_mp_neg_cobros u where u.pago = nro) then return false; end if;
  update public.cfx_mp_neg_cobros set pago = nro, pagado_at = now() where id = c.id;
  if to_regprocedure('public.cfx_mp_neg_pagado_app(text, text, integer)') is not null then
    execute 'select public.cfx_mp_neg_pagado_app($1, $2, $3)' using c.ref, nro, c.monto;
  end if;
  return true;
end $$;

create or replace function public.cfx_flow_neg_estado() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('dueno', n is not null, 'conectado', f.negocio is not null, 'activo', coalesce(f.activo, false), 'sandbox', coalesce(f.sandbox, false), 'fin', right(public.cfx_secreto(f.apikey), 4),
    'desde', f.llave_desde, 'rotar', coalesce(f.llave_desde < now() - interval '365 days', false))
  from (select public.cfx_mp_neg_mio() n) x left join public.cfx_flow_negocio f on f.negocio = x.n
$$;

-- El dueño conecta (llaves), activa/pausa (p_activo) o desconecta (sin llaves y p_activo null).
create or replace function public.cfx_flow_neg_guardar(p_apikey text, p_secret text, p_activo boolean, p_sandbox boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.cfx_mp_neg_mio(); k text := nullif(regexp_replace(coalesce(p_apikey, ''), '\s', '', 'g'), '');
        sc text := nullif(regexp_replace(coalesce(p_secret, ''), '\s', '', 'g'), ''); r jsonb;
begin
  if n is null then raise exception 'Solo el dueño del negocio'; end if;
  if k is null and sc is null then
    if p_activo is null then delete from public.cfx_flow_negocio where negocio = n;
    else
      update public.cfx_flow_negocio set activo = p_activo, updated_at = now() where negocio = n;
      if not found and p_activo then raise exception 'Pega tu API Key y tu Secret Key de Flow'; end if;
    end if;
    return public.cfx_flow_neg_estado();
  end if;
  if k is null or sc is null then raise exception 'Pega las 2 llaves: API Key y Secret Key'; end if;
  if k !~ '^[A-Za-z0-9-]{20,80}$' then raise exception 'Esa no parece una API Key de Flow (Integración → API Keys)'; end if;
  if sc !~ '^[A-Za-z0-9]{20,100}$' then raise exception 'Esa no parece una Secret Key de Flow'; end if;
  r := public.cfx_flow_api('GET', '/payment/getStatusByCommerceId', jsonb_build_object('commerceId', 'cfx-prueba'),
    jsonb_build_object('apikey', k, 'secret', sc, 'sandbox', coalesce(p_sandbox, false)));
  if coalesce((r ->> 'status')::int, 0) = 0 then raise exception 'No se pudo conectar con Flow. Intenta de nuevo.'; end if;
  if (r ->> 'status')::int in (401, 403) then raise exception 'Flow no aceptó las llaves: cópialas de nuevo (¿son de producción o de pruebas?)'; end if;
  insert into public.cfx_flow_negocio (negocio, apikey, secret, sandbox, activo) values (n, k, sc, coalesce(p_sandbox, false), coalesce(p_activo, true))
  on conflict (negocio) do update set apikey = excluded.apikey, secret = excluded.secret, sandbox = excluded.sandbox, activo = excluded.activo, updated_at = now();
  return public.cfx_flow_neg_estado();
end $$;

revoke all on function public.cfx_flow_neg_cfg(uuid), public.cfx_flow_neg_cobro(uuid, text, text, int, text, timestamptz), public.cfx_flow_neg_confirmar(public.cfx_mp_neg_cobros) from public, anon, authenticated;
revoke all on function public.cfx_flow_neg_estado(), public.cfx_flow_neg_guardar(text, text, boolean, boolean) from public, anon;
grant execute on function public.cfx_flow_neg_estado(), public.cfx_flow_neg_guardar(text, text, boolean, boolean) to authenticated;

revoke all on function public.cfx_mp_neg_mio(), public.cfx_mp_neg_activo(uuid), public.cfx_mp_neg_cobro(uuid, text, text, int, text, timestamptz, text),
  public.cfx_mp_neg_mp(uuid), public.cfx_flow_neg_on(uuid), public.cfx_mp_neg_medios(uuid),
  public.cfx_mp_neg_confirmar(uuid), public.cfx_mp_neg_revisar(text), public.cfx_mp_neg_pagado(text), public.cfx_mp_neg_revisar_pendientes() from public, anon, authenticated;
revoke all on function public.cfx_mp_neg_estado(), public.cfx_mp_neg_guardar(text, boolean) from public, anon;
grant execute on function public.cfx_mp_neg_estado(), public.cfx_mp_neg_guardar(text, boolean) to authenticated;
do $$
begin
  perform cron.unschedule(jobid) from cron.job where jobname = 'cfx-mp-neg';
  perform cron.schedule('cfx-mp-neg', '* * * * *', 'select public.cfx_mp_neg_revisar_pendientes()');
exception when others then
  raise notice 'Revisión de Mercado Pago de los negocios no programada (%).', sqlerrm;
end $$;

-- ---------------------------------------------------------------------
-- G106 ⚡ PAGO AUTOMÁTICO CON TARJETA (suscripción "preapproval" de Mercado Pago, con el MP PROPIO del negocio).
--   La persona autoriza su tarjeta 1 vez en Mercado Pago; MP la cobra sola cada mes, sin que nadie toque nada.
--   La app crea la suscripción con cfx_mp_neg_suscribir(negocio, ref, título, monto, correo, volver, inicio) → url de MP.
--   La BASE pregunta a MP (al volver y con el cron 'cfx-mp-neg'): estado de la suscripción + cobros aprobados (CLP, monto
--   completo, cada cobro 1 sola vez) → gancho de la app cfx_mp_neg_sub_app(ref, evento, pago, monto); evento = 'activa' | 'cobro' | 'cancelada'.
--   cfx_mp_neg_sub_cancelar(ref) la apaga EN Mercado Pago (si MP no responde, no se marca: se reintenta).
-- ---------------------------------------------------------------------
create table if not exists public.cfx_mp_neg_subs (
  id          uuid primary key default gen_random_uuid(),
  negocio     uuid not null,
  ref         text not null,
  titulo      text,
  monto       int not null check (monto > 0),
  preapproval text unique,
  estado      text not null default 'pendiente' check (estado in ('pendiente', 'activa', 'pausada', 'cancelada')),
  cobros      int not null default 0,
  ultimo_at   timestamptz,
  revisado_at timestamptz,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index if not exists cfx_mp_neg_subs_ref on public.cfx_mp_neg_subs (ref, created_at desc);
create index if not exists cfx_mp_neg_subs_viva on public.cfx_mp_neg_subs (revisado_at) where estado <> 'cancelada';
alter table public.cfx_mp_neg_subs enable row level security;
revoke all on public.cfx_mp_neg_subs from anon, authenticated;

create table if not exists public.cfx_mp_neg_sub_pagos (
  id    text primary key,          -- n° del cobro autorizado de MP (1 sola vez)
  sub   uuid not null,
  pago  text,
  monto int not null,
  at    timestamptz not null default now()
);
alter table public.cfx_mp_neg_sub_pagos enable row level security;
revoke all on public.cfx_mp_neg_sub_pagos from anon, authenticated;

create or replace function public._cfx_mp_neg_sub_gancho(p_ref text, p_evento text, p_pago text, p_monto int) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if to_regprocedure('public.cfx_mp_neg_sub_app(text, text, text, integer)') is not null then
    execute 'select public.cfx_mp_neg_sub_app($1, $2, $3, $4)' using p_ref, p_evento, p_pago, p_monto;
  end if;
end $$;

-- La app pide la suscripción (solo desde sus funciones). Devuelve { ok, url } o { ok: false, error }.
create or replace function public.cfx_mp_neg_suscribir(p_negocio uuid, p_ref text, p_titulo text, p_monto int, p_email text, p_volver text, p_inicio timestamptz default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare tk text; s public.cfx_mp_neg_subs; r jsonb; v text := left(coalesce(p_volver, ''), 500); m text := lower(trim(coalesce(p_email, '')));
  ini timestamptz := greatest(coalesce(p_inicio, now()), now() + interval '5 minutes');
begin
  select public.cfx_secreto(token) into tk from public.cfx_mp_negocio where negocio = p_negocio and activo;
  if tk is null then return jsonb_build_object('ok', false, 'error', 'Este negocio no tiene Mercado Pago activo'); end if;
  if coalesce(p_monto, 0) < 1 then return jsonb_build_object('ok', false, 'error', 'Monto no válido'); end if;
  if m !~ '^[^@\s"<>]+@[^@\s"<>]+\.[a-z]{2,}$' or length(m) > 120 then return jsonb_build_object('ok', false, 'error', 'Escribe el correo de tu cuenta de Mercado Pago'); end if;
  if v !~ '^https://[^\s"<>]+$' then return jsonb_build_object('ok', false, 'error', 'Falta la dirección de regreso'); end if;
  if exists (select 1 from public.cfx_mp_neg_subs where ref = p_ref and estado in ('activa', 'pausada')) then
    return jsonb_build_object('ok', false, 'error', 'Ya tienes el pago automático');
  end if;
  update public.cfx_mp_neg_subs set estado = 'cancelada', updated_at = now() where ref = p_ref and estado = 'pendiente';  -- intento anterior sin autorizar
  insert into public.cfx_mp_neg_subs (negocio, ref, titulo, monto) values (p_negocio, left(p_ref, 120), left(coalesce(p_titulo, 'Pago mensual'), 120), p_monto)
  returning * into s;
  r := public.cfx_mp_api(tk, 'POST', '/preapproval', jsonb_build_object(
    'reason', s.titulo, 'external_reference', s.id::text, 'payer_email', m, 'back_url', v, 'status', 'pending',
    'auto_recurring', jsonb_build_object('frequency', 1, 'frequency_type', 'months', 'currency_id', 'CLP', 'transaction_amount', s.monto,
      'start_date', to_char(ini at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS".000+00:00"'))));
  if coalesce((r ->> 'status')::int, 0) not in (200, 201) or r #>> '{body,init_point}' is null or r #>> '{body,id}' is null then
    delete from public.cfx_mp_neg_subs where id = s.id;
    return jsonb_build_object('ok', false, 'error', coalesce('Mercado Pago: ' || left(r #>> '{body,message}', 160), 'Mercado Pago no respondió. Intenta de nuevo.'));
  end if;
  update public.cfx_mp_neg_subs set preapproval = left(r #>> '{body,id}', 60), revisado_at = now() where id = s.id;
  return jsonb_build_object('ok', true, 'url', r #>> '{body,init_point}');
end $$;

-- Pregunta a MP por UNA suscripción: estado + cobros nuevos. Devuelve cuántos cobros nuevos encontró.
create or replace function public.cfx_mp_neg_sub_revisar(p_id uuid) returns int
language plpgsql security definer set search_path = '' as $$
declare s public.cfx_mp_neg_subs; tk text; r jsonb; e jsonb; nuevo text; n int := 0;
begin
  select * into s from public.cfx_mp_neg_subs where id = p_id for update skip locked;
  if s.id is null or s.preapproval is null or s.estado = 'cancelada' then return 0; end if;
  select public.cfx_secreto(token) into tk from public.cfx_mp_negocio where negocio = s.negocio;
  if tk is null then return 0; end if;
  update public.cfx_mp_neg_subs set revisado_at = now() where id = s.id;
  r := public.cfx_mp_api(tk, 'GET', '/preapproval/' || s.preapproval);
  if coalesce((r ->> 'status')::int, 0) = 200 then
    nuevo := case r #>> '{body,status}' when 'authorized' then 'activa' when 'paused' then 'pausada' when 'cancelled' then 'cancelada' else s.estado end;
    if nuevo <> s.estado then
      update public.cfx_mp_neg_subs set estado = nuevo, updated_at = now() where id = s.id;
      if nuevo in ('activa', 'cancelada') then perform public._cfx_mp_neg_sub_gancho(s.ref, nuevo, null, s.monto); end if;
    end if;
  end if;
  r := public.cfx_mp_api(tk, 'GET', '/authorized_payments/search?preapproval_id=' || s.preapproval);
  for e in select x from jsonb_array_elements(coalesce(r #> '{body,results}', '[]'::jsonb)) x
           where coalesce(x #>> '{payment,status}', '') = 'approved' and coalesce(x ->> 'preapproval_id', s.preapproval) = s.preapproval
             and coalesce(x ->> 'currency_id', 'CLP') = 'CLP' and coalesce((x ->> 'transaction_amount')::numeric, 0) >= s.monto
             and x ->> 'id' is not null loop
    insert into public.cfx_mp_neg_sub_pagos (id, sub, pago, monto) values (left(e ->> 'id', 40), s.id, left(e #>> '{payment,id}', 40), s.monto)
    on conflict do nothing;
    if found then
      n := n + 1;
      update public.cfx_mp_neg_subs set cobros = cobros + 1, ultimo_at = now(), estado = case when estado = 'pendiente' then 'activa' else estado end, updated_at = now() where id = s.id;
      perform public._cfx_mp_neg_sub_gancho(s.ref, 'cobro', left(coalesce(e #>> '{payment,id}', e ->> 'id'), 40), s.monto);
    end if;
  end loop;
  return n;
end $$;

-- La app revisa las suscripciones de una referencia (al volver de MP), dentro de su propia función con su control de acceso.
create or replace function public.cfx_mp_neg_sub_revisar_ref(p_ref text) returns int
language plpgsql security definer set search_path = '' as $$
declare i uuid; n int := 0;
begin
  for i in select id from public.cfx_mp_neg_subs where ref = p_ref and estado <> 'cancelada' order by created_at desc limit 3 loop
    n := n + public.cfx_mp_neg_sub_revisar(i);
  end loop;
  return n;
end $$;

-- Lo que la app muestra: la suscripción viva más nueva de esa referencia (o null).
create or replace function public.cfx_mp_neg_sub_ver(p_ref text) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('estado', estado, 'monto', monto, 'cobros', cobros, 'ultimo', ultimo_at, 'desde', created_at)
  from public.cfx_mp_neg_subs where ref = p_ref and estado <> 'cancelada' order by created_at desc limit 1
$$;

-- Apaga en Mercado Pago todas las suscripciones vivas de esa referencia. false = MP no respondió (no se marca; se reintenta).
create or replace function public.cfx_mp_neg_sub_cancelar(p_ref text) returns boolean
language plpgsql security definer set search_path = '' as $$
declare s public.cfx_mp_neg_subs; tk text; r jsonb; todo boolean := true;
begin
  for s in select * from public.cfx_mp_neg_subs where ref = p_ref and estado <> 'cancelada' for update loop
    select public.cfx_secreto(token) into tk from public.cfx_mp_negocio where negocio = s.negocio;
    if s.preapproval is not null and tk is not null then
      r := public.cfx_mp_api(tk, 'PUT', '/preapproval/' || s.preapproval, jsonb_build_object('status', 'cancelled'));
      if coalesce((r ->> 'status')::int, 0) not in (200, 201) and coalesce(r #>> '{body,status}', '') <> 'cancelled' then todo := false; continue; end if;
    end if;
    update public.cfx_mp_neg_subs set estado = 'cancelada', updated_at = now() where id = s.id;
  end loop;
  return todo;
end $$;

-- Cron: pendientes (cada 1 min, 2 días; después se dan por abandonadas) · vivas (cada 30 min).
create or replace function public.cfx_mp_neg_subs_revisar() returns int
language plpgsql security definer set search_path = '' as $$
declare i uuid; n int := 0;
begin
  update public.cfx_mp_neg_subs set estado = 'cancelada', updated_at = now() where estado = 'pendiente' and created_at < now() - interval '2 days' and cobros = 0;
  for i in select id from public.cfx_mp_neg_subs where estado <> 'cancelada' and preapproval is not null
             and (revisado_at is null or revisado_at < now() - case when estado = 'pendiente' then interval '1 minute' else interval '30 minutes' end)
           order by revisado_at nulls first limit 30 loop
    n := n + public.cfx_mp_neg_sub_revisar(i);
  end loop;
  return n;
end $$;

revoke all on function public._cfx_mp_neg_sub_gancho(text, text, text, int), public.cfx_mp_neg_suscribir(uuid, text, text, int, text, text, timestamptz),
  public.cfx_mp_neg_sub_revisar(uuid), public.cfx_mp_neg_sub_revisar_ref(text), public.cfx_mp_neg_sub_ver(text), public.cfx_mp_neg_sub_cancelar(text),
  public.cfx_mp_neg_subs_revisar() from public, anon, authenticated;
do $$
begin
  perform cron.unschedule(jobid) from cron.job where jobname = 'cfx-mp-neg-subs';
  perform cron.schedule('cfx-mp-neg-subs', '* * * * *', 'select public.cfx_mp_neg_subs_revisar()');
exception when others then
  raise notice 'Revisión de pagos automáticos no programada (%).', sqlerrm;
end $$;

-- ---------- G112 c1 · 🔒 Llaves de pago y secretos a Supabase Vault (se puede volver a correr) ----------
-- G112 c2 · 🔄 Fecha de cada llave (llave_desde / 'desde'): las pantallas avisan a los 12 meses "Cámbiala".
-- Al guardar una llave (CM → Pagos, el dueño en su app, Turnstile, GitHub, Cloudflare) un trigger la pasa a Vault y en la tabla queda
-- solo 'vault:<nombre>'. Al desconectar se borra también de Vault. Sin Vault: queda como antes (la base vieja no se rompe).
create or replace function public._cfx_vault_cfg() returns trigger
language plpgsql security definer set search_path = '' as $$
declare k text; nueva boolean := false;
begin
  if tg_op = 'DELETE' then perform public.cfx_secreto_quitar('cfx_cfg_' || old.clave || '_'); return old; end if;
  if new.clave not in ('mp', 'flow') then return new; end if;
  foreach k in array array['token', 'apikey', 'secret'] loop
    if coalesce(new.valor ->> k, '') <> '' and new.valor ->> k not like 'vault:%' then
      -- G112 c2: ¿es una llave nueva? (no la misma que ya estaba) → se anota la fecha para avisar a los 12 meses.
      nueva := nueva or tg_op = 'INSERT' or new.valor ->> k is distinct from public.cfx_secreto(old.valor ->> k);
      new.valor := jsonb_set(new.valor, array[k], to_jsonb(public.cfx_secreto_poner('cfx_cfg_' || new.clave || '_' || k, new.valor ->> k)));
    end if;
  end loop;
  if nueva or (not new.valor ? 'desde' and coalesce(new.valor ->> 'token', new.valor ->> 'apikey', '') <> '') then
    new.valor := new.valor || jsonb_build_object('desde', now());
  end if;
  return new;
end $$;
create or replace function public._cfx_vault_mp_neg() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'DELETE' then perform public.cfx_secreto_quitar('cfx_mpneg_' || old.negocio); return old; end if;
  if tg_op = 'INSERT' or (new.token not like 'vault:%' and new.token is distinct from public.cfx_secreto(old.token)) then new.llave_desde := now(); end if;
  new.token := public.cfx_secreto_poner('cfx_mpneg_' || new.negocio, new.token);
  return new;
end $$;
create or replace function public._cfx_vault_flow_neg() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'DELETE' then perform public.cfx_secreto_quitar('cfx_flowneg_' || old.negocio || '_'); return old; end if;
  if tg_op = 'INSERT' or (new.apikey not like 'vault:%' and new.apikey is distinct from public.cfx_secreto(old.apikey))
     or (new.secret not like 'vault:%' and new.secret is distinct from public.cfx_secreto(old.secret)) then new.llave_desde := now(); end if;
  new.apikey := public.cfx_secreto_poner('cfx_flowneg_' || new.negocio || '_apikey', new.apikey);
  new.secret := public.cfx_secreto_poner('cfx_flowneg_' || new.negocio || '_secret', new.secret);
  return new;
end $$;
create or replace function public._cfx_vault_secretos() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'DELETE' then perform public.cfx_secreto_quitar('cfx_sec_' || old.clave || '_'); return old; end if;
  new.valor := public.cfx_secreto_poner('cfx_sec_' || new.clave || '_', new.valor);
  return new;
end $$;
revoke all on function public._cfx_vault_cfg(), public._cfx_vault_mp_neg(), public._cfx_vault_flow_neg(), public._cfx_vault_secretos() from public, anon, authenticated;
drop trigger if exists cfx_vault on public.cfx_config;
create trigger cfx_vault before insert or update on public.cfx_config for each row execute function public._cfx_vault_cfg();
drop trigger if exists cfx_vault_borrar on public.cfx_config;
create trigger cfx_vault_borrar after delete on public.cfx_config for each row when (old.clave in ('mp', 'flow')) execute function public._cfx_vault_cfg();
drop trigger if exists cfx_vault on public.cfx_mp_negocio;
create trigger cfx_vault before insert or update on public.cfx_mp_negocio for each row execute function public._cfx_vault_mp_neg();
drop trigger if exists cfx_vault_borrar on public.cfx_mp_negocio;
create trigger cfx_vault_borrar after delete on public.cfx_mp_negocio for each row execute function public._cfx_vault_mp_neg();
drop trigger if exists cfx_vault on public.cfx_flow_negocio;
create trigger cfx_vault before insert or update on public.cfx_flow_negocio for each row execute function public._cfx_vault_flow_neg();
drop trigger if exists cfx_vault_borrar on public.cfx_flow_negocio;
create trigger cfx_vault_borrar after delete on public.cfx_flow_negocio for each row execute function public._cfx_vault_flow_neg();
drop trigger if exists cfx_vault on public.cfx_secretos;
create trigger cfx_vault before insert or update on public.cfx_secretos for each row execute function public._cfx_vault_secretos();
drop trigger if exists cfx_vault_borrar on public.cfx_secretos;
create trigger cfx_vault_borrar after delete on public.cfx_secretos for each row execute function public._cfx_vault_secretos();
-- Las llaves que ya estaban (en texto) pasan a Vault al correr este archivo (el trigger hace el trabajo; si no hay Vault, no cambia nada).
do $$
begin
  if public.cfx_vault_hay() then
    update public.cfx_config set valor = valor where clave in ('mp', 'flow') and valor::text !~ '"(token|apikey|secret)": "vault:';
    update public.cfx_mp_negocio set token = token where token not like 'vault:%';
    update public.cfx_flow_negocio set apikey = apikey where apikey not like 'vault:%' or secret not like 'vault:%';
    update public.cfx_secretos set valor = valor where valor not like 'vault:%';
  end if;
end $$;
-- La función de servidor (Cloudflare) abre su token con esto: solo la llave de servicio puede llamarla.
create or replace function public.cfx_secreto_srv(p_clave text) returns text
language sql stable security definer set search_path = '' as $$
  select public.cfx_secreto(valor) from public.cfx_secretos where clave = p_clave $$;
revoke all on function public.cfx_secreto_srv(text) from public, anon, authenticated;
do $$ begin grant execute on function public.cfx_secreto_srv(text) to service_role; exception when others then null; end $$;
-- ---------- G112 d · 🎬 Estudio de contenido (módulo 'estudio' de las 5 apps con negocios) ----------
-- Mismo motor que el 🎬 Estudio del Centro de Mando (est-motor.js, SIN API de IA): el negocio arma su base de temas, genera ideas
-- (gancho, guión, copy, hashtags, CTA, hora) y anota sus métricas para que el motor aprenda. Datos PRIVADOS de cada negocio:
-- la tabla no tiene políticas (nadie la lee directo); solo el dueño, por estas funciones. Leer y borrar: siempre (🛡️ sus datos
-- nunca se ocultan). Crear o cambiar: con el módulo (o Premium si la venta de módulos está apagada), igual que 📣 promos.
create table if not exists public.cfx_estudio (
  id      uuid primary key default gen_random_uuid(),
  negocio uuid not null,
  tipo    text not null check (tipo in ('conf', 'base', 'idea')),
  titulo  text not null default '' check (length(titulo) <= 300),
  fecha   date,
  estado  text not null default 'pendiente' check (estado in ('pendiente', 'grabada', 'publicada', 'abierto')),
  datos   jsonb not null default '{}' check (jsonb_typeof(datos) = 'object' and pg_column_size(datos) <= 6000),
  creado  timestamptz not null default now()
);
create index if not exists cfx_estudio_negocio_idx on public.cfx_estudio (negocio, tipo);
alter table public.cfx_estudio enable row level security;
revoke all on public.cfx_estudio from anon, authenticated;

-- El negocio de quien llama, solo si es el dueño (null si no).
create or replace function public.cfx_estudio_negocio() returns uuid
language sql stable security definer set search_path = '' as $$
  select n from (select public.cfx_negocio_cuenta(auth.uid()) n) x where n is not null and public.cfx_negocio_dueno(n) = auth.uid()
$$;
create or replace function public.cfx_estudio_puede(n uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select n is not null and case when public.cfx_venta_on() and 'estudio' = any (public.cfx_modulos_de_app()) then public.cfx_modulo_de('estudio', n)
    else public.cfx_negocio_premium(n) end
$$;
create or replace function public.cfx_estudio_fila(e public.cfx_estudio) returns jsonb
language sql immutable as $$
  select jsonb_build_object('id', e.id, 'tipo', e.tipo, 'titulo', e.titulo, 'fecha', e.fecha, 'estado', e.estado, 'datos', e.datos, 'created_at', e.creado)
$$;
create or replace function public.cfx_estudio_mio() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare n uuid := public.cfx_estudio_negocio();
begin
  if n is null then raise exception 'Solo el dueño del negocio'; end if;
  return jsonb_build_object('puede', public.cfx_estudio_puede(n),
    'lista', coalesce((select jsonb_agg(public.cfx_estudio_fila(e) order by e.creado) from public.cfx_estudio e where e.negocio = n), '[]'));
end $$;
-- Guarda una fila o una lista (máx. 500 por vez). Con id = cambia esa fila (solo la del mismo negocio); sin id = nueva.
-- Topes por negocio: 3000 filas de base, 3000 ideas, 1 configuración. Devuelve las filas guardadas.
create or replace function public.cfx_estudio_guardar(p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.cfx_estudio_negocio(); x jsonb; r public.cfx_estudio; out jsonb := '[]'; i uuid; t text; es text; f date; d jsonb;
begin
  if n is null then raise exception 'Solo el dueño del negocio'; end if;
  if not public.cfx_estudio_puede(n) then raise exception '🎬 Estudio de contenido es un módulo 🧩: pruébalo gratis o actívalo en Mi plan y módulos'; end if;
  if jsonb_typeof(p) = 'object' then p := jsonb_build_array(p); end if;
  if jsonb_typeof(p) is distinct from 'array' or jsonb_array_length(p) = 0 then raise exception 'Nada que guardar'; end if;
  if jsonb_array_length(p) > 500 then raise exception 'Máximo 500 filas por vez'; end if;
  for x in select * from jsonb_array_elements(p) loop
    i := nullif(x ->> 'id', '')::uuid;
    d := coalesce(x -> 'datos', '{}'); if jsonb_typeof(d) <> 'object' then d := '{}'; end if;
    if pg_column_size(d) > 6000 then raise exception 'Idea muy larga'; end if;
    f := case when coalesce(x ->> 'fecha', '') ~ '^\d{4}-\d{2}-\d{2}' then left(x ->> 'fecha', 10)::date end;
    if i is not null then
      update public.cfx_estudio set titulo = left(trim(coalesce(x ->> 'titulo', titulo)), 300),
        fecha = case when x ? 'fecha' then f else fecha end,
        estado = case when x ->> 'estado' in ('pendiente', 'grabada', 'publicada', 'abierto') then x ->> 'estado' else estado end,
        datos = case when x ? 'datos' then d else datos end
      where id = i and negocio = n returning * into r;
      if r.id is null then raise exception 'No encontrada'; end if;
    else
      t := x ->> 'tipo';
      if t is null or t not in ('conf', 'base', 'idea') then raise exception 'Tipo inválido'; end if;
      if t = 'conf' and exists (select 1 from public.cfx_estudio where negocio = n and tipo = 'conf') then
        update public.cfx_estudio set datos = d where negocio = n and tipo = 'conf' returning * into r;
      else
        if (select count(*) from public.cfx_estudio where negocio = n and tipo = t) >= 3000 then
          raise exception 'Llegaste al máximo de 3000 %: borra algunas', case when t = 'base' then 'filas de base' else 'ideas' end; end if;
        es := case when x ->> 'estado' in ('pendiente', 'grabada', 'publicada', 'abierto') then x ->> 'estado' when t = 'idea' then 'pendiente' else 'abierto' end;
        insert into public.cfx_estudio (negocio, tipo, titulo, fecha, estado, datos)
        values (n, t, left(trim(coalesce(x ->> 'titulo', '')), 300), f, es, d) returning * into r;
      end if;
    end if;
    out := out || jsonb_build_array(public.cfx_estudio_fila(r)); r := null;
  end loop;
  return out;
end $$;
-- Borrar es siempre posible (son sus datos), con o sin el módulo.
create or replace function public.cfx_estudio_borrar(p_ids uuid[]) returns int
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.cfx_estudio_negocio(); k int;
begin
  if n is null then raise exception 'Solo el dueño del negocio'; end if;
  delete from public.cfx_estudio where negocio = n and id = any (coalesce(p_ids, '{}'));
  get diagnostics k = row_count;
  return k;
end $$;
revoke all on function public.cfx_estudio_negocio(), public.cfx_estudio_puede(uuid), public.cfx_estudio_fila(public.cfx_estudio) from public, anon, authenticated;
revoke all on function public.cfx_estudio_mio(), public.cfx_estudio_guardar(jsonb), public.cfx_estudio_borrar(uuid[]) from public, anon;
grant execute on function public.cfx_estudio_mio(), public.cfx_estudio_guardar(jsonb), public.cfx_estudio_borrar(uuid[]) to authenticated;
-- ===================== G122 🖼️ Fotos a Storage (núcleo) =====================
-- Bucket público 'vitrina': cada uno sube SOLO a su carpeta (<su id>/<uuid>.webp), hasta 700 KB, solo imágenes. Nadie lista lo ajeno.
-- Las apps aceptan en sus fotos de vitrina el texto base64 de siempre O una URL de este bucket (cfx_foto_ok). Lo viejo sigue igual.
-- G131 b 🧹 Carpeta de una CUENTA BORRADA: solo el admin (Centro de Mando) la ve y la borra por la API de Storage.
-- Nunca lanza error (va dentro de las reglas de Storage): ante la duda, false.
create or replace function public.cfx_foto_sin_cuenta(p_name text) returns boolean
language plpgsql stable security definer set search_path = '' as $$
declare c text := split_part(coalesce(p_name, ''), '/', 1);
begin
  if c !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or (select auth.uid()) is null then return false; end if;
  if exists (select 1 from auth.users where id = c::uuid) then return false; end if;
  perform public.cfx_es_admin();
  return true;
exception when others then return false;
end $$;
revoke all on function public.cfx_foto_sin_cuenta(text) from public, anon;
grant execute on function public.cfx_foto_sin_cuenta(text) to authenticated;
do $$ begin
  if to_regclass('storage.buckets') is not null then
    insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values ('vitrina', 'vitrina', true, 716800, array['image/webp', 'image/jpeg', 'image/png'])
    on conflict (id) do update set public = true, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
    drop policy if exists cfx_vitrina_subir on storage.objects;
    drop policy if exists cfx_vitrina_ver on storage.objects;
    drop policy if exists cfx_vitrina_borrar on storage.objects;
    create policy cfx_vitrina_subir on storage.objects for insert to authenticated
      with check (bucket_id = 'vitrina' and (storage.foldername(name))[1] = (select auth.uid())::text);
    create policy cfx_vitrina_ver on storage.objects for select to authenticated
      using ((bucket_id = 'vitrina' and (storage.foldername(name))[1] = (select auth.uid())::text) or (bucket_id = 'vitrina' and public.cfx_foto_sin_cuenta(name)));
    create policy cfx_vitrina_borrar on storage.objects for delete to authenticated
      using ((bucket_id = 'vitrina' and (storage.foldername(name))[1] = (select auth.uid())::text) or (bucket_id = 'vitrina' and public.cfx_foto_sin_cuenta(name)));
  end if;
end $$;

-- ¿Es una foto de la nube (bucket vitrina de Supabase)? Con p_uid: además, ¿la subió esa persona?
create or replace function public.cfx_foto_nube(t text, p_uid uuid default null) returns boolean
language sql immutable set search_path = '' as $$
  select coalesce(t, '') ~ '^https://[a-z0-9-]+\.supabase\.co/storage/v1/object/public/vitrina/[0-9a-f-]{36}/[0-9a-f-]{36}\.(webp|jpg|png)$'
    and (p_uid is null or split_part(split_part(t, '/vitrina/', 2), '/', 1) = p_uid::text)
$$;
-- Foto de vitrina válida: vacía, base64 liviano (≤ maxlen) o de la nube.
create or replace function public.cfx_foto_ok(t text, maxlen int) returns boolean
language sql immutable set search_path = '' as $$
  select coalesce(t, '') = '' or (t ~ '^data:image/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$' and length(t) <= maxlen) or public.cfx_foto_nube(t)
$$;
grant execute on function public.cfx_foto_nube(text, uuid), public.cfx_foto_ok(text, int) to authenticated, anon;

-- G122 b 🧹 Fotos huérfanas: de una lista de MIS archivos (<uuid>.webp de mi carpeta), ¿cuáles NO aparecen en ninguna tabla?
-- Busca en TODAS las columnas de texto/json/arreglo de la app (también respaldos), así nunca se borra una foto en uso.
-- Ante cualquier duda (nombre raro, error al leer una tabla) devuelve vacío: no se borra nada.
-- Interno: de los archivos p_nombres de la carpeta u, ¿cuáles aparecen en alguna tabla? null = no se pudo leer todo (no borrar nada).
create or replace function public.cfx_fotos_en_uso(u uuid, p_nombres text[]) returns text[]
language plpgsql stable security definer set search_path = '' as $$
declare pat text; r record; txt text; n text; usados text[] := '{}';
begin
  pat := '%/vitrina/' || u::text || '/%';
  for r in select c.table_schema s, c.table_name t, c.column_name col
      from information_schema.columns c join information_schema.tables tb on tb.table_schema = c.table_schema and tb.table_name = c.table_name
      where tb.table_type = 'BASE TABLE' and c.data_type in ('text', 'character varying', 'jsonb', 'json', 'ARRAY')
        and c.table_schema not in ('storage', 'auth', 'information_schema', 'vault', 'pgsodium', 'pgsodium_masks', 'realtime', '_realtime',
          'supabase_functions', 'supabase_migrations', 'extensions', 'graphql', 'graphql_public', 'net', 'cron', 'pgbouncer', '_analytics')
        and c.table_schema !~ '^pg_' loop
    begin
      execute format('select string_agg(%I::text, '' '') from %I.%I where %I::text like $1', r.col, r.s, r.t, r.col) into txt using pat;
    exception when others then return null;
    end;
    if txt is not null then
      foreach n in array p_nombres loop
        if position(u::text || '/' || n in txt) > 0 then usados := usados || n; end if;
      end loop;
    end if;
  end loop;
  return usados;
end $$;
revoke all on function public.cfx_fotos_en_uso(uuid, text[]) from public, anon, authenticated;

create or replace function public.cfx_fotos_libres(p_nombres text[]) returns text[]
language plpgsql security definer set search_path = '' as $$
declare u uuid := auth.uid(); n text; usados text[]; libres text[] := '{}';
begin
  if u is null or coalesce(array_length(p_nombres, 1), 0) = 0 or array_length(p_nombres, 1) > 1000 then return '{}'; end if;
  foreach n in array p_nombres loop
    if n is null or n !~ '^[0-9a-f-]{36}\.(webp|jpg|png)$' then return '{}'; end if;
  end loop;
  usados := public.cfx_fotos_en_uso(u, p_nombres);
  if usados is null then return '{}'; end if;
  foreach n in array p_nombres loop
    if not (n = any(usados)) then libres := libres || n; end if;
  end loop;
  return libres;
end $$;
revoke all on function public.cfx_fotos_libres(text[]) from public, anon;
grant execute on function public.cfx_fotos_libres(text[]) to authenticated;

-- G131 b 🧹 Fotos de CUENTAS BORRADAS (solo admin): archivos 'carpeta/archivo' que ya no usa ninguna tabla → el CM los borra por Storage.
-- Las que algo aún usa (respaldos, otra fila) se quedan. Hasta 1000 por vez.
create or replace function public.cfx_fotos_sin_cuenta() returns text[]
language plpgsql security definer set search_path = '' as $$
declare r record; usados text[]; n text; sale text[] := '{}';
begin
  perform public.cfx_es_admin();
  if to_regclass('storage.objects') is null then return '{}'; end if;
  for r in execute $q$select split_part(name, '/', 1) c, array_agg(split_part(name, '/', 2) order by name) a from storage.objects
      where bucket_id = 'vitrina' and split_part(name, '/', 1) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        and split_part(name, '/', 2) ~ '^[0-9a-f-]{36}\.(webp|jpg|png)$'
        and not exists (select 1 from auth.users x where x.id::text = split_part(name, '/', 1))
      group by 1 order by 1$q$ loop
    usados := public.cfx_fotos_en_uso(r.c::uuid, r.a);
    if usados is null then return '{}'; end if;
    foreach n in array r.a loop
      if not (n = any(usados)) then sale := sale || (r.c || '/' || n); end if;
      if array_length(sale, 1) >= 1000 then return sale; end if;
    end loop;
  end loop;
  return sale;
end $$;
revoke all on function public.cfx_fotos_sin_cuenta() from public, anon;
grant execute on function public.cfx_fotos_sin_cuenta() to authenticated;
-- ---------------------------------------------------------------------
-- CodeFix · G140 🎨 Personalizar (igual en las 7 apps; lo reparte nucleo/sincronizar.py).
--   Lo que cada persona elige en Mi perfil → 🎨 Personalizar (colores a su gusto, letra y barra de abajo) queda en su cuenta:
--   en otro celular se ve igual. El color y el modo de la app los guarda cada app como antes.
--   cfx_personal()                → lo guardado de la cuenta ({} si nada).
--   cfx_personal_guardar(datos)   → guarda solo lo permitido (col, letra, barra, v) y con tamaño acotado.
-- ---------------------------------------------------------------------
create table if not exists public.cfx_personal (
  cuenta   uuid primary key references auth.users (id) on delete cascade,
  datos    jsonb not null default '{}'::jsonb,
  cambiado timestamptz not null default now()
);
alter table public.cfx_personal enable row level security;
revoke all on public.cfx_personal from anon, authenticated;

create or replace function public.cfx_personal() returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce((select datos from public.cfx_personal where cuenta = auth.uid()), '{}'::jsonb)
$$;

create or replace function public.cfx_personal_guardar(p_datos jsonb) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare u uuid := auth.uid(); d jsonb;
begin
  if u is null then raise exception 'Inicia sesión para guardar.'; end if;
  if p_datos is null or jsonb_typeof(p_datos) <> 'object' then raise exception 'Datos no válidos.'; end if;
  if octet_length(p_datos::text) > 6000 then raise exception 'Demasiados datos.'; end if;
  d := jsonb_strip_nulls(jsonb_build_object(
    'v', case when jsonb_typeof(p_datos -> 'v') = 'number' then p_datos -> 'v' end,
    'col', case when jsonb_typeof(p_datos -> 'col') = 'object' then p_datos -> 'col' end,
    'letra', case when jsonb_typeof(p_datos -> 'letra') = 'object' then p_datos -> 'letra' end,
    'barra', case when jsonb_typeof(p_datos -> 'barra') = 'object' then p_datos -> 'barra' end));
  insert into public.cfx_personal (cuenta, datos, cambiado) values (u, d, now())
  on conflict (cuenta) do update set datos = excluded.datos, cambiado = now();
end $$;

revoke all on function public.cfx_personal(), public.cfx_personal_guardar(jsonb) from public, anon;
grant execute on function public.cfx_personal(), public.cfx_personal_guardar(jsonb) to authenticated;
-- ---------------------------------------------------------------------
-- CodeFix · G141 a 🔗 Mis redes (igual en las 7 apps; lo reparte nucleo/sincronizar.py).
--   El dueño pega el link de su perfil (Instagram, TikTok, Facebook, YouTube, X, Threads, LinkedIn, WhatsApp, Pinterest,
--   Spotify o su web) y su página pública muestra botones con ícono. Gratis (FREE opera completo).
--   cfx_redes_mias()            → { lista: [{red, url}] } del negocio de quien llama (dueño o equipo; solo lectura para el equipo).
--   cfx_redes_guardar(p_lista)  → solo el DUEÑO; valida en el servidor red, https y dominio de cada red (máx. 12).
--   cfx_redes_publicas(p_llave) → lista pública (anon). La app traduce su llave pública (slug, código…) con el gancho
--                                 cfx_redes_llave_app(text) → uuid del negocio; sin gancho → [] (nunca error).
-- ---------------------------------------------------------------------
create table if not exists public.cfx_redes (
  negocio  uuid primary key,
  lista    jsonb not null default '[]'::jsonb check (jsonb_typeof(lista) = 'array' and pg_column_size(lista) <= 4000),
  cambiado timestamptz not null default now()
);
alter table public.cfx_redes enable row level security;
revoke all on public.cfx_redes from anon, authenticated;
-- G144 d: sin_wa = el dueño QUITÓ a propósito el WhatsApp del registro (no se vuelve a poner solo).
alter table public.cfx_redes add column if not exists sin_wa boolean not null default false;

-- Dominio permitido por red ('web' = cualquier https).
create or replace function public.cfx_red_ok(p_red text, p_url text) returns boolean
language sql immutable set search_path = '' as $$
  select coalesce(p_url, '') ~ '^https://[^\s<>"''`\\]{3,200}$' and case p_red
    when 'instagram' then p_url ~* '^https://([a-z0-9-]+\.)?instagram\.com/'
    when 'facebook' then p_url ~* '^https://([a-z0-9-]+\.)?(facebook\.com|fb\.com|fb\.me)/'
    when 'tiktok' then p_url ~* '^https://([a-z0-9-]+\.)?tiktok\.com/'
    when 'youtube' then p_url ~* '^https://([a-z0-9-]+\.)?(youtube\.com|youtu\.be)/'
    when 'x' then p_url ~* '^https://([a-z0-9-]+\.)?(x\.com|twitter\.com)/'
    when 'threads' then p_url ~* '^https://([a-z0-9-]+\.)?threads\.(net|com)/'
    when 'linkedin' then p_url ~* '^https://([a-z0-9-]+\.)?linkedin\.com/'
    when 'whatsapp' then p_url ~* '^https://(wa\.me|([a-z0-9-]+\.)?whatsapp\.com)/'
    when 'pinterest' then p_url ~* '^https://([a-z0-9-]+\.)?(pinterest\.[a-z.]{2,6}|pin\.it)/'
    when 'spotify' then p_url ~* '^https://open\.spotify\.com/'
    when 'web' then true
    else false end
$$;

-- G144 d 💬 El WhatsApp del registro pasa solo a las redes: gancho por app cfx_whatsapp_app(negocio) → número (sin gancho → nada;
--   Estaciona no lo tiene: son personas, su número no se publica). Nunca lanza error.
create or replace function public.cfx_redes_wa(p_negocio uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare t text;
begin
  if p_negocio is null or to_regprocedure('public.cfx_whatsapp_app(uuid)') is null then return null; end if;
  execute 'select public.cfx_whatsapp_app($1)' into t using p_negocio;
  t := regexp_replace(coalesce(t, ''), '\D', '', 'g');
  if t ~ '^9\d{8}$' then t := '56' || t; end if;
  if t !~ '^\d{10,15}$' then return null; end if;
  return jsonb_build_object('red', 'whatsapp', 'url', 'https://wa.me/' || t, 'auto', true);  -- auto: no lo guardó el dueño (la app suma sus redes antiguas)
exception when others then return null;
end $$;
-- Lista guardada + el WhatsApp del registro si no hay uno (y el dueño no lo quitó).
create or replace function public.cfx_redes_con_wa(p_negocio uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare l jsonb; sw boolean; w jsonb;
begin
  select r.lista, r.sin_wa into l, sw from public.cfx_redes r where r.negocio = p_negocio;
  l := coalesce(l, '[]'::jsonb);
  if coalesce(sw, false) or exists (select 1 from jsonb_array_elements(l) e where e ->> 'red' = 'whatsapp') or jsonb_array_length(l) >= 12 then return l; end if;
  w := public.cfx_redes_wa(p_negocio);
  return case when w is null then l else jsonb_build_array(w) || l end;
exception when others then return coalesce(l, '[]'::jsonb);
end $$;

create or replace function public.cfx_redes_mias() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare n uuid := public.cfx_negocio_cuenta(auth.uid());
begin
  if n is null then return jsonb_build_object('lista', '[]'::jsonb, 'dueno', false); end if;
  return jsonb_build_object('lista', public.cfx_redes_con_wa(n), 'dueno', public.cfx_negocio_dueno(n) = auth.uid());
end $$;

-- G142 c: validar una lista (la usan las redes del negocio y las de cada persona). Lanza error con el link malo.
create or replace function public.cfx_redes_limpiar(p_lista jsonb) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare x jsonb; r text; u text; out jsonb := '[]'::jsonb;
begin
  if p_lista is null or jsonb_typeof(p_lista) <> 'array' then raise exception 'Lista no válida.'; end if;
  if jsonb_array_length(p_lista) > 12 then raise exception 'Máximo 12 redes.'; end if;
  for x in select * from jsonb_array_elements(p_lista) loop
    r := lower(coalesce(x ->> 'red', '')); u := trim(coalesce(x ->> 'url', ''));
    if not public.cfx_red_ok(r, u) then raise exception 'Link no válido para %: %', r, left(u, 80); end if;
    -- G144 d: un solo WhatsApp por lista.
    if r = 'whatsapp' and exists (select 1 from jsonb_array_elements(out) y where y ->> 'red' = 'whatsapp' and y ->> 'url' <> u) then
      raise exception 'Ya tienes un WhatsApp en tus redes: deja uno solo.';
    end if;
    if not exists (select 1 from jsonb_array_elements(out) y where y ->> 'url' = u) then
      out := out || jsonb_build_array(jsonb_build_object('red', r, 'url', u));
    end if;
  end loop;
  return out;
end $$;

create or replace function public.cfx_redes_guardar(p_lista jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.cfx_negocio_cuenta(auth.uid()); out jsonb;
begin
  if auth.uid() is null then raise exception 'Inicia sesión para guardar.'; end if;
  if n is null or public.cfx_negocio_dueno(n) is distinct from auth.uid() then raise exception 'Solo el dueño del negocio cambia sus redes.'; end if;
  out := public.cfx_redes_limpiar(p_lista);
  -- G144 d: si guarda sin WhatsApp habiendo uno en el registro, es porque lo quitó → no se vuelve a poner solo.
  insert into public.cfx_redes (negocio, lista, cambiado, sin_wa) values (n, out, now(),
    not exists (select 1 from jsonb_array_elements(out) y where y ->> 'red' = 'whatsapp') and public.cfx_redes_wa(n) is not null)
  on conflict (negocio) do update set lista = excluded.lista, cambiado = now(), sin_wa = excluded.sin_wa;
  return jsonb_build_object('ok', true, 'lista', out);
end $$;

-- G142 c 📱 Redes POR PERSONA (barbero, mecánico… como Booksy): cada cuenta del equipo de un negocio tiene las suyas.
--   cfx_redes_persona_mias() / cfx_redes_persona_guardar(lista) → las propias (solo quien es parte de un negocio).
--   cfx_redes_equipo(llave) → { "<id de la persona>": [redes] } del equipo de ese negocio (pública, nunca error).
create table if not exists public.cfx_redes_persona (
  cuenta   uuid primary key references auth.users (id) on delete cascade,
  lista    jsonb not null default '[]'::jsonb,
  cambiado timestamptz not null default now()
);
alter table public.cfx_redes_persona enable row level security;
revoke all on public.cfx_redes_persona from anon, authenticated;

create or replace function public.cfx_redes_persona_mias() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('lista', coalesce((select r.lista from public.cfx_redes_persona r where r.cuenta = auth.uid()), '[]'::jsonb), 'dueno', true,
    'equipo', public.cfx_negocio_cuenta(auth.uid()) is not null)
$$;

create or replace function public.cfx_redes_persona_guardar(p_lista jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare out jsonb;
begin
  if auth.uid() is null then raise exception 'Inicia sesión para guardar.'; end if;
  if public.cfx_negocio_cuenta(auth.uid()) is null then raise exception 'Tus redes personales son para quienes atienden en un negocio.'; end if;
  out := public.cfx_redes_limpiar(p_lista);
  insert into public.cfx_redes_persona (cuenta, lista, cambiado) values (auth.uid(), out, now())
  on conflict (cuenta) do update set lista = excluded.lista, cambiado = now();
  return jsonb_build_object('ok', true, 'lista', out);
end $$;

create or replace function public.cfx_redes_equipo(p_llave text) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare n uuid;
begin
  if coalesce(p_llave, '') = '' or length(p_llave) > 120 or to_regprocedure('public.cfx_redes_llave_app(text)') is null then return '{}'::jsonb; end if;
  begin execute 'select public.cfx_redes_llave_app($1)' into n using p_llave; exception when others then return '{}'::jsonb; end;
  if n is null then return '{}'::jsonb; end if;
  return coalesce((select jsonb_object_agg(r.cuenta::text, r.lista) from public.cfx_redes_persona r
    where jsonb_array_length(r.lista) > 0 and public.cfx_negocio_cuenta(r.cuenta) = n), '{}'::jsonb);
exception when others then return '{}'::jsonb;
end $$;

-- Pública: nunca lanza error (llave rara, sin gancho o sin redes → []).
create or replace function public.cfx_redes_publicas(p_llave text) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare n uuid;
begin
  if coalesce(p_llave, '') = '' or length(p_llave) > 120 or to_regprocedure('public.cfx_redes_llave_app(text)') is null then return '[]'::jsonb; end if;
  begin execute 'select public.cfx_redes_llave_app($1)' into n using p_llave; exception when others then return '[]'::jsonb; end;
  if n is null then return '[]'::jsonb; end if;
  return public.cfx_redes_con_wa(n);
end $$;

revoke all on function public.cfx_red_ok(text, text), public.cfx_redes_mias(), public.cfx_redes_guardar(jsonb), public.cfx_redes_publicas(text) from public, anon, authenticated;
revoke all on function public.cfx_redes_wa(uuid), public.cfx_redes_con_wa(uuid) from public, anon, authenticated;
revoke all on function public.cfx_redes_limpiar(jsonb), public.cfx_redes_persona_mias(), public.cfx_redes_persona_guardar(jsonb), public.cfx_redes_equipo(text) from public, anon, authenticated;
grant execute on function public.cfx_redes_persona_mias(), public.cfx_redes_persona_guardar(jsonb) to authenticated;
grant execute on function public.cfx_redes_equipo(text) to anon, authenticated;
grant execute on function public.cfx_redes_mias(), public.cfx_redes_guardar(jsonb) to authenticated;
grant execute on function public.cfx_redes_publicas(text) to anon, authenticated;
-- ---------------------------------------------------------------------
-- CodeFix · G142 b 📚 Catálogo de texto: lo que cada negocio escribe y no estaba en la lista de fábrica (nucleo/catalogo.js)
--   queda en SU lista (marcas, modelos, colores…) y le aparece al autocompletar. Igual en las 7 (lo reparte nucleo/sincronizar.py).
--   cfx_catalogo_mio(lista)          → ['Bici Pepe 3000', …] (las más usadas primero; máx. 300).
--   cfx_catalogo_sumar(lista, valor) → suma o cuenta 1 uso más (máx. 500 por lista y negocio; nunca molesta: sin negocio no hace nada).
-- ---------------------------------------------------------------------
create table if not exists public.cfx_catalogo_propio (
  negocio uuid not null,
  lista   text not null check (lista ~ '^[a-z_]{2,20}$'),
  valor   text not null check (length(valor) between 2 and 60),
  usos    int not null default 1,
  creado  timestamptz not null default now()
);
create unique index if not exists cfx_catalogo_propio_uq on public.cfx_catalogo_propio (negocio, lista, lower(valor));
alter table public.cfx_catalogo_propio enable row level security;
revoke all on public.cfx_catalogo_propio from anon, authenticated;

create or replace function public.cfx_catalogo_mio(p_lista text) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce((select jsonb_agg(valor order by usos desc, creado desc) from (
    select valor, usos, creado from public.cfx_catalogo_propio
    where negocio = public.cfx_negocio_cuenta(auth.uid()) and lista = p_lista order by usos desc, creado desc limit 300) x), '[]'::jsonb)
$$;

create or replace function public.cfx_catalogo_sumar(p_lista text, p_valor text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare n uuid := public.cfx_negocio_cuenta(auth.uid()); v text := regexp_replace(trim(coalesce(p_valor, '')), '[[:cntrl:]]|\s+', ' ', 'g');
begin
  if n is null or coalesce(p_lista, '') !~ '^[a-z_]{2,20}$' or length(v) not between 2 and 60 then return; end if;
  update public.cfx_catalogo_propio set usos = usos + 1 where negocio = n and lista = p_lista and lower(valor) = lower(v);
  if found or (select count(*) from public.cfx_catalogo_propio where negocio = n and lista = p_lista) >= 500 then return; end if;
  insert into public.cfx_catalogo_propio (negocio, lista, valor) values (n, p_lista, v) on conflict do nothing;
end $$;

revoke all on function public.cfx_catalogo_mio(text), public.cfx_catalogo_sumar(text, text) from public, anon;
grant execute on function public.cfx_catalogo_mio(text), public.cfx_catalogo_sumar(text, text) to authenticated;
-- ---------------------------------------------------------------------
-- CodeFix · G142 b 👤 Clientes sin cuenta que después se registran: el negocio crea al cliente con su CORREO (y sus bicis, órdenes…);
--   cuando esa persona CONFIRMA ese correo, cada app le asocia lo suyo con el gancho cfx_reclamar_app(cuenta, correo).
--   🛡️ Nunca sin correo verificado: el disparador solo corre cuando auth.users.email_confirmed_at pasa a tener fecha.
--   Si el gancho falla, el registro sigue igual (nunca bloquea la cuenta).
--   cfx_correo_verificado(correo) → id de la cuenta con ese correo YA confirmado (o null); para asociar al tiro al crear.
-- ---------------------------------------------------------------------
create or replace function public.cfx_correo_verificado(p_correo text) returns uuid
language sql stable security definer set search_path = public, pg_temp as $$
  select u.id from auth.users u where lower(u.email) = lower(trim(coalesce(p_correo, ''))) and length(trim(coalesce(p_correo, ''))) > 3
    and u.email_confirmed_at is not null limit 1
$$;
revoke all on function public.cfx_correo_verificado(text) from public, anon, authenticated;

create or replace function public.cfx_reclamar_correo() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if new.email_confirmed_at is not null and new.email is not null and (tg_op = 'INSERT' or old.email_confirmed_at is null or lower(old.email) is distinct from lower(new.email))
     and to_regprocedure('public.cfx_reclamar_app(uuid, text)') is not null then
    begin
      execute 'select public.cfx_reclamar_app($1, $2)' using new.id, lower(new.email);
    exception when others then null;  -- nunca bloquear el registro
    end;
  end if;
  return new;
end $$;
revoke all on function public.cfx_reclamar_correo() from public, anon, authenticated;
drop trigger if exists zz_cfx_reclamar on auth.users;
create trigger zz_cfx_reclamar after insert or update of email_confirmed_at, email on auth.users
  for each row execute function public.cfx_reclamar_correo();
-- <<< CFX núcleo

-- G95 🎁 Prueba por botón: quien ya tuvo su prueba Pro queda anotado por correo (no se borra) · al probar se marca trial_used.
insert into public.cfx_pruebas_usadas (hash, item)
select public.cfx_hash_correo(p.email), 'pro' from public.profiles p where p.trial_used and nullif(btrim(p.email), '') is not null
on conflict do nothing;
create or replace function public.cfx_pro_prueba_app(p_cuenta uuid, p_rol text, p_dias int) returns timestamptz
language plpgsql security definer set search_path = '' as $$
declare h timestamptz := public.cfx_dar_premium(p_cuenta, p_rol, p_dias);
begin
  update public.profiles set trial_used = true where id = p_cuenta;
  return h;
end $$;
revoke all on function public.cfx_pro_prueba_app(uuid, text, int) from public, anon, authenticated;

-- ---------- VERSIÓN 5.34 · C17 + C18 + B10 (se puede volver a correr) ----------
-- carritos → cfx_carritos y auditoria → cfx_registro: se copian y se borran las tablas viejas.
do $$
begin
  if to_regclass('public.carritos') is not null then
    execute $q$ insert into public.cfx_carritos (cliente, negocio, items, actualizado, avisado)
      select k.cliente_id, k.negocio_id, k.items, k.updated_at, k.avisado_at from public.carritos k
      where exists (select 1 from auth.users u where u.id = k.cliente_id) on conflict do nothing $q$;
    drop table public.carritos;
  end if;
  if to_regclass('public.auditoria') is not null then
    execute $q$ insert into public.cfx_registro (quien, accion, detalle, creado) select 'sistema', left(a.accion, 60), a.detalle, a.created_at from public.auditoria a $q$;
    drop table public.auditoria;
  end if;
end $$;
-- Ganchos del carrito (C17): puede guardar el cliente de la tienda; el aviso solo en tiendas Pro que no están de vacaciones.
create or replace function public.cfx_carrito_puede(u uuid, n uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select public.puede_comprar(u, n) and exists (select 1 from public.profiles where id = u and role = 'client')
$$;
create or replace function public.cfx_carrito_aviso(p_cliente uuid, p_negocio uuid, p_n int) returns boolean
language plpgsql security definer set search_path = '' as $$
declare t text;
begin
  select coalesce(nullif(x.empresa, ''), 'la tienda') into t from public.profiles x join public.profiles c on c.id = p_cliente
    where x.id = p_negocio and not x.suspended and not c.suspended and c.negocio_id = p_negocio and public.pro_o_modulo(x.id, 'carrito') and not public.en_vacaciones(x.id);
  if t is null then return false; end if;
  perform public.notify_user(p_cliente, '🛒 Tu pedido en ' || t || ' te espera',
    'Dejaste ' || p_n || ' producto(s) en el carrito. ¡Termina tu pedido con un toque!', 'apps/catalogo/?v=pedidos');
  return true;
end $$;
revoke all on function public.cfx_carrito_puede(uuid, uuid), public.cfx_carrito_aviso(uuid, uuid, int) from public, anon, authenticated;
-- B10: índices de lo que corre cada minuto (pedidos por liberar, avisos por enviar) y de las listas por cuenta.
create index if not exists pedidos_pagando_idx on public.pedidos (retenido_hasta) where estado = 'pagando';
create index if not exists pedidos_negocio_estado_idx on public.pedidos (negocio_id, estado);
create index if not exists notifications_envio_idx on public.notifications (send_at) where status = 'scheduled';
create index if not exists push_subscriptions_user_idx on public.push_subscriptions (user_id);
create index if not exists requests_user_idx on public.requests (user_id, status);
create index if not exists conexiones_para_idx on public.conexiones (para);
create index if not exists avisos_stock_negocio_idx on public.avisos_stock (negocio_id, clave);
create index if not exists notification_reads_user_idx on public.notification_reads (user_id);
create index if not exists publicacion_vistas_user_idx on public.publicacion_vistas (user_id);
create index if not exists user_invites_negocio_idx on public.user_invites (negocio_id);

-- ---------- VERSIÓN 5.33 · C15 + C16: calificaciones, cupones y sellos pasan al núcleo (se puede volver a correr) ----------
-- calificaciones → cfx_calificaciones (ref = id del pedido), cupones → cfx_descuentos, sellos → cfx_sellos, profiles.sellos_meta/premio → cfx_sellos_cfg.
drop function if exists public.guardar_cupon(text, int, date), public.borrar_cupon(uuid), public.mis_cupones(), public.validar_cupon(uuid, text),
  public.mis_sellos(uuid), public.calificar_pedido(text, int);
do $$
declare f int;
begin
  if to_regclass('public.calificaciones') is not null then
    execute $q$ insert into public.cfx_calificaciones (ref, de_negocio, negocio_id, cliente_id, cliente_ref, estrellas, creado)
      select q.pedido_id::text, q.de_negocio, x.negocio_id, (select u.id from auth.users u where u.id = x.cliente_id),
        case when x.cliente_id is null then x.invitado_tel end, q.estrellas, q.created_at
      from public.calificaciones q join public.pedidos x on x.id = q.pedido_id
      on conflict (ref, de_negocio) do nothing $q$;
    drop table public.calificaciones;
  end if;
  if to_regclass('public.cupones') is not null then
    execute $q$ insert into public.cfx_descuentos (id, owner_id, codigo, porcentaje, hasta, activo, usos, creado)
      select c.id, c.owner_id, c.codigo, c.porcentaje, c.hasta, c.activo, c.usos, c.created_at from public.cupones c
      where c.codigo ~ '^[A-Z0-9]{3,20}$' on conflict do nothing $q$;
    execute $q$ select count(*) from public.cupones c where not exists (select 1 from public.cfx_descuentos d where d.owner_id = c.owner_id and d.codigo = c.codigo) $q$ into f;
    if f = 0 then drop table public.cupones; else raise notice 'cupones: % sin copiar, la tabla queda', f; end if;
  end if;
  if to_regclass('public.sellos') is not null then
    execute $q$ insert into public.cfx_sellos (negocio_id, cliente_id, cantidad, premios)
      select s.negocio_id, s.cliente_id, s.cantidad, s.premios from public.sellos s
      where exists (select 1 from auth.users u where u.id = s.cliente_id) on conflict do nothing $q$;
    drop table public.sellos;
  end if;
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'profiles' and column_name = 'sellos_meta') then
    execute $q$ insert into public.cfx_sellos_cfg (owner_id, meta, premio)
      select p.id, p.sellos_meta, nullif(left(trim(coalesce(p.sellos_premio, '')), 80), '') from public.profiles p
      where p.sellos_meta between 2 and 30 on conflict do nothing $q$;
    alter table public.profiles drop column sellos_meta, drop column if exists sellos_premio;
  end if;
end $$;

-- Lo que leen las pantallas, ahora desde el núcleo (con el módulo apagado: sin estrellas, sin "Califica" y sin tarjeta).
create or replace function public.estrellas_tienda(n uuid) returns jsonb
language sql stable security definer set search_path = '' as $$ select public.cfx_calif_negocio(n) $$;

create or replace function public.tienda_info(p_negocio uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('id', t.id, 'empresa', t.empresa, 'slug', t.slug,
    'telefono', t.telefono, 'datos_pago', t.datos_pago, 'horario', t.horario, 'abierto', t.abierto,
    'sellos_meta', (s.c ->> 'meta')::int, 'sellos_premio', s.c ->> 'premio',
    'pro', public.is_pro(t.id), 'logo', t.logo, 'color', t.color,
    'vacaciones_hasta', case when public.en_vacaciones(t.id) then t.vacaciones_hasta end,
    'vacaciones_msg', case when public.en_vacaciones(t.id) then t.vacaciones_msg end,
    'estrellas', public.estrellas_tienda(t.id), 'cobra_online', public.link_activo(t.id, 'pedido') is not null,
    'cobra_mp', coalesce((public.link_activo(t.id, 'pedido') ->> 'mp')::boolean, false),
    'desc_premium', t.desc_premium, 'rubro', t.rubro, 'despacho', t.despacho, 'perfil', t.perfil, 'desde', t.created_at::date,
    'verificado', exists (select 1 from public.cfx_verificaciones v where v.cuenta = t.id and v.estado = 'aprobada'))  -- G154 ✓ tienda verificada
  from public.profiles t cross join lateral (select public.cfx_sellos_cfg_de(t.id) as c) s
  where t.id = p_negocio and (public.puede_comprar(auth.uid(), t.id) or public.negocio_de(auth.uid()) = t.id or public.is_admin())
$$;

create or replace function public.mis_pedidos(p_negocio uuid default null)
returns table (id uuid, negocio text, lineas jsonb, subtotal numeric, descuento numeric, total numeric, cupon text,
               entrega text, direccion text, nota text, estado text, fecha timestamptz, actualizado timestamptz,
               retenido_hasta timestamptz, tiene_comprobante boolean, devolucion text, calificado boolean, token text,
               desc_premium numeric, motivo text, rechazos int, boleta jsonb)
language sql stable security definer set search_path = '' as $$
  select x.id, t.empresa, x.lineas, x.subtotal, x.descuento, x.total, x.cupon,
         x.entrega, x.direccion, x.nota, x.estado, x.created_at, x.updated_at, x.retenido_hasta, x.comprobante is not null, x.devolucion,
         public.cfx_calif_hecha(x.id::text, false), x.token, x.desc_premium, x.motivo, x.rechazos,
         case when x.boleta_folio is not null then public.boleta_de(x) end
  from public.pedidos x join public.profiles t on t.id = x.negocio_id
  where x.cliente_id = auth.uid() and (p_negocio is null or x.negocio_id = p_negocio)
  order by x.created_at desc limit 50
$$;

create or replace function public.pedidos_tienda(p_estado text default null)
returns table (id uuid, cliente_id uuid, cliente text, telefono text, lineas jsonb, subtotal numeric, descuento numeric,
               total numeric, cupon text, entrega text, direccion text, nota text, estado text, fecha timestamptz,
               retenido_hasta timestamptz, tiene_comprobante boolean, devolucion text, invitado boolean, calificado boolean, cliente_estrellas numeric,
               premium boolean, desc_premium numeric, rechazos int, motivo text, boleta jsonb, medio text)
language sql stable security definer set search_path = '' as $$
  select x.id, x.cliente_id, coalesce(nullif(c.empresa, ''), split_part(c.email, '@', 1), x.invitado_nombre, 'Cliente'),
         coalesce(c.telefono, x.invitado_tel), x.lineas, x.subtotal, x.descuento, x.total, x.cupon, x.entrega, x.direccion, x.nota, x.estado,
         x.created_at, x.retenido_hasta, x.comprobante is not null, x.devolucion, x.cliente_id is null,
         public.cfx_calif_hecha(x.id::text, true),
         (public.cfx_calif_cliente(x.cliente_id, case when x.cliente_id is null then x.invitado_tel end) ->> 'promedio')::numeric,
         pr.premium, x.desc_premium, x.rechazos, x.motivo, public.boleta_de(x),
         case when x.mp_pago is not null then 'mercadopago' when x.comprobante_at is not null then 'transferencia' end
  from public.pedidos x left join public.profiles c on c.id = x.cliente_id
  cross join lateral (select c.role = 'client' and public.is_pro(c.id) as premium) pr
  where x.negocio_id = public.negocio_de(auth.uid())
    and (p_estado is null or (p_estado = 'activos' and x.estado in ('recibido', 'preparando', 'listo', 'en_camino'))
         or (p_estado = 'revisar' and x.estado = 'en_revision') or (p_estado = 'pagando' and x.estado = 'pagando')
         or (p_estado = 'devolver' and x.devolucion = 'pendiente')
         or (p_estado = 'historial' and x.estado in ('entregado', 'cancelado', 'rechazado', 'expirado')) or x.estado = p_estado)
  -- ⭐ Los pedidos pendientes de clientes Premium van primero en la fila.
  order by (coalesce(pr.premium, false) and x.estado in ('pagando', 'en_revision', 'recibido', 'preparando', 'listo', 'en_camino')) desc, x.created_at desc
  limit 300
$$;

-- Al borrar una tienda o un pedido, se borra lo suyo en el núcleo (antes lo hacía la clave foránea).
create or replace function public.borrar_fidelidad() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_table_name = 'profiles' then
    perform public.cfx_fid_borrar(old.id);
    perform public.cfx_calif_borrar(old.id);
    perform public.cfx_carrito_borrar(old.id);
    perform public.cfx_modulos_borrar(old.id);
  else
    perform public.cfx_calif_borrar(old.negocio_id, old.id::text);
  end if;
  return old;
end $$;
revoke all on function public.borrar_fidelidad() from public, anon, authenticated;
drop trigger if exists borrar_fidelidad on public.profiles;
create trigger borrar_fidelidad after delete on public.profiles for each row execute function public.borrar_fidelidad();
drop trigger if exists borrar_fidelidad on public.pedidos;
create trigger borrar_fidelidad after delete on public.pedidos for each row execute function public.borrar_fidelidad();

-- ---------- VERSIÓN 5.32 · C14: el chat pasa al núcleo. messages/blocks/reports → cfx_mensajes/cfx_bloqueos/cfx_reportes (se puede volver a correr) ----------
drop function if exists public.chat_remaining(uuid), public.send_message(uuid, text), public.chat_list(), public.chat_messages(uuid),
  public.block_contact(uuid, boolean), public.report_message(uuid, text), public.admin_resolve_report(uuid, boolean), public.chat_borrar(uuid);
do $$
declare f int;
begin
  if to_regclass('public.messages') is not null then
    execute $q$ insert into public.cfx_mensajes (id, de, para, texto, creado, leido)
      select m.id, m.sender, m.recipient, m.body, m.created_at, m.read_at from public.messages m
      where exists (select 1 from auth.users u where u.id = m.sender) and exists (select 1 from auth.users u where u.id = m.recipient)
      on conflict (id) do nothing $q$;
  end if;
  if to_regclass('public.blocks') is not null then
    execute $q$ insert into public.cfx_bloqueos (quien, a, creado)
      select b.blocker, b.blocked, b.created_at from public.blocks b
      where exists (select 1 from auth.users u where u.id = b.blocker) and exists (select 1 from auth.users u where u.id = b.blocked)
      on conflict do nothing $q$;
    drop table public.blocks;
  end if;
  if to_regclass('public.reports') is not null then
    execute $q$ insert into public.cfx_reportes (id, quien, a, mensaje, motivo, extracto, resuelto, creado)
      select r.id, r.reporter, r.reported, (select x.id from public.cfx_mensajes x where x.id = r.message_id), r.reason, coalesce(r.excerpt, ''), r.resolved, r.created_at
      from public.reports r
      where exists (select 1 from auth.users u where u.id = r.reporter) and exists (select 1 from auth.users u where u.id = r.reported)
      on conflict (id) do nothing $q$;
    drop table public.reports;
  end if;
  if to_regclass('public.messages') is not null then
    execute $q$ select count(*) from public.messages m where not exists (select 1 from public.cfx_mensajes x where x.id = m.id)
      and exists (select 1 from auth.users u where u.id = m.sender) and exists (select 1 from auth.users u where u.id = m.recipient) $q$ into f;
    if f = 0 then drop table public.messages; else raise notice 'messages: % sin copiar, la tabla queda', f; end if;
  end if;
end $$;

-- ---------- VERSIÓN 5.30 · A5: copiar las tablas viejas a las del núcleo y borrarlas (se puede volver a correr) ----------
drop function if exists public.admin_create_license(text, int, numeric, text), public.admin_revoke_license(uuid), public.admin_stats(),
  public.puede_resenar(uuid, uuid), public.dejar_resena(uuid, int, text), public.ver_resenas(uuid), public.responder_resena(uuid, text),
  public.destacar_resena(uuid, boolean), public.subir_pago_premium(text), public.subir_pago_premium(text, boolean), public.mis_pagos(),
  public.admin_pagos(text), public.admin_pago_comprobante(uuid), public.admin_revisar_pago(uuid, boolean, text),
  public.admin_revisar_pago(uuid, boolean, text, int);
do $$
declare n int; f int;
begin
  -- 🔑 Keys: las sin usar siguen sirviendo (mismo código); las usadas quedan como historial.
  if to_regclass('public.licenses') is not null then
    execute $q$ insert into public.cfx_keys (hash, ultimos, rol, dias, nota, creado, usada_por, usada_email, usada_at, revocada)
      select encode(sha256(convert_to(upper(l.key), 'UTF8')), 'hex'), right(l.key, 4), 'negocio', least(3660, coalesce(l.months * 31, 3660)),
        left('Key antigua · ' || l.empresa || coalesce(' · ' || l.note, ''), 300), l.created_at, l.redeemed_by, u.email, l.redeemed_at, l.revoked
      from public.licenses l left join auth.users u on u.id = l.redeemed_by
      on conflict (hash) do nothing $q$;
    execute $q$ select count(*) from public.licenses l where not exists (select 1 from public.cfx_keys k where k.hash = encode(sha256(convert_to(upper(l.key), 'UTF8')), 'hex')) $q$ into f;
    if f = 0 then drop table public.licenses; else raise notice 'licenses: % keys sin copiar, la tabla queda', f; end if;
  end if;
  -- 💰 Pagos Premium con comprobante: los "en revisión" quedan pendientes en el Centro de Mando → Pagos.
  if to_regclass('public.pagos') is not null then
    execute $q$ insert into public.cfx_pagos (id, cuenta, email, nombre, rol, periodo, monto, medio, nota, comprobante, estado, dias, motivo, creado, resuelto)
      select g.id, g.user_id, coalesce(p.email, ''), coalesce(nullif(p.empresa, ''), p.email, ''), case when g.tipo = 'premium_cliente' then 'cliente' else 'negocio' end,
        case when coalesce(to_jsonb(g) ->> 'anual', 'false')::boolean then 'anual' else 'mensual' end, least(100000000, greatest(1, coalesce(g.monto, 1))),
        'transferencia', 'Pago anterior a Pagos del núcleo',
        case when g.estado = 'en_revision' and g.comprobante ~ '^data:image/(jpeg|png|webp);base64,' and length(g.comprobante) <= 400000 then g.comprobante end,
        case when g.estado = 'en_revision' then 'pendiente' else g.estado end, g.dias, coalesce(g.motivo, ''), g.created_at, g.revisado_at
      from public.pagos g left join public.profiles p on p.id = g.user_id
      on conflict (id) do nothing $q$;
    execute $q$ select count(*) from public.pagos g where not exists (select 1 from public.cfx_pagos c where c.id = g.id) $q$ into f;
    if f = 0 then drop table public.pagos; else raise notice 'pagos: % sin copiar, la tabla queda', f; end if;
  end if;
  -- ⭐ Reseñas viejas (sin pantalla): se guardan en el registro del Centro de Mando y se borra la tabla. Las estrellas siguen en calificaciones.
  if to_regclass('public.resenas') is not null then
    execute $q$ insert into public.cfx_registro (quien, accion, detalle)
      select 'sistema', 'reseña archivada', left(jsonb_build_object('tienda', t.empresa, 'autor', a.empresa, 'estrellas', r.estrellas, 'texto', r.texto,
        'respuesta', r.respuesta, 'fecha', r.created_at)::text, 400)
      from public.resenas r left join public.profiles t on t.id = r.negocio_id left join public.profiles a on a.id = r.autor_id $q$;
    get diagnostics n = row_count;
    drop table public.resenas;
    if n > 0 then raise notice 'resenas: % archivadas en cfx_registro', n; end if;
  end if;
end $$;

-- =====================================================================
--  Envío automático: cada minuto llama a la función "enviar".
--  (Viene incluido aquí: no hay que pegarlo aparte. Requiere la Edge Function "enviar".)
-- =====================================================================
create extension if not exists pg_cron with schema pg_catalog;
create extension if not exists pg_net with schema extensions;

select cron.unschedule(jobid) from cron.job where jobname = 'enviar-notificaciones';

select cron.schedule(
  'enviar-notificaciones',
  '* * * * *',
  $$
  select net.http_post(
    url := 'https://gilsamacgappycibcqhq.supabase.co/functions/v1/enviar',
    headers := '{"Content-Type": "application/json"}'::jsonb,
    body := '{}'::jsonb
  );
  $$
);

-- Cada día (10:00 hora de Chile aprox.): avisa a quienes se les vence el plan (15 y 5 días antes, editable en Reglas).
select cron.unschedule(jobid) from cron.job where jobname = 'avisar-vencimientos';
select cron.schedule('avisar-vencimientos', '0 13 * * *', $$ select public.avisar_vencimientos(); $$);

-- Cada día (madrugada en Chile): borra avisos y mensajes de más de 30 días (avisa antes). Los pedidos no se tocan.
select cron.unschedule(jobid) from cron.job where jobname = 'limpiar-registros';
select cron.schedule('limpiar-registros', '0 8 * * *', $$ select public.limpiar_registros(); $$);

-- Cada hora: si subí una versión nueva de la app, te llega un aviso para tocar "Actualizar".
create extension if not exists http with schema extensions;
select cron.unschedule(jobid) from cron.job where jobname = 'avisar-version';
select cron.schedule('avisar-version', '17 * * * *', $$ select public.avisar_version_nueva(); $$);

-- Cada minuto: los pedidos sin comprobante a tiempo se liberan solos.
select cron.unschedule(jobid) from cron.job where jobname = 'expirar-retenciones';
select cron.schedule('expirar-retenciones', '* * * * *', $$ select public.expirar_retenciones(); $$);
-- Cada día: borra comprobantes viejos y pedidos expirados (los demás registros ya los limpia "limpiar-registros").
select cron.unschedule(jobid) from cron.job where jobname = 'limpiar-comprobantes';
select cron.schedule('limpiar-comprobantes', '10 8 * * *', $$ select public.limpiar('comprobantes'); select public.limpiar('pedidos'); $$);
-- Recordatorio de carritos: desde 5.34 lo hace el núcleo ('cfx-carritos', módulo 🛒 Recordar carrito).
select cron.unschedule(jobid) from cron.job where jobname = 'recordar-carritos';
-- Cada lunes (9:00 de Chile aprox.): reporte semanal de ventas a las tiendas Pro.
select cron.unschedule(jobid) from cron.job where jobname = 'reporte-semanal';
-- =====================================================================
-- Actualización automática (núcleo CodeFix): cada 10 minutos la base revisa GitHub (rama main).
--   · Si hay una base nueva (version.json), descarga y ejecuta este mismo instalar.sql (no borra datos).
--   · La app la liberas tú cuando la pruebes (panel de la app o Centro de Mando → Liberar).
--   Si algo falla no cambia nada y lo reintenta en la siguiente vuelta. Hay que correr este archivo UNA vez.
-- =====================================================================
create or replace function public.auto_actualizar() returns text
language plpgsql security definer set search_path = '' as $f$
declare
  base constant text := 'https://raw.githubusercontent.com/CodeFixService/Aplicaciones/main/';
  marca text := '?t=' || extract(epoch from now())::bigint; j jsonb; v_bd text; v_app text; codigo text; lib text;
  re constant text := '^[0-9]+(\.[0-9]+)*$';
begin
  execute 'select content from extensions.http_get($1)' into codigo using base || 'version.json' || marca;
  j := codigo::jsonb; v_bd := j ->> 'bd'; v_app := j ->> 'version';
  if v_bd ~ re and coalesce((public.db_version())::text, '0') ~ re and string_to_array(v_bd, '.')::int[] > string_to_array(coalesce((public.db_version())::text, '0'), '.')::int[] then
    execute 'select content from extensions.http_get($1)' into codigo using base || 'supabase/instalar.sql' || marca;
    if codigo is null or length(codigo) < 1000 then return 'instalar.sql no disponible'; end if;
    execute codigo;
    return 'base actualizada a ' || (public.db_version())::text;
  end if;
  -- La app NO se libera sola: la liberas tú desde el panel o el Centro de Mando después de probarla.
  return 'al día';
exception when others then
  return 'sin cambios: ' || sqlerrm;
end $f$;
revoke execute on function public.auto_actualizar() from public, anon, authenticated;
do $$
begin
  create extension if not exists http with schema extensions;
  perform cron.unschedule(jobid) from cron.job where jobname = 'cfx-auto';
  perform cron.schedule('cfx-auto', '*/10 * * * *', 'select public.auto_actualizar()');
exception when others then
  raise notice 'Actualización automática no activada (%). Activa pg_cron en Supabase y vuelve a correr este archivo.', sqlerrm;
end $$;

select cron.schedule('reporte-semanal', '7 12 * * 1', $$ select public.reporte_semanal(); $$);

-- ---------- VERSIÓN 5.41 · Lanzamiento: 📄 políticas, 📦 despacho a todo Chile, 🚚 seguimiento, ✉️ correo al comprador, 📊 medir anuncios y 🌐 dominio propio (se puede volver a correr) ----------
alter table public.pedidos add column if not exists invitado_correo text;
alter table public.pedidos add column if not exists envio_courier text;
alter table public.pedidos add column if not exists envio_codigo text;
alter table public.pedidos add column if not exists envio_link text;
alter table public.pedidos add column if not exists envio_por_pagar boolean not null default false;
alter table public.profiles add column if not exists medicion jsonb not null default '{}'::jsonb;
alter table public.profiles add column if not exists dominio text;
create unique index if not exists profiles_dominio_idx on public.profiles (dominio) where dominio is not null;
alter table public.notifications add column if not exists email_directo text;
alter table public.notifications add column if not exists nombre_directo text;
alter table public.notifications drop constraint if exists notifications_audience_check;
alter table public.notifications add constraint notifications_audience_check
  check (audience in ('all_users', 'all_businesses', 'pro_users', 'free_users', 'all_clients', 'my_subscribers', 'self', 'direct', 'correo'));

-- ✉️ 'correo' = un correo a una persona (comprador sin cuenta o cliente): no sale en ninguna bandeja; la Edge Function "enviar" lo manda igual que los demás.
create or replace function public.notification_targets(p_id uuid)
returns table (endpoint text, p256dh text, auth text, email text, nombre text)
language plpgsql stable security definer set search_path = '' as $$
declare n public.notifications;
begin
  select * into n from public.notifications where id = p_id;
  if n.audience = 'correo' then
    return query select null::text, null::text, null::text, n.email_directo, n.nombre_directo where coalesce(n.email_directo, '') <> '';
  elsif n.audience = 'my_subscribers' then
    return query
      select s.endpoint, s.p256dh, s.auth, s.email, s.nombre
        from public.subscribers s where s.negocio_id = n.owner_id and not coalesce(n.solo_premium, false)
      union all
      select ps.endpoint, ps.p256dh, ps.auth, null::text, c.empresa
        from public.profiles c join public.push_subscriptions ps on ps.user_id = c.id
        where c.negocio_id = n.owner_id and c.role = 'client' and not c.suspended and not c.mute_offers
          and (not coalesce(n.solo_premium, false) or public.is_pro(c.id))
      union all
      select null, null, null, c.email, c.empresa from public.profiles c
        where c.negocio_id = n.owner_id and c.role = 'client' and not c.suspended and not c.mute_offers
          and (not coalesce(n.solo_premium, false) or public.is_pro(c.id));
  elsif n.audience = 'direct' then
    return query select ps.endpoint, ps.p256dh, ps.auth, null::text, null::text
      from public.push_subscriptions ps where ps.user_id = n.target_id;
  elsif n.audience = 'self' then
    return query
      select ps.endpoint, ps.p256dh, ps.auth, null::text, null::text
        from public.push_subscriptions ps where ps.user_id = n.owner_id
      union all
      select null, null, null, p.email, p.empresa from public.profiles p where p.id = n.owner_id;
  else
    return query
      with users as (
        select p.id, p.email, p.empresa from public.profiles p
        where not p.suspended and p.role <> 'admin'
          and (n.audience = 'all_users'
               or (n.audience = 'all_businesses' and p.role = 'user')
               or (n.audience = 'pro_users' and p.role = 'user' and public.is_pro(p.id))
               or (n.audience = 'free_users' and p.role = 'user' and not public.is_pro(p.id))
               or (n.audience = 'all_clients' and p.role = 'client'))
      )
      select ps.endpoint, ps.p256dh, ps.auth, null::text, u.empresa
        from users u join public.push_subscriptions ps on ps.user_id = u.id
      union all
      select null, null, null, u.email, u.empresa from users u;
  end if;
end $$;
revoke all on function public.notification_targets(uuid) from public, anon, authenticated;

-- 🚚 Link del courier para seguir el envío (o el link que pegó la tienda).
create or replace function public.envio_link(p_courier text, p_codigo text, p_link text) returns text
language sql immutable set search_path = '' as $$
  select case when coalesce(p_codigo, '') = '' and coalesce(p_link, '') = '' then null
    when coalesce(p_link, '') <> '' then p_link
    when p_courier = 'starken' then 'https://www.starken.cl/seguimiento?codigo=' || p_codigo
    when p_courier = 'chilexpress' then 'https://centrodeayuda.chilexpress.cl/seguimiento/' || p_codigo
    when p_courier = 'blue' then 'https://www.blue.cl/seguimiento/?n_seguimiento=' || p_codigo
    when p_courier = 'correos' then 'https://www.correos.cl/web/guest/seguimiento-en-linea?codigos=' || p_codigo end
$$;
create or replace function public.envio_de(x public.pedidos) returns jsonb
language sql stable set search_path = '' as $$
  select case when x.envio_codigo is not null or x.envio_link is not null or x.envio_por_pagar then jsonb_build_object(
    'courier', x.envio_courier, 'nombre', case x.envio_courier when 'starken' then 'Starken' when 'chilexpress' then 'Chilexpress' when 'blue' then 'Blue Express'
      when 'correos' then 'Correos de Chile' when 'propio' then 'Reparto de la tienda' else 'Courier' end,
    'codigo', x.envio_codigo, 'link', public.envio_link(x.envio_courier, x.envio_codigo, x.envio_link), 'por_pagar', x.envio_por_pagar) end
$$;

-- La tienda (o su equipo con Pedidos) anota el courier y el código. Si el pedido estaba preparándose o listo, pasa a "en camino" (avisa al cliente).
create or replace function public.pedido_seguimiento(p_id uuid, p_courier text, p_codigo text, p_link text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare x public.pedidos; c text := lower(coalesce(nullif(trim(p_courier), ''), 'otro')); k text := nullif(upper(regexp_replace(coalesce(p_codigo, ''), '\s', '', 'g')), '');
  l text := nullif(trim(coalesce(p_link, '')), ''); t text;
begin
  if not public.equipo_puede('pedidos') then raise exception 'Sin permiso'; end if;
  select * into x from public.pedidos where id = p_id and negocio_id = public.negocio_de(auth.uid());
  if x.id is null then raise exception 'Pedido no encontrado'; end if;
  if x.entrega <> 'despacho' then raise exception 'Este pedido es con retiro en tienda'; end if;
  if x.estado in ('cancelado', 'rechazado', 'expirado', 'pagando', 'en_revision') then raise exception 'Este pedido no está para enviar'; end if;
  if c not in ('starken', 'chilexpress', 'blue', 'correos', 'propio', 'otro') then raise exception 'Courier no válido'; end if;
  if k is not null and k !~ '^[A-Z0-9-]{4,40}$' then raise exception 'El código de seguimiento lleva solo letras, números y guiones (4 a 40)'; end if;
  if l is not null and (l !~* '^https://[^\s<>"'']+$' or length(l) > 300) then raise exception 'El link debe empezar con https://'; end if;
  if k is null and l is null and c <> 'propio' then raise exception 'Escribe el código de seguimiento'; end if;
  update public.pedidos set envio_courier = c, envio_codigo = k, envio_link = l, updated_at = now() where id = x.id returning * into x;
  if x.estado in ('recibido', 'preparando', 'listo') then
    perform public.actualizar_pedido(x.id, 'en_camino');
  else
    select coalesce(nullif(empresa, ''), 'Tu tienda') into t from public.profiles where id = x.negocio_id;
    perform public.aviso_cliente(x, '🚚 Sigue tu envío', t || ' · ' || coalesce((public.envio_de(x)) ->> 'nombre', '') || coalesce(' · ' || k, ''));
  end if;
  return public.envio_de((select p from public.pedidos p where p.id = x.id));
end $$;
revoke all on function public.envio_link(text, text, text), public.envio_de(public.pedidos) from public, anon, authenticated;
revoke all on function public.pedido_seguimiento(uuid, text, text, text) from public, anon;
grant execute on function public.pedido_seguimiento(uuid, text, text, text) to authenticated;

-- 📦 Envío "por pagar": queda anotado en el pedido (la tienda lo ve y el cliente también).
create or replace function public.pedido_por_pagar() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  begin
    if new.entrega = 'despacho' and coalesce(new.costo_despacho, 0) = 0 then
      new.envio_por_pagar := coalesce((public.costo_despacho(new.negocio_id, new.entrega, new.direccion, new.subtotal) ->> 'por_pagar')::boolean, false);
    end if;
  exception when others then null;
  end;
  return new;
end $$;
revoke all on function public.pedido_por_pagar() from public, anon, authenticated;
drop trigger if exists pedido_por_pagar on public.pedidos;
create trigger pedido_por_pagar before insert on public.pedidos for each row execute function public.pedido_por_pagar();

-- G42f ✉️ Correo propio del negocio: lo que el negocio manda a SUS clientes sale con SU Gmail (nunca con el de CodeFix).
-- La clave se guarda solo para el servidor: ninguna pantalla la puede volver a leer.
create table if not exists public.negocio_correo (
  negocio_id  uuid primary key references public.profiles (id) on delete cascade,
  usuario     text not null,
  clave       text not null,
  nombre      text not null default '',
  actualizado timestamptz not null default now()
);
alter table public.negocio_correo enable row level security;  -- sin políticas = nadie salvo el servidor
revoke all on table public.negocio_correo from anon, authenticated;

create or replace function public.tapar_correo(e text) returns text
language sql immutable set search_path = '' as $$
  select case when coalesce(e, '') !~ '@' then '' else left(e, 1) || '•••' || substring(e from position('@' in e)) end
$$;

create or replace function public.mi_correo() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare x public.negocio_correo;
begin
  if not public.is_business(auth.uid()) then return jsonb_build_object('ok', false, 'error', 'Solo las tiendas'); end if;
  select * into x from public.negocio_correo where negocio_id = auth.uid();
  return jsonb_build_object('ok', true, 'configurado', x.negocio_id is not null, 'usuario', public.tapar_correo(x.usuario), 'nombre', coalesce(x.nombre, ''));
end $$;

create or replace function public.mi_correo_guardar(p_usuario text, p_clave text, p_nombre text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare u text := lower(trim(coalesce(p_usuario, ''))); k text := regexp_replace(coalesce(p_clave, ''), '\s', '', 'g');
begin
  if not public.is_business(auth.uid()) then return jsonb_build_object('ok', false, 'error', 'Solo las tiendas'); end if;
  if u !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' or length(u) > 120 then return jsonb_build_object('ok', false, 'error', 'Revisa tu Gmail'); end if;
  if k !~ '^[A-Za-z]{16}$' then return jsonb_build_object('ok', false, 'error', 'La contraseña de aplicación tiene 16 letras'); end if;
  insert into public.negocio_correo (negocio_id, usuario, clave, nombre, actualizado)
  values (auth.uid(), u, k, left(trim(coalesce(p_nombre, '')), 60), now())
  on conflict (negocio_id) do update set usuario = excluded.usuario, clave = excluded.clave, nombre = excluded.nombre, actualizado = now();
  return jsonb_build_object('ok', true, 'usuario', public.tapar_correo(u));
end $$;

create or replace function public.mi_correo_quitar() returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  if not public.is_business(auth.uid()) then return jsonb_build_object('ok', false, 'error', 'Solo las tiendas'); end if;
  delete from public.negocio_correo where negocio_id = auth.uid();
  return jsonb_build_object('ok', true);
end $$;

-- Para la función "enviar": con qué Gmail sale cada notificación. CodeFix (admin) → el de Control → ✉️ Correo; negocio → el suyo; sin él → null (no se manda correo).
create or replace function public.notif_correo(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare o uuid; r text; x public.negocio_correo;
begin
  select n.owner_id, p.role into o, r from public.notifications n left join public.profiles p on p.id = n.owner_id where n.id = p_id;
  if o is null then return null; end if;
  if r = 'admin' then
    return (select case when count(*) filter (where name in ('gmail_user', 'gmail_app_password') and coalesce(value, '') <> '') = 2
      then jsonb_build_object('usuario', max(value) filter (where name = 'gmail_user'), 'clave', max(value) filter (where name = 'gmail_app_password'),
        'nombre', coalesce(max(value) filter (where name = 'mail_from_name'), 'CodeFix'), 'propio', false) end from public.app_secrets);
  end if;
  select * into x from public.negocio_correo where negocio_id = o;
  if x.negocio_id is null then return null; end if;
  return jsonb_build_object('usuario', x.usuario, 'clave', x.clave, 'nombre', coalesce(nullif(x.nombre, ''), (select nullif(empresa, '') from public.profiles where id = o), 'Tu tienda'), 'propio', true);
end $$;

revoke all on function public.notif_correo(uuid) from public, anon, authenticated;
revoke all on function public.tapar_correo(text) from public, anon;
revoke all on function public.mi_correo(), public.mi_correo_guardar(text, text, text), public.mi_correo_quitar() from public, anon;
grant execute on function public.mi_correo(), public.mi_correo_guardar(text, text, text), public.mi_correo_quitar() to authenticated;

-- ✉️ Correo al comprador: al hacer el pedido y en cada cambio de estado (solo si la tienda puso SU correo: Mi tienda → ✉️ Correo). Nunca rompe el pedido.
create or replace function public.pedido_correo() returns trigger
language plpgsql security definer set search_path = '' as $$
declare dest text; nom text; t public.profiles; tit text; cab text; res text; url text; env jsonb; resumen boolean := false;
begin
  begin
    if not exists (select 1 from public.negocio_correo where negocio_id = new.negocio_id) then return null; end if;
    dest := coalesce(new.invitado_correo, (select c.email from public.profiles c where c.id = new.cliente_id and c.role = 'client'));
    if coalesce(dest, '') = '' then return null; end if;
    if tg_op = 'INSERT' then resumen := new.estado in ('pagando', 'recibido');
    elsif new.invitado_correo is distinct from old.invitado_correo then resumen := true;
    elsif new.envio_codigo is distinct from old.envio_codigo or new.envio_link is distinct from old.envio_link then
      if not (old.estado = 'en_camino' and new.estado = 'en_camino') then return null; end if;
    elsif new.estado is not distinct from old.estado then return null;
    end if;
    select * into t from public.profiles where id = new.negocio_id;
    nom := coalesce(nullif(t.empresa, ''), 'La tienda');
    env := public.envio_de(new);
    tit := case when resumen and new.estado = 'pagando' then '🛒 Tu pedido en ' || nom || ' está apartado'
      when resumen then '📦 ' || nom || ' recibió tu pedido'
      else case new.estado when 'recibido' then '📦 ' || nom || ' recibió tu pedido' when 'preparando' then '👨‍🍳 ' || nom || ' está preparando tu pedido'
        when 'listo' then '✅ Tu pedido está listo para retirar' when 'en_camino' then '🚚 Tu pedido va en camino'
        when 'entregado' then '🎉 Pedido entregado. ¡Gracias por tu compra!' when 'cancelado' then '❌ Tu pedido fue cancelado'
        when 'rechazado' then '❌ No pudimos confirmar tu pago' end end;
    if tit is null then return null; end if;
    cab := case when resumen and new.estado = 'pagando' then 'Paga antes de las ' || to_char(new.retenido_hasta at time zone 'America/Santiago', 'HH24:MI') || ' para confirmarlo.'
      when new.estado = 'entregado' then 'Cuéntanos cómo te fue: califica tu compra en el link.'
      when new.estado = 'rechazado' then coalesce('Motivo: ' || nullif(new.motivo, ''), 'Escríbele a la tienda para resolverlo.')
      else '' end;
    if env is not null and new.estado = 'en_camino' then
      cab := trim(cab || E'\n' || (env ->> 'nombre') || coalesce(' · código ' || (env ->> 'codigo'), '') || coalesce(E'\nSigue tu envío: ' || (env ->> 'link'), ''));
    end if;
    if coalesce((env ->> 'por_pagar')::boolean, false) then cab := trim(cab || E'\n📦 Envío por pagar: lo pagas al recibir.'); end if;
    res := (select string_agg((l ->> 'cant') || ' × ' || (l ->> 'nombre') || coalesce(' (' || nullif(l ->> 'opcion', '') || ')', ''), E'\n')
            from (select l from jsonb_array_elements(new.lineas) l limit 8) z);
    url := coalesce(public.cfx_sitio_url(), (select value from public.app_settings where key = 'app_url'), 'https://aplicaciones.juanjosuecastilloloyola.workers.dev/');
    url := regexp_replace(url, '/?$', '/') || 'r/?t=' || new.token;
    insert into public.notifications (owner_id, audience, channels, title, body, url, send_at, email_directo, nombre_directo)
    values (new.negocio_id, 'correo', '{email}', left(tit, 80),
      left(trim(cab || E'\n\n' || coalesce(res, '') || E'\nTotal: $' || to_char(new.total, 'FM999G999G999') || E'\n' ||
        case when new.entrega = 'despacho' then '🚚 Despacho a ' || coalesce(new.direccion, '') else '🏪 Retiro en tienda' end), 1200),
      url, now(), dest, coalesce(new.invitado_nombre, (select c.empresa from public.profiles c where c.id = new.cliente_id)));
  exception when others then null;
  end;
  return null;
end $$;
revoke all on function public.pedido_correo() from public, anon, authenticated;
drop trigger if exists pedido_correo on public.pedidos;
create trigger pedido_correo after insert or update of estado, invitado_correo, envio_codigo, envio_link on public.pedidos for each row execute function public.pedido_correo();

-- El comprador sin cuenta deja su correo después de pedir (con el enlace secreto del pedido). Una sola vez por pedido.
create or replace function public.pedido_correo_guardar(p_ref text, p_correo text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare x public.pedidos; c text := lower(trim(coalesce(p_correo, '')));
begin
  if length(coalesce(p_ref, '')) <> 24 then return jsonb_build_object('ok', false, 'error', 'Pedido no encontrado'); end if;
  select * into x from public.pedidos where token = p_ref;
  if x.id is null or x.cliente_id is not null then return jsonb_build_object('ok', false, 'error', 'Pedido no encontrado'); end if;
  if c !~ '^[^@\s<>"]+@[^@\s<>"]+\.[a-z]{2,}$' or length(c) > 120 then return jsonb_build_object('ok', false, 'error', 'Correo no válido'); end if;
  if x.invitado_correo is not null then return jsonb_build_object('ok', true); end if;
  update public.pedidos set invitado_correo = c where id = x.id;
  return jsonb_build_object('ok', true);
end $$;
revoke all on function public.pedido_correo_guardar(text, text) from public;
grant execute on function public.pedido_correo_guardar(text, text) to anon, authenticated;

-- El pedido con su envío (cliente, comprador sin cuenta y tienda).
create or replace function public.ver_pedido(p_ref text) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare x public.pedidos := public.pedido_ref(p_ref); t public.profiles;
begin
  if x.id is null then return null; end if;
  select * into t from public.profiles where id = x.negocio_id;
  return jsonb_build_object('id', x.id, 'token', x.token, 'estado', x.estado, 'lineas', x.lineas, 'subtotal', x.subtotal, 'descuento', x.descuento,
    'desc_premium', x.desc_premium, 'total', x.total, 'entrega', x.entrega, 'direccion', x.direccion, 'nota', x.nota, 'fecha', x.created_at,
    'retenido_hasta', x.retenido_hasta, 'rechazos', x.rechazos,
    'tiene_comprobante', x.comprobante is not null, 'devolucion', x.devolucion, 'motivo', x.motivo, 'nombre', x.invitado_nombre,
    'tienda', jsonb_build_object('nombre', t.empresa, 'slug', t.slug, 'logo', t.logo, 'color', t.color, 'telefono', t.telefono, 'datos_pago', t.datos_pago),
    'link', case when x.estado = 'pagando' then public.link_activo(x.negocio_id, 'pedido') end,
    'cancel_min', public.regla('cancel_min', 10),
    'calificado', public.cfx_calif_hecha(x.id::text, false),
    'boleta', case when x.boleta_folio is not null then public.boleta_de(x) end,
    'envio', public.envio_de(x), 'con_correo', x.cliente_id is not null or x.invitado_correo is not null);
end $$;

drop function if exists public.mis_pedidos(uuid);
create or replace function public.mis_pedidos(p_negocio uuid default null)
returns table (id uuid, negocio text, lineas jsonb, subtotal numeric, descuento numeric, total numeric, cupon text,
               entrega text, direccion text, nota text, estado text, fecha timestamptz, actualizado timestamptz,
               retenido_hasta timestamptz, tiene_comprobante boolean, devolucion text, calificado boolean, token text,
               desc_premium numeric, motivo text, rechazos int, boleta jsonb, envio jsonb)
language sql stable security definer set search_path = '' as $$
  select x.id, t.empresa, x.lineas, x.subtotal, x.descuento, x.total, x.cupon,
         x.entrega, x.direccion, x.nota, x.estado, x.created_at, x.updated_at, x.retenido_hasta, x.comprobante is not null, x.devolucion,
         public.cfx_calif_hecha(x.id::text, false), x.token, x.desc_premium, x.motivo, x.rechazos,
         case when x.boleta_folio is not null then public.boleta_de(x) end, public.envio_de(x)
  from public.pedidos x join public.profiles t on t.id = x.negocio_id
  where x.cliente_id = auth.uid() and (p_negocio is null or x.negocio_id = p_negocio)
  order by x.created_at desc limit 50
$$;
revoke all on function public.mis_pedidos(uuid) from public, anon;
grant execute on function public.mis_pedidos(uuid) to authenticated;

drop function if exists public.pedidos_tienda(text);
create or replace function public.pedidos_tienda(p_estado text default null)
returns table (id uuid, cliente_id uuid, cliente text, telefono text, lineas jsonb, subtotal numeric, descuento numeric,
               total numeric, cupon text, entrega text, direccion text, nota text, estado text, fecha timestamptz,
               retenido_hasta timestamptz, tiene_comprobante boolean, devolucion text, invitado boolean, calificado boolean, cliente_estrellas numeric,
               premium boolean, desc_premium numeric, rechazos int, motivo text, boleta jsonb, medio text, envio jsonb)
language sql stable security definer set search_path = '' as $$
  select x.id, x.cliente_id, coalesce(nullif(c.empresa, ''), split_part(c.email, '@', 1), x.invitado_nombre, 'Cliente'),
         coalesce(c.telefono, x.invitado_tel), x.lineas, x.subtotal, x.descuento, x.total, x.cupon, x.entrega, x.direccion, x.nota, x.estado,
         x.created_at, x.retenido_hasta, x.comprobante is not null, x.devolucion, x.cliente_id is null,
         public.cfx_calif_hecha(x.id::text, true),
         (public.cfx_calif_cliente(x.cliente_id, case when x.cliente_id is null then x.invitado_tel end) ->> 'promedio')::numeric,
         pr.premium, x.desc_premium, x.rechazos, x.motivo, public.boleta_de(x),
         case when x.mp_pago is not null then 'mercadopago' when x.comprobante_at is not null then 'transferencia' end, public.envio_de(x)
  from public.pedidos x left join public.profiles c on c.id = x.cliente_id
  cross join lateral (select c.role = 'client' and public.is_pro(c.id) as premium) pr
  where x.negocio_id = public.negocio_de(auth.uid())
    and (p_estado is null or (p_estado = 'activos' and x.estado in ('recibido', 'preparando', 'listo', 'en_camino'))
         or (p_estado = 'revisar' and x.estado = 'en_revision') or (p_estado = 'pagando' and x.estado = 'pagando')
         or (p_estado = 'devolver' and x.devolucion = 'pendiente')
         or (p_estado = 'historial' and x.estado in ('entregado', 'cancelado', 'rechazado', 'expirado')) or x.estado = p_estado)
  order by (coalesce(pr.premium, false) and x.estado in ('pagando', 'en_revision', 'recibido', 'preparando', 'listo', 'en_camino')) desc, x.created_at desc
  limit 300
$$;
revoke all on function public.pedidos_tienda(text) from public, anon;
grant execute on function public.pedidos_tienda(text) to authenticated;

-- 📄 Perfil con las políticas de la tienda (Ley 19.496): vendedor, RUT, cambios y devoluciones, envíos y si excluye el retracto.
create or replace function public.set_mi_perfil(p_perfil jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare r jsonb := '{}'::jsonb; k text; v text;
  lim constant jsonb := '{"descripcion":400,"direccion":150,"comuna":60,"instagram":100,"facebook":100,"tiktok":100,"web":150,"correo":120,"razon":120,"rut":12,"cambios":800,"envios":400,"sin_retracto":1}';
begin
  if not public.is_business(auth.uid()) then raise exception 'Solo las empresas'; end if;
  for k in select jsonb_object_keys(lim) loop
    v := nullif(trim(regexp_replace(coalesce(p_perfil ->> k, ''), '[<>]', '', 'g')), '');
    if v is null then continue; end if;
    if k = 'rut' then v := public.rut_normal(v); if v is null then raise exception 'RUT no válido'; end if; end if;
    if k = 'sin_retracto' then v := '1'; end if;
    v := left(v, (lim ->> k)::int);
    if k = 'web' and v !~* '^https?://' then v := 'https://' || v; end if;
    if k = 'correo' and v !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Correo no válido'; end if;
    r := r || jsonb_build_object(k, v);
  end loop;
  update public.profiles set perfil = r where id = auth.uid();
  return r;
end $$;
revoke all on function public.set_mi_perfil(jsonb) from public, anon;
grant execute on function public.set_mi_perfil(jsonb) to authenticated;

-- 📊 Medir anuncios (Meta Pixel y Google Analytics 4) y 🌐 dominio propio: módulos (sin venta de módulos: Pro).
create or replace function public.mi_marca_web() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare p public.profiles;
begin
  select * into p from public.profiles where id = public.webhook_dueno();
  return jsonb_build_object('slug', p.slug, 'meta', p.medicion ->> 'meta', 'ga', p.medicion ->> 'ga', 'dominio', p.dominio,
    'medicion', public.pro_o_modulo(p.id, 'medicion'), 'con_dominio', public.pro_o_modulo(p.id, 'dominio'), 'modulos', public.mis_modulos(p.id) is not null);
end $$;
create or replace function public.medicion_guardar(p_meta text, p_ga text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare me uuid := public.webhook_dueno(); m text := nullif(regexp_replace(coalesce(p_meta, ''), '\s', '', 'g'), ''); g text := nullif(upper(trim(coalesce(p_ga, ''))), '');
begin
  if not public.pro_o_modulo(me, 'medicion') then raise exception '📊 Medir anuncios es % ', case when public.mis_modulos(me) is not null then 'un módulo: actívalo en Ajustes → 🧩 Módulos' else 'de la versión Pro' end; end if;
  if m is not null and m !~ '^[0-9]{8,20}$' then raise exception 'El ID del Pixel de Meta son solo números (8 a 20)'; end if;
  if g is not null and g !~ '^G-[A-Z0-9]{4,15}$' then raise exception 'El ID de Google Analytics empieza con G- (ej: G-AB12CD34EF)'; end if;
  update public.profiles set medicion = jsonb_strip_nulls(jsonb_build_object('meta', m, 'ga', g)) where id = me;
  return public.mi_marca_web();
end $$;
create or replace function public.dominio_guardar(p_dominio text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare me uuid := public.webhook_dueno(); d text := nullif(lower(trim(regexp_replace(coalesce(p_dominio, ''), '^https?://|/.*$', '', 'gi'))), ''); antes text;
begin
  if not public.pro_o_modulo(me, 'dominio') then raise exception '🌐 Dominio propio es % ', case when public.mis_modulos(me) is not null then 'un módulo: actívalo en Ajustes → 🧩 Módulos' else 'de la versión Pro' end; end if;
  if d is not null and (d !~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}$' or length(d) > 80 or d ~ '(workers\.dev|supabase\.|pages\.dev|codefix)') then
    raise exception 'Escribe solo el dominio, ej: mitienda.cl';
  end if;
  if d is not null and exists (select 1 from public.profiles where dominio = d and id <> me) then raise exception 'Ese dominio ya lo usa otra tienda'; end if;
  select dominio into antes from public.profiles where id = me;
  update public.profiles set dominio = d where id = me;
  if d is not null and d is distinct from antes then
    -- G145 a: la tienda lo conecta sola desde su app (función enviar → Cloudflare). Al CM solo llega el aviso.
    perform public.cfx_al_cm('🌐 Dominio nuevo: ' || d, 'Tienda ' || coalesce((select slug from public.profiles where id = me), '') ||
      '. Se conecta solo desde su app (Ajustes → 🌐 Mi dominio); no tienes que hacer nada.');
  end if;
  return public.mi_marca_web();
end $$;
-- El Worker pregunta de qué tienda es un dominio (solo dominios con el módulo vigente).
create or replace function public.tienda_por_dominio(p_host text) returns text
language sql stable security definer set search_path = '' as $$
  select p.slug from public.profiles p
  where p.dominio = lower(regexp_replace(trim(coalesce(p_host, '')), '^www\.', '')) and p.role = 'user' and not p.suspended and public.pro_o_modulo(p.id, 'dominio')
$$;
revoke all on function public.mi_marca_web(), public.medicion_guardar(text, text), public.dominio_guardar(text) from public, anon;
grant execute on function public.mi_marca_web(), public.medicion_guardar(text, text), public.dominio_guardar(text) to authenticated;
revoke all on function public.tienda_por_dominio(text) from public;
grant execute on function public.tienda_por_dominio(text) to anon, authenticated;

-- La vitrina pública con la medición (solo si la tienda tiene el módulo) y las políticas (vienen en perfil).
create or replace function public.tienda_publica(p_slug text) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('id', t.id, 'empresa', t.empresa, 'slug', t.slug, 'telefono', t.telefono, 'horario', t.horario, 'abierto', t.abierto,
    'logo', t.logo, 'color', t.color, 'datos_pago', t.datos_pago,
    'vacaciones_hasta', case when public.en_vacaciones(t.id) then t.vacaciones_hasta end,
    'vacaciones_msg', case when public.en_vacaciones(t.id) then t.vacaciones_msg end,
    'estrellas', public.estrellas_tienda(t.id), 'cobra_online', public.link_activo(t.id, 'pedido') is not null,
    'retencion_min', public.regla('retencion_min', 30), 'pro', public.is_pro(t.id), 'desc_premium', t.desc_premium, 'despacho', t.despacho,
    'perfil', t.perfil, 'rubro', t.rubro, 'desde', t.created_at::date,
    'cobra_mp', coalesce((public.link_activo(t.id, 'pedido') ->> 'mp')::boolean, false),
    'medicion', case when t.medicion <> '{}'::jsonb and public.pro_o_modulo(t.id, 'medicion') then t.medicion end,
    'verificado', exists (select 1 from public.cfx_verificaciones v where v.cuenta = t.id and v.estado = 'aprobada'))  -- G154 ✓ tienda verificada
  from public.profiles t where t.slug = lower(trim(coalesce(p_slug, ''))) and t.role = 'user' and not t.suspended
$$;

-- Módulos de Órbita (+ 📊 medir anuncios y 🌐 dominio propio).
create or replace function public.cfx_modulos_app() returns text[]
language sql immutable as $$ select array['chat', 'calificaciones', 'cupones', 'sellos', 'carrito', 'analisis', 'estadisticas', 'equipo', 'campanas', 'redes', 'webhooks', 'medicion', 'dominio', 'giftcards', 'suscripciones', 'proveedores'] $$;  -- G96: +3
revoke all on function public.cfx_modulos_app() from public, anon, authenticated;

-- Guía para partir: + 📄 políticas de la tienda; el despacho cuenta también el resto de Chile.
create or replace function public.cfx_guia_app() returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce((select jsonb_build_array(
    jsonb_build_object('k', 'perfil', 't', 'Nombre y logo de tu tienda', 'd', 'Así te ven tus clientes en el catálogo.', 'ir', '#ajustes', 'ok', p.empresa <> '' and p.logo is not null),
    jsonb_build_object('k', 'whatsapp', 't', 'Tu WhatsApp', 'd', 'Para recibir y coordinar pedidos.', 'ir', '#ajustes', 'ok', coalesce(p.telefono, '') <> ''),
    jsonb_build_object('k', 'productos', 't', 'Tus productos', 'd', 'Sube al menos un producto con foto y precio.', 'ir', 'apps/caja/',
      'ok', exists (select 1 from public.catalog_items i where i.owner_id = p.id)),
    jsonb_build_object('k', 'cobro', 't', 'Cómo te pagan los pedidos', 'd', 'Tu link de pago o tus datos de transferencia. Los pedidos se pagan completos.', 'ir', '#links',
      'ok', coalesce(p.datos_pago, '') <> '' or exists (select 1 from public.links_pago l where l.owner_id = p.id and l.tipo = 'pedido' and l.activo and l.url <> '')),
    jsonb_build_object('k', 'despacho', 't', 'Despacho o retiro', 'd', 'Retiro en tienda, precio por comuna y envío al resto de Chile.', 'ir', '#despacho',
      'ok', coalesce((p.despacho ->> 'retiro')::boolean, false) or jsonb_array_length(coalesce(p.despacho -> 'zonas', '[]'::jsonb)) > 0
        or coalesce(p.despacho #>> '{resto,modo}', 'no') <> 'no'),
    jsonb_build_object('k', 'politicas', 't', 'Políticas de la tienda', 'd', 'Quién vende (RUT) y tu política de cambios: la ley las pide en la venta por internet.', 'ir', '#ajustes',
      'ok', coalesce(p.perfil ->> 'rut', '') <> '' and coalesce(p.perfil ->> 'cambios', '') <> ''))
  from public.profiles p where p.id = auth.uid()), '[]'::jsonb)
$$;
revoke all on function public.cfx_guia_app() from public, anon, authenticated;

-- ---------- VERSIÓN 5.42 · G25 ⏰ Renovación obligatoria (se puede volver a correr) ----------
-- Pro/Premium sin fecha de término → 30 días desde hoy (o desde que se activó). Al vencer, is_pro() deja de valer solo: hay que renovar.
create or replace function public.pro_con_fecha() returns trigger
language plpgsql set search_path = '' as $$
begin
  if new.plan = 'pro' and new.pro_until is null and new.role <> 'admin' then new.pro_until := now() + interval '30 days'; end if;
  return new;
end $$;
revoke all on function public.pro_con_fecha() from public, anon, authenticated;
drop trigger if exists profiles_vence on public.profiles;
create trigger profiles_vence before insert or update of plan, pro_until, role on public.profiles for each row execute function public.pro_con_fecha();
update public.profiles set pro_until = now() + interval '30 days' where plan = 'pro' and pro_until is null and role <> 'admin';

-- ---------- VERSIÓN 5.43 · G29 🌐 Dominio con Cloudflare for SaaS (se puede volver a correr) ----------
-- El administrador guarda en el CM (Control → Órbita → 🌐 Dominio) a dónde apunta el CNAME del negocio (ej: tiendas.codefix.cl).
-- El negocio ve: CNAME www → ese destino. El dominio se guarda sin "www." (el Worker lo quita al buscar la tienda).
insert into public.cfx_config (clave, valor) values ('dominio', '{"cname": ""}') on conflict (clave) do nothing;
create or replace function public.cfx_dominio() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  perform public.cfx_es_admin();
  return (select valor from public.cfx_config where clave = 'dominio') || jsonb_build_object('tiendas', coalesce((select jsonb_agg(jsonb_build_object('slug', p.slug, 'dominio', p.dominio,
    'activo', public.pro_o_modulo(p.id, 'dominio')) order by p.dominio) from public.profiles p where p.dominio is not null and p.role = 'user'), '[]'::jsonb));
end $$;
create or replace function public.cfx_dominio_guardar(p_cname text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare c text := nullif(lower(trim(regexp_replace(coalesce(p_cname, ''), '^https?://|/.*$|\.$', '', 'gi'))), '');
begin
  perform public.cfx_es_admin();
  if c is not null and (c !~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}$' or length(c) > 80) then raise exception 'Escribe solo el nombre, ej: tiendas.codefix.cl'; end if;
  insert into public.cfx_config (clave, valor) values ('dominio', jsonb_build_object('cname', coalesce(c, '')))
    on conflict (clave) do update set valor = excluded.valor;
  return public.cfx_dominio();
end $$;
revoke all on function public.cfx_dominio(), public.cfx_dominio_guardar(text) from public, anon;
grant execute on function public.cfx_dominio(), public.cfx_dominio_guardar(text) to authenticated;

create or replace function public.mi_marca_web() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare p public.profiles;
begin
  select * into p from public.profiles where id = public.webhook_dueno();
  return jsonb_build_object('slug', p.slug, 'meta', p.medicion ->> 'meta', 'ga', p.medicion ->> 'ga', 'dominio', p.dominio,
    'medicion', public.pro_o_modulo(p.id, 'medicion'), 'con_dominio', public.pro_o_modulo(p.id, 'dominio'), 'modulos', public.mis_modulos(p.id) is not null,
    'cname', nullif((select valor ->> 'cname' from public.cfx_config where clave = 'dominio'), ''));
end $$;
create or replace function public.dominio_guardar(p_dominio text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare me uuid := public.webhook_dueno(); d text := nullif(regexp_replace(lower(trim(regexp_replace(coalesce(p_dominio, ''), '^https?://|/.*$', '', 'gi'))), '^www\.', ''), ''); antes text;
begin
  if not public.pro_o_modulo(me, 'dominio') then raise exception '🌐 Dominio propio es % ', case when public.mis_modulos(me) is not null then 'un módulo: actívalo en Ajustes → 🧩 Módulos' else 'de la versión Pro' end; end if;
  if d is not null and (d !~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}$' or length(d) > 80 or d ~ '(workers\.dev|supabase\.|pages\.dev|codefix)') then
    raise exception 'Escribe solo el dominio, ej: mitienda.cl';
  end if;
  if d is not null and exists (select 1 from public.profiles where dominio = d and id <> me) then raise exception 'Ese dominio ya lo usa otra tienda'; end if;
  select dominio into antes from public.profiles where id = me;
  update public.profiles set dominio = d where id = me;
  if d is not null and d is distinct from antes then
    perform public.cfx_al_cm('🌐 Dominio nuevo: www.' || d, 'Tienda ' || coalesce((select slug from public.profiles where id = me), '') ||
      '. Se conecta solo desde su app (Ajustes → 🌐 Mi dominio, G145 a); no tienes que hacer nada.');
  end if;
  return public.mi_marca_web();
end $$;
update public.profiles set dominio = regexp_replace(dominio, '^www\.', '') where dominio ~ '^www\.'
  and not exists (select 1 from public.profiles q where q.dominio = regexp_replace(public.profiles.dominio, '^www\.', ''));

-- ---------- VERSIÓN 5.44 · G32 🧾 Boleta SII desde la Caja (venta en local) con OpenFactura o folio manual (se puede volver a correr) ----------
-- Las ventas de Caja viven en el equipo (localStorage); aquí queda solo la boleta emitida (una por venta, sin repetir).
create table if not exists public.boletas_caja (
  negocio_id uuid not null references public.profiles(id) on delete cascade,
  venta_id   text not null check (venta_id ~ '^[A-Za-z0-9_-]{4,40}$'),
  total      numeric not null default 0,
  folio      text,
  url        text,
  error      text,
  created_at timestamptz not null default now(),
  primary key (negocio_id, venta_id)
);
alter table public.boletas_caja enable row level security;
revoke all on public.boletas_caja from anon, authenticated;

-- p = { venta, items: [{ nombre, cant, precio }], folio? }. Con folio = modo manual (anota el N° del SII). Sin folio = OpenFactura.
create or replace function public.boleta_caja(p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  n uuid := public.negocio_de(auth.uid()); v text := p ->> 'venta'; c public.boleta_cuentas; x public.pedidos; b public.boletas_caja;
  l jsonb; lin jsonb := '[]'::jsonb; tot numeric := 0; q numeric; pr numeric; r jsonb; f text; e text;
  fm text := nullif(regexp_replace(coalesce(p ->> 'folio', ''), '\D', '', 'g'), '');
begin
  if n is null or not public.equipo_puede('caja') then raise exception 'Sin permiso para vender en la Caja'; end if;
  if v is null or v !~ '^[A-Za-z0-9_-]{4,40}$' then raise exception 'Venta no válida'; end if;
  select * into b from public.boletas_caja where negocio_id = n and venta_id = v;
  if b.folio is not null then return jsonb_build_object('ok', true, 'folio', b.folio, 'url', b.url); end if;
  if jsonb_typeof(p -> 'items') <> 'array' or jsonb_array_length(p -> 'items') not between 1 and 60 then raise exception 'La venta no tiene productos'; end if;
  for l in select * from jsonb_array_elements(p -> 'items') loop
    q := greatest(coalesce((l ->> 'cant')::numeric, 1), 1); pr := greatest(coalesce((l ->> 'precio')::numeric, 0), 0);
    lin := lin || jsonb_build_object('nombre', left(coalesce(nullif(trim(l ->> 'nombre'), ''), 'Producto'), 80),
      'cant', q, 'subtotal', round(q * pr));
    tot := tot + round(q * pr);
  end loop;
  if tot < 1 then raise exception 'La venta no tiene monto'; end if;
  select * into c from public.boleta_cuentas where owner_id = n;
  if c.owner_id is null then raise exception 'Primero completa tus datos de boleta en Ajustes → 🧾 Boletas'; end if;
  if fm is not null or c.modo <> 'openfactura' then
    if fm is null or length(fm) > 10 then raise exception 'Escribe el N° (folio) de la boleta del SII'; end if;
    insert into public.boletas_caja (negocio_id, venta_id, total, folio) values (n, v, tot, fm)
    on conflict (negocio_id, venta_id) do update set folio = excluded.folio, total = excluded.total, error = null;
    return jsonb_build_object('ok', true, 'folio', fm);
  end if;
  if c.apikey is null then raise exception 'Pega tu API key de OpenFactura en Ajustes → 🧾 Boletas'; end if;
  x.lineas := lin; x.total := tot;
  r := public.of_api(c.apikey, public.boleta_dte(x, c), 'cfx-caja-' || n::text || '-' || v);
  f := nullif(coalesce(r #>> '{body,FOLIO}', r #>> '{body,folio}'), '');
  if coalesce((r ->> 'status')::int, 0) in (200, 201) and f is not null then
    insert into public.boletas_caja (negocio_id, venta_id, total, folio, url) values (n, v, tot, left(f, 20),
      case when r #>> '{body,SELF_SERVICE,url}' ~ '^https://[^\s"<>]+$' then left(r #>> '{body,SELF_SERVICE,url}', 500) end)
    on conflict (negocio_id, venta_id) do update set folio = excluded.folio, url = excluded.url, total = excluded.total, error = null
    returning * into b;
    return jsonb_build_object('ok', true, 'folio', b.folio, 'url', b.url);
  end if;
  e := left(coalesce(case when (r ->> 'status')::int = 0 then 'No se pudo conectar con OpenFactura' end,
                     r #>> '{body,error,message}', r #>> '{body,message}', 'OpenFactura respondió ' || coalesce(r ->> 'status', '?')), 200);
  if (r ->> 'status')::int in (401, 403) then e := 'OpenFactura no aceptó la API key'; end if;
  insert into public.boletas_caja (negocio_id, venta_id, total, error) values (n, v, tot, e)
  on conflict (negocio_id, venta_id) do update set error = excluded.error;
  return jsonb_build_object('ok', false, 'error', e);
end $$;
revoke all on function public.boleta_caja(jsonb) from public, anon;
grant execute on function public.boleta_caja(jsonb) to authenticated;

-- =====================================================================
--  VERSIÓN 5.72 · G96 🧩 MÓDULOS DE TIENDA: 🎁 gift cards · 🛒 carritos olvidados por WhatsApp · 🔁 compras recurrentes ·
--  📦 stock mínimo y proveedores. Todo se valida aquí (pro_o_modulo); lo de antes no cambia.
-- =====================================================================
-- 🎁 Gift cards (tablas y giftcard_valida: antes de guardar_pedido).
create or replace function public.giftcard_json(g public.giftcards) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('id', g.id, 'codigo', g.codigo, 'monto', g.monto, 'saldo', g.saldo, 'para', g.para, 'de', g.de, 'vence', g.vence,
    'anulada', g.anulada, 'vigente', not g.anulada and g.saldo > 0 and g.vence >= (now() at time zone 'America/Santiago')::date, 'created_at', g.created_at)
$$;
create or replace function public.giftcard_crear(p_monto int, p_para text default null, p_de text default null, p_medio text default 'efectivo') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.negocio_de(auth.uid()); g public.giftcards; c text;
begin
  if n is null or n <> auth.uid() then raise exception 'Solo el dueño de la tienda vende gift cards'; end if;
  if not public.pro_o_modulo(n, 'giftcards') then raise exception '🎁 Gift cards es un módulo 🧩: actívalo en Más → Mi plan y módulos'; end if;
  if coalesce(p_monto, 0) not between 1000 and 1000000 then raise exception 'Monto entre $1.000 y $1.000.000'; end if;
  if (select count(*) from public.giftcards where negocio_id = n and created_at > now() - interval '1 day') >= 50 then raise exception 'Máximo 50 gift cards por día'; end if;
  loop
    c := 'GC' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
    exit when not exists (select 1 from public.giftcards where codigo = c);
  end loop;
  insert into public.giftcards (negocio_id, codigo, monto, saldo, para, de, medio, vence, creada_por)
  values (n, c, p_monto, p_monto, left(nullif(trim(p_para), ''), 60), left(nullif(trim(p_de), ''), 60),
          case when p_medio in ('efectivo', 'tarjeta', 'transferencia') then p_medio else 'efectivo' end,
          (now() at time zone 'America/Santiago')::date + 365, auth.uid()) returning * into g;
  return public.giftcard_json(g);
end $$;
create or replace function public.giftcard_lista() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare n uuid := public.negocio_de(auth.uid());
begin
  if n is null or n <> auth.uid() then raise exception 'Solo el dueño de la tienda'; end if;
  return jsonb_build_object(
    'lista', (select coalesce(jsonb_agg(public.giftcard_json(g) order by g.created_at desc), '[]') from
      (select * from public.giftcards where negocio_id = n order by created_at desc limit 100) g),
    'vendido_mes', (select coalesce(sum(monto), 0) from public.giftcards where negocio_id = n and not anulada and created_at >= date_trunc('month', now())),
    'saldo', (select coalesce(sum(saldo), 0) from public.giftcards where negocio_id = n and not anulada and vence >= (now() at time zone 'America/Santiago')::date));
end $$;
-- Canje en la Caja (dueño o equipo con Caja): descuenta del saldo.
create or replace function public.giftcard_canjear(p_codigo text, p_monto int) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.negocio_de(auth.uid()); g public.giftcards;
begin
  if n is null or not public.equipo_puede('caja') then raise exception 'Sin permiso'; end if;
  if not public.pro_o_modulo(n, 'giftcards') then raise exception '🎁 Gift cards es un módulo 🧩: actívalo en Más → Mi plan y módulos'; end if;
  select * into g from public.giftcards where negocio_id = n and codigo = upper(regexp_replace(coalesce(p_codigo, ''), '[^A-Za-z0-9]', '', 'g')) for update;
  if g.id is null then raise exception 'No existe una gift card con ese código'; end if;
  if g.anulada then raise exception 'Esta gift card está anulada'; end if;
  if g.vence < (now() at time zone 'America/Santiago')::date then raise exception 'Esta gift card venció el %', to_char(g.vence, 'DD/MM/YYYY'); end if;
  if coalesce(p_monto, 0) <= 0 then raise exception 'Escribe cuánto se descuenta'; end if;
  if p_monto > g.saldo then raise exception 'Le queda $% de saldo', replace(to_char(g.saldo, 'FM999,999,999'), ',', '.'); end if;
  update public.giftcards set saldo = saldo - p_monto where id = g.id returning * into g;
  insert into public.giftcard_usos (giftcard_id, monto, por, donde) values (g.id, p_monto, auth.uid(), 'caja');
  return public.giftcard_json(g);
end $$;
create or replace function public.giftcard_anular(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if public.negocio_de(auth.uid()) is distinct from auth.uid() then raise exception 'Solo el dueño de la tienda'; end if;
  update public.giftcards set anulada = true where id = p_id and negocio_id = auth.uid();
  if not found then raise exception 'Gift card no encontrada'; end if;
end $$;
-- El cliente revisa el saldo en su carrito (solo de su tienda).
create or replace function public.giftcard_saldo(p_negocio uuid, p_codigo text) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare g public.giftcards;
begin
  if not (public.puede_comprar(auth.uid(), p_negocio) or public.negocio_de(auth.uid()) = p_negocio) then raise exception 'No puedes pedirle a esta tienda'; end if;
  g := public.giftcard_valida(p_negocio, p_codigo);
  if g.id is null then raise exception 'Cupón o gift card no válido o vencido'; end if;
  return jsonb_build_object('codigo', g.codigo, 'saldo', g.saldo, 'vence', g.vence);
end $$;
-- Si el pedido se cancela, se rechaza o expira, el saldo vuelve a la gift card.
create or replace function public.giftcard_devolver() returns trigger
language plpgsql security definer set search_path = '' as $$
declare g uuid;
begin
  if new.gift_monto > 0 and new.estado in ('cancelado', 'rechazado', 'expirado') and old.estado not in ('cancelado', 'rechazado', 'expirado') then
    select id into g from public.giftcards where codigo = new.gift_codigo and negocio_id = new.negocio_id;
    if g is not null then
      update public.giftcards set saldo = saldo + new.gift_monto where id = g;
      insert into public.giftcard_usos (giftcard_id, monto, pedido_id, donde) values (g, -new.gift_monto, new.id, 'devuelto');
    end if;
  end if;
  return new;
end $$;
drop trigger if exists pedidos_giftcard_devolver on public.pedidos;
create trigger pedidos_giftcard_devolver after update of estado on public.pedidos for each row execute function public.giftcard_devolver();

-- 🛒 Carritos olvidados (núcleo cfx_carritos_mios): nombre y WhatsApp del cliente de esta tienda.
create or replace function public.cfx_carrito_contacto_app(p_cliente uuid, p_negocio uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('nombre', coalesce(nullif(c.empresa, ''), split_part(c.email, '@', 1)), 'tel', c.telefono)
  from public.profiles c where c.id = p_cliente and c.role = 'client' and c.negocio_id = p_negocio and not c.suspended
    and public.pro_o_modulo(p_negocio, 'carrito')
$$;
revoke all on function public.cfx_carrito_contacto_app(uuid, uuid) from public, anon, authenticated;

-- 🔁 Compras recurrentes (módulo 'suscripciones'): la tienda arma el pedido fijo de un cliente y cada X días se crea solo.
create table if not exists public.suscripciones (
  id          uuid primary key default gen_random_uuid(),
  negocio_id  uuid not null references public.profiles (id) on delete cascade,
  cliente_id  uuid not null references public.profiles (id) on delete cascade,
  items       jsonb not null,
  cada        int not null check (cada in (7, 14, 30)),
  entrega     text not null default 'retiro' check (entrega in ('retiro', 'despacho')),
  direccion   text,
  proxima     date not null,
  activa      boolean not null default true,
  pedidos     int not null default 0,
  error       text,
  created_at  timestamptz not null default now()
);
create index if not exists suscripciones_negocio_idx on public.suscripciones (negocio_id, created_at desc);
create index if not exists suscripciones_proxima_idx on public.suscripciones (proxima) where activa;
create index if not exists suscripciones_cliente_idx on public.suscripciones (cliente_id);
alter table public.suscripciones enable row level security;
revoke all on public.suscripciones from anon, authenticated;
create or replace function public.suscripcion_json(x public.suscripciones) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('id', x.id, 'cliente', x.cliente_id, 'items', x.items, 'cada', x.cada, 'entrega', x.entrega, 'direccion', x.direccion,
    'proxima', x.proxima, 'activa', x.activa, 'pedidos', x.pedidos, 'error', x.error,
    'nombre', (select coalesce(nullif(c.empresa, ''), split_part(c.email, '@', 1)) from public.profiles c where c.id = x.cliente_id),
    'tienda', (select coalesce(nullif(t.empresa, ''), 'Tu tienda') from public.profiles t where t.id = x.negocio_id),
    'lineas', (select a -> 'lineas' from (select public.armar_pedido(x.negocio_id, x.items) a) z where not (a ? 'error')),
    'total', (select (a ->> 'sub')::numeric from (select public.armar_pedido(x.negocio_id, x.items) a) z where not (a ? 'error')))
$$;
create or replace function public.suscripcion_guardar(p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.negocio_de(auth.uid()); x public.suscripciones; it jsonb; l jsonb := '[]'::jsonb; a jsonb;
  cli uuid := nullif(p ->> 'cliente', '')::uuid; v_cada int := coalesce((p ->> 'cada')::int, 30); ent text := coalesce(p ->> 'entrega', 'retiro');
  dir text := nullif(left(trim(coalesce(p ->> 'direccion', '')), 200), ''); desde date := coalesce(nullif(p ->> 'proxima', '')::date, (now() at time zone 'America/Santiago')::date);
begin
  if n is null or n <> auth.uid() then raise exception 'Solo el dueño de la tienda'; end if;
  if not public.pro_o_modulo(n, 'suscripciones') then raise exception '🔁 Compras recurrentes es un módulo 🧩: actívalo en Más → Mi plan y módulos'; end if;
  if not exists (select 1 from public.profiles c where c.id = cli and c.role = 'client' and c.negocio_id = n) then raise exception 'Elige un cliente de tu tienda'; end if;
  if v_cada not in (7, 14, 30) then raise exception 'Elige cada 7, 14 o 30 días'; end if;
  if ent not in ('retiro', 'despacho') then raise exception 'Elige retiro o despacho'; end if;
  if ent = 'despacho' and dir is null then raise exception 'Escribe la dirección de despacho'; end if;
  if desde < (now() at time zone 'America/Santiago')::date then raise exception 'La primera fecha no puede ser antes de hoy'; end if;
  for it in select * from jsonb_array_elements(case when jsonb_typeof(p -> 'items') = 'array' then p -> 'items' else '[]' end) limit 30 loop
    continue when coalesce(it ->> 'clave', '') = '';
    l := l || jsonb_build_object('clave', left(it ->> 'clave', 60), 'cant', least(greatest(coalesce((it ->> 'cant')::int, 1), 1), 99), 'opcion', nullif(left(it ->> 'opcion', 60), ''));
  end loop;
  if jsonb_array_length(l) = 0 then raise exception 'Agrega al menos un producto'; end if;
  a := public.armar_pedido(n, l);
  if a ? 'error' then raise exception '%', a ->> 'error'; end if;
  if nullif(p ->> 'id', '') is null then
    if (select count(*) from public.suscripciones where negocio_id = n) >= 300 then raise exception 'Máximo 300 compras recurrentes'; end if;
    insert into public.suscripciones (negocio_id, cliente_id, items, cada, entrega, direccion, proxima)
    values (n, cli, l, v_cada, ent, case when ent = 'despacho' then dir end, desde) returning * into x;
    perform public.notify_user(cli, '🔁 Compra recurrente lista',
      (select coalesce(nullif(empresa, ''), 'Tu tienda') from public.profiles where id = n) || ' te armará este pedido cada ' || v_cada || ' días. Puedes pausarla cuando quieras.', 'apps/catalogo/?v=pedidos');
  else
    update public.suscripciones set cliente_id = cli, items = l, cada = v_cada, entrega = ent, direccion = case when ent = 'despacho' then dir end,
      proxima = desde, error = null where id = (p ->> 'id')::uuid and negocio_id = n returning * into x;
    if x.id is null then raise exception 'Compra recurrente no encontrada'; end if;
  end if;
  return public.suscripcion_json(x);
end $$;
create or replace function public.suscripciones_lista() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare n uuid := public.negocio_de(auth.uid());
begin
  if n is null or n <> auth.uid() then raise exception 'Solo el dueño de la tienda'; end if;
  return (select coalesce(jsonb_agg(public.suscripcion_json(x) order by x.activa desc, x.proxima), '[]') from public.suscripciones x where x.negocio_id = n);
end $$;
-- Pausar o seguir: la tienda o el mismo cliente.
create or replace function public.suscripcion_estado(p_id uuid, p_activa boolean) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare x public.suscripciones; hoy date := (now() at time zone 'America/Santiago')::date;
begin
  update public.suscripciones set activa = coalesce(p_activa, false), error = null,
    proxima = case when coalesce(p_activa, false) and proxima < hoy then hoy else proxima end
  where id = p_id and (negocio_id = auth.uid() or cliente_id = auth.uid()) returning * into x;
  if x.id is null then raise exception 'Compra recurrente no encontrada'; end if;
  if x.cliente_id = auth.uid() then
    perform public.notify_user(x.negocio_id, case when x.activa then '🔁 Compra recurrente retomada' else '⏸️ Compra recurrente pausada' end,
      coalesce((select coalesce(nullif(empresa, ''), split_part(email, '@', 1)) from public.profiles where id = x.cliente_id), 'Un cliente') ||
      case when x.activa then ' la retomó.' else ' la pausó.' end, './#recurrentes');
  end if;
  return public.suscripcion_json(x);
end $$;
create or replace function public.suscripcion_borrar(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  delete from public.suscripciones where id = p_id and negocio_id = auth.uid();
  if not found then raise exception 'Compra recurrente no encontrada'; end if;
end $$;
create or replace function public.mis_suscripciones() returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(public.suscripcion_json(x) order by x.proxima), '[]') from public.suscripciones x where x.cliente_id = auth.uid()
$$;
-- Cada mañana (pg_cron): crea los pedidos del día con los precios de hoy y avisa. Si no se puede, queda el motivo y avisa a la tienda.
create or replace function public.suscripciones_correr() returns int
language plpgsql security definer set search_path = '' as $$
declare x public.suscripciones; r jsonb; k int := 0; hoy date := (now() at time zone 'America/Santiago')::date; t text;
begin
  for x in select * from public.suscripciones where activa and proxima <= hoy order by proxima limit 500 for update skip locked loop
    if not public.pro_o_modulo(x.negocio_id, 'suscripciones') or not exists (select 1 from public.profiles c where c.id = x.cliente_id and not c.suspended and c.negocio_id = x.negocio_id) then
      update public.suscripciones set error = 'Sin el módulo 🔁 o el cliente ya no es de la tienda', proxima = hoy + 1 where id = x.id; continue;
    end if;
    if public.en_vacaciones(x.negocio_id) then update public.suscripciones set proxima = hoy + 1 where id = x.id; continue; end if;
    r := public.guardar_pedido(x.negocio_id, x.cliente_id, null, null, x.items, x.entrega, x.direccion, '🔁 Compra recurrente', null);
    if coalesce((r ->> 'ok')::boolean, false) then
      update public.suscripciones set pedidos = pedidos + 1, error = null, proxima = greatest(proxima, hoy) + cada where id = x.id;
      select coalesce(nullif(empresa, ''), 'Tu tienda') into t from public.profiles where id = x.negocio_id;
      perform public.notify_user(x.cliente_id, '🔁 Tu pedido de ' || t || ' ya está hecho',
        'Total $' || to_char((r ->> 'total')::numeric, 'FM999G999G999') || case when r ->> 'estado' = 'pagando' then ' · Págalo para que lo preparen.' else ' · Ya lo están preparando.' end,
        'apps/catalogo/?v=pedidos');
      k := k + 1;
    else
      update public.suscripciones set error = left(r ->> 'error', 200), proxima = greatest(proxima, hoy) + cada where id = x.id;
      perform public.notify_user(x.negocio_id, '⚠️ No se pudo crear una compra recurrente', left(coalesce(r ->> 'error', ''), 120), './#recurrentes');
    end if;
  end loop;
  return k;
end $$;
select cron.schedule('suscripciones', '5 12 * * *', $$ select public.suscripciones_correr(); $$);

-- 📦 Stock mínimo y proveedores (módulo 'proveedores'): cada producto con su mínimo y su proveedor; pedir por WhatsApp con un toque.
create table if not exists public.proveedores (
  id          uuid primary key default gen_random_uuid(),
  negocio_id  uuid not null references public.profiles (id) on delete cascade,
  nombre      text not null check (length(nombre) between 1 and 60),
  tel         text,
  nota        text,
  created_at  timestamptz not null default now()
);
create index if not exists proveedores_negocio_idx on public.proveedores (negocio_id);
alter table public.proveedores enable row level security;
revoke all on public.proveedores from anon, authenticated;
alter table public.catalog_items add column if not exists stock_min int;
alter table public.catalog_items add column if not exists proveedor_id uuid references public.proveedores (id) on delete set null;
create or replace function public.proveedores_lista() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare n uuid := public.negocio_de(auth.uid());
begin
  if n is null or not public.equipo_puede('inventario') then raise exception 'Sin permiso'; end if;
  if not public.pro_o_modulo(n, 'proveedores') then raise exception '📦 Stock mínimo y proveedores es un módulo 🧩: actívalo en Más → Mi plan y módulos'; end if;
  return jsonb_build_object(
    'proveedores', (select coalesce(jsonb_agg(jsonb_build_object('id', v.id, 'nombre', v.nombre, 'tel', v.tel, 'nota', v.nota,
        'bajos', (select count(*) from public.catalog_items c where c.proveedor_id = v.id and c.stock_min is not null and coalesce(c.stock, 0) <= c.stock_min)) order by v.nombre), '[]')
      from public.proveedores v where v.negocio_id = n),
    'productos', (select coalesce(jsonb_agg(jsonb_build_object('clave', c.client_key, 'nombre', c.nombre, 'stock', c.stock, 'min', c.stock_min, 'proveedor', c.proveedor_id,
        'bajo', c.stock_min is not null and coalesce(c.stock, 0) <= c.stock_min) order by (c.stock_min is not null and coalesce(c.stock, 0) <= c.stock_min) desc, c.nombre), '[]')
      from public.catalog_items c where c.owner_id = n));
end $$;
create or replace function public.proveedor_guardar(p_id uuid, p_nombre text, p_tel text, p_nota text default null) returns uuid
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.negocio_de(auth.uid()); t text := regexp_replace(coalesce(p_tel, ''), '\D', '', 'g'); r uuid;
begin
  if n is null or not public.equipo_puede('inventario') then raise exception 'Sin permiso'; end if;
  if not public.pro_o_modulo(n, 'proveedores') then raise exception '📦 Stock mínimo y proveedores es un módulo 🧩: actívalo en Más → Mi plan y módulos'; end if;
  if coalesce(trim(p_nombre), '') = '' then raise exception 'Escribe el nombre del proveedor'; end if;
  if length(t) = 9 and left(t, 1) = '9' then t := '56' || t; end if;
  if t <> '' and t !~ '^569\d{8}$' then raise exception 'WhatsApp: +56 9 y 8 números'; end if;
  if p_id is null then
    if (select count(*) from public.proveedores where negocio_id = n) >= 100 then raise exception 'Máximo 100 proveedores'; end if;
    insert into public.proveedores (negocio_id, nombre, tel, nota) values (n, left(trim(p_nombre), 60), nullif(t, ''), nullif(left(trim(coalesce(p_nota, '')), 200), '')) returning id into r;
  else
    update public.proveedores set nombre = left(trim(p_nombre), 60), tel = nullif(t, ''), nota = nullif(left(trim(coalesce(p_nota, '')), 200), '')
    where id = p_id and negocio_id = n returning id into r;
    if r is null then raise exception 'Proveedor no encontrado'; end if;
  end if;
  return r;
end $$;
create or replace function public.proveedor_borrar(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if public.negocio_de(auth.uid()) is null or not public.equipo_puede('inventario') then raise exception 'Sin permiso'; end if;
  delete from public.proveedores where id = p_id and negocio_id = public.negocio_de(auth.uid());
end $$;
create or replace function public.producto_minimo(p_clave text, p_min int, p_proveedor uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.negocio_de(auth.uid());
begin
  if n is null or not public.equipo_puede('inventario') then raise exception 'Sin permiso'; end if;
  if not public.pro_o_modulo(n, 'proveedores') then raise exception '📦 Stock mínimo y proveedores es un módulo 🧩: actívalo en Más → Mi plan y módulos'; end if;
  if p_min is not null and (p_min < 0 or p_min > 100000) then raise exception 'Mínimo entre 0 y 100.000'; end if;
  if p_proveedor is not null and not exists (select 1 from public.proveedores where id = p_proveedor and negocio_id = n) then raise exception 'Proveedor no encontrado'; end if;
  update public.catalog_items set stock_min = p_min, proveedor_id = p_proveedor where owner_id = n and client_key = p_clave;
  if not found then raise exception 'Producto no encontrado (publícalo primero)'; end if;
end $$;
-- Texto listo del pedido al proveedor: lo que está en su mínimo o menos, para llegar al doble del mínimo.
create or replace function public.pedido_proveedor(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare n uuid := public.negocio_de(auth.uid()); v public.proveedores; l text;
begin
  if n is null or not public.equipo_puede('inventario') then raise exception 'Sin permiso'; end if;
  if not public.pro_o_modulo(n, 'proveedores') then raise exception '📦 Stock mínimo y proveedores es un módulo 🧩: actívalo en Más → Mi plan y módulos'; end if;
  select * into v from public.proveedores where id = p_id and negocio_id = n;
  if v.id is null then raise exception 'Proveedor no encontrado'; end if;
  select string_agg('• ' || greatest(1, c.stock_min * 2 - coalesce(c.stock, 0)) || ' × ' || c.nombre, E'\n' order by c.nombre) into l
  from public.catalog_items c where c.owner_id = n and c.proveedor_id = v.id and c.stock_min is not null and coalesce(c.stock, 0) <= c.stock_min;
  if l is null then raise exception 'Nada bajo el mínimo con este proveedor'; end if;
  return jsonb_build_object('tel', v.tel, 'texto', 'Hola ' || v.nombre || ' 👋 Soy de ' ||
    (select coalesce(nullif(empresa, ''), 'mi tienda') from public.profiles where id = n) || '. Necesito:' || E'\n' || l || E'\n' || '¡Gracias!');
end $$;
-- Aviso al dueño cuando un producto baja de su mínimo (una vez por bajada).
create or replace function public.stock_minimo_aviso() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.stock is not null and new.stock_min is not null and new.stock <= new.stock_min and coalesce(old.stock, new.stock_min + 1) > new.stock_min
     and public.pro_o_modulo(new.owner_id, 'proveedores') then
    perform public.notify_user(new.owner_id, '📦 ' || new.nombre || ' bajó de su mínimo', 'Quedan ' || new.stock || ' (mínimo ' || new.stock_min || '). Pídelo a tu proveedor con un toque.', './#proveedores');
  end if;
  return new;
end $$;
drop trigger if exists catalog_stock_minimo on public.catalog_items;
create trigger catalog_stock_minimo after update of stock on public.catalog_items for each row execute function public.stock_minimo_aviso();

revoke all on function public.giftcard_json(public.giftcards), public.giftcard_devolver(), public.suscripcion_json(public.suscripciones),
  public.suscripciones_correr(), public.stock_minimo_aviso() from public, anon, authenticated;
revoke all on function public.giftcard_crear(int, text, text, text), public.giftcard_lista(), public.giftcard_canjear(text, int), public.giftcard_anular(uuid),
  public.giftcard_saldo(uuid, text), public.suscripcion_guardar(jsonb), public.suscripciones_lista(), public.suscripcion_estado(uuid, boolean),
  public.suscripcion_borrar(uuid), public.mis_suscripciones(), public.proveedores_lista(), public.proveedor_guardar(uuid, text, text, text),
  public.proveedor_borrar(uuid), public.producto_minimo(text, int, uuid), public.pedido_proveedor(uuid) from public, anon;
grant execute on function public.giftcard_crear(int, text, text, text), public.giftcard_lista(), public.giftcard_canjear(text, int), public.giftcard_anular(uuid),
  public.giftcard_saldo(uuid, text), public.suscripcion_guardar(jsonb), public.suscripciones_lista(), public.suscripcion_estado(uuid, boolean),
  public.suscripcion_borrar(uuid), public.mis_suscripciones(), public.proveedores_lista(), public.proveedor_guardar(uuid, text, text, text),
  public.proveedor_borrar(uuid), public.producto_minimo(text, int, uuid), public.pedido_proveedor(uuid) to authenticated;

-- =====================================================================
--  VERSIÓN 5.73 · G96 b 🏬 SUCURSALES Y BODEGAS (módulo 'sucursales') · 📣 PROMOS EN LA APP de tus clientes (módulo 'promos', núcleo).
--  Sucursales: el stock de siempre (catalog_items.stock) sigue siendo el TOTAL que ve la tienda online. Cada sucursal extra guarda
--  cuánto de ese total está ahí; la principal (Casa matriz) es lo que queda (total − sucursales). Así los pedidos online, la Caja sin
--  sucursal y "entró mercadería" siguen igual (cuentan en la principal) y nada de lo de antes cambia. Las opciones (talla/color) van en el total.
-- =====================================================================
create table if not exists public.bodegas (
  id          uuid primary key default gen_random_uuid(),
  negocio_id  uuid not null references public.profiles (id) on delete cascade,
  nombre      text not null check (length(nombre) between 1 and 40),
  direccion   text check (length(direccion) <= 120),
  telefono    text check (length(telefono) <= 16),
  principal   boolean not null default false,
  created_at  timestamptz not null default now()
);
create unique index if not exists bodegas_principal_idx on public.bodegas (negocio_id) where principal;
create index if not exists bodegas_negocio_idx on public.bodegas (negocio_id, created_at);
alter table public.bodegas enable row level security;
revoke all on public.bodegas from anon, authenticated;
create table if not exists public.stock_bodega (
  bodega_id   uuid not null references public.bodegas (id) on delete cascade,
  negocio_id  uuid not null references public.profiles (id) on delete cascade,
  clave       text not null,
  cant        int not null default 0 check (cant between 0 and 1000000),
  primary key (bodega_id, clave)
);
create index if not exists stock_bodega_negocio_idx on public.stock_bodega (negocio_id, clave);
alter table public.stock_bodega enable row level security;
revoke all on public.stock_bodega from anon, authenticated;

-- Lo que hay en las sucursales que NO son la principal (para calcular la principal).
create or replace function public.stock_fuera(n uuid, k text) returns int
language sql stable security definer set search_path = '' as $$
  select coalesce(sum(s.cant), 0)::int from public.stock_bodega s join public.bodegas b on b.id = s.bodega_id and not b.principal where s.negocio_id = n and s.clave = k
$$;
create or replace function public.bodegas_lista() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare n uuid := public.negocio_de(auth.uid()); inv boolean := public.equipo_puede('inventario');
begin
  if n is null or not (inv or public.equipo_puede('caja')) then raise exception 'Sin permiso'; end if;
  if not public.pro_o_modulo(n, 'sucursales') then raise exception '🏬 Sucursales y bodegas es un módulo 🧩: actívalo en Más → Mi plan y módulos'; end if;
  return jsonb_build_object('dueno', n = auth.uid(),
    'bodegas', coalesce((select jsonb_agg(jsonb_build_object('id', b.id, 'nombre', b.nombre, 'direccion', b.direccion, 'telefono', b.telefono, 'principal', b.principal)
      order by b.principal desc, b.created_at) from public.bodegas b where b.negocio_id = n), '[]'),
    'productos', case when inv then coalesce((select jsonb_agg(jsonb_build_object('clave', c.client_key, 'nombre', c.nombre, 'total', c.stock,
        'principal', case when c.stock is null then null else c.stock - public.stock_fuera(n, c.client_key) end,
        'en', coalesce((select jsonb_object_agg(s.bodega_id, s.cant) from public.stock_bodega s where s.negocio_id = n and s.clave = c.client_key), '{}'))
      order by c.nombre) from public.catalog_items c where c.owner_id = n), '[]') else '[]' end);
end $$;
-- Crear / editar una sucursal (solo el dueño). La primera vez crea también la principal ("Casa matriz", se puede renombrar).
create or replace function public.bodega_guardar(p_id uuid, p_nombre text, p_direccion text default null, p_tel text default null) returns uuid
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.negocio_de(auth.uid()); r uuid; t text := regexp_replace(coalesce(p_tel, ''), '\D', '', 'g');
begin
  if n is null or n <> auth.uid() then raise exception 'Solo el dueño de la tienda'; end if;
  if not public.pro_o_modulo(n, 'sucursales') then raise exception '🏬 Sucursales y bodegas es un módulo 🧩: actívalo en Más → Mi plan y módulos'; end if;
  if coalesce(trim(p_nombre), '') = '' then raise exception 'Escribe el nombre de la sucursal'; end if;
  if length(t) = 9 and left(t, 1) = '9' then t := '56' || t; end if;
  if t <> '' and t !~ '^56\d{9}$' then raise exception 'Teléfono: +56 y 9 números'; end if;
  if not exists (select 1 from public.bodegas where negocio_id = n and principal) then
    insert into public.bodegas (negocio_id, nombre, principal) values (n, 'Casa matriz', true);
  end if;
  if p_id is null then
    if (select count(*) from public.bodegas where negocio_id = n) >= 20 then raise exception 'Máximo 20 sucursales'; end if;
    insert into public.bodegas (negocio_id, nombre, direccion, telefono) values (n, left(trim(p_nombre), 40), nullif(left(trim(coalesce(p_direccion, '')), 120), ''), nullif(t, ''))
    returning id into r;
  else
    update public.bodegas set nombre = left(trim(p_nombre), 40), direccion = nullif(left(trim(coalesce(p_direccion, '')), 120), ''), telefono = nullif(t, '')
    where id = p_id and negocio_id = n returning id into r;
    if r is null then raise exception 'Sucursal no encontrada'; end if;
  end if;
  return r;
end $$;
-- Borrar una sucursal: lo que tenía vuelve a la principal (el total no cambia; nada se pierde). La principal no se borra.
create or replace function public.bodega_borrar(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.negocio_de(auth.uid());
begin
  if n is null or n <> auth.uid() then raise exception 'Solo el dueño de la tienda'; end if;
  if exists (select 1 from public.bodegas where id = p_id and negocio_id = n and principal) then raise exception 'La principal no se borra (puedes cambiarle el nombre)'; end if;
  delete from public.bodegas where id = p_id and negocio_id = n;
end $$;
-- Contar lo que hay en una sucursal: el total sube o baja lo mismo (la principal no cambia).
create or replace function public.bodega_stock_fijar(p_bodega uuid, p_clave text, p_cant int) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.negocio_de(auth.uid()); b public.bodegas; c public.catalog_items; antes int; fuera int;
begin
  if n is null or not public.equipo_puede('inventario') then raise exception 'Sin permiso para el inventario'; end if;
  if not public.pro_o_modulo(n, 'sucursales') then raise exception '🏬 Sucursales y bodegas es un módulo 🧩: actívalo en Más → Mi plan y módulos'; end if;
  if p_cant is null or p_cant < 0 or p_cant > 1000000 then raise exception 'Cantidad no válida'; end if;
  select * into b from public.bodegas where id = p_bodega and negocio_id = n;
  if b.id is null then raise exception 'Sucursal no encontrada'; end if;
  select * into c from public.catalog_items where owner_id = n and client_key = p_clave for update;
  if c.id is null then raise exception 'Publica el producto primero'; end if;
  fuera := public.stock_fuera(n, p_clave);
  if b.principal then
    update public.catalog_items set stock = fuera + p_cant, updated_at = now() where id = c.id;
  else
    antes := coalesce((select cant from public.stock_bodega where bodega_id = b.id and clave = p_clave), 0);
    insert into public.stock_bodega (bodega_id, negocio_id, clave, cant) values (b.id, n, p_clave, p_cant)
    on conflict (bodega_id, clave) do update set cant = excluded.cant;
    update public.catalog_items set stock = greatest(fuera - antes + p_cant, coalesce(c.stock, 0) - antes + p_cant), updated_at = now() where id = c.id;
  end if;
  return jsonb_build_object('total', (select stock from public.catalog_items where id = c.id), 'principal', (select stock from public.catalog_items where id = c.id) - public.stock_fuera(n, p_clave));
end $$;
-- Mover mercadería entre sucursales (el total no cambia).
create or replace function public.bodega_mover(p_clave text, p_de uuid, p_a uuid, p_cant int) returns void
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.negocio_de(auth.uid()); de public.bodegas; a public.bodegas; hay int;
begin
  if n is null or not public.equipo_puede('inventario') then raise exception 'Sin permiso para el inventario'; end if;
  if not public.pro_o_modulo(n, 'sucursales') then raise exception '🏬 Sucursales y bodegas es un módulo 🧩: actívalo en Más → Mi plan y módulos'; end if;
  if p_cant is null or p_cant <= 0 or p_cant > 1000000 then raise exception 'Cantidad no válida'; end if;
  select * into de from public.bodegas where id = p_de and negocio_id = n;
  select * into a from public.bodegas where id = p_a and negocio_id = n;
  if de.id is null or a.id is null or de.id = a.id then raise exception 'Elige de dónde y a dónde'; end if;
  perform 1 from public.catalog_items where owner_id = n and client_key = p_clave for update;
  if not found then raise exception 'Producto no encontrado'; end if;
  hay := case when de.principal then coalesce((select stock from public.catalog_items where owner_id = n and client_key = p_clave), 0) - public.stock_fuera(n, p_clave)
              else coalesce((select cant from public.stock_bodega where bodega_id = de.id and clave = p_clave), 0) end;
  if p_cant > hay then raise exception 'En % hay %', de.nombre, greatest(hay, 0); end if;
  if not de.principal then update public.stock_bodega set cant = cant - p_cant where bodega_id = de.id and clave = p_clave; end if;
  if not a.principal then
    insert into public.stock_bodega (bodega_id, negocio_id, clave, cant) values (a.id, n, p_clave, p_cant)
    on conflict (bodega_id, clave) do update set cant = public.stock_bodega.cant + excluded.cant;
  end if;
end $$;

-- Venta en la Caja: igual que antes; si la línea trae "bodega" (Caja de una sucursal), también baja ahí.
create or replace function public.caja_descontar(p_items jsonb) returns void
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.negocio_de(auth.uid()); it jsonb; c int; bg uuid; mod boolean;
begin
  if n is null or not public.equipo_puede('caja') then raise exception 'Sin permiso para vender en la Caja'; end if;
  if jsonb_typeof(coalesce(p_items, '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p_items, '[]'::jsonb)) > 500 then raise exception 'Lista no válida'; end if;
  mod := public.pro_o_modulo(n, 'sucursales');
  for it in select * from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) loop
    c := least(greatest(coalesce((it ->> 'cant')::int, 0), 0), 999);
    continue when c = 0;
    update public.catalog_items set stock = greatest(0, stock - c)
    where owner_id = n and client_key = it ->> 'clave' and stock is not null;
    if nullif(trim(coalesce(it ->> 'opcion', '')), '') is not null then
      update public.variantes set stock = greatest(0, stock - c)
      where owner_id = n and clave = it ->> 'clave' and lower(nombre) = lower(trim(it ->> 'opcion')) and stock is not null;
    end if;
    bg := case when mod and coalesce(it ->> 'bodega', '') ~ '^[0-9a-f-]{36}$' then (it ->> 'bodega')::uuid end;
    if bg is not null then
      update public.stock_bodega s set cant = greatest(0, s.cant - c) from public.bodegas b
      where s.bodega_id = bg and s.clave = it ->> 'clave' and b.id = s.bodega_id and b.negocio_id = n and not b.principal;
    end if;
  end loop;
end $$;

-- 📣 Promos (núcleo): los clientes de Despega son de UNA tienda (profiles.negocio_id).
create or replace function public.cfx_promo_negocios_app(u uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce((select jsonb_agg(jsonb_build_object('n', n.id, 'nombre', coalesce(nullif(n.empresa, ''), 'Tu tienda')))
    from public.profiles c join public.profiles n on n.id = c.negocio_id where c.id = u and c.role = 'client' and not n.suspended), '[]')
$$;
revoke all on function public.cfx_promo_negocios_app(uuid), public.stock_fuera(uuid, text) from public, anon, authenticated;
revoke all on function public.bodegas_lista(), public.bodega_guardar(uuid, text, text, text), public.bodega_borrar(uuid), public.bodega_stock_fijar(uuid, text, int),
  public.bodega_mover(text, uuid, uuid, int), public.caja_descontar(jsonb) from public, anon;
grant execute on function public.bodegas_lista(), public.bodega_guardar(uuid, text, text, text), public.bodega_borrar(uuid), public.bodega_stock_fijar(uuid, text, int),
  public.bodega_mover(text, uuid, uuid, int), public.caja_descontar(jsonb) to authenticated;

create or replace function public.cfx_modulos_app() returns text[]
language sql immutable as $$ select array['chat', 'calificaciones', 'cupones', 'sellos', 'carrito', 'analisis', 'estadisticas', 'equipo', 'campanas', 'redes', 'webhooks', 'medicion', 'dominio', 'giftcards', 'suscripciones', 'proveedores', 'sucursales', 'promos', 'mercadolibre', 'courier', 'estudio'] $$;  -- G96 b: +2 · G101: 🛒 · G102: 🚚 · G112 d: 🎬
revoke all on function public.cfx_modulos_app() from public, anon, authenticated;
-- G112 b: 3 packs iguales en todas las apps (🌱 Básico · ⭐ Normal · 💎 Completo). Solo si sigue el de fábrica.
update public.cfx_config set valor = jsonb_set(valor, '{packs,crecer,nombre}', '"⭐ Normal"')
where clave = 'modulos_venta' and valor #>> '{packs,crecer,nombre}' = '🚀 Crecer';
-- G112 d: 🎬 Estudio de contenido entra al ⭐ Normal (el 💎 Completo ya trae todos). Solo si sigue el de fábrica.
update public.cfx_config set valor = jsonb_set(valor, '{packs,crecer,modulos}', (valor #> '{packs,crecer,modulos}') || '["estudio"]')
where clave = 'modulos_venta' and valor #> '{packs,crecer,modulos}' = '["cupones", "sellos", "calificaciones", "chat", "carrito", "redes", "estadisticas"]'::jsonb;

-- =====================================================================
--  🛒 G101 Mercado Libre (módulo 'mercadolibre'): la tienda conecta SU cuenta de ML (OAuth), une cada producto con su
--  publicación y el stock queda igual en los dos lados: vende allá → se descuenta aquí; cambia aquí → se manda allá.
--  Las credenciales de la app de desarrollador (ml_client_id / ml_client_secret / ml_redirect) las pone el admin (CM → Control → 🛒).
--  Los tokens viven en ml_cuentas sin políticas: nadie los lee desde la app. Todo se valida aquí (pro_o_modulo).
-- =====================================================================
create table if not exists public.ml_cuentas (
  negocio_id uuid primary key references public.profiles (id) on delete cascade,
  ml_user bigint not null,
  nick text,
  access_token text not null,
  refresh_token text,
  expira timestamptz not null,
  activo boolean not null default true,
  desde timestamptz not null default now(),
  ordenes_desde timestamptz,
  revisado_at timestamptz,
  ultimo_error text
);
alter table public.ml_cuentas enable row level security;
revoke all on public.ml_cuentas from anon, authenticated;
create table if not exists public.ml_estados (
  state text primary key,
  negocio_id uuid not null references public.profiles (id) on delete cascade,
  creado timestamptz not null default now()
);
alter table public.ml_estados enable row level security;
revoke all on public.ml_estados from anon, authenticated;
create table if not exists public.ml_vinculos (
  id uuid primary key default gen_random_uuid(),
  negocio_id uuid not null references public.profiles (id) on delete cascade,
  item_id text not null check (item_id ~ '^[A-Z]{3}[0-9]{4,15}$'),
  clave text not null,
  titulo text,
  enviado int,
  enviado_at timestamptz,
  error text,
  creado timestamptz not null default now(),
  unique (negocio_id, item_id),
  unique (negocio_id, clave)
);
alter table public.ml_vinculos enable row level security;
revoke all on public.ml_vinculos from anon, authenticated;
create table if not exists public.ml_ventas (
  negocio_id uuid not null references public.profiles (id) on delete cascade,
  orden text not null,
  item_id text not null,
  cant int not null,
  total numeric(12, 2),
  at timestamptz not null default now(),
  primary key (negocio_id, orden, item_id)
);
alter table public.ml_ventas enable row level security;
revoke all on public.ml_ventas from anon, authenticated;

-- Codifica para URL (sin depender de la extensión http).
create or replace function public.ml_cod(t text) returns text
language sql immutable set search_path = '' as $$
  select coalesce(string_agg(case when x.ch ~ '^[A-Za-z0-9_.~-]$' then x.ch
    else upper(regexp_replace(encode(convert_to(x.ch, 'UTF8'), 'hex'), '(..)', '%\1', 'g')) end, '' order by x.i), '')
  from unnest(regexp_split_to_array(coalesce(t, ''), '')) with ordinality as x(ch, i)
$$;

-- Llamada a la API de Mercado Libre (solo dentro de la base). Con token = Bearer; sin token y con forma = formulario (OAuth).
create or replace function public.ml_api(p_token text, p_metodo text, p_ruta text, p_cuerpo jsonb default null, p_forma text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare st int; c text;
begin
  perform extensions.http_set_curlopt('CURLOPT_TIMEOUT', '10');
  execute 'select status, content from extensions.http(row($1, $2, $3, $4, $5)::extensions.http_request)' into st, c
    using p_metodo, 'https://api.mercadolibre.com' || p_ruta,
          case when p_token is null then array[row('Accept', 'application/json')::extensions.http_header]
               else array[row('Authorization', 'Bearer ' || p_token)::extensions.http_header] end,
          case when p_forma is not null then 'application/x-www-form-urlencoded' else 'application/json' end,
          coalesce(p_forma, p_cuerpo::text);
  return jsonb_build_object('status', st, 'body', case when c ~ '^\s*[\{\[]' then c::jsonb end);
exception when others then
  return jsonb_build_object('status', 0, 'error', sqlerrm);
end $$;

create or replace function public.ml_app() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('id', (select value from public.app_secrets where name = 'ml_client_id'),
    'secreto', (select value from public.app_secrets where name = 'ml_client_secret'),
    'volver', (select value from public.app_secrets where name = 'ml_redirect'))
$$;

-- Admin (CM → Control → 🛒 Mercado Libre): credenciales de la app de desarrollador. El secreto nunca se vuelve a leer.
create or replace function public.ml_app_guardar(p_id text, p_secreto text, p_volver text) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  perform public.cfx_es_admin();
  if coalesce(p_id, '') !~ '^[0-9]{4,25}$' then raise exception 'El App ID son solo números'; end if;
  if coalesce(p_volver, '') !~ '^https://[^\s?#]+$' then raise exception 'La URL de redirección empieza con https:// (sin ? ni #)'; end if;
  insert into public.app_secrets (name, value) values ('ml_client_id', p_id), ('ml_redirect', p_volver)
  on conflict (name) do update set value = excluded.value;
  if nullif(trim(coalesce(p_secreto, '')), '') is not null then
    if length(trim(p_secreto)) < 10 then raise exception 'Revisa la Clave secreta'; end if;
    insert into public.app_secrets (name, value) values ('ml_client_secret', trim(p_secreto)) on conflict (name) do update set value = excluded.value;
  end if;
  return public.ml_app_estado();
end $$;
create or replace function public.ml_app_estado() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare a jsonb := public.ml_app();
begin
  perform public.cfx_es_admin();
  return jsonb_build_object('id', a ->> 'id', 'volver', a ->> 'volver', 'secreto', a ->> 'secreto' is not null,
    'cuentas', (select count(*) from public.ml_cuentas), 'vinculos', (select count(*) from public.ml_vinculos));
end $$;

-- Token vigente de la tienda (lo renueva si vence en menos de 5 minutos). null = hay que volver a conectar.
create or replace function public.ml_token(n uuid) returns text
language plpgsql security definer set search_path = '' as $$
declare c public.ml_cuentas; a jsonb := public.ml_app(); r jsonb;
begin
  select * into c from public.ml_cuentas where negocio_id = n;
  if not found then return null; end if;
  if c.expira > now() + interval '5 minutes' then return c.access_token; end if;
  if c.refresh_token is null or a ->> 'id' is null or a ->> 'secreto' is null then
    update public.ml_cuentas set ultimo_error = 'Vuelve a conectar Mercado Libre' where negocio_id = n; return null;
  end if;
  r := public.ml_api(null, 'POST', '/oauth/token', null, 'grant_type=refresh_token&client_id=' || public.ml_cod(a ->> 'id') ||
    '&client_secret=' || public.ml_cod(a ->> 'secreto') || '&refresh_token=' || public.ml_cod(c.refresh_token));
  if (r ->> 'status')::int = 200 and r #>> '{body,access_token}' is not null then
    update public.ml_cuentas set access_token = r #>> '{body,access_token}', refresh_token = coalesce(r #>> '{body,refresh_token}', refresh_token),
      expira = now() + make_interval(secs => coalesce((r #>> '{body,expires_in}')::int, 21600)), ultimo_error = null where negocio_id = n;
    return r #>> '{body,access_token}';
  end if;
  update public.ml_cuentas set ultimo_error = 'Vuelve a conectar Mercado Libre (el permiso venció)' where negocio_id = n;
  return null;
end $$;

create or replace function public.ml_negocio() returns uuid
language plpgsql stable security definer set search_path = '' as $$
declare n uuid := public.negocio_de(auth.uid());
begin
  if n is null or n <> auth.uid() then raise exception 'Solo el dueño de la tienda'; end if;
  if not public.pro_o_modulo(n, 'mercadolibre') then raise exception '🛒 Mercado Libre es un módulo 🧩: actívalo en Más → Mi plan y módulos'; end if;
  return n;
end $$;

create or replace function public.ml_estado() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.ml_negocio(); c public.ml_cuentas; a jsonb := public.ml_app();
begin
  select * into c from public.ml_cuentas where negocio_id = n;
  return jsonb_build_object('app', a ->> 'id' is not null and a ->> 'secreto' is not null and a ->> 'volver' is not null,
    'conectado', c.negocio_id is not null, 'nick', c.nick, 'activo', coalesce(c.activo, false), 'error', c.ultimo_error, 'revisado', c.revisado_at,
    'ventas_mes', (select coalesce(sum(v.cant), 0) from public.ml_ventas v where v.negocio_id = n and v.at >= date_trunc('month', now())),
    'vinculos', (select coalesce(jsonb_agg(jsonb_build_object('id', l.id, 'item', l.item_id, 'titulo', l.titulo, 'clave', l.clave,
        'nombre', i.nombre, 'stock', i.stock, 'enviado', l.enviado, 'error', l.error, 'existe', i.id is not null) order by l.creado), '[]')
      from public.ml_vinculos l left join public.catalog_items i on i.owner_id = n and i.client_key = l.clave where l.negocio_id = n),
    'productos', (select coalesce(jsonb_agg(jsonb_build_object('clave', i.client_key, 'nombre', i.nombre, 'stock', i.stock) order by i.nombre), '[]')
      from public.catalog_items i where i.owner_id = n));
end $$;

-- 1) Conectar: arma el link de autorización de ML (state al azar, vale 15 minutos).
create or replace function public.ml_conectar() returns text
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.ml_negocio(); a jsonb := public.ml_app(); s text := 'ml' || encode(extensions.gen_random_bytes(16), 'hex');
begin
  if a ->> 'id' is null or a ->> 'secreto' is null or a ->> 'volver' is null then raise exception 'CodeFix aún no activa Mercado Libre: avísanos por 🛟 Soporte'; end if;
  delete from public.ml_estados where negocio_id = n or creado < now() - interval '1 day';
  insert into public.ml_estados (state, negocio_id) values (s, n);
  return 'https://auth.mercadolibre.cl/authorization?response_type=code&client_id=' || public.ml_cod(a ->> 'id') ||
    '&redirect_uri=' || public.ml_cod(a ->> 'volver') || '&state=' || s;
end $$;

-- 2) Vuelta desde ML (?code=…&state=…): canjea el código por el token aquí (con la clave secreta, que nunca sale de la base).
create or replace function public.ml_volver(p_state text, p_code text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.ml_negocio(); a jsonb := public.ml_app(); r jsonb; u jsonb;
begin
  if coalesce(p_state, '') !~ '^ml[0-9a-f]{32}$' or coalesce(p_code, '') !~ '^[A-Za-z0-9_-]{6,200}$' then raise exception 'Link de Mercado Libre no válido'; end if;
  delete from public.ml_estados where state = p_state and negocio_id = n and creado > now() - interval '15 minutes';
  if not found then raise exception 'El permiso venció o no es de esta tienda: toca Conectar de nuevo'; end if;
  r := public.ml_api(null, 'POST', '/oauth/token', null, 'grant_type=authorization_code&client_id=' || public.ml_cod(a ->> 'id') ||
    '&client_secret=' || public.ml_cod(a ->> 'secreto') || '&code=' || public.ml_cod(p_code) || '&redirect_uri=' || public.ml_cod(a ->> 'volver'));
  if coalesce((r ->> 'status')::int, 0) <> 200 or r #>> '{body,access_token}' is null then
    raise exception 'Mercado Libre no aceptó la conexión (%). Toca Conectar de nuevo', coalesce(r #>> '{body,message}', r ->> 'error', r ->> 'status');
  end if;
  u := public.ml_api(r #>> '{body,access_token}', 'GET', '/users/me');
  if coalesce((u ->> 'status')::int, 0) <> 200 or u #>> '{body,id}' is null then raise exception 'No pudimos leer tu cuenta de Mercado Libre'; end if;
  if (u #>> '{body,id}')::bigint <> coalesce((r #>> '{body,user_id}')::bigint, (u #>> '{body,id}')::bigint) then raise exception 'La cuenta no coincide'; end if;
  insert into public.ml_cuentas (negocio_id, ml_user, nick, access_token, refresh_token, expira, activo, desde, ordenes_desde, ultimo_error)
  values (n, (u #>> '{body,id}')::bigint, left(u #>> '{body,nickname}', 80), r #>> '{body,access_token}', r #>> '{body,refresh_token}',
          now() + make_interval(secs => coalesce((r #>> '{body,expires_in}')::int, 21600)), true, now(), now(), null)
  on conflict (negocio_id) do update set ml_user = excluded.ml_user, nick = excluded.nick, access_token = excluded.access_token,
    refresh_token = excluded.refresh_token, expira = excluded.expira, activo = true, ultimo_error = null,
    ordenes_desde = case when public.ml_cuentas.ml_user = excluded.ml_user then public.ml_cuentas.ordenes_desde else now() end;
  return jsonb_build_object('nick', u #>> '{body,nickname}');
end $$;

create or replace function public.ml_pausar(p_activo boolean) returns void
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.ml_negocio();
begin update public.ml_cuentas set activo = coalesce(p_activo, false) where negocio_id = n; end $$;

-- Desconectar: borra los tokens; las uniones quedan guardadas (🛡️) para cuando vuelva a conectar.
create or replace function public.ml_desconectar() returns void
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.negocio_de(auth.uid());
begin
  if n is null or n <> auth.uid() then raise exception 'Solo el dueño de la tienda'; end if;
  delete from public.ml_cuentas where negocio_id = n;
end $$;

-- Tus publicaciones activas en ML (para unirlas con tus productos).
create or replace function public.ml_publicaciones() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.ml_negocio(); t text := public.ml_token(n); c public.ml_cuentas; r jsonb; ids text; d jsonb;
begin
  if t is null then raise exception 'Conecta tu Mercado Libre primero'; end if;
  select * into c from public.ml_cuentas where negocio_id = n;
  r := public.ml_api(t, 'GET', '/users/' || c.ml_user || '/items/search?status=active&limit=50');
  if coalesce((r ->> 'status')::int, 0) <> 200 then raise exception 'Mercado Libre no respondió: prueba en un rato'; end if;
  select string_agg(x, ',') into ids from (select jsonb_array_elements_text(coalesce(r #> '{body,results}', '[]')) x limit 50) s where x ~ '^[A-Z]{3}[0-9]{4,15}$';
  if ids is null then return '[]'; end if;
  d := '[]';
  for r in select value from jsonb_array_elements(coalesce((public.ml_api(t, 'GET', '/items?ids=' || ids || '&attributes=id,title,price,available_quantity,thumbnail')) -> 'body', '[]')) loop
    continue when coalesce((r ->> 'code')::int, 200) <> 200;
    d := d || jsonb_build_array(jsonb_build_object('item', r #>> '{body,id}', 'titulo', r #>> '{body,title}', 'precio', (r #>> '{body,price}')::numeric,
      'stock', (r #>> '{body,available_quantity}')::int, 'foto', case when r #>> '{body,thumbnail}' ~ '^https://' then r #>> '{body,thumbnail}' end,
      'clave', (select l.clave from public.ml_vinculos l where l.negocio_id = n and l.item_id = r #>> '{body,id}')));
  end loop;
  return d;
end $$;

-- Unir (o soltar con p_clave = null) una publicación de ML con un producto de la tienda.
create or replace function public.ml_vincular(p_item text, p_clave text, p_titulo text default null) returns void
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.ml_negocio();
begin
  if coalesce(p_item, '') !~ '^[A-Z]{3}[0-9]{4,15}$' then raise exception 'Publicación no válida'; end if;
  if p_clave is null then delete from public.ml_vinculos where negocio_id = n and item_id = p_item; return; end if;
  if not exists (select 1 from public.catalog_items where owner_id = n and client_key = p_clave) then raise exception 'Producto no encontrado'; end if;
  if (select count(*) from public.ml_vinculos where negocio_id = n) >= 300 then raise exception 'Máximo 300 publicaciones unidas'; end if;
  delete from public.ml_vinculos where negocio_id = n and (clave = p_clave or item_id = p_item);
  insert into public.ml_vinculos (negocio_id, item_id, clave, titulo) values (n, p_item, p_clave, left(nullif(trim(coalesce(p_titulo, '')), ''), 120));
end $$;

-- El trabajo: ventas pagadas en ML → descuenta aquí (1 vez por orden) · stock distinto al enviado → lo manda a ML.
create or replace function public.ml_sincronizar(p_negocio uuid default null) returns int
language plpgsql security definer set search_path = '' as $$
declare c public.ml_cuentas; t text; r jsonb; o jsonb; it jsonb; l public.ml_vinculos; s int; q int; hechos int := 0; hasta timestamptz; nom text;
begin
  for c in select * from public.ml_cuentas m where m.activo and (p_negocio is null or m.negocio_id = p_negocio) order by m.revisado_at nulls first limit 30 loop
    continue when not public.pro_o_modulo(c.negocio_id, 'mercadolibre');
    t := public.ml_token(c.negocio_id);
    if t is null then update public.ml_cuentas set revisado_at = now() where negocio_id = c.negocio_id; continue; end if;
    hasta := coalesce(c.ordenes_desde, c.desde);
    r := public.ml_api(t, 'GET', '/orders/search?seller=' || c.ml_user || '&order.status=paid&sort=date_asc&limit=50&order.date_created.from=' ||
      public.ml_cod(to_char(hasta at time zone 'UTC' - interval '10 minutes', 'YYYY-MM-DD"T"HH24:MI:SS".000-00:00"')));
    if coalesce((r ->> 'status')::int, 0) = 200 then
      for o in select value from jsonb_array_elements(coalesce(r #> '{body,results}', '[]')) loop
        for it in select value from jsonb_array_elements(coalesce(o -> 'order_items', '[]')) loop
          select * into l from public.ml_vinculos where negocio_id = c.negocio_id and item_id = it #>> '{item,id}';
          continue when not found;
          q := greatest(0, coalesce((it ->> 'quantity')::int, 0));
          continue when q = 0;
          insert into public.ml_ventas (negocio_id, orden, item_id, cant, total) values (c.negocio_id, o ->> 'id', l.item_id, q, (it ->> 'unit_price')::numeric * q)
          on conflict do nothing;
          continue when not found;
          update public.catalog_items set stock = greatest(0, stock - q) where owner_id = c.negocio_id and client_key = l.clave and stock is not null
          returning nombre into nom;
          update public.ml_vinculos set enviado = greatest(0, enviado - q) where id = l.id and enviado is not null;  -- ML ya lo bajó allá
          insert into public.notifications (owner_id, target_id, audience, channels, title, body, url, send_at)
          values (c.negocio_id, c.negocio_id, 'direct', '{push}', '🛒 Vendiste en Mercado Libre',
                  q || ' × ' || coalesce(nom, l.titulo, l.item_id) || ': ya lo descontamos de tu stock.', './#mercadolibre', now());
          hechos := hechos + 1;
        end loop;
        hasta := greatest(hasta, coalesce((o ->> 'date_created')::timestamptz, hasta));
      end loop;
      update public.ml_cuentas set ordenes_desde = hasta where negocio_id = c.negocio_id;
    end if;
    for l in select v.* from public.ml_vinculos v join public.catalog_items i on i.owner_id = v.negocio_id and i.client_key = v.clave
             where v.negocio_id = c.negocio_id and i.stock is not null and i.stock is distinct from v.enviado limit 50 loop
      select stock into s from public.catalog_items where owner_id = c.negocio_id and client_key = l.clave;
      r := public.ml_api(t, 'PUT', '/items/' || l.item_id, jsonb_build_object('available_quantity', greatest(0, s)));
      if coalesce((r ->> 'status')::int, 0) = 200 then
        update public.ml_vinculos set enviado = s, enviado_at = now(), error = null where id = l.id; hechos := hechos + 1;
      else
        update public.ml_vinculos set error = left(coalesce(r #>> '{body,message}', r ->> 'error', 'Error ' || (r ->> 'status')), 160) where id = l.id;
      end if;
    end loop;
    update public.ml_cuentas set revisado_at = now() where negocio_id = c.negocio_id;
  end loop;
  return hechos;
end $$;

-- 🔄 Sincronizar ahora (botón de la tienda).
create or replace function public.ml_sincronizar_mio() returns int
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.ml_negocio();
begin return public.ml_sincronizar(n); end $$;

revoke all on function public.ml_cod(text), public.ml_api(text, text, text, jsonb, text), public.ml_app(), public.ml_token(uuid), public.ml_sincronizar(uuid), public.ml_negocio()
  from public, anon, authenticated;
revoke all on function public.ml_app_guardar(text, text, text), public.ml_app_estado(), public.ml_estado(), public.ml_conectar(), public.ml_volver(text, text),
  public.ml_pausar(boolean), public.ml_desconectar(), public.ml_publicaciones(), public.ml_vincular(text, text, text), public.ml_sincronizar_mio() from public, anon;
grant execute on function public.ml_app_guardar(text, text, text), public.ml_app_estado(), public.ml_estado(), public.ml_conectar(), public.ml_volver(text, text),
  public.ml_pausar(boolean), public.ml_desconectar(), public.ml_publicaciones(), public.ml_vincular(text, text, text), public.ml_sincronizar_mio() to authenticated;
do $$ begin
  perform cron.unschedule('ml-sync') where exists (select 1 from cron.job where jobname = 'ml-sync');
  perform cron.schedule('ml-sync', '*/5 * * * *', 'select public.ml_sincronizar()');
exception when others then null; end $$;

-- =====================================================================
--  🚚 G102 a Courier Chilexpress (módulo 'courier'): la tienda pone SUS llaves de la API de Chilexpress
--  (developers.wschilexpress.com: Cotizador, Coberturas y Envíos) y su N° de cliente (TCC, del contrato).
--  · 💲 Cotiza el envío a cualquier comuna (calculadora en Más → 🚚 Courier y al hacer la etiqueta).
--  · 🏷️ Etiqueta desde Pedidos: crea la orden de transporte (OT), guarda la etiqueta para imprimir y pone el
--    código de seguimiento solo (pedido_seguimiento → el cliente recibe el aviso "En camino").
--  Las llaves viven en courier_cuentas sin políticas: nadie las lee desde la app. Todo se valida aquí (pro_o_modulo).
-- =====================================================================
create table if not exists public.courier_cuentas (
  negocio_id uuid primary key references public.profiles (id) on delete cascade,
  prueba boolean not null default false,
  llave_cot text,
  llave_cob text,
  llave_env text,
  tcc text,
  origen text,
  origen_cod text,
  rem_nombre text,
  rem_tel text,
  rem_correo text,
  rem_calle text,
  rem_numero text,
  rem_extra text,
  peso numeric(6, 2) not null default 1,
  tamano text not null default 'chica',
  ultimo_error text,
  actualizado timestamptz not null default now()
);
alter table public.courier_cuentas enable row level security;
revoke all on public.courier_cuentas from anon, authenticated;
-- Comunas de Chilexpress (código de cobertura). Datos públicos que se traen 1 vez al día como mucho.
create table if not exists public.chx_comunas (
  cod text primary key,
  nombre text not null,
  norm text not null,
  region text,
  at timestamptz not null default now()
);
create index if not exists chx_comunas_norm_idx on public.chx_comunas (norm);
alter table public.chx_comunas enable row level security;
revoke all on public.chx_comunas from anon, authenticated;
create table if not exists public.courier_envios (
  pedido_id uuid primary key references public.pedidos (id) on delete cascade,
  negocio_id uuid not null references public.profiles (id) on delete cascade,
  ot text not null,
  servicio text,
  valor int,
  etiqueta text,
  tipo text,
  creado timestamptz not null default now()
);
create index if not exists courier_envios_negocio_idx on public.courier_envios (negocio_id, creado desc);
alter table public.courier_envios enable row level security;
revoke all on public.courier_envios from anon, authenticated;

-- Llamada a la API de Chilexpress (solo dentro de la base). prueba = ambiente de pruebas (testservices).
create or replace function public.chx_api(p_llave text, p_prueba boolean, p_metodo text, p_ruta text, p_cuerpo jsonb default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare st int; c text;
begin
  if nullif(p_llave, '') is null then return jsonb_build_object('status', 0, 'error', 'Falta la llave'); end if;
  perform extensions.http_set_curlopt('CURLOPT_TIMEOUT', '12');
  execute 'select status, content from extensions.http(row($1, $2, $3, $4, $5)::extensions.http_request)' into st, c
    using p_metodo, case when p_prueba then 'https://testservices.wschilexpress.com' else 'https://services.wschilexpress.com' end || p_ruta,
          array[row('Ocp-Apim-Subscription-Key', p_llave)::extensions.http_header, row('Cache-Control', 'no-cache')::extensions.http_header],
          'application/json', p_cuerpo::text;
  return jsonb_build_object('status', st, 'body', case when c ~ '^\s*[\{\[]' then c::jsonb end);
exception when others then
  return jsonb_build_object('status', 0, 'error', sqlerrm);
end $$;

-- Mensaje de error de Chilexpress en palabras simples.
create or replace function public.chx_error(r jsonb) returns text
language sql immutable set search_path = '' as $$
  select left(coalesce(case when (r ->> 'status') in ('401', '403') then 'la llave no es válida o no tiene ese servicio' end,
    r #>> '{body,statusDescription}', r #>> '{body,message}', r #>> '{body,errors,0}', r ->> 'error', 'sin respuesta (' || coalesce(r ->> 'status', '0') || ')'), 200)
$$;

-- Código de cobertura de una comuna (por nombre). Si no está, trae las comunas de Chilexpress (1 vez al día como mucho).
create or replace function public.chx_codigo(c public.courier_cuentas, p_comuna text) returns text
language plpgsql security definer set search_path = '' as $$
declare k text; nm text := public.cfx_comuna_norm(p_comuna); r jsonb; g jsonb; a jsonb; llave text := coalesce(nullif(c.llave_cob, ''), c.llave_cot);
begin
  if nm = '' then return null; end if;
  select cod into k from public.chx_comunas where norm = nm order by cod limit 1;
  if k is not null then return k; end if;
  if exists (select 1 from public.chx_comunas where at > now() - interval '1 day') or llave is null then return null; end if;
  r := public.chx_api(llave, c.prueba, 'GET', '/georeference/api/v1.0/regions');
  if coalesce((r ->> 'status')::int, 0) <> 200 then
    update public.courier_cuentas set ultimo_error = 'Coberturas: ' || public.chx_error(r) where negocio_id = c.negocio_id; return null;
  end if;
  for g in select * from jsonb_array_elements(coalesce(r #> '{body,regions}', '[]'::jsonb)) loop
    continue when coalesce(g ->> 'regionId', '') !~ '^[A-Z0-9]{1,6}$';
    a := public.chx_api(llave, c.prueba, 'GET', '/georeference/api/v1.0/coverage-areas?RegionCode=' || (g ->> 'regionId') || '&type=0');
    insert into public.chx_comunas (cod, nombre, norm, region, at)
    select left(x ->> 'countyCode', 12), left(x ->> 'countyName', 60), public.cfx_comuna_norm(x ->> 'countyName'), g ->> 'regionId', now()
    from jsonb_array_elements(coalesce(a #> '{body,coverageAreas}', '[]'::jsonb)) x
    where coalesce(x ->> 'countyCode', '') ~ '^[A-Z0-9]{2,12}$' and coalesce(x ->> 'countyName', '') <> ''
    on conflict (cod) do update set nombre = excluded.nombre, norm = excluded.norm, region = excluded.region, at = now();
  end loop;
  select cod into k from public.chx_comunas where norm = nm order by cod limit 1;
  return k;
end $$;

-- Medidas por tamaño (cm): sobre · chica · mediana · grande.
create or replace function public.chx_medidas(t text) returns jsonb
language sql immutable set search_path = '' as $$
  select case coalesce(t, 'chica') when 'sobre' then '{"alto":2,"ancho":25,"largo":35}' when 'mediana' then '{"alto":20,"ancho":25,"largo":30}'
    when 'grande' then '{"alto":30,"ancho":40,"largo":50}' else '{"alto":10,"ancho":15,"largo":20}' end::jsonb
$$;

create or replace function public.courier_negocio() returns uuid
language plpgsql stable security definer set search_path = '' as $$
declare n uuid := public.negocio_de(auth.uid());
begin
  if n is null or n <> auth.uid() then raise exception 'Solo el dueño de la tienda'; end if;
  if not public.pro_o_modulo(n, 'courier') then raise exception '🚚 Courier Chilexpress es un módulo 🧩: actívalo en Más → Mi plan y módulos'; end if;
  return n;
end $$;

-- Dueño o equipo con Pedidos (para cotizar y hacer etiquetas).
create or replace function public.courier_mio() returns public.courier_cuentas
language plpgsql stable security definer set search_path = '' as $$
declare n uuid := public.negocio_de(auth.uid()); c public.courier_cuentas;
begin
  if n is null or not public.equipo_puede('pedidos') then raise exception 'Sin permiso'; end if;
  if not public.pro_o_modulo(n, 'courier') then raise exception '🚚 Courier Chilexpress es un módulo 🧩: actívalo en Más → Mi plan y módulos'; end if;
  select * into c from public.courier_cuentas where negocio_id = n;
  if c.negocio_id is null or c.llave_cot is null or c.origen_cod is null then raise exception 'Primero conecta Chilexpress en Más → 🚚 Courier'; end if;
  return c;
end $$;

create or replace function public.courier_estado() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.courier_negocio(); c public.courier_cuentas; p public.profiles;
begin
  select * into c from public.courier_cuentas where negocio_id = n;
  select * into p from public.profiles where id = n;
  return jsonb_build_object('conectado', c.llave_cot is not null and c.origen_cod is not null, 'etiquetas', c.llave_env is not null and c.tcc is not null,
    'prueba', coalesce(c.prueba, false), 'llave_cot', c.llave_cot is not null, 'llave_cob', c.llave_cob is not null, 'llave_env', c.llave_env is not null,
    'tcc', case when c.tcc is not null then '•••' || right(c.tcc, 3) end, 'origen', c.origen,
    'rem_nombre', coalesce(c.rem_nombre, p.empresa), 'rem_tel', coalesce(c.rem_tel, p.telefono), 'rem_correo', c.rem_correo,
    'rem_calle', c.rem_calle, 'rem_numero', c.rem_numero, 'rem_extra', c.rem_extra,
    'peso', coalesce(c.peso, 1), 'tamano', coalesce(c.tamano, 'chica'), 'error', c.ultimo_error,
    'envios_mes', (select count(*) from public.courier_envios e where e.negocio_id = n and e.creado >= date_trunc('month', now())),
    'ultimos', (select coalesce(jsonb_agg(jsonb_build_object('pedido', e.pedido_id, 'ot', e.ot, 'servicio', e.servicio, 'valor', e.valor, 'creado', e.creado,
        'cliente', coalesce(nullif(cl.empresa, ''), x.invitado_nombre, split_part(cl.email, '@', 1), 'Cliente')) order by e.creado desc), '[]')
      from (select * from public.courier_envios where negocio_id = n order by creado desc limit 10) e
      join public.pedidos x on x.id = e.pedido_id left join public.profiles cl on cl.id = x.cliente_id));
end $$;

-- Guardar la conexión. Las llaves y el TCC solo se cambian si vienen escritos (nunca se vuelven a leer).
create or replace function public.courier_guardar(p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare n uuid := public.courier_negocio(); c public.courier_cuentas; k text; v text; tel text;
begin
  if jsonb_typeof(p) is distinct from 'object' then raise exception 'Datos no válidos'; end if;
  insert into public.courier_cuentas (negocio_id) values (n) on conflict (negocio_id) do nothing;
  foreach k in array array['llave_cot', 'llave_cob', 'llave_env'] loop
    v := nullif(trim(coalesce(p ->> k, '')), '');
    if v is not null and v !~ '^[A-Za-z0-9]{16,64}$' then raise exception 'Revisa la llave: son 32 letras y números (Chilexpress → Mis suscripciones)'; end if;
    if v is not null then execute format('update public.courier_cuentas set %I = $1 where negocio_id = $2', k) using v, n; end if;
  end loop;
  v := nullif(regexp_replace(coalesce(p ->> 'tcc', ''), '\D', '', 'g'), '');
  if v is not null and length(v) not between 5 and 12 then raise exception 'El N° de cliente (TCC) son 5 a 12 números'; end if;
  if v is not null then update public.courier_cuentas set tcc = v where negocio_id = n; end if;
  if coalesce((p ->> 'borrar_envios')::boolean, false) then update public.courier_cuentas set llave_env = null, tcc = null where negocio_id = n; end if;
  tel := regexp_replace(coalesce(p ->> 'rem_tel', ''), '\D', '', 'g');
  if tel <> '' and tel !~ '^(56)?9[0-9]{8}$' and tel !~ '^(56)?[2-8][0-9]{8}$' then raise exception 'Teléfono no válido (ej: +56 9 1234 5678)'; end if;
  if coalesce(p ->> 'rem_correo', '') <> '' and (p ->> 'rem_correo') !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Correo no válido'; end if;
  if coalesce((p ->> 'peso')::numeric, 1) not between 0.1 and 100 then raise exception 'El peso va de 0,1 a 100 kg'; end if;
  if coalesce(p ->> 'tamano', 'chica') not in ('sobre', 'chica', 'mediana', 'grande') then raise exception 'Tamaño no válido'; end if;
  update public.courier_cuentas set prueba = coalesce((p ->> 'prueba')::boolean, false),
    rem_nombre = left(nullif(trim(p ->> 'rem_nombre'), ''), 60), rem_tel = nullif(right(tel, 9), ''), rem_correo = left(nullif(trim(p ->> 'rem_correo'), ''), 80),
    rem_calle = left(nullif(trim(p ->> 'rem_calle'), ''), 80), rem_numero = left(nullif(trim(p ->> 'rem_numero'), ''), 10), rem_extra = left(nullif(trim(p ->> 'rem_extra'), ''), 40),
    peso = coalesce((p ->> 'peso')::numeric, 1), tamano = coalesce(p ->> 'tamano', 'chica'), actualizado = now()
  where negocio_id = n returning * into c;
  if nullif(trim(coalesce(p ->> 'origen', '')), '') is not null and (c.origen is distinct from trim(p ->> 'origen') or c.origen_cod is null) then
    if c.llave_cot is null then raise exception 'Escribe la llave del Cotizador'; end if;
    k := public.chx_codigo(c, p ->> 'origen');
    if k is null then raise exception 'No encontramos la comuna "%" en Chilexpress. Revisa cómo se escribe (o la llave)', left(trim(p ->> 'origen'), 40); end if;
    update public.courier_cuentas set origen = left(trim(p ->> 'origen'), 40), origen_cod = k, ultimo_error = null where negocio_id = n;
  end if;
  return public.courier_estado();
end $$;

-- 💲 Cotizar: opciones de servicio [{codigo, nombre, valor}] de la comuna de origen a la de destino.
create or replace function public.chx_cotizar(c public.courier_cuentas, p_comuna text, p_peso numeric, p_tamano text, p_valor numeric) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare d text := public.chx_codigo(c, p_comuna); m jsonb := public.chx_medidas(p_tamano); r jsonb;
begin
  if d is null then raise exception 'Chilexpress no encuentra la comuna "%" (revisa cómo se escribe)', left(coalesce(trim(p_comuna), ''), 40); end if;
  if coalesce(p_peso, 0) not between 0.1 and 100 then raise exception 'El peso va de 0,1 a 100 kg'; end if;
  r := public.chx_api(c.llave_cot, c.prueba, 'POST', '/rating/api/v1.0/rates/courier', jsonb_build_object(
    'originCountyCode', c.origen_cod, 'destinationCountyCode', d,
    'package', jsonb_build_object('weight', p_peso::text, 'height', m ->> 'alto', 'width', m ->> 'ancho', 'length', m ->> 'largo'),
    'productType', 3, 'contentType', 1, 'declaredWorth', round(greatest(coalesce(p_valor, 0), 0))::text, 'deliveryTime', 0));
  if coalesce((r ->> 'status')::int, 0) <> 200 or jsonb_typeof(r #> '{body,data,courierServiceOptions}') is distinct from 'array' then
    raise exception 'Chilexpress no pudo cotizar: %', public.chx_error(r);
  end if;
  return jsonb_build_object('destino', d, 'opciones', (select coalesce(jsonb_agg(jsonb_build_object('codigo', (o ->> 'serviceTypeCode')::int,
      'nombre', initcap(lower(left(o ->> 'serviceDescription', 40))), 'valor', round((o ->> 'serviceValue')::numeric)) order by (o ->> 'serviceValue')::numeric), '[]')
    from jsonb_array_elements(r #> '{body,data,courierServiceOptions}') o
    where coalesce(o ->> 'serviceTypeCode', '') ~ '^[0-9]{1,3}$' and coalesce(o ->> 'serviceValue', '') ~ '^[0-9]+(\.[0-9]+)?$'));
end $$;
create or replace function public.courier_cotizar(p_comuna text, p_peso numeric default null, p_tamano text default null, p_valor numeric default 0) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare c public.courier_cuentas := public.courier_mio();
begin
  return public.chx_cotizar(c, p_comuna, coalesce(p_peso, c.peso), coalesce(p_tamano, c.tamano), p_valor);
end $$;

-- Datos para la etiqueta de un pedido: destino (comuna, calle y número separados), cliente y cotización.
create or replace function public.courier_preparar(p_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare c public.courier_cuentas := public.courier_mio(); x public.pedidos; cl public.profiles; com text; dir text; m text[]; q jsonb; e public.courier_envios;
begin
  select * into x from public.pedidos where id = p_id and negocio_id = c.negocio_id;
  if x.id is null then raise exception 'Pedido no encontrado'; end if;
  if x.entrega <> 'despacho' then raise exception 'Este pedido es con retiro en tienda'; end if;
  select * into e from public.courier_envios where pedido_id = x.id;
  if e.pedido_id is not null then return jsonb_build_object('hecha', true, 'ot', e.ot); end if;
  select * into cl from public.profiles where id = x.cliente_id;
  com := coalesce(nullif(x.comuna, ''), nullif(trim(regexp_replace(coalesce(x.direccion, ''), '^.*,', '')), ''));
  dir := trim(case when position(',' in coalesce(x.direccion, '')) > 0 then regexp_replace(x.direccion, ',[^,]*$', '') else coalesce(x.direccion, '') end);
  m := regexp_match(dir, '^(.*?)\s*(?:#|[Nn][°º.])?\s*([0-9]{1,6})\y\s*(.*)$');
  begin q := public.chx_cotizar(c, com, c.peso, c.tamano, x.subtotal); exception when others then q := jsonb_build_object('error', sqlerrm); end;
  return jsonb_build_object('hecha', false, 'etiquetas', c.llave_env is not null and c.tcc is not null,
    'cliente', coalesce(nullif(cl.empresa, ''), x.invitado_nombre, split_part(cl.email, '@', 1), 'Cliente'), 'tel', coalesce(cl.telefono, x.invitado_tel),
    'comuna', com, 'calle', coalesce(trim(m[1]), dir), 'numero', m[2], 'extra', nullif(trim(m[3]), ''),
    'peso', c.peso, 'tamano', c.tamano, 'valor', round(x.subtotal), 'cotizacion', q);
end $$;

-- 🏷️ Crear la orden de transporte y la etiqueta. Pone el seguimiento solo (el cliente recibe el aviso).
create or replace function public.courier_etiqueta(p_id uuid, p_servicio int, p_peso numeric, p_tamano text, p_calle text, p_numero text, p_extra text default null, p_comuna text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare c public.courier_cuentas := public.courier_mio(); x public.pedidos; cl public.profiles; d text; m jsonb := public.chx_medidas(p_tamano); r jsonb; o jsonb;
  ot text; tel text; q jsonb; srv jsonb;
begin
  if c.llave_env is null or c.tcc is null then raise exception 'Para etiquetas falta la llave de Envíos y tu N° de cliente (TCC) en Más → 🚚 Courier'; end if;
  if c.rem_calle is null or c.rem_numero is null or c.rem_tel is null then raise exception 'Completa tu dirección y teléfono de retiro en Más → 🚚 Courier'; end if;
  select * into x from public.pedidos where id = p_id and negocio_id = c.negocio_id for update;
  if x.id is null then raise exception 'Pedido no encontrado'; end if;
  if x.entrega <> 'despacho' then raise exception 'Este pedido es con retiro en tienda'; end if;
  if x.estado in ('cancelado', 'rechazado', 'expirado', 'pagando', 'en_revision', 'entregado') then raise exception 'Este pedido no está para enviar'; end if;
  if exists (select 1 from public.courier_envios where pedido_id = x.id) then raise exception 'Este pedido ya tiene etiqueta'; end if;
  if coalesce(trim(p_calle), '') = '' or coalesce(p_numero, '') !~ '^[0-9]{1,6}[A-Za-z]?$' then raise exception 'Escribe la calle y el número del cliente'; end if;
  if coalesce(p_peso, 0) not between 0.1 and 100 then raise exception 'El peso va de 0,1 a 100 kg'; end if;
  if coalesce(p_tamano, '') not in ('sobre', 'chica', 'mediana', 'grande') then raise exception 'Tamaño no válido'; end if;
  q := public.chx_cotizar(c, coalesce(nullif(trim(p_comuna), ''), x.comuna, trim(regexp_replace(coalesce(x.direccion, ''), '^.*,', ''))), p_peso, p_tamano, x.subtotal);
  d := q ->> 'destino';
  select s into srv from jsonb_array_elements(q -> 'opciones') s where (s ->> 'codigo')::int = p_servicio;
  if srv is null then raise exception 'Ese servicio no está disponible para esa comuna: elige otro'; end if;
  select * into cl from public.profiles where id = x.cliente_id;
  tel := right(regexp_replace(coalesce(cl.telefono, x.invitado_tel, ''), '\D', '', 'g'), 9);
  r := public.chx_api(c.llave_env, c.prueba, 'POST', '/transport-orders/api/v1.0/transport-orders', jsonb_build_object(
    'header', jsonb_build_object('certificateNumber', 0, 'customerCardNumber', c.tcc, 'countyOfOriginCoverageCode', c.origen_cod, 'labelType', 2, 'sellerRut', 'DEFAULT'),
    'details', jsonb_build_array(jsonb_build_object(
      'addresses', jsonb_build_array(
        jsonb_build_object('addressId', 0, 'countyCoverageCode', d, 'streetName', left(trim(p_calle), 60), 'streetNumber', p_numero,
          'supplement', left(coalesce(trim(p_extra), ''), 40), 'addressType', 'DEST', 'deliveryOnCommercialOffice', false, 'observation', left(coalesce(x.nota, ''), 60)),
        jsonb_build_object('addressId', 0, 'countyCoverageCode', c.origen_cod, 'streetName', c.rem_calle, 'streetNumber', c.rem_numero,
          'supplement', coalesce(c.rem_extra, ''), 'addressType', 'DEV', 'deliveryOnCommercialOffice', false, 'observation', '')),
      'contacts', jsonb_build_array(
        jsonb_build_object('name', left(coalesce(c.rem_nombre, 'Tienda'), 60), 'phoneNumber', c.rem_tel, 'mail', coalesce(c.rem_correo, ''), 'contactType', 'R'),
        jsonb_build_object('name', left(coalesce(nullif(cl.empresa, ''), x.invitado_nombre, split_part(cl.email, '@', 1), 'Cliente'), 60), 'phoneNumber', tel, 'mail', coalesce(x.invitado_correo, cl.email, ''), 'contactType', 'D')),
      'packages', jsonb_build_array(jsonb_build_object('weight', p_peso::text, 'height', m ->> 'alto', 'width', m ->> 'ancho', 'length', m ->> 'largo',
        'serviceDeliveryCode', p_servicio::text, 'productCode', '3', 'deliveryReference', upper(left(x.id::text, 8)), 'groupReference', 'CODEFIX',
        'declaredValue', round(x.subtotal)::text, 'declaredContent', '5', 'receivableAmountInDelivery', 0))))));
  o := r #> '{body,data,detail,0}';
  ot := o ->> 'transportOrderNumber';
  if coalesce((r ->> 'status')::int, 0) not in (200, 201) or coalesce(ot, '') !~ '^[0-9A-Za-z-]{4,40}$' then
    raise exception 'Chilexpress no creó el envío: %', coalesce(o ->> 'statusDescription', public.chx_error(r));
  end if;
  insert into public.courier_envios (pedido_id, negocio_id, ot, servicio, valor, etiqueta, tipo)
  values (x.id, c.negocio_id, ot, srv ->> 'nombre', (srv ->> 'valor')::int,
    case when coalesce(o #>> '{label,labelData}', '') ~ '^[A-Za-z0-9+/=\s]{20,}$' then regexp_replace(o #>> '{label,labelData}', '\s', '', 'g') end, 'img');
  perform public.pedido_seguimiento(x.id, 'chilexpress', ot, null);
  update public.courier_cuentas set ultimo_error = null where negocio_id = c.negocio_id;
  return jsonb_build_object('ot', ot, 'servicio', srv ->> 'nombre', 'valor', (srv ->> 'valor')::int, 'etiqueta', (select etiqueta from public.courier_envios where pedido_id = x.id));
end $$;

-- Volver a ver/imprimir la etiqueta (dueño o equipo con Pedidos).
create or replace function public.courier_etiqueta_ver(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare n uuid := public.negocio_de(auth.uid()); e public.courier_envios;
begin
  if n is null or not public.equipo_puede('pedidos') then raise exception 'Sin permiso'; end if;
  select * into e from public.courier_envios where pedido_id = p_id and negocio_id = n;
  if e.pedido_id is null then raise exception 'Este pedido no tiene etiqueta'; end if;
  return jsonb_build_object('ot', e.ot, 'servicio', e.servicio, 'valor', e.valor, 'etiqueta', e.etiqueta, 'creado', e.creado);
end $$;

-- Pedidos con etiqueta (para mostrar 🖨️ en la lista de Pedidos sin traer la imagen).
create or replace function public.courier_con_etiqueta() returns uuid[]
language sql stable security definer set search_path = '' as $$
  select coalesce(array_agg(pedido_id), '{}') from public.courier_envios
  where negocio_id = public.negocio_de(auth.uid()) and public.equipo_puede('pedidos') and creado > now() - interval '120 days'
$$;

revoke all on function public.chx_api(text, boolean, text, text, jsonb), public.chx_error(jsonb), public.chx_codigo(public.courier_cuentas, text),
  public.chx_medidas(text), public.chx_cotizar(public.courier_cuentas, text, numeric, text, numeric), public.courier_negocio(), public.courier_mio() from public, anon, authenticated;
revoke all on function public.courier_estado(), public.courier_guardar(jsonb), public.courier_cotizar(text, numeric, text, numeric), public.courier_preparar(uuid),
  public.courier_etiqueta(uuid, int, numeric, text, text, text, text, text), public.courier_etiqueta_ver(uuid), public.courier_con_etiqueta() from public, anon;
grant execute on function public.courier_estado(), public.courier_guardar(jsonb), public.courier_cotizar(text, numeric, text, numeric), public.courier_preparar(uuid),
  public.courier_etiqueta(uuid, int, numeric, text, text, text, text, text), public.courier_etiqueta_ver(uuid), public.courier_con_etiqueta() to authenticated;

-- =====================================================================
--  💲 G102 b TARIFA CHILEXPRESS EN EL CARRITO (Ajustes → Despacho → Resto de Chile = "💲 Tarifa Chilexpress").
--  · El cliente escribe su comuna y ve el costo antes de pedir; guardar_pedido cobra ESA tarifa (la calcula el servidor, nunca la app).
--  · Usa el peso y tamaño de siempre de la tienda (Más → 🚚 Courier) y el servicio más barato.
--  · Caché por comuna 12 h y máximo 120 consultas a Chilexpress por hora por tienda (la llave es de la tienda).
--  · Si Chilexpress no responde (o el módulo venció): cobra el respaldo; con respaldo $0 = envío por pagar. 🛡️ Nunca bloquea el pedido.
-- =====================================================================
create table if not exists public.chx_tarifas (
  negocio_id uuid not null references public.profiles (id) on delete cascade,
  norm text not null,
  peso numeric(6, 2) not null,
  tamano text not null,
  valor int not null,
  servicio text,
  at timestamptz not null default now(),
  primary key (negocio_id, norm)
);
alter table public.chx_tarifas enable row level security;
revoke all on public.chx_tarifas from anon, authenticated;
alter table public.courier_cuentas add column if not exists cot_desde timestamptz;
alter table public.courier_cuentas add column if not exists cot_n int not null default 0;

-- {costo, servicio} · {error} (Chilexpress no llega a esa comuna) · {fallo} (sin respuesta, sin módulo o sin conexión → respaldo).
create or replace function public.courier_tarifa(p_negocio uuid, p_comuna text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare c public.courier_cuentas; t public.chx_tarifas; nm text := public.cfx_comuna_norm(p_comuna); d text; q jsonb;
begin
  if nm = '' then return jsonb_build_object('error', 'Escribe tu comuna'); end if;
  if not public.pro_o_modulo(p_negocio, 'courier') then return jsonb_build_object('fallo', 'sin módulo'); end if;
  select * into c from public.courier_cuentas where negocio_id = p_negocio;
  if c.negocio_id is null or c.llave_cot is null or c.origen_cod is null then return jsonb_build_object('fallo', 'sin conexión'); end if;
  select * into t from public.chx_tarifas where negocio_id = p_negocio and norm = nm and peso = c.peso and tamano = c.tamano and at > now() - interval '12 hours';
  if t.negocio_id is not null then return jsonb_build_object('costo', t.valor, 'servicio', t.servicio); end if;
  -- Tope de consultas por hora (cuenta solo las que van a Chilexpress).
  if c.cot_desde is null or c.cot_desde < now() - interval '1 hour' then
    update public.courier_cuentas set cot_desde = now(), cot_n = 1 where negocio_id = p_negocio;
  elsif c.cot_n >= 120 then return jsonb_build_object('fallo', 'tope por hora');
  else update public.courier_cuentas set cot_n = cot_n + 1 where negocio_id = p_negocio;
  end if;
  d := public.chx_codigo(c, p_comuna);
  if d is null then
    if exists (select 1 from public.chx_comunas) then return jsonb_build_object('error', 'Chilexpress no encuentra la comuna "' || left(trim(p_comuna), 40) || '": revisa cómo se escribe'); end if;
    return jsonb_build_object('fallo', 'sin comunas');
  end if;
  begin q := public.chx_cotizar(c, p_comuna, c.peso, c.tamano, 0);
  exception when others then
    update public.courier_cuentas set ultimo_error = left('Tarifa del carrito: ' || sqlerrm, 200) where negocio_id = p_negocio;
    return jsonb_build_object('fallo', 'cotizar');
  end;
  if jsonb_array_length(coalesce(q -> 'opciones', '[]'::jsonb)) = 0 then return jsonb_build_object('error', 'Chilexpress no tiene envío a esa comuna'); end if;
  insert into public.chx_tarifas (negocio_id, norm, peso, tamano, valor, servicio, at)
  values (p_negocio, nm, c.peso, c.tamano, (q #>> '{opciones,0,valor}')::int, 'Chilexpress', now())
  on conflict (negocio_id, norm) do update set peso = excluded.peso, tamano = excluded.tamano, valor = excluded.valor, servicio = excluded.servicio, at = now();
  return jsonb_build_object('costo', (q #>> '{opciones,0,valor}')::int, 'servicio', 'Chilexpress');
end $$;

-- Costo del despacho (reemplaza al de arriba): igual que antes + la tarifa de Chilexpress cuando la tienda la eligió.
create or replace function public.costo_despacho(p_negocio uuid, p_entrega text, p_direccion text, p_monto numeric) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare d jsonb := public.cfx_despacho_costo((select despacho from public.profiles where id = p_negocio), p_entrega, p_direccion, p_monto); q jsonb;
begin
  if not coalesce((d ->> 'cotizar')::boolean, false) then return d - 'cotizar' - 'respaldo'; end if;
  q := public.courier_tarifa(p_negocio, d ->> 'comuna');
  if q ? 'error' then return jsonb_build_object('error', q ->> 'error'); end if;
  if q ? 'costo' then return jsonb_build_object('comuna', d ->> 'comuna', 'costo', (q ->> 'costo')::numeric, 'servicio', q ->> 'servicio'); end if;
  return d - 'cotizar' - 'respaldo';
end $$;
revoke all on function public.courier_tarifa(uuid, text), public.costo_despacho(uuid, text, text, numeric) from public, anon, authenticated;

-- 🛒 El carrito pregunta el costo antes de pedir (también el invitado de la tienda pública). Solo devuelve el costo.
create or replace function public.despacho_cotizar(p_negocio uuid, p_comuna text, p_monto numeric default 0) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare d jsonb; c text := left(trim(replace(coalesce(p_comuna, ''), ',', ' ')), 40);
begin
  if not exists (select 1 from public.profiles where id = p_negocio and public.is_business(id)) then return jsonb_build_object('error', 'Tienda no encontrada'); end if;
  if length(c) < 2 then return jsonb_build_object('error', 'Escribe tu comuna'); end if;
  d := public.costo_despacho(p_negocio, 'despacho', 'x, ' || c, greatest(coalesce(p_monto, 0), 0));
  if d ? 'error' then return jsonb_build_object('error', d ->> 'error'); end if;
  return jsonb_build_object('costo', round(coalesce((d ->> 'costo')::numeric, 0)), 'por_pagar', coalesce((d ->> 'por_pagar')::boolean, false), 'servicio', d ->> 'servicio');
end $$;
revoke all on function public.despacho_cotizar(uuid, text, numeric) from public;
grant execute on function public.despacho_cotizar(uuid, text, numeric) to anon, authenticated;

-- Ajustes → Despacho: elegir la tarifa de Chilexpress exige el módulo y Chilexpress conectado.
create or replace function public.guardar_despacho(p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  if not public.is_business(auth.uid()) then raise exception 'Solo el dueño de la tienda'; end if;
  if p #>> '{resto,modo}' = 'courier' and coalesce((select despacho #>> '{resto,modo}' from public.profiles where id = auth.uid()), '') <> 'courier'
     and not (public.pro_o_modulo(auth.uid(), 'courier') and exists (select 1 from public.courier_cuentas where negocio_id = auth.uid() and llave_cot is not null and origen_cod is not null)) then
    raise exception 'Para la tarifa de Chilexpress primero conecta 🚚 Courier Chilexpress (Más → Tu tienda)';
  end if;
  update public.profiles set despacho = public.cfx_despacho_limpio(p) where id = auth.uid();
  delete from public.chx_tarifas where negocio_id = auth.uid();
  return (select despacho from public.profiles where id = auth.uid());
end $$;
revoke all on function public.guardar_despacho(jsonb) from public, anon;
grant execute on function public.guardar_despacho(jsonb) to authenticated;

-- =====================================================================
--  🧾 G38 FACTURA ELECTRÓNICA (tipo 33) en Despega (G67: la factura es solo de Despega; las demás apps dan boleta).
--  · El comprador marca "🧾 Necesito factura" al pedir (RUT, razón social, giro, dirección, comuna) → pedidos.factura.
--    También la tienda puede ponerla desde Pedidos (si el cliente la pide por chat). Se cambia hasta que se emite.
--  · Al emitir (OpenFactura o folio anotado a mano) sale FACTURA 33 en vez de boleta 39 (montos con IVA: MntBruto).
--  · pedidos.boleta_tipo = 33 cuando el documento emitido es factura (null/39 = boleta). Vender con o sin RUT sigue igual (G31).
-- =====================================================================
alter table public.pedidos add column if not exists factura jsonb;
alter table public.pedidos add column if not exists boleta_tipo int;
-- Código de actividad económica del SII (6 dígitos): la factura lo exige; la boleta no.
alter table public.boleta_cuentas add column if not exists acteco int;

create or replace function public.boleta_estado() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('conectado', b.owner_id is not null, 'modo', b.modo, 'rut', b.rut, 'razon', b.razon, 'giro', b.giro,
    'direccion', b.direccion, 'comuna', b.comuna, 'auto', coalesce(b.auto, true), 'acteco', b.acteco,
    'fin', case when b.owner_id = auth.uid() then right(b.apikey, 4) end)
  from (select 1) x left join public.boleta_cuentas b on b.owner_id = public.negocio_de(auth.uid())
$$;

-- Igual que antes + acteco (opcional; vacío = sin facturas automáticas).
create or replace function public.boleta_guardar(p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  md text := coalesce(p ->> 'modo', 'manual');
  rt text := public.rut_normal(p ->> 'rut');
  k text := nullif(regexp_replace(coalesce(p ->> 'apikey', ''), '\s', '', 'g'), '');
  ac text := nullif(regexp_replace(coalesce(p ->> 'acteco', ''), '\D', '', 'g'), '');
  t text;
begin
  if not exists (select 1 from public.profiles where id = auth.uid() and role = 'user' and not suspended) then raise exception 'Solo el dueño de la tienda'; end if;
  if p is null then delete from public.boleta_cuentas where owner_id = auth.uid(); return public.boleta_estado(); end if;
  if md not in ('manual', 'openfactura') then raise exception 'Modo no válido'; end if;
  if rt is null then raise exception 'RUT no válido: revisa el número y el dígito verificador'; end if;
  foreach t in array array['razon', 'giro', 'direccion', 'comuna'] loop
    if length(trim(coalesce(p ->> t, ''))) < 2 then
      raise exception 'Falta %', case t when 'razon' then 'la razón social' when 'giro' then 'el giro' when 'direccion' then 'la dirección' else 'la comuna' end;
    end if;
  end loop;
  if ac is not null and length(ac) not between 5 and 6 then raise exception 'El código de actividad (Acteco) tiene 6 números: búscalo en sii.cl → Mi SII'; end if;
  if k is not null and (k !~ '^[A-Za-z0-9_-]{16,120}$') then raise exception 'Esa no parece una API key de OpenFactura'; end if;
  if md = 'openfactura' and k is null and not exists (select 1 from public.boleta_cuentas where owner_id = auth.uid() and apikey is not null) then
    raise exception 'Pega tu API key de OpenFactura';
  end if;
  insert into public.boleta_cuentas (owner_id, modo, apikey, rut, razon, giro, direccion, comuna, auto, acteco)
  values (auth.uid(), md, k, rt, left(trim(p ->> 'razon'), 100), left(trim(p ->> 'giro'), 80), left(trim(p ->> 'direccion'), 70),
          left(trim(p ->> 'comuna'), 20), coalesce((p ->> 'auto')::boolean, true), ac::int)
  on conflict (owner_id) do update set modo = excluded.modo, apikey = coalesce(excluded.apikey, public.boleta_cuentas.apikey),
    rut = excluded.rut, razon = excluded.razon, giro = excluded.giro, direccion = excluded.direccion, comuna = excluded.comuna,
    auto = excluded.auto, acteco = excluded.acteco, updated_at = now();
  perform public.auditar('Boleta SII configurada', md || ' · ' || rt);
  return public.boleta_estado();
end $$;
revoke all on function public.boleta_estado(), public.boleta_guardar(jsonb) from public, anon;
grant execute on function public.boleta_estado(), public.boleta_guardar(jsonb) to authenticated;

-- Datos del receptor revisados (RUT con dígito verificador; largos del SII). Error claro si falta algo.
create or replace function public.factura_datos(p jsonb) returns jsonb
language plpgsql immutable set search_path = '' as $$
declare rt text := public.rut_normal(p ->> 'rut'); t text; c text := lower(trim(coalesce(p ->> 'correo', '')));
begin
  if rt is null then raise exception 'RUT de la empresa no válido: revisa el número y el dígito verificador'; end if;
  foreach t in array array['razon', 'giro', 'direccion', 'comuna'] loop
    if length(trim(coalesce(p ->> t, ''))) < 2 then
      raise exception 'Para la factura falta %', case t when 'razon' then 'la razón social' when 'giro' then 'el giro' when 'direccion' then 'la dirección' else 'la comuna' end;
    end if;
  end loop;
  if c <> '' and (c !~ '^[^@\s<>"]+@[^@\s<>"]+\.[a-z]{2,}$' or length(c) > 80) then raise exception 'Correo de la factura no válido'; end if;
  return jsonb_build_object('rut', rt, 'razon', left(trim(p ->> 'razon'), 100), 'giro', left(trim(p ->> 'giro'), 40),
    'direccion', left(trim(p ->> 'direccion'), 70), 'comuna', left(trim(p ->> 'comuna'), 20)) || case when c <> '' then jsonb_build_object('correo', c) else '{}'::jsonb end;
end $$;

-- Comprador (con el token del pedido o su id) o la tienda (id + permiso Pedidos) ponen, cambian o quitan (p null) los datos de factura.
create or replace function public.pedido_factura_guardar(p_ref text, p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare x public.pedidos := public.pedido_ref(p_ref); d jsonb;
begin
  if x.id is null then return jsonb_build_object('ok', false, 'error', 'Pedido no encontrado'); end if;
  if x.negocio_id = public.negocio_de(auth.uid()) and x.cliente_id is distinct from auth.uid() and not public.equipo_puede('pedidos') then raise exception 'Sin permiso'; end if;
  if x.boleta_folio is not null then return jsonb_build_object('ok', false, 'error', 'El documento ya se emitió: pide a la tienda una nota de crédito'); end if;
  if x.estado in ('cancelado', 'rechazado', 'expirado') then return jsonb_build_object('ok', false, 'error', 'Este pedido ya no está activo'); end if;
  d := case when p is null then null else public.factura_datos(p) end;
  update public.pedidos set factura = d, boleta_error = null, boleta_intentos = 0 where id = x.id;
  return jsonb_build_object('ok', true, 'factura', d);
end $$;
revoke all on function public.factura_datos(jsonb) from public, anon, authenticated;
revoke all on function public.pedido_factura_guardar(text, jsonb) from public;
grant execute on function public.pedido_factura_guardar(text, jsonb) to anon, authenticated;

-- Boleta 39 (como antes) o FACTURA 33 si el pedido trae datos de factura (montos con IVA → MntBruto = 1).
create or replace function public.boleta_dte(x public.pedidos, c public.boleta_cuentas) returns jsonb
language plpgsql stable set search_path = '' as $$
declare det jsonb := '[]'::jsonb; l jsonb; n int := 0; suma numeric := 0; m numeric; q numeric; tot numeric := round(x.total); neto numeric; d numeric;
        f jsonb := x.factura; idd jsonb; rec jsonb;
begin
  for l in select * from jsonb_array_elements(x.lineas) loop
    exit when n >= 59;
    q := greatest(coalesce((l ->> 'cant')::numeric, 1), 1); m := round(coalesce((l ->> 'subtotal')::numeric, 0));
    if m <= 0 then continue; end if;
    n := n + 1; suma := suma + m;
    det := det || jsonb_build_object('NroLinDet', n, 'NmbItem', left(coalesce(nullif(trim(l ->> 'nombre'), ''), 'Producto'), 80),
      'QtyItem', q, 'PrcItem', round(m / q, 2), 'MontoItem', m);
  end loop;
  if suma < tot then n := n + 1; det := det || jsonb_build_object('NroLinDet', n, 'NmbItem', 'Otros', 'QtyItem', 1, 'PrcItem', tot - suma, 'MontoItem', tot - suma); suma := tot; end if;
  d := suma - tot; neto := round(tot / 1.19);
  if f is null then
    idd := jsonb_build_object('TipoDTE', 39, 'Folio', 0, 'FchEmis', to_char(now() at time zone 'America/Santiago', 'YYYY-MM-DD'), 'IndServicio', 3);
    rec := jsonb_build_object('RUTRecep', '66666666-6');
  else
    idd := jsonb_build_object('TipoDTE', 33, 'Folio', 0, 'FchEmis', to_char(now() at time zone 'America/Santiago', 'YYYY-MM-DD'), 'MntBruto', 1, 'FmaPago', 1);
    rec := jsonb_build_object('RUTRecep', f ->> 'rut', 'RznSocRecep', f ->> 'razon', 'GiroRecep', f ->> 'giro', 'DirRecep', f ->> 'direccion', 'CmnaRecep', f ->> 'comuna')
        || case when f ->> 'correo' is not null then jsonb_build_object('CorreoRecep', f ->> 'correo') else '{}'::jsonb end;
  end if;
  return jsonb_build_object('response', jsonb_build_array('FOLIO', 'SELF_SERVICE'), 'dte', jsonb_build_object(
    'Encabezado', jsonb_build_object('IdDoc', idd,
      'Emisor', case when f is null then jsonb_build_object('RUTEmisor', c.rut, 'RznSocEmisor', c.razon, 'GiroEmisor', c.giro, 'DirOrigen', c.direccion, 'CmnaOrigen', c.comuna)
        else jsonb_build_object('RUTEmisor', c.rut, 'RznSoc', c.razon, 'GiroEmis', c.giro, 'Acteco', coalesce(c.acteco, 0), 'DirOrigen', c.direccion, 'CmnaOrigen', c.comuna) end,
      'Receptor', rec,
      'Totales', jsonb_build_object('MntNeto', neto, 'TasaIVA', 19, 'IVA', tot - neto, 'MntTotal', tot) - case when f is null then 'TasaIVA' else '' end),
    'Detalle', det) || case when d > 0 then jsonb_build_object('DscRcgGlobal', jsonb_build_array(
      jsonb_build_object('NroLinDR', 1, 'TpoMov', 'D', 'GlosaDR', 'Descuento', 'TpoValor', '$', 'ValorDR', d))) else '{}'::jsonb end);
end $$;

-- Igual que antes; además anota si salió factura (33) y el aviso al cliente dice "Factura" o "Boleta".
create or replace function public.boleta_intentar(p_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare x public.pedidos; c public.boleta_cuentas; r jsonb; f text; e text; doc text;
begin
  select * into x from public.pedidos where id = p_id for update;
  if x.id is null then return jsonb_build_object('ok', false, 'error', 'Pedido no encontrado'); end if;
  if x.boleta_folio is not null then return jsonb_build_object('ok', true, 'folio', x.boleta_folio, 'url', x.boleta_url, 'tipo', coalesce(x.boleta_tipo, 39)); end if;
  if x.estado not in ('preparando', 'listo', 'en_camino', 'entregado') then return jsonb_build_object('ok', false, 'error', 'El pedido aún no está pagado'); end if;
  if round(x.total) < 1 then return jsonb_build_object('ok', false, 'error', 'Pedido sin monto'); end if;
  select * into c from public.boleta_cuentas where owner_id = x.negocio_id;
  if c.owner_id is null or c.modo <> 'openfactura' or c.apikey is null then return jsonb_build_object('ok', false, 'error', 'Configura la boleta automática en Ajustes'); end if;
  doc := case when x.factura is not null then 'Factura' else 'Boleta' end;
  if x.factura is not null and c.acteco is null then
    update public.pedidos set boleta_error = 'Para facturar pon tu código de actividad (Acteco) en Ajustes → Boleta SII' where id = x.id;
    return jsonb_build_object('ok', false, 'error', 'Para facturar pon tu código de actividad (Acteco) en Ajustes → Boleta SII');
  end if;
  r := public.of_api(c.apikey, public.boleta_dte(x, c), 'cfx-' || x.id::text || case when x.factura is not null then '-33' else '' end);
  f := nullif(coalesce(r #>> '{body,FOLIO}', r #>> '{body,folio}'), '');
  if coalesce((r ->> 'status')::int, 0) in (200, 201) and f is not null then
    update public.pedidos set boleta_folio = left(f, 20), boleta_url = case when r #>> '{body,SELF_SERVICE,url}' ~ '^https://[^\s"<>]+$' then left(r #>> '{body,SELF_SERVICE,url}', 500) end,
      boleta_at = now(), boleta_error = null, boleta_tipo = case when x.factura is not null then 33 end where id = x.id returning * into x;
    perform public.aviso_cliente(x, '🧾 Tu ' || lower(doc), doc || ' electrónica N° ' || f || ' de tu pedido');
    return jsonb_build_object('ok', true, 'folio', x.boleta_folio, 'url', x.boleta_url, 'tipo', coalesce(x.boleta_tipo, 39));
  end if;
  e := left(coalesce(case when (r ->> 'status')::int = 0 then 'No se pudo conectar con OpenFactura' end,
                     r #>> '{body,error,message}', r #>> '{body,message}', 'OpenFactura respondió ' || coalesce(r ->> 'status', '?')), 200);
  if (r ->> 'status')::int in (401, 403) then e := 'OpenFactura no aceptó la API key'; end if;
  update public.pedidos set boleta_error = e, boleta_intentos = boleta_intentos + 1 where id = x.id;
  return jsonb_build_object('ok', false, 'error', e);
end $$;

-- Modo manual: anota el folio (de la boleta o, si el pedido pide factura, de la factura emitida en sii.cl).
create or replace function public.boleta_anotar(p_id uuid, p_folio text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare x public.pedidos; f text := nullif(regexp_replace(coalesce(p_folio, ''), '\D', '', 'g'), ''); doc text;
begin
  select * into x from public.pedidos where id = p_id and negocio_id = public.negocio_de(auth.uid()) for update;
  if x.id is null or not public.equipo_puede('pedidos') then raise exception 'Sin permiso'; end if;
  if x.estado not in ('preparando', 'listo', 'en_camino', 'entregado') then raise exception 'El pedido aún no está pagado'; end if;
  if f is not null and length(f) > 10 then raise exception 'Folio no válido'; end if;
  if x.boleta_url is not null then raise exception 'Este documento lo emitió OpenFactura: no se cambia'; end if;
  doc := case when x.factura is not null then 'Factura' else 'Boleta' end;
  update public.pedidos set boleta_folio = f, boleta_at = case when f is null then null else now() end, boleta_error = null,
    boleta_tipo = case when f is not null and x.factura is not null then 33 end
  where id = x.id returning * into x;
  if f is not null then perform public.aviso_cliente(x, '🧾 Tu ' || lower(doc), doc || ' electrónica N° ' || f || ' de tu pedido'); end if;
  return jsonb_build_object('ok', true, 'folio', f, 'tipo', coalesce(x.boleta_tipo, 39));
end $$;

-- Lo que ve el cliente y la tienda: documento emitido (con tipo 33/39), error, o los datos de factura pedidos.
create or replace function public.boleta_de(x public.pedidos) returns jsonb
language sql stable security definer set search_path = '' as $$
  select case when x.boleta_folio is not null then jsonb_build_object('folio', x.boleta_folio, 'url', x.boleta_url, 'fecha', x.boleta_at,
    'rut', c.rut, 'razon', c.razon, 'tipo', coalesce(x.boleta_tipo, 39))
    when x.boleta_error is not null then jsonb_build_object('error', x.boleta_error) else '{}'::jsonb end
    || case when x.factura is not null then jsonb_build_object('factura', x.factura) else '{}'::jsonb end
  from (select 1) z left join public.boleta_cuentas c on c.owner_id = x.negocio_id
$$;
revoke all on function public.boleta_dte(public.pedidos, public.boleta_cuentas), public.boleta_intentar(uuid), public.boleta_de(public.pedidos) from public, anon, authenticated;
revoke all on function public.boleta_anotar(uuid, text) from public, anon;
grant execute on function public.boleta_anotar(uuid, text) to authenticated;

-- ¿Esta tienda puede dar factura? (tiene sus datos de emisor en Ajustes → Boleta SII). Para mostrar "🧾 Necesito factura".
create or replace function public.factura_disponible(p_negocio uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.boleta_cuentas where owner_id = p_negocio)
$$;
revoke all on function public.factura_disponible(uuid) from public;
grant execute on function public.factura_disponible(uuid) to anon, authenticated;

-- =====================================================================
--  G107 💳 WEBPAY CON EL FLOW DE LA TIENDA (núcleo mp_negocio.sql: cfx_flow_neg_*). El dueño lo conecta en Ajustes → Cobros,
--  debajo de ⚡ Mercado Pago. El cliente ve "💳 Pagar con Webpay" en su pedido y se aprueba solo (ref 'pedido:<id>' →
--  gancho cfx_mp_neg_pagado_app). link.mp = hay pago automático (MP o Flow) · link.medios = { mp, flow } para los botones.
-- =====================================================================
create or replace function public.link_activo(o uuid, t text) returns jsonb
language sql stable security definer set search_path = '' as $$
  select case when t = 'pedido' and (m.mp or public.cfx_flow_neg_on(o))
    then coalesce(s.l, '{}'::jsonb) || jsonb_build_object('mp', true, 'medios', jsonb_build_object('mp', m.mp, 'flow', public.cfx_flow_neg_on(o))) else s.l end
  from (select (select jsonb_build_object('titulo', titulo, 'url', url, 'precio', precio) from public.links_pago
                where owner_id = o and tipo = t and activo and url <> '' limit 1) as l) s,
       (select exists (select 1 from public.mp_cuentas c where c.owner_id = o and c.activo) as mp) m
$$;

-- Aprueba el pedido pagado en línea (lo mismo que hace mp_confirmar al encontrar el pago).
create or replace function public.pedido_pagado_auto(p_id uuid, p_pago text, p_medio text) returns boolean
language plpgsql security definer set search_path = '' as $$
declare x public.pedidos;
begin
  select * into x from public.pedidos where id = p_id for update;
  if x.id is null or x.mp_pago is not null then return false; end if;
  if x.estado not in ('pagando', 'expirado') then
    update public.pedidos set mp_pago = left(p_pago, 40), updated_at = now() where id = x.id;
    perform public.notify_user(x.negocio_id, '💳 Pago recibido: revísalo', coalesce(x.invitado_nombre, 'Un cliente') || ' pagó $' ||
      to_char(x.total, 'FM999G999G999') || ' con ' || p_medio || ' un pedido que ya no esperaba pago', 'apps/pedidos/');
    return false;
  end if;
  perform public.mover_stock(x, -1);
  update public.pedidos set estado = 'preparando', pagado_at = now(), stock_descontado = true, motivo = null,
    mp_pago = left(p_pago, 40), updated_at = now() where id = x.id;
  -- G139: al pagar recién le llega a la tienda (y al equipo): "prepáralo".
  perform public.notify_user(x.negocio_id, '💳 Pagado: prepara el pedido de ' || coalesce(x.invitado_nombre, (select coalesce(nullif(empresa, ''), split_part(email, '@', 1)) from public.profiles where id = x.cliente_id), 'un cliente'),
    case when x.cobro = 'abono' then 'Abono $' || to_char(x.a_pagar, 'FM999G999G999') || ' de $' || to_char(x.total, 'FM999G999G999') else '$' || to_char(x.total, 'FM999G999G999') end ||
    ' con ' || p_medio || case when x.estado = 'expirado' then ' · llegó tarde: revisa el stock' else '' end, 'apps/pedidos/');
  perform public.notify_user(e.id, '📦 Pedido para preparar', coalesce(x.invitado_nombre, 'Un cliente') || ' pagó con ' || p_medio, 'apps/pedidos/')
    from public.profiles e where e.role = 'equipo' and e.negocio_id = x.negocio_id and not e.suspended;
  perform public.aviso_cliente(x, '✅ Pago recibido', p_medio || ' aprobó tu pago: estamos preparando tu pedido');
  return true;
end $$;

create or replace function public.cfx_mp_neg_pagado_app(p_ref text, p_pago text, p_monto int) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if p_ref !~ '^pedido:[0-9a-f-]{36}$' then return; end if;
  perform public.pedido_pagado_auto(substr(p_ref, 8)::uuid, p_pago, case when p_pago like 'flow:%' then 'Webpay' else 'Mercado Pago' end);
end $$;

-- p_medio 'mp' | 'flow'; null = Mercado Pago si está, si no Webpay.
drop function if exists public.mp_pagar(text, text);
create or replace function public.mp_pagar(p_ref text, p_volver text, p_medio text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare x public.pedidos := public.pedido_ref(p_ref); tk text; t text; r jsonb; v text := left(coalesce(p_volver, ''), 500);
begin
  if x.id is null then return jsonb_build_object('ok', false, 'error', 'Pedido no encontrado'); end if;
  if x.estado <> 'pagando' or x.retenido_hasta < now() then return jsonb_build_object('ok', false, 'error', 'Este pedido ya no espera pago'); end if;
  select token into tk from public.mp_cuentas where owner_id = x.negocio_id and activo;
  if p_medio = 'flow' or (tk is null and coalesce(p_medio, '') <> 'mp') then
    select coalesce(nullif(trim(empresa), ''), 'Tienda') into t from public.profiles where id = x.negocio_id;
    r := public.cfx_flow_neg_cobro(x.negocio_id, 'pedido:' || x.id, left('Pedido en ' || t, 120), round(coalesce(x.a_pagar, x.total))::int, p_volver, x.retenido_hasta);
    if (r ->> 'ok')::boolean then update public.pedidos set mp_desde = coalesce(mp_desde, now()) where id = x.id; end if;
    return r;
  end if;
  if tk is null then return jsonb_build_object('ok', false, 'error', 'La tienda no tiene Mercado Pago activo'); end if;
  if round(coalesce(x.a_pagar, x.total)) < 1 then return jsonb_build_object('ok', false, 'error', 'Monto no válido'); end if;
  if v !~ '^https://[^\s"<>]+$' then v := null; end if;
  select coalesce(nullif(trim(empresa), ''), 'Tienda') into t from public.profiles where id = x.negocio_id;
  r := public.mp_api(tk, 'POST', '/checkout/preferences', jsonb_build_object(
    'items', jsonb_build_array(jsonb_build_object('id', x.id, 'title', left(case when x.cobro = 'abono' then 'Abono pedido en ' else 'Pedido en ' end || t, 120), 'quantity', 1,
                                                  'currency_id', 'CLP', 'unit_price', round(coalesce(x.a_pagar, x.total)))),
    'external_reference', x.id::text,
    'payment_methods', jsonb_build_object('excluded_payment_types', jsonb_build_array(jsonb_build_object('id', 'ticket'))),
    'expires', true,
    'expiration_date_to', to_char(x.retenido_hasta at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS".000+00:00"'))
    || public.cfx_mp_notif('d:' || x.id::text)
    || case when v is null then '{}'::jsonb else jsonb_build_object('back_urls', jsonb_build_object('success', v, 'pending', v, 'failure', v),
                                                                   'auto_return', 'approved') end);
  if coalesce((r ->> 'status')::int, 0) not in (200, 201) or r #>> '{body,init_point}' is null then
    return jsonb_build_object('ok', false, 'error', 'Mercado Pago no respondió. Intenta de nuevo o usa otro medio de pago.');
  end if;
  update public.pedidos set mp_desde = coalesce(mp_desde, now()) where id = x.id;
  return jsonb_build_object('ok', true, 'url', r #>> '{body,init_point}');
end $$;

create or replace function public.mp_revisar(p_ref text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare x public.pedidos := public.pedido_ref(p_ref);
begin
  if x.id is null then return jsonb_build_object('ok', false, 'error', 'Pedido no encontrado'); end if;
  if x.mp_desde is not null and x.mp_pago is null then perform public.cfx_mp_neg_revisar('pedido:' || x.id); end if;
  return jsonb_build_object('ok', true, 'estado', public.mp_confirmar(x.id));
end $$;

revoke all on function public.pedido_pagado_auto(uuid, text, text), public.cfx_mp_neg_pagado_app(text, text, int) from public, anon, authenticated;
revoke all on function public.mp_pagar(text, text, text) from public, anon;
grant execute on function public.mp_pagar(text, text, text), public.mp_revisar(text) to anon, authenticated;

-- =====================================================================
--  G128 🛒 COBRO DE PEDIDOS. a) 🏦 transferencia (datos_pago) = medio → 'pagando' + comprobante + la tienda aprueba ·
--  b) por ítem ⚡ Pagar ahora (de fábrica) / 💵 Abono % / 💰 Pagar al retirar · c) tipo 📦 producto / 🛠️ servicio (sin stock ni despacho) /
--  🔑 acceso digital (se entrega al aprobarse el pago) · d) sin ningún medio → "💰 Pagas al retirar" · e) 💬 chat DEL pedido (solo con cuenta,
--  núcleo cfx_hilo_*). Pedidos viejos: cobro null = ⚡ pagar ahora; a_pagar null = total. La BASE calcula todo.
-- =====================================================================
alter table public.catalog_items add column if not exists tipo text not null default 'producto';
alter table public.catalog_items add column if not exists cobro text not null default 'ahora';
alter table public.catalog_items add column if not exists abono_pct int;
alter table public.catalog_items add column if not exists acceso text;
alter table public.catalog_items drop constraint if exists catalog_items_g128_check;
alter table public.catalog_items add constraint catalog_items_g128_check check (tipo in ('producto', 'servicio', 'digital') and cobro in ('ahora', 'abono', 'retiro')
  and (abono_pct is null or abono_pct between 10 and 90) and (acceso is null or char_length(acceso) <= 500));
alter table public.pedidos add column if not exists cobro text;
alter table public.pedidos add column if not exists a_pagar numeric(12, 2);
alter table public.pedidos add column if not exists abonado_at timestamptz;
alter table public.pedidos add column if not exists accesos jsonb;
alter table public.pedidos drop constraint if exists pedidos_cobro_check;
alter table public.pedidos add constraint pedidos_cobro_check check (cobro is null or cobro in ('ahora', 'abono', 'retiro'));

-- Reglas fijas del ítem: 🔑 digital siempre se paga ahora; 🛠️ servicio y 🔑 digital no llevan stock; abono 10–90 % (50 de fábrica).
create or replace function public.catalog_venta_fija() returns trigger
language plpgsql set search_path = '' as $$
begin
  if new.tipo is null or new.tipo not in ('producto', 'servicio', 'digital') then new.tipo := 'producto'; end if;
  if new.cobro is null or new.cobro not in ('ahora', 'abono', 'retiro') then new.cobro := 'ahora'; end if;
  if new.tipo = 'digital' then new.cobro := 'ahora'; end if;
  if new.tipo <> 'producto' then new.stock := null; end if;
  new.abono_pct := case when new.cobro = 'abono' then least(90, greatest(10, coalesce(new.abono_pct, 50))) end;
  new.acceso := case when new.tipo = 'digital' then nullif(left(trim(coalesce(new.acceso, '')), 500), '') end;
  return new;
end $$;
revoke all on function public.catalog_venta_fija() from public, anon, authenticated;
drop trigger if exists catalog_venta_fija on public.catalog_items;
create trigger catalog_venta_fija before insert or update on public.catalog_items for each row execute function public.catalog_venta_fija();

-- El dueño elige tipo y forma de pago de un producto publicado. p = { tipo, cobro, abono, acceso }.
create or replace function public.catalogo_venta(p_key text, p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare tp text := coalesce(nullif(p ->> 'tipo', ''), 'producto'); cb text := coalesce(nullif(p ->> 'cobro', ''), 'ahora'); pc int; ac text := nullif(trim(coalesce(p ->> 'acceso', '')), ''); r public.catalog_items;
begin
  if not public.is_business(auth.uid()) then raise exception 'Solo las empresas'; end if;
  if tp not in ('producto', 'servicio', 'digital') then raise exception 'Tipo no válido'; end if;
  if cb not in ('ahora', 'abono', 'retiro') then raise exception 'Forma de pago no válida'; end if;
  if tp = 'digital' then cb := 'ahora'; end if;
  if cb = 'abono' then
    if coalesce(p ->> 'abono', '') !~ '^\d{1,2}$' or (p ->> 'abono')::int not between 10 and 90 then raise exception 'El abono va de 10 a 90 %%'; end if;
    pc := (p ->> 'abono')::int;
  end if;
  if tp = 'digital' and ac is null then raise exception 'Escribe lo que recibe el cliente al pagar (link, código o instrucciones)'; end if;
  if char_length(coalesce(ac, '')) > 500 then raise exception 'El acceso tiene máximo 500 caracteres'; end if;
  update public.catalog_items set tipo = tp, cobro = cb, abono_pct = pc, acceso = ac, updated_at = now()
  where owner_id = auth.uid() and client_key = left(coalesce(p_key, ''), 80) returning * into r;
  if r.id is null then raise exception 'Primero marca "Mostrar en mi catálogo" y guarda el producto'; end if;
  return jsonb_build_object('tipo', r.tipo, 'cobro', r.cobro, 'abono', r.abono_pct, 'acceso', r.acceso);
end $$;
create or replace function public.catalogo_venta_ver(p_key text) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('tipo', c.tipo, 'cobro', c.cobro, 'abono', c.abono_pct, 'acceso', c.acceso)
  from public.catalog_items c where c.owner_id = auth.uid() and c.client_key = p_key
$$;
-- Lo que el carrito necesita saber (nunca el acceso digital): solo los ítems que no son "📦 producto ⚡ pagar ahora".
create or replace function public.catalogo_venta_publica(p_slug text) returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('clave', c.client_key, 'tipo', c.tipo, 'cobro', c.cobro, 'abono', c.abono_pct)), '[]'::jsonb)
  from public.catalog_items c join public.profiles t on t.id = c.owner_id
  where t.slug = lower(trim(coalesce(p_slug, ''))) and t.role = 'user' and not t.suspended and (c.tipo <> 'producto' or c.cobro <> 'ahora')
$$;
create or replace function public.catalogo_venta_negocio(p_negocio uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('clave', c.client_key, 'tipo', c.tipo, 'cobro', c.cobro, 'abono', c.abono_pct)), '[]'::jsonb)
  from public.catalog_items c join public.profiles t on t.id = c.owner_id
  where c.owner_id = p_negocio and t.role = 'user' and not t.suspended and (c.tipo <> 'producto' or c.cobro <> 'ahora')
$$;
revoke all on function public.catalogo_venta(text, jsonb), public.catalogo_venta_ver(text), public.catalogo_venta_publica(text), public.catalogo_venta_negocio(uuid) from public, anon;
grant execute on function public.catalogo_venta(text, jsonb), public.catalogo_venta_ver(text), public.catalogo_venta_negocio(uuid) to authenticated;
grant execute on function public.catalogo_venta_publica(text) to anon, authenticated;

-- a) 🏦 La transferencia también es un medio: con datos_pago el pedido queda por pagar (comprobante + la tienda aprueba).
--    link.transferencia = true · link.mp = hay pago automático · link.medios = { mp, flow } · sin nada = null (💰 paga al retirar).
create or replace function public.link_activo(o uuid, t text) returns jsonb
language sql stable security definer set search_path = '' as $$
  select case when t <> 'pedido' then s.l
    when m.mp or m.flow then coalesce(s.l, '{}'::jsonb) || jsonb_build_object('mp', true, 'medios', jsonb_build_object('mp', m.mp, 'flow', m.flow)) || m.tr
    when m.tr <> '{}'::jsonb then coalesce(s.l, '{}'::jsonb) || m.tr
    else s.l end
  from (select (select jsonb_build_object('titulo', titulo, 'url', url, 'precio', precio) from public.links_pago
                where owner_id = o and tipo = t and activo and url <> '' limit 1) as l) s,
       (select exists (select 1 from public.mp_cuentas c where c.owner_id = o and c.activo) as mp, public.cfx_flow_neg_on(o) as flow,
               case when exists (select 1 from public.profiles p where p.id = o and coalesce(trim(p.datos_pago), '') <> '') then '{"transferencia": true}'::jsonb
                    else '{}'::jsonb end as tr) m
$$;

-- El pedido: p_cobro = 'ahora' (de fábrica) | 'abono' | 'retiro'. La base revisa que esté permitido y calcula a_pagar.
drop function if exists public.guardar_pedido(uuid, uuid, text, text, jsonb, text, text, text, text);
create or replace function public.guardar_pedido(p_negocio uuid, p_cliente uuid, p_nombre text, p_tel text, p_items jsonb, p_entrega text,
                                                 p_direccion text, p_nota text, p_cupon text, p_cobro text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare a jsonb; pct int := 0; desc_ numeric := 0; dp numeric := 0; sub numeric; ped public.pedidos; l jsonb := public.link_activo(p_negocio, 'pedido');
  quien text; prem boolean := public.es_cliente_premium(p_cliente); dsp jsonb; gc public.giftcards; gm int := 0;
  cb text := coalesce(nullif(p_cobro, ''), 'ahora'); ent text := p_entrega; ln jsonb; lin jsonb := '[]'::jsonb; vt text; vc text; vp int; s numeric;
  fis boolean := false; base numeric := 0; ya numeric := 0; todo_retiro boolean := true; hay_abono boolean := false; costo numeric; tot numeric; pagar numeric;
begin
  if public.en_vacaciones(p_negocio) then return jsonb_build_object('ok', false, 'error', 'La tienda está de vacaciones. Podrás pedir a su regreso.'); end if;
  if cb not in ('ahora', 'abono', 'retiro') then return jsonb_build_object('ok', false, 'error', 'Elige cómo pagas'); end if;
  a := public.armar_pedido(p_negocio, p_items);
  if a ? 'error' then return jsonb_build_object('ok', false, 'error', a ->> 'error'); end if;
  -- Tipo y forma de pago de cada línea (lo viejo y las ofertas = 📦 producto ⚡ pagar ahora).
  for ln in select * from jsonb_array_elements(a -> 'lineas') loop
    vt := null; vc := null; vp := null;
    select c.tipo, c.cobro, c.abono_pct into vt, vc, vp from public.catalog_items c where c.owner_id = p_negocio and c.client_key = ln ->> 'clave';
    vt := coalesce(vt, 'producto'); vc := coalesce(vc, 'ahora'); s := coalesce((ln ->> 'subtotal')::numeric, 0);
    lin := lin || (ln || jsonb_build_object('tipo', vt, 'cobro', vc) || case when vc = 'abono' then jsonb_build_object('abono', vp) else '{}'::jsonb end);
    fis := fis or vt = 'producto'; base := base + s;
    ya := ya + case vc when 'abono' then s * coalesce(vp, 50) / 100.0 when 'retiro' then 0 else s end;
    todo_retiro := todo_retiro and vc = 'retiro'; hay_abono := hay_abono or vc = 'abono';
  end loop;
  a := jsonb_set(a, '{lineas}', lin);
  -- 🛠️ Solo servicios o 🔑 accesos: sin despacho.
  if not fis then ent := 'retiro';
  else
    if ent not in ('retiro', 'despacho') then return jsonb_build_object('ok', false, 'error', 'Elige despacho o retiro en tienda'); end if;
    if ent = 'despacho' and coalesce(trim(p_direccion), '') = '' then return jsonb_build_object('ok', false, 'error', 'Escribe la dirección de despacho'); end if;
    if ent = 'retiro' and not coalesce((select (despacho ->> 'retiro')::boolean from public.profiles where id = p_negocio), true) then
      return jsonb_build_object('ok', false, 'error', 'Esta tienda no tiene retiro: elige despacho');
    end if;
  end if;
  sub := (a ->> 'sub')::numeric;
  if coalesce(trim(p_cupon), '') <> '' then
    pct := public.cfx_desc_pct(p_negocio, p_cupon);
    if pct is null then
      gc := public.giftcard_valida(p_negocio, p_cupon);
      if gc.id is null then return jsonb_build_object('ok', false, 'error', 'Cupón o gift card no válido o vencido'); end if;
      pct := 0;
    end if;
    desc_ := round(sub * pct / 100.0);
  end if;
  if prem then dp := round(sub * coalesce((select desc_premium from public.profiles where id = p_negocio), 0) / 100.0); end if;
  dp := least(dp, sub - desc_);
  dsp := public.costo_despacho(p_negocio, ent, p_direccion, sub - desc_ - dp);
  if dsp ? 'error' then return jsonb_build_object('ok', false, 'error', dsp ->> 'error'); end if;
  costo := coalesce((dsp ->> 'costo')::numeric, 0);
  if costo > 0 then
    a := jsonb_set(a, '{lineas}', (a -> 'lineas') || jsonb_build_object('nombre', '🚚 ' || coalesce(dsp ->> 'servicio', 'Despacho') || ' a ' || (dsp ->> 'comuna'), 'cant', 1, 'precio', costo,
      'subtotal', costo, 'clave', 'despacho', 'opcion', null));
  end if;
  if gc.id is not null then gm := least(gc.saldo, greatest(0, sub - desc_ - dp + costo))::int; end if;
  tot := sub - desc_ - dp + costo - gm;
  -- 💳 Cómo paga (d: sin ningún medio, paga al retirar/recibir).
  if l is null then cb := 'retiro';
  elsif cb = 'retiro' and not (todo_retiro and ent = 'retiro') then return jsonb_build_object('ok', false, 'error', 'Este pedido se paga en línea: elige ⚡ Pagar ahora');
  elsif cb = 'abono' and not hay_abono then return jsonb_build_object('ok', false, 'error', 'Este pedido no tiene abono: elige ⚡ Pagar ahora');
  end if;
  pagar := case when tot <= 0 or cb = 'retiro' then 0
                when cb = 'abono' and base > 0 then least(tot, greatest(1, round((tot - costo) * ya / base) + costo))
                else tot end;
  if cb = 'abono' and pagar >= tot then cb := 'ahora'; end if;
  insert into public.pedidos (negocio_id, cliente_id, invitado_nombre, invitado_tel, lineas, subtotal, descuento, desc_premium, total, cupon, entrega, direccion, nota,
                              estado, retenido_hasta, token, costo_despacho, comuna, gift_codigo, gift_monto, cobro, a_pagar)
  values (p_negocio, p_cliente, p_nombre, p_tel, a -> 'lineas', sub, desc_ + dp + gm, dp, tot,
          nullif(upper(regexp_replace(coalesce(p_cupon, ''), '[^A-Za-z0-9]', '', 'g')), ''), ent,
          case when ent = 'despacho' then left(trim(p_direccion), 200) end, nullif(left(trim(coalesce(p_nota, '')), 300), ''),
          case when pagar > 0 then 'pagando' else 'recibido' end,
          case when pagar > 0 then now() + make_interval(mins => public.regla('retencion_min', 30)) end,
          left(replace(gen_random_uuid()::text, '-', ''), 24), costo, dsp ->> 'comuna', gc.codigo, gm, cb, pagar)
  returning * into ped;
  if pct > 0 then perform public.cfx_desc_usar(p_negocio, p_cupon); end if;
  if gm > 0 then
    update public.giftcards set saldo = saldo - gm where id = gc.id;
    insert into public.giftcard_usos (giftcard_id, monto, pedido_id, donde) values (gc.id, gm, ped.id, 'pedido');
  end if;
  quien := coalesce(p_nombre, (select coalesce(nullif(empresa, ''), split_part(email, '@', 1)) from public.profiles where id = p_cliente));
  -- G139: si hay que pagar antes, la tienda NO recibe aviso al apartar: le llega "💳 Pagado: prepáralo" al pagar (o "🧾 Comprobante por revisar").
  if pagar <= 0 then
  perform public.notify_user(p_negocio, case when prem then '⭐ ' else '' end ||
    case when cb = 'retiro' and tot > 0 then '💰 Nuevo pedido (paga al retirar) de ' else '📦 Nuevo pedido de ' end || quien,
    'Total $' || to_char(ped.total, 'FM999G999G999') || case when cb = 'abono' then ' · abono $' || to_char(pagar, 'FM999G999G999') else '' end || ' · ' ||
    case when not fis then 'Sin envío' when ent = 'despacho' then 'Despacho' else 'Retiro en tienda' end ||
    case when prem then ' · Cliente Premium' else '' end, 'apps/pedidos/');
    perform public.notify_user(e.id, '📦 Pedido para preparar', quien || ' · Total $' || to_char(ped.total, 'FM999G999G999'), 'apps/pedidos/')
    from public.profiles e where e.role = 'equipo' and e.negocio_id = p_negocio and not e.suspended;
  end if;
  return jsonb_build_object('ok', true, 'id', ped.id, 'token', ped.token, 'subtotal', ped.subtotal, 'descuento', ped.descuento, 'desc_premium', ped.desc_premium,
    'total', ped.total, 'despacho', ped.costo_despacho, 'gift', ped.gift_monto, 'estado', ped.estado, 'retenido_hasta', ped.retenido_hasta, 'link', l,
    'cobro', ped.cobro, 'a_pagar', ped.a_pagar, 'entrega', ped.entrega);
exception when others then
  return jsonb_build_object('status', 0, 'error', sqlerrm);
end $$;
revoke all on function public.guardar_pedido(uuid, uuid, text, text, jsonb, text, text, text, text, text) from public, anon, authenticated;

drop function if exists public.crear_pedido(uuid, jsonb, text, text, text, text);
create or replace function public.crear_pedido(p_negocio uuid, p_items jsonb, p_entrega text, p_direccion text,
                                               p_nota text, p_cupon text, p_cobro text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare r jsonb;
begin
  if not public.puede_comprar(auth.uid(), p_negocio) then return jsonb_build_object('ok', false, 'error', 'No puedes pedirle a esta tienda'); end if;
  if (select count(*) from public.pedidos where cliente_id = auth.uid() and created_at > now() - interval '1 day') >= 20 then
    return jsonb_build_object('ok', false, 'error', 'Máximo 20 pedidos por día');
  end if;
  r := public.guardar_pedido(p_negocio, auth.uid(), null, null, p_items, p_entrega, p_direccion, p_nota, p_cupon, p_cobro);
  if (r ->> 'ok')::boolean then perform public.cfx_carrito_vaciar(auth.uid(), p_negocio); end if;
  return r;
end $$;
revoke all on function public.crear_pedido(uuid, jsonb, text, text, text, text, text) from public, anon;
grant execute on function public.crear_pedido(uuid, jsonb, text, text, text, text, text) to authenticated;

drop function if exists public.crear_pedido_invitado(text, text, text, jsonb, text, text, text, text);
create or replace function public.crear_pedido_invitado(p_slug text, p_nombre text, p_tel text, p_items jsonb, p_entrega text,
                                                        p_direccion text, p_nota text, p_humano text default null, p_cobro text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare t uuid; nom text := left(trim(coalesce(p_nombre, '')), 60); tel text := regexp_replace(coalesce(p_tel, ''), '\D', '', 'g');
begin
  select id into t from public.profiles where slug = lower(trim(coalesce(p_slug, ''))) and role = 'user' and not suspended;
  if t is null then return jsonb_build_object('ok', false, 'error', 'Tienda no encontrada'); end if;
  if not public.cfx_humano_ok(p_humano) then return jsonb_build_object('ok', false, 'error', 'Confirma que no eres un robot y vuelve a intentar'); end if;
  if nom = '' then return jsonb_build_object('ok', false, 'error', 'Escribe tu nombre'); end if;
  if length(tel) < 8 or length(tel) > 15 then return jsonb_build_object('ok', false, 'error', 'Escribe tu WhatsApp (con código de país, ej: 56912345678)'); end if;
  if (select count(*) from public.pedidos where negocio_id = t and invitado_tel = tel and estado in ('pagando', 'en_revision', 'recibido')) >= 3 then
    return jsonb_build_object('ok', false, 'error', 'Ya tienes 3 pedidos pendientes en esta tienda');
  end if;
  if (select count(*) from public.pedidos where negocio_id = t and cliente_id is null and created_at > now() - interval '1 hour') >= 30 then
    return jsonb_build_object('ok', false, 'error', 'La tienda recibió muchos pedidos seguidos. Intenta en un rato.');
  end if;
  return public.guardar_pedido(t, null, nom, tel, p_items, p_entrega, p_direccion, p_nota, null, p_cobro);
end $$;
revoke all on function public.crear_pedido_invitado(text, text, text, jsonb, text, text, text, text, text) from public;
grant execute on function public.crear_pedido_invitado(text, text, text, jsonb, text, text, text, text, text) to anon, authenticated;

-- 💵 Abono aprobado ≠ pago completo (el resto se cobra al entregar) · 💰 entregado = pagado · 🔑 pago aprobado = se entrega el acceso.
create or replace function public.pedido_g128() returns trigger
language plpgsql security definer set search_path = '' as $$
declare ac jsonb;
begin
  if new.cobro = 'abono' and new.pagado_at is not null and old.pagado_at is null and new.abonado_at is null and new.estado <> 'entregado' then
    new.abonado_at := new.pagado_at; new.pagado_at := null;
  end if;
  if new.cobro in ('abono', 'retiro') and new.estado = 'entregado' and old.estado <> 'entregado' and new.pagado_at is null then new.pagado_at := now(); end if;
  if new.accesos is null and new.estado in ('preparando', 'listo', 'en_camino', 'entregado')
     and (new.pagado_at is not null or new.abonado_at is not null or new.estado = 'entregado' or new.total <= 0) then
    select jsonb_agg(jsonb_build_object('nombre', l ->> 'nombre', 'acceso', c.acceso)) into ac
    from jsonb_array_elements(new.lineas) l join public.catalog_items c on c.owner_id = new.negocio_id and c.client_key = l ->> 'clave'
    where l ->> 'tipo' = 'digital' and c.tipo = 'digital' and c.acceso is not null;
    if ac is not null then
      new.accesos := ac;
      -- Solo accesos digitales: queda entregado al tiro.
      if not exists (select 1 from jsonb_array_elements(new.lineas) l where coalesce(l ->> 'tipo', 'producto') <> 'digital') then
        new.estado := 'entregado'; new.pagado_at := coalesce(new.pagado_at, now());
      end if;
    end if;
  end if;
  return new;
end $$;
create or replace function public.pedido_g128_aviso() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.accesos is not null and old.accesos is null then
    perform public.aviso_cliente(new, '🔑 Tu acceso digital está listo', 'Ábrelo en el detalle de tu pedido');
  end if;
  return null;
end $$;
revoke all on function public.pedido_g128(), public.pedido_g128_aviso() from public, anon, authenticated;
drop trigger if exists pedido_g128 on public.pedidos;
create trigger pedido_g128 before update on public.pedidos for each row execute function public.pedido_g128();
drop trigger if exists pedido_g128_aviso on public.pedidos;
create trigger pedido_g128_aviso after update of accesos on public.pedidos for each row execute function public.pedido_g128_aviso();

-- e) 💬 Chat DEL pedido (núcleo cfx_hilo_*): solo el cliente CON cuenta y la tienda (dueño o equipo). ref = 'pedido:<id>'.
create or replace function public.cfx_hilo_app(p_ref text, u uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare x public.pedidos;
begin
  if coalesce(p_ref, '') !~ '^pedido:[0-9a-f-]{36}$' then return jsonb_build_object('ok', false, 'existe', false); end if;
  select * into x from public.pedidos where id = substr(p_ref, 8)::uuid;
  if x.id is null or x.cliente_id is null then return jsonb_build_object('ok', false, 'existe', false); end if;
  return jsonb_build_object('existe', true,
    'cerrado', case when x.estado in ('entregado', 'cancelado', 'rechazado', 'expirado') then x.updated_at end,
    'ok', u is not null and (u = x.cliente_id or public.negocio_de(u) is not distinct from x.negocio_id),
    'tienda', u is not null and u <> x.cliente_id and public.negocio_de(u) is not distinct from x.negocio_id);
end $$;
create or replace function public.cfx_hilo_aviso_app(p_ref text, p_de uuid, p_texto text) returns void
language plpgsql security definer set search_path = '' as $$
declare x public.pedidos;
begin
  select * into x from public.pedidos where id = substr(p_ref, 8)::uuid;
  if x.id is null then return; end if;
  if p_de = x.cliente_id then
    perform public.notify_user(x.negocio_id, '💬 ' || coalesce((select coalesce(nullif(empresa, ''), split_part(email, '@', 1)) from public.profiles where id = x.cliente_id), 'Un cliente') ||
      ' escribió por su pedido', left(p_texto, 120), 'apps/pedidos/');
  else
    perform public.aviso_cliente(x, '💬 La tienda te respondió', left(p_texto, 120));
  end if;
end $$;
revoke all on function public.cfx_hilo_app(text, uuid), public.cfx_hilo_aviso_app(text, uuid, text) from public, anon, authenticated;

-- G128: lo que ven el cliente, el comprador sin cuenta y la tienda (cobro, monto a pagar ahora, si ya está pagado, accesos y token para 📲 enviar el enlace).
--   pagado = pago completo (⚡ aprobado o entregado) · abonado = 💵 abono aprobado · servicio/digital = todo el pedido es de ese tipo.
create or replace function public.ver_pedido(p_ref text) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare x public.pedidos := public.pedido_ref(p_ref); t public.profiles;
begin
  if x.id is null then return null; end if;
  select * into t from public.profiles where id = x.negocio_id;
  return jsonb_build_object('id', x.id, 'token', x.token, 'estado', x.estado, 'lineas', x.lineas, 'subtotal', x.subtotal, 'descuento', x.descuento,
    'desc_premium', x.desc_premium, 'total', x.total, 'entrega', x.entrega, 'direccion', x.direccion, 'nota', x.nota, 'fecha', x.created_at,
    'retenido_hasta', x.retenido_hasta, 'rechazos', x.rechazos,
    'tiene_comprobante', x.comprobante is not null, 'devolucion', x.devolucion, 'motivo', x.motivo, 'nombre', x.invitado_nombre,
    'tienda', jsonb_build_object('nombre', t.empresa, 'slug', t.slug, 'logo', t.logo, 'color', t.color, 'telefono', t.telefono, 'datos_pago', t.datos_pago),
    'link', case when x.estado = 'pagando' then public.link_activo(x.negocio_id, 'pedido') end,
    'cancel_min', public.regla('cancel_min', 10),
    'calificado', public.cfx_calif_hecha(x.id::text, false),
    'boleta', case when x.boleta_folio is not null then public.boleta_de(x) end,
    'envio', public.envio_de(x), 'con_correo', x.cliente_id is not null or x.invitado_correo is not null,
    'cobro', coalesce(x.cobro, 'ahora'), 'a_pagar', coalesce(x.a_pagar, x.total), 'pagado', x.pagado_at is not null, 'abonado', x.abonado_at is not null,
    'accesos', x.accesos, 'con_cuenta', x.cliente_id is not null, 'servicio', public.pedido_solo(x.lineas, 'servicio'), 'digital', public.pedido_solo(x.lineas, 'digital'));
end $$;

-- ¿Todas las líneas (sin el despacho) son de este tipo? (líneas viejas sin tipo = 📦 producto)
create or replace function public.pedido_solo(p_lineas jsonb, p_tipo text) returns boolean
language sql immutable set search_path = '' as $$
  select coalesce(bool_and(coalesce(l ->> 'tipo', 'producto') = p_tipo), false) from jsonb_array_elements(coalesce(p_lineas, '[]'::jsonb)) l where l ->> 'clave' is distinct from 'despacho'
$$;
revoke all on function public.pedido_solo(jsonb, text) from public, anon, authenticated;

drop function if exists public.mis_pedidos(uuid);
create or replace function public.mis_pedidos(p_negocio uuid default null)
returns table (id uuid, negocio text, lineas jsonb, subtotal numeric, descuento numeric, total numeric, cupon text,
               entrega text, direccion text, nota text, estado text, fecha timestamptz, actualizado timestamptz,
               retenido_hasta timestamptz, tiene_comprobante boolean, devolucion text, calificado boolean, token text,
               desc_premium numeric, motivo text, rechazos int, boleta jsonb, envio jsonb,
               cobro text, a_pagar numeric, pagado boolean, abonado boolean, accesos jsonb, servicio boolean, digital boolean)
language sql stable security definer set search_path = '' as $$
  select x.id, t.empresa, x.lineas, x.subtotal, x.descuento, x.total, x.cupon,
         x.entrega, x.direccion, x.nota, x.estado, x.created_at, x.updated_at, x.retenido_hasta, x.comprobante is not null, x.devolucion,
         public.cfx_calif_hecha(x.id::text, false), x.token, x.desc_premium, x.motivo, x.rechazos,
         case when x.boleta_folio is not null then public.boleta_de(x) end, public.envio_de(x),
         coalesce(x.cobro, 'ahora'), coalesce(x.a_pagar, x.total), x.pagado_at is not null, x.abonado_at is not null, x.accesos,
         public.pedido_solo(x.lineas, 'servicio'), public.pedido_solo(x.lineas, 'digital')
  from public.pedidos x join public.profiles t on t.id = x.negocio_id
  where x.cliente_id = auth.uid() and (p_negocio is null or x.negocio_id = p_negocio)
  order by x.created_at desc limit 50
$$;
revoke all on function public.mis_pedidos(uuid) from public, anon;
grant execute on function public.mis_pedidos(uuid) to authenticated;

drop function if exists public.pedidos_tienda(text);
create or replace function public.pedidos_tienda(p_estado text default null)
returns table (id uuid, cliente_id uuid, cliente text, telefono text, lineas jsonb, subtotal numeric, descuento numeric,
               total numeric, cupon text, entrega text, direccion text, nota text, estado text, fecha timestamptz,
               retenido_hasta timestamptz, tiene_comprobante boolean, devolucion text, invitado boolean, calificado boolean, cliente_estrellas numeric,
               premium boolean, desc_premium numeric, rechazos int, motivo text, boleta jsonb, medio text, envio jsonb,
               cobro text, a_pagar numeric, pagado boolean, abonado boolean, token text, servicio boolean, digital boolean)
language sql stable security definer set search_path = '' as $$
  select x.id, x.cliente_id, coalesce(nullif(c.empresa, ''), split_part(c.email, '@', 1), x.invitado_nombre, 'Cliente'),
         coalesce(c.telefono, x.invitado_tel), x.lineas, x.subtotal, x.descuento, x.total, x.cupon, x.entrega, x.direccion, x.nota, x.estado,
         x.created_at, x.retenido_hasta, x.comprobante is not null, x.devolucion, x.cliente_id is null,
         public.cfx_calif_hecha(x.id::text, true),
         (public.cfx_calif_cliente(x.cliente_id, case when x.cliente_id is null then x.invitado_tel end) ->> 'promedio')::numeric,
         pr.premium, x.desc_premium, x.rechazos, x.motivo, public.boleta_de(x),
         case when x.mp_pago is not null then 'mercadopago' when x.comprobante_at is not null then 'transferencia' end, public.envio_de(x),
         coalesce(x.cobro, 'ahora'), coalesce(x.a_pagar, x.total), x.pagado_at is not null, x.abonado_at is not null, x.token,
         public.pedido_solo(x.lineas, 'servicio'), public.pedido_solo(x.lineas, 'digital')
  from public.pedidos x left join public.profiles c on c.id = x.cliente_id
  cross join lateral (select c.role = 'client' and public.is_pro(c.id) as premium) pr
  where x.negocio_id = public.negocio_de(auth.uid())
    and (p_estado is null or (p_estado = 'activos' and x.estado in ('recibido', 'preparando', 'listo', 'en_camino'))
         or (p_estado = 'revisar' and x.estado = 'en_revision') or (p_estado = 'pagando' and x.estado = 'pagando')
         or (p_estado = 'devolver' and x.devolucion = 'pendiente')
         or (p_estado = 'historial' and x.estado in ('entregado', 'cancelado', 'rechazado', 'expirado')) or x.estado = p_estado)
  order by (coalesce(pr.premium, false) and x.estado in ('pagando', 'en_revision', 'recibido', 'preparando', 'listo', 'en_camino')) desc, x.created_at desc
  limit 300
$$;
revoke all on function public.pedidos_tienda(text) from public, anon;
grant execute on function public.pedidos_tienda(text) to authenticated;

-- ---------- VERSIÓN 5.98 · G145 a 🌐 Dominio de la tienda se conecta SOLO desde su app (se puede volver a correr) ----------
-- La función "enviar" (con la sesión del dueño) pide estos datos; el dominio SIEMPRE sale de la base, nunca del navegador.
-- antes_libre: el dominio anterior ya no lo usa ninguna tienda → se puede borrar su Custom Hostname.
create or replace function public.dominio_cf_datos(p_uid uuid, p_antes text default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare p record; a text := nullif(regexp_replace(lower(trim(regexp_replace(coalesce(p_antes, ''), '^https?://|/.*$', '', 'gi'))), '^www\.', ''), '');
begin
  select id, dominio, role, suspended into p from public.profiles where id = p_uid;
  if p.id is null or p.role not in ('user', 'admin') then return jsonb_build_object('ok', false, 'error', 'Solo el dueño de la tienda'); end if;
  return jsonb_build_object('ok', true, 'dominio', p.dominio, 'modulo', not coalesce(p.suspended, false) and public.pro_o_modulo(p.id, 'dominio'),
    'cname', coalesce((select valor ->> 'cname' from public.cfx_config where clave = 'dominio'), ''),
    'antes', a, 'antes_libre', a is not null and not exists (select 1 from public.profiles x where x.dominio = a));
end $$;
revoke all on function public.dominio_cf_datos(uuid, text) from public, anon, authenticated;
